    'This policy explains how [COMPANY NAME], company ID [ID], registered at [ADDRESS], processes the personal data you entrust to us.' => 'Esta política explica cómo [NOMBRE DE LA EMPRESA], con número de registro [ID] y domicilio en [DIRECCIÓN], trata los datos personales que nos confías.',
    'What data we process' => 'Qué datos tratamos',
