    'scrolls with content' => 'se desplaza con el contenido',
    'The Newsletter sign-up element in the builder: visitors enter an e-mail and confirm it by a link (double opt-in). The site sends confirmed subscribers to your mailing service (Brevo, MailerLite, Mailchimp, Ecomail, SmartEmailing, webhook), or you export them to CSV.' => 'El elemento Suscripción al boletín en el builder: los visitantes introducen un correo y lo confirman mediante un enlace (doble opt-in). El sitio envía los suscriptores confirmados a tu servicio de envío (Brevo, MailerLite, Mailchimp, Ecomail, SmartEmailing, webhook), o puedes exportarlos a CSV.',
    'Subscribers' => 'Suscriptores',
    'The subscriber has been deleted.' => 'Se ha eliminado el suscriptor.',
    'Subscribed' => 'Suscrito',
    'Confirmed' => 'Confirmado',
    'Unsubscribe link' => 'Enlace de baja',
    'Addresses from the Newsletter sign-up element. Only people who confirmed by the link in the e-mail count as subscribers. Send with your own tool – the export includes the unsubscribe link.' => 'Direcciones del elemento Suscripción al boletín. Solo cuentan como suscriptores las personas que confirmaron mediante el enlace del correo. Envía con tu propia herramienta – la exportación incluye el enlace de baja.',
    'Search e-mail' => 'Buscar correo',
    'Export confirmed (CSV)' => 'Exportar confirmados (CSV)',
    'No subscribers yet.' => 'Aún no hay suscriptores.',
    'Nothing found.' => 'No se ha encontrado nada.',
    'Put the Newsletter sign-up element on the website – for example in the footer.' => 'Coloca el elemento Suscripción al boletín en el sitio web – por ejemplo, en el pie de página.',
    'confirmed' => 'confirmado',
    'awaiting confirmation' => 'pendiente de confirmación',
    'Remove the address from the subscriber list?' => '¿Quitar la dirección de la lista de suscriptores?',
    'Only an editor or administrator can publish. Your changes stay saved as a draft.' => 'Solo un editor o un administrador puede publicar. Tus cambios se quedan guardados como borrador.',
    'Only an administrator edits a shared class – a change applies to the whole website at once. Set the look of a single element in its style.' => 'Solo un administrador edita una clase compartida – un cambio se aplica a todo el sitio web a la vez. Define el aspecto de un único elemento en su estilo.',
    'Only an editor or administrator edits, publishes and deletes published pages. You can prepare a new hidden page.' => 'Solo un editor o un administrador edita, publica y elimina páginas publicadas. Puedes preparar una nueva página oculta.',
    'This news item is published – only an editor or administrator can save changes to it. Ask them to edit it.' => 'Esta noticia está publicada – solo un editor o un administrador puede guardar cambios en ella. Pídele que la edite.',
    'The website requires two-step sign-in – you can create a token once you turn it on.' => 'El sitio web exige la verificación en dos pasos – podrás crear un token cuando la actives.',
    'These fields have an invalid format and were not saved: %s. Please correct them (they are highlighted); the other settings are saved.' => 'Estos campos tienen un formato no válido y no se han guardado: %s. Corrígelos (están resaltados); el resto de ajustes se han guardado.',
    'Enquiries older than the given number of months will be permanently deleted right away – including attachments. Save anyway?' => 'Las consultas con más antigüedad que el número de meses indicado se eliminarán definitivamente ahora mismo – incluidos los adjuntos. ¿Guardar de todos modos?',
    'The database is back in its state before the restore.' => 'La base de datos ha vuelto a su estado anterior a la restauración.',
    'The state before the restore is in backup %s – please restore it.' => 'El estado anterior a la restauración está en la copia de seguridad %s – restáurala.',
    'The backup is incomplete or damaged (the end of the file is missing) – the restore was stopped.' => 'La copia de seguridad está incompleta o dañada (falta el final del archivo) – se ha detenido la restauración.',
    'The website files have been returned to their state before the update.' => 'Los archivos del sitio web han vuelto a su estado anterior a la actualización.',
    'The server cannot use encrypted FTP (FTPS). Send backups to S3 storage, or download them manually.' => 'El servidor no puede usar FTP cifrado (FTPS). Envía las copias de seguridad a un almacenamiento S3 o descárgalas manualmente.',
    'to an FTP server with FTPS encryption (another host, home NAS)' => 'a un servidor FTP con cifrado FTPS (otro hosting, NAS doméstico)',
    'The builder needs a larger screen.' => 'El builder necesita una pantalla más grande.',
    'Build pages on a computer or tablet. On a phone, edit texts with the “Edit here” button right on the website.' => 'Crea las páginas en un equipo de escritorio o una tableta. En el móvil, edita los textos con el botón “Editar aquí” directamente en el sitio web.',
    'Back to the administration' => 'Volver a la administración',
    'Please confirm that you want to receive news at %s.' => 'Confirma que quieres recibir noticias en %s.',
    'Do you really no longer want to receive news at %s?' => '¿De verdad ya no quieres recibir noticias en %s?',
    'tag' => 'etiqueta',
    'category' => 'categoría',
    'my section' => 'mi sección',
    'user' => 'usuario',
    'Invalid sign-in request' => 'Solicitud de inicio de sesión no válida',
    'The application did not register correctly with this website (unknown client or return address). Please connect it again.' => 'La aplicación no se ha registrado correctamente en este sitio web (cliente o dirección de retorno desconocidos). Vuelve a conectarla.',
    'Connect an application' => 'Conectar una aplicación',
    'The request to connect the application has expired or does not exist. Start connecting again in the application.' => 'La solicitud para conectar la aplicación ha caducado o no existe. Vuelve a iniciar la conexión en la aplicación.',
    'wants to work with the website %s.' => 'quiere trabajar con el sitio web %s.',
    'It will act with the permissions of your account %s (%s): read and edit pages, news, site parts and appearance – just like you in the administration. Builds and news are saved as drafts.' => 'Actuará con los permisos de tu cuenta %s (%s): leer y editar páginas, noticias, partes del sitio y la apariencia – igual que tú en la administración. Las páginas del builder y las noticias se guardan como borradores.',
    'After allowing it you return to the application at %s. You can revoke the connection at any time in My account → Connected applications.' => 'Tras permitirlo, volverás a la aplicación en %s. Puedes revocar la conexión en cualquier momento en Mi cuenta → Aplicaciones conectadas.',
    'Allow access' => 'Permitir acceso',
    'Deny' => 'Denegar',
    'The easiest way is to add a custom connector in the Claude app with the address %s – Claude sends you here to sign in and confirm access, no token to copy. The token below is for Claude Code and other tools without sign-in.' => 'Lo más sencillo es añadir un conector personalizado en la app de Claude con la dirección %s – Claude te trae aquí para iniciar sesión y confirmar el acceso, sin copiar ningún token. El token de abajo es para Claude Code y otras herramientas sin inicio de sesión.',
    'Connected applications' => 'Aplicaciones conectadas',
    'connected %s' => 'conectada el %s',
    'Disconnect the application? It will not get into the website until you allow it again.' => '¿Desconectar la aplicación? No podrá acceder al sitio web hasta que vuelvas a permitirlo.',
