    'This server cannot download files from other sites (both curl and allow_url_fopen are missing, or the GD extension). Move the images manually: upload them to Media and replace them in the articles.' => 'Este servidor no puede descargar archivos de otros sitios (faltan curl y allow_url_fopen, o la extensión GD). Mueve las imágenes manualmente: súbelas a Medios y sustitúyelas en los artículos.',
    'The file does not contain the address of the old site, so the images cannot be downloaded.' => 'El archivo no contiene la dirección del sitio antiguo, así que no se pueden descargar las imágenes.',
    'Try downloading again' => 'Volver a intentar la descarga',
    'Download images from the old site' => 'Descargar las imágenes del sitio antiguo',
    'The PHP extension xmlreader or dom is missing on the server – a WordPress export cannot be read without them.' => 'Falta en el servidor la extensión PHP xmlreader o dom – sin ellas no se puede leer una exportación de WordPress.',
    'WordPress export' => 'Exportación de WordPress',
    'The server allows uploads of at most %s. Copy a larger file over FTP into the storage/import/ folder – it will appear in the list below.' => 'El servidor permite subir como máximo %s. Copia un archivo más grande por FTP en la carpeta storage/import/ – aparecerá en la lista de abajo.',
    'Upload and show preview' => 'Subir y mostrar vista previa',
    'Uploaded' => 'Subido',
    'Delete the file %s? Content that has already been imported stays on the site.' => '¿Eliminar el archivo %s? El contenido ya importado se queda en el sitio.',
    'You can import the same file repeatedly – whatever has already been imported is skipped. Delete the file when the import is finished; it contains e-mail addresses of authors and commenters from the old site.' => 'Puedes importar el mismo archivo varias veces – lo que ya se ha importado se omite. Elimina el archivo cuando termine la importación; contiene direcciones de correo de autores y comentaristas del sitio antiguo.',
    'Export of the whole site' => 'Exportación del sitio completo',
    'The PHP zip extension is missing on the server, so the export contains data only (JSON). Download the media/ folder over FTP.' => 'Falta en el servidor la extensión PHP zip, así que la exportación solo contiene datos (JSON). Descarga la carpeta media/ por FTP.',
    'Create export' => 'Crear exportación',
    'Delete the export %s?' => '¿Eliminar la exportación %s?',
    'The last three exports are kept. To restore this site, use the database backup in Settings → Backups and updates.' => 'Se conservan las tres últimas exportaciones. Para restaurar este sitio, usa la copia de seguridad de la base de datos en Ajustes → Copias de seguridad y actualizaciones.',
    'being read' => 'leyéndose',
    'ready to import' => 'listo para importar',
    'import in progress' => 'importación en curso',
    'content imported' => 'contenido importado',
    'downloading images' => 'descargando imágenes',
    'imported including images' => 'importado con imágenes',
    'Result' => 'Resultado',
    'Show preview' => 'Mostrar vista previa',
    'Read again' => 'Volver a leer',
    'The file could not be uploaded. If it is larger than the server allows, upload it over FTP into the storage/import/ folder.' => 'No se ha podido subir el archivo. Si es más grande de lo que permite el servidor, súbelo por FTP a la carpeta storage/import/.',
    'The file must have the .xml extension – it is an export from WordPress (Tools → Export).' => 'El archivo debe tener la extensión .xml – es una exportación de WordPress (Herramientas → Exportar).',
    'The file could not be saved – check write permissions for storage/import.' => 'No se ha podido guardar el archivo – comprueba los permisos de escritura de storage/import.',
    'The file does not exist.' => 'El archivo no existe.',
    'The file has been deleted. The imported content stays on the site.' => 'Se ha eliminado el archivo. El contenido importado se queda en el sitio.',
    'The export is ready – download it from the list below.' => 'La exportación está lista – descárgala de la lista de abajo.',
    'The export does not exist.' => 'La exportación no existe.',
    'The export has been deleted.' => 'Se ha eliminado la exportación.',
    'Cannot create the storage/import folder – check write permissions.' => 'No se puede crear la carpeta storage/import – comprueba los permisos de escritura.',
    'The file is empty or larger than 1 GB. Export a large site from WordPress in parts (by date).' => 'El archivo está vacío o supera 1 GB. Exporta un sitio grande de WordPress por partes (por fecha).',
    'The file could not be opened.' => 'No se ha podido abrir el archivo.',
    'This is not a WordPress export. In WordPress open Tools → Export, choose “All content” and download the .xml file.' => 'Esto no es una exportación de WordPress. En WordPress abre Herramientas → Exportar, elige “Todo el contenido” y descarga el archivo .xml.',
    'The file contains no site content (the channel element is missing).' => 'El archivo no contiene contenido del sitio (falta el elemento channel).',
    'The file contains a DOCTYPE or custom entities. A WordPress export never has them – the file was rejected for security reasons.' => 'El archivo contiene un DOCTYPE o entidades personalizadas. Una exportación de WordPress nunca los tiene – el archivo se ha rechazado por motivos de seguridad.',
    'The file is not valid XML – it is damaged or incomplete. Download the export from WordPress again. The error is on line:' => 'El archivo no es un XML válido – está dañado o incompleto. Vuelve a descargar la exportación de WordPress. El error está en la línea:',
    '(untitled)' => '(sin título)',
    'The address does not belong to the old site.' => 'La dirección no pertenece al sitio antiguo.',
    'The domain of the old site does not exist or points to an internal network.' => 'El dominio del sitio antiguo no existe o apunta a una red interna.',
    'The old site did not return the image, it responded with error' => 'El sitio antiguo no ha devuelto la imagen; ha respondido con el error',
    'The file is not a JPG, PNG, GIF or WebP image.' => 'El archivo no es una imagen JPG, PNG, GIF o WebP.',
    'Too many redirects.' => 'Demasiadas redirecciones.',
    'The image is larger than 15 MB.' => 'La imagen supera los 15 MB.',
    'The old site is not responding.' => 'El sitio antiguo no responde.',
    'The old site responds too slowly.' => 'El sitio antiguo responde demasiado despacio.',
    'The media exceed 1 GB, so the export contains data only (JSON). Download the media/ folder over FTP.' => 'Los medios superan 1 GB, así que la exportación solo contiene datos (JSON). Descarga la carpeta media/ por FTP.',
    'There is not enough disk space for an archive with media, so the export contains data only (JSON). Download the media/ folder over FTP.' => 'No hay espacio en disco suficiente para un archivo comprimido con los medios, así que la exportación solo contiene datos (JSON). Descarga la carpeta media/ por FTP.',
    'The archive could not be created – check write permissions for storage/zalohy.' => 'No se ha podido crear el archivo comprimido – comprueba los permisos de escritura de storage/zalohy.',
    'The archive could not be finished – the disk is probably full.' => 'No se ha podido terminar el archivo comprimido – probablemente el disco está lleno.',
    'Cannot write to storage/zalohy – check write permissions.' => 'No se puede escribir en storage/zalohy – comprueba los permisos de escritura.',
