    'Logo and navigation at the top of every page.' => 'Logotipo y navegación en la parte superior de cada página.',
    'Contacts, links and copyright at the bottom of every page.' => 'Contactos, enlaces y copyright en la parte inferior de cada página.',
    'A wrapper around the news list, category, tag and search results.' => 'Un marco alrededor de la lista de noticias, categorías, etiquetas y resultados de búsqueda.',
    'A wrapper around the page-not-found message – e.g. with links onward.' => 'Un marco alrededor del mensaje de página no encontrada – p. ej. con enlaces para seguir navegando.',
    'The header and footer appear on every page. Wrappers add sections around content assembled by the system – news items, lists and the 404 message. Until you publish a part from the builder, it has its default design.' => 'El encabezado y el pie de página aparecen en todas las páginas. Los marcos añaden secciones alrededor del contenido que compone el sistema – noticias, listas y el mensaje 404. Mientras no publiques una parte desde el builder, tendrá su diseño predeterminado.',
    'Part' => 'Parte',
    'from the builder' => 'desde el builder',
    'Edit in the builder' => 'Editar en el builder',
    'Revert to default' => 'Restablecer el predeterminado',
    'Revert this part to its default design? The builder version stays in the history.' => '¿Restablecer el diseño predeterminado de esta parte? La versión del builder se queda en el historial.',
    'The site part is back to its default design. The previous design is in the history when you open it in the builder again.' => 'La parte del sitio ha vuelto a su diseño predeterminado. El diseño anterior está en el historial cuando la vuelvas a abrir en el builder.',
    'There is no published version yet – nothing to revert to.' => 'Aún no hay ninguna versión publicada – no hay nada que restablecer.',
