    'Resolved' => 'Resuelta',
    'No enquiries yet.' => 'Aún no hay consultas.',
    'Add a Form element in the page builder (or the ready-made Enquiry form section) – submitted messages will appear here and arrive by email.' => 'Añade un elemento Formulario en el builder (o la sección prediseñada Formulario de consulta) – los mensajes enviados aparecerán aquí y llegarán por correo electrónico.',
    'Open pages' => 'Abrir páginas',
