    'Company' => 'Empresa',
    'Fill these in once and the site uses them everywhere: in the footer and on the contact page (the Business details element in the builder) and for Google, maps and AI assistants – so they answer correctly when you are open and where to find you.' => 'Rellénalos una vez y el sitio los usará en todas partes: en el pie de página y en la página de contacto (el elemento Datos de la empresa en el builder), y para Google, los mapas y los asistentes de IA – para que respondan correctamente cuándo abres y dónde encontrarte.',
    'Registered company name' => 'Razón social',
    'The exact registered name, e.g. “Novak Joinery Ltd”. Elsewhere the site uses the site name.' => 'La razón social exacta, p. ej. “Carpintería Novak S.L.”. En los demás lugares el sitio usa el nombre del sitio.',
    'Business type' => 'Tipo de negocio',
    'Search engines show opening hours, a map and reviews depending on the type. If customers visit you, do not choose “company without premises”.' => 'Según el tipo, los buscadores muestran horario, mapa y opiniones. Si los clientes te visitan, no elijas “empresa sin local”.',
    'VAT payers only, with the country prefix, e.g. DE123456789 or FR12345678901.' => 'Solo para quienes declaran IVA, con el prefijo del país, p. ej. ESB12345678 o DE123456789.',
    'Address and contact' => 'Dirección y contacto',
    'Street and number' => 'Calle y número',
    'Postcode' => 'Código postal',
    'City' => 'Ciudad',
    'Country (code)' => 'País (código)',
    'Two-letter code, e.g. GB, IE, DE, FR. Empty = not stated.' => 'Código de dos letras, p. ej. ES, MX, DE, FR. Vacío = sin indicar.',
    'Opening hours and map' => 'Horario y mapa',
    'One day or range of days per line: “Mo–Fr 8:00–17:00”, “Sa 9–12”, “Su closed”, lunch break “Tu 8–12, 13–17”. Empty = no opening hours.' => 'Un día o rango de días por línea: “Mo–Fr 8:00–17:00”, “Sa 9–12”, “Su closed”, pausa para comer “Tu 8–12, 13–17”. Vacío = sin horario.',
    'Map link' => 'Enlace al mapa',
    'Link to the place on Google Maps, OpenStreetMap or another map – the Business details element turns it into a “Show on map” link.' => 'Enlace al lugar en Google Maps, OpenStreetMap u otro mapa – el elemento Datos de la empresa lo convierte en un enlace “Mostrar en el mapa”.',
    'Coordinates (optional)' => 'Coordenadas (opcional)',
    'Latitude and longitude, e.g. 50.0875, 14.4213 – a more precise location for maps and search engines.' => 'Latitud y longitud, p. ej. 50.0875, 14.4213 – una ubicación más precisa para mapas y buscadores.',
    'company without premises for customers' => 'empresa sin local para clientes',
    'business premises (general)' => 'local comercial (general)',
    'crafts and construction' => 'oficios y construcción',
    'professional services (consulting, agency)' => 'servicios profesionales (consultoría, agencia)',
    'legal services' => 'servicios jurídicos',
