    'Registered name and company ID' => 'Razón social y número de registro',
    'Fill in business details' => 'Rellenar los datos de la empresa',
    'Address, phone and opening hours appear on the contact page, in the footer and to search engines.' => 'La dirección, el teléfono y el horario aparecen en la página de contacto, en el pie de página y en los buscadores.',
    'Collections' => 'Colecciones',
    'New collection' => 'Nueva colección',
    'No collections yet.' => 'Aún no hay colecciones.',
    'A collection is a list of similar things with their own fields – testimonials, team members, products, branches, a price list. Put them on the site with the Collection list element in the builder; each item can also have its own page.' => 'Una colección es una lista de cosas similares con sus propios campos – testimonios, miembros del equipo, productos, sedes, una lista de precios. Colócalas en el sitio con el elemento Lista de colección en el builder; cada elemento también puede tener su propia página.',
    'Create a collection' => 'Crear una colección',
    'Items' => 'Elementos',
    'Item pages' => 'Páginas de elementos',
    'Add item' => 'Añadir elemento',
    'Fields and settings' => 'Campos y ajustes',
    'Detail template' => 'Plantilla de detalle',
    'Detail template (%s)' => 'Plantilla de detalle (%s)',
    'Collection name' => 'Nombre de la colección',
    'e.g. Testimonials, Team, Products' => 'p. ej. Testimonios, Equipo, Productos',
    'From the name if left empty. Item pages will then be at /address/item-name.' => 'Si lo dejas vacío, se crea a partir del nombre. Las páginas de los elementos estarán entonces en /direccion/nombre-del-elemento.',
    'each item has its own page (detail)' => 'cada elemento tiene su propia página (detalle)',
    'Design the detail page in the builder (Detail template). Without a detail page, items are just cards in the list.' => 'Diseña la página de detalle en el builder (Plantilla de detalle). Sin página de detalle, los elementos son solo tarjetas en la lista.',
    'Item fields' => 'Campos de los elementos',
    'Every item always has a name. Add the fields you need – in the builder you insert them with a {{key}} tag. An empty label removes the field; the key of a saved field never changes.' => 'Cada elemento tiene siempre un nombre. Añade los campos que necesites – en el builder los insertas con una etiqueta {{key}}. Una etiqueta de campo vacía quita el campo; la clave de un campo guardado nunca cambia.',
    'created from the label' => 'creado a partir de la etiqueta',
    'Save collection' => 'Guardar colección',
    'Delete the collection with all its items? Lists on the site will disappear.' => '¿Eliminar la colección con todos sus elementos? Las listas del sitio desaparecerán.',
    'Delete collection' => 'Eliminar colección',
    'All collections' => 'Todas las colecciones',
    'The collection is empty.' => 'La colección está vacía.',
    'Add the first item – then put it on the site with the Collection list element in the builder.' => 'Añade el primer elemento – luego colócalo en el sitio con el elemento Lista de colección en el builder.',
    'Address, order and visibility' => 'Dirección, orden y visibilidad',
    'Smaller number = earlier in the list.' => 'Número menor = más arriba en la lista.',
    'published on the site' => 'publicado en el sitio',
    'Save item' => 'Guardar elemento',
