    'The address “%s” is already used by the system or another collection.' => 'La dirección “%s” ya la usa el sistema u otra colección.',
    'Only the site administrator can change the collection definition and detail template.' => 'Solo el administrador del sitio puede cambiar la definición de la colección y la plantilla de detalle.',
