    'Component' => 'Componente',
    'A reusable block – editing the component updates it everywhere it is used.' => 'Un bloque reutilizable – al editar el componente se actualiza en todos los lugares donde se usa.',
    'Properties' => 'Propiedades',
    'Components' => 'Componentes',
    'New component' => 'Nuevo componente',
    'No components yet.' => 'Aún no hay componentes.',
    'A component is a block you use in several places – a service card, a contact strip, a call to action. In the builder, select an element and choose “Save as component”; when you edit it later, it changes everywhere at once.' => 'Un componente es un bloque que usas en varios lugares – una tarjeta de servicio, una franja de contacto, una llamada a la acción. En el builder, selecciona un elemento y elige “Guardar como componente”; cuando lo edites más adelante, cambiará en todas partes a la vez.',
    'Create a component' => 'Crear un componente',
    'Name and properties' => 'Nombre y propiedades',
    'Really delete this component?' => '¿Seguro que quieres eliminar este componente?',
    'Component name' => 'Nombre del componente',
    'e.g. Service card' => 'p. ej. Tarjeta de servicio',
    'What can differ between uses of the component – heading, text, image, link. In the builder you insert them into the component with a {{key}} tag, then fill in a value for each use (empty = default).' => 'Lo que puede variar entre los usos del componente – título, texto, imagen, enlace. En el builder los insertas en el componente con una etiqueta {{key}} y luego rellenas un valor para cada uso (vacío = predeterminado).',
    'Default value' => 'Valor predeterminado',
    'Save component' => 'Guardar componente',
    'The component needs a name.' => 'El componente necesita un nombre.',
    'The component does not exist.' => 'El componente no existe.',
    'The component was saved.' => 'El componente se ha guardado.',
    'The component was deleted. Places where it was used will be empty.' => 'El componente se ha eliminado. Los lugares donde se usaba quedarán vacíos.',
    'Name or element is missing.' => 'Falta el nombre o el elemento.',
    'A component cannot be created from this element.' => 'No se puede crear un componente a partir de este elemento.',
    'Component: %s' => 'Componente: %s',
    'Services and content' => 'Servicios y contenido',
    'Trust' => 'Confianza',
    'About the company' => 'Sobre la empresa',
    'Contact and calls to action' => 'Contacto y llamadas a la acción',
    'Writing assistant – provider, your key and model' => 'Asistente de redacción – proveedor, tu clave y modelo',
    'Provider' => 'Proveedor',
    'Create a key with the provider:' => 'Crea una clave en el proveedor:',
    'Mistral AI (Europe)' => 'Mistral AI (Europa)',
    'You pay only for actual use; one suggestion costs a fraction of a cent. The key is stored only on your site.' => 'Solo pagas por el uso real; una sugerencia cuesta una fracción de céntimo. La clave se guarda solo en tu sitio.',
    'API key' => 'Clave API',
    'For Claude, choose from the list (Sonnet is recommended). For other providers, enter the exact model name from their documentation – their model line-up changes often.' => 'Para Claude, elige de la lista (se recomienda Sonnet). Para otros proveedores, introduce el nombre exacto del modelo según su documentación – su oferta de modelos cambia a menudo.',
    'The assistant only suggests – a person decides on every change. When used, the text is sent to the chosen provider; nothing is sent anywhere without clicking an assistant button.' => 'El asistente solo sugiere – una persona decide sobre cada cambio. Al usarlo, el texto se envía al proveedor elegido; no se envía nada a ningún sitio sin hacer clic en un botón del asistente.',
    'The writing assistant is not enabled (Features).' => 'El asistente de redacción no está activado (Funciones).',
    'Enter the model name of the chosen provider under Features (Writing assistant).' => 'Introduce el nombre del modelo del proveedor elegido en Funciones (Asistente de redacción).',
    'The API key is missing – an administrator enters it under Features (Writing assistant).' => 'Falta la clave API – un administrador la introduce en Funciones (Asistente de redacción).',
    'Could not reach %s. Check that the server may make outgoing connections.' => 'No se pudo conectar con %s. Comprueba que el servidor puede realizar conexiones salientes.',
    'The %s API key is not valid. Check it under Features.' => 'La clave API de %s no es válida. Compruébala en Funciones.',
    '%s is busy right now or the key\'s limit is used up. Try again shortly.' => '%s está ocupado ahora mismo o se ha agotado el límite de la clave. Inténtalo de nuevo en breve.',
    'The %s account has run out of credit.' => 'La cuenta de %s se ha quedado sin crédito.',
    '%s does not know the model. Check its name under Features.' => '%s no conoce el modelo. Comprueba su nombre en Funciones.',
    '%s is down. Try again shortly.' => '%s no está disponible. Inténtalo de nuevo en breve.',
    'Describe the section in at least one sentence – what it should contain and for whom.' => 'Describe la sección en al menos una frase – qué debe contener y para quién.',
    'The assistant did not return a usable section. Try refining the description.' => 'El asistente no ha devuelto una sección utilizable. Prueba a precisar la descripción.',
    'The element has no text to rewrite.' => 'El elemento no tiene texto que reescribir.',
    'Add variant' => 'Añadir variante',
    'not on any page yet' => 'aún no está en ninguna página',
    'on pages: %s' => 'en las páginas: %s',
    'variant' => 'variante',
    'Delete the variant? The selected pages will get the default version.' => '¿Eliminar la variante? Las páginas seleccionadas recibirán la versión predeterminada.',
    'A variant applies only to the selected pages; elsewhere the default stays. For example a landing page with a simpler header. If you leave the variant empty in the builder, the page will have no header (footer).' => 'Una variante se aplica solo a las páginas seleccionadas; en el resto se mantiene la predeterminada. Por ejemplo, una landing page con un encabezado más sencillo. Si dejas la variante vacía en el builder, la página no tendrá encabezado (pie de página).',
    'Variant name' => 'Nombre de la variante',
    'e.g. Landing page' => 'p. ej. Landing page',
    'Only the header and footer can have variants.' => 'Solo el encabezado y el pie de página pueden tener variantes.',
    'Variant: %s' => 'Variante: %s',
    'The variant needs a name.' => 'La variante necesita un nombre.',
    'The variant was deleted – the selected pages have the default version again.' => 'La variante se ha eliminado – las páginas seleccionadas vuelven a tener la versión predeterminada.',
    'by field – ascending' => 'por campo – ascendente',
    'by field – descending' => 'por campo – descendente',
    'Sort field (key, e.g. price)' => 'Campo de ordenación (clave, p. ej. price)',
    'Filter by field (key, optional)' => 'Filtrar por campo (clave, opcional)',
    'Filter buttons for visitors (by the field above)' => 'Botones de filtro para visitantes (según el campo de arriba)',
    'Paginate (by “Maximum items”)' => 'Paginar (según “Máximo de elementos”)',
    'In the builder, new sections from a description and text rewrites; in news, headlines, intro, SEO description, tags, proofreading, image descriptions and translation. Needs your own Claude, OpenAI, Google or Mistral key (below); text is sent only when you click an assistant button.' => 'En el builder, nuevas secciones a partir de una descripción y reescritura de textos; en noticias, titulares, entradilla, descripción SEO, etiquetas, corrección, descripciones de imágenes y traducción. Necesita tu propia clave de Claude, OpenAI, Google o Mistral (abajo); el texto se envía solo cuando haces clic en un botón del asistente.',
    'MCP server at /mcp: Claude builds pages in the builder with your account\'s permissions, edits the header, footer, collections and look, and writes news. Pages and news are saved as drafts that you publish, the menu and look go into the draft look; settings apply straight away. Everyone creates their access token under My account.' => 'Servidor MCP en /mcp: Claude crea páginas en el builder con los permisos de tu cuenta, edita el encabezado, el pie de página, las colecciones y la apariencia, y escribe noticias. Las páginas y noticias se guardan como borradores que tú publicas, el menú y la apariencia van al borrador de la apariencia; los ajustes se aplican de inmediato. Cada persona crea su token de acceso en Mi cuenta.',
    'Someone else has edited this page in the meantime (or you opened it in another window).' => 'Otra persona ha editado esta página mientras tanto (o la has abierto en otra ventana).',
    '%d files in use were not deleted – remove them from the site first (the list shows where they are used).' => '%d archivos en uso no se han eliminado – quítalos primero del sitio (la lista muestra dónde se usan).',
    'page' => 'página',
    'site part' => 'parte del sitio',
    'collection' => 'colección',
    'collection item' => 'elemento de la colección',
    'component' => 'componente',
    'class' => 'clase',
    'settings' => 'ajustes',
    'Unused' => 'Sin usar',
    'Used in: %s' => 'Se usa en: %s',
    'Shown under a news item\'s main photo unless it has its own photo credit.' => 'Se muestra bajo la foto principal de una noticia, salvo que tenga su propio crédito fotográfico.',
    'Site menu (Appearance → Menu) with submenus and the language switcher; collapsible on phones.' => 'Menú del sitio (Apariencia → Menú) con submenús y el selector de idioma; plegable en móviles.',
    'Main menu' => 'Menú principal',
    'Footer menu' => 'Menú del pie de página',
    'Link to news (in the automatic menu)' => 'Enlace a noticias (en el menú automático)',
    'Language version:' => 'Versión de idioma:',
    'The menu is currently built automatically from pages ticked “in navigation”. Once you edit and save it here, this version applies.' => 'Ahora el menú se crea automáticamente a partir de las páginas marcadas “en la navegación”. En cuanto lo edites y guardes aquí, se aplicará esta versión.',
    'Reorder by dragging or with the arrows. The right arrow moves an item into the submenu of the one above.' => 'Reordena arrastrando o con las flechas. La flecha derecha mueve un elemento al submenú del de arriba.',
    'Links in the site footer (privacy policy, contact, careers…). Used by the default footer and by a Navigation element set to the footer menu.' => 'Enlaces en el pie de página del sitio (política de privacidad, contacto, empleo…). Los usan el pie de página predeterminado y un elemento Navegación configurado como menú del pie de página.',
    'The menu is empty – add the first item.' => 'El menú está vacío – añade el primer elemento.',
    'Add page' => 'Añadir página',
    'Custom link' => 'Enlace personalizado',
    'Group' => 'Grupo',
    'An item without a link that only opens a submenu' => 'Un elemento sin enlace que solo abre un submenú',
    'Save menu' => 'Guardar menú',
    'Return the menu to being built automatically from pages? Your changes will be discarded.' => '¿Volver a crear el menú automáticamente a partir de las páginas? Tus cambios se descartarán.',
    'Empty the footer menu?' => '¿Vaciar el menú del pie de página?',
    'Back to automatic menu' => 'Volver al menú automático',
    'Empty the menu' => 'Vaciar el menú',
    'The menu has been saved.' => 'El menú se ha guardado.',
    'The menu could not be saved – please try again.' => 'No se pudo guardar el menú – inténtalo de nuevo.',
    'The menu is again built automatically from pages in the navigation.' => 'El menú vuelve a crearse automáticamente a partir de las páginas de la navegación.',
    'The footer menu is empty.' => 'El menú del pie de página está vacío.',
    'The site has a custom menu – the page is added to its end. Change the order and submenus in Appearance → Menu.' => 'El sitio tiene un menú personalizado – la página se añade al final. Cambia el orden y los submenús en Apariencia → Menú.',
    'Lower number = earlier in the page list and in the automatic menu.' => 'Número más bajo = antes en la lista de páginas y en el menú automático.',
    'Which menu' => 'Qué menú',
    'First fill in the Site e-mail on the General tab.' => 'Primero rellena el correo del sitio en la pestaña General.',
    'The page is in the trash. You can restore it for %d days.' => 'La página está en la papelera. Puedes restaurarla durante %d días.',
    '%s (copy)' => '%s (copia)',
    'The page shows the text from the editor (the build\'s content without the layout). You will find the build in versions when you open the builder.' => 'La página muestra el texto del editor (el contenido del diseño sin la maquetación). Encontrarás el diseño en las versiones al abrir el builder.',
    'The home page cannot be deleted. First choose another home page in Settings → General.' => 'No se puede eliminar la página de inicio. Primero elige otra página de inicio en Ajustes → General.',
    'The home page cannot be hidden. First choose another home page in Settings → General.' => 'No se puede ocultar la página de inicio. Primero elige otra página de inicio en Ajustes → General.',
    'A page in the trash uses this address – restore it or delete it permanently.' => 'Una página de la papelera usa esta dirección – restáurala o elimínala definitivamente.',
    'The page has been restored as hidden – publish it in its settings.' => 'La página se ha restaurado como oculta – publícala en sus ajustes.',
    'The page has been permanently deleted.' => 'La página se ha eliminado definitivamente.',
    'The copy of the page is hidden – edit it and publish it.' => 'La copia de la página está oculta – edítala y publícala.',
    'Tag deleted. The news items remain, they just no longer carry it.' => 'Etiqueta eliminada. Las noticias se mantienen, solo que ya no la llevan.',
    'Page' => 'Página',
    'The editor now contains the version from %s. It takes effect once you save the news item.' => 'El editor contiene ahora la versión del %s. Se aplicará cuando guardes la noticia.',
    'News items moved to the trash: %d. They can be restored for 30 days (News → Trash).' => 'Noticias movidas a la papelera: %d. Se pueden restaurar durante 30 días (Noticias → Papelera).',
    'News items restored: %d. They are back as drafts.' => 'Noticias restauradas: %d. Vuelven como borradores.',
    'News items permanently deleted: %d.' => 'Noticias eliminadas definitivamente: %d.',
    'The news item does not exist or you do not have access to it.' => 'La noticia no existe o no tienes acceso a ella.',
    'Only an editor or administrator can edit a published news item.' => 'Solo un editor o administrador puede editar una noticia publicada.',
    'Save the news item first, then it can be translated.' => 'Guarda primero la noticia; después se podrá traducir.',
    'This version of the news item does not exist.' => 'Esta versión de la noticia no existe.',
    'The news item will be checked again within a few minutes.' => 'La noticia se volverá a comprobar en unos minutos.',
    'Categories' => 'Categorías',
    'The category does not exist.' => 'La categoría no existe.',
    'Category saved.' => 'Categoría guardada.',
    'The category cannot be deleted while it contains news items (including those in the trash). Move them elsewhere first.' => 'No se puede eliminar la categoría mientras contenga noticias (incluidas las de la papelera). Muévelas primero a otra.',
    'Category deleted.' => 'Categoría eliminada.',
    'Fill in the category name.' => 'Rellena el nombre de la categoría.',
    'Site appearance' => 'Apariencia del sitio',
    'The site appearance has been saved.' => 'La apariencia del sitio se ha guardado.',
    'Does not write news' => 'No escribe noticias',
    'Writes, edits and publishes news by all authors' => 'Escribe, edita y publica noticias de todos los autores',
    'Writes and edits their own news; an editor publishes it' => 'Escribe y edita sus propias noticias; un editor las publica',
    'The user has been deleted. Their news items remain, without an author.' => 'El usuario se ha eliminado. Sus noticias se mantienen, sin autor.',
    'The build is not valid JSON.' => 'El diseño no es un JSON válido.',
    'There is nothing to publish.' => 'No hay nada que publicar.',
    'The section is not in the library.' => 'La sección no está en la biblioteca.',
    'Class name: lowercase letters without accents, digits and hyphens (e.g. card, card--highlighted).' => 'Nombre de clase: letras minúsculas sin acentos, dígitos y guiones (p. ej. card, card--highlighted).',
    'Declaration not allowed: %s' => 'Declaración no permitida: %s',
    'The version does not exist.' => 'La versión no existe.',
    '/new-address or https://…' => '/nueva-direccion o https://…',
    'A redirect is only used when nothing exists at the old address. It is created automatically when the address of a page, news item or category changes.' => 'Una redirección solo se usa cuando no existe nada en la dirección antigua. Se crea automáticamente cuando cambia la dirección de una página, noticia o categoría.',
    'Nothing to do – when you change the address of a page or news item, a redirect is created automatically.' => 'Nada que hacer – cuando cambias la dirección de una página o noticia, se crea una redirección automáticamente.',
    'Addresses visitors could not find (404)' => 'Direcciones que los visitantes no encontraron (404)',
    'Write a news item' => 'Escribir una noticia',
    'Images used in the news item “%s”.' => 'Imágenes usadas en la noticia “%s”.',
    'Upload your first photos with the form above – or drag them straight into the text in the editor.' => 'Sube tus primeras fotos con el formulario de arriba – o arrástralas directamente al texto en el editor.',
    'Really delete the selected files? Files the site still uses are skipped.' => '¿Seguro que quieres eliminar los archivos seleccionados? Se omitirán los archivos que el sitio aún usa.',
    'Image credit' => 'Crédito de la imagen',
    'Scheduled news is published and dates are shown according to it. It is now %s.' => 'Las noticias programadas se publican y las fechas se muestran según esta zona. Ahora son las %s.',
    'The site texts (Search, News, Read more…) are in this language, and the site declares it to search engines.' => 'Los textos del sitio (Buscar, Noticias, Leer más…) están en este idioma, y el sitio lo declara a los buscadores.',
    'Each version has its own pages, categories and news. A news item\'s language is set by its category. Link translations in the editor.' => 'Cada versión tiene sus propias páginas, categorías y noticias. El idioma de una noticia lo determina su categoría. Enlaza las traducciones en el editor.',
    'Home page and news' => 'Página de inicio y noticias',
    'Site home page' => 'Página de inicio del sitio',
    '– news list –' => '– lista de noticias –',
    'The page shown at the site address. News is always at %s.' => 'La página que se muestra en la dirección del sitio. Las noticias están siempre en %s.',
    'The site sends password reset links and system notifications, and enquiries from forms. With your own SMTP server, messages go out from a verified mailbox and do not end up in spam.' => 'El sitio envía enlaces para restablecer la contraseña, notificaciones del sistema y consultas de los formularios. Con tu propio servidor SMTP, los mensajes salen de un buzón verificado y no acaban en spam.',
    'Send a test e-mail to the site address' => 'Enviar un correo de prueba a la dirección del sitio',
    'Scheduled news, notifications and outgoing mail run on site visits. A low-traffic site makes them more precise by calling this address every 5 minutes from your hosting\'s cron:' => 'Las noticias programadas, las notificaciones y el correo saliente se ejecutan con las visitas al sitio. Un sitio con poco tráfico los hace más precisos llamando a esta dirección cada 5 minutos desde el cron de tu hosting:',
    'Restore the database from this backup? Everything added to the site since it was created (pages, news, enquiries, settings) will be lost. The current state is saved to a new backup first.' => '¿Restaurar la base de datos desde esta copia de seguridad? Se perderá todo lo añadido al sitio desde que se creó (páginas, noticias, consultas, ajustes). Antes, el estado actual se guarda en una nueva copia de seguridad.',
    'The database backup contains pages, news, settings and users; uploaded images are in the media backup. Backups are stored in the backups folder storage/zalohy/, which is not accessible from the web – download copies off the server too.' => 'La copia de seguridad de la base de datos contiene páginas, noticias, ajustes y usuarios; las imágenes subidas están en la copia de seguridad de medios. Las copias se guardan en la carpeta storage/zalohy/, que no es accesible desde la web – descarga también copias fuera del servidor.',
    'Language' => 'Idioma',
    'unpublished changes' => 'cambios sin publicar',
    'Category name' => 'Nombre de la categoría',
    'The part of the address after %s.' => 'La parte de la dirección después de %s.',
    'Shown above the category\'s news list and used as the description for search engines.' => 'Se muestra encima de la lista de noticias de la categoría y se usa como descripción para los buscadores.',
    'Higher number = higher in the list.' => 'Número más alto = más arriba en la lista.',
    'News in this category belongs to this language version of the site.' => 'Las noticias de esta categoría pertenecen a esta versión de idioma del sitio.',
    'New category' => 'Nueva categoría',
    'Back to news' => 'Volver a noticias',
    'No category has been created yet.' => 'Aún no se ha creado ninguna categoría.',
    'Every news item belongs to one category – without it, the news item cannot be saved.' => 'Cada noticia pertenece a una categoría – sin ella, la noticia no se puede guardar.',
    'Create the first category' => 'Crear la primera categoría',
    'News items' => 'Noticias',
    'Really delete the category?' => '¿Seguro que quieres eliminar la categoría?',
    'Open the builder' => 'Abrir el builder',
    'This page\'s content is built in the builder.' => 'El contenido de esta página se crea en el builder.',
    'Want to build the page from sections, columns and buttons?' => '¿Quieres crear la página con secciones, columnas y botones?',
    'Open in the builder' => 'Abrir en el builder',
    'Search engines and sharing' => 'Buscadores y redes sociales',
    'empty = page name' => 'vacío = nombre de la página',
    'One or two sentences on what visitors will find on the page (up to 160 characters).' => 'Una o dos frases sobre lo que los visitantes encontrarán en la página (hasta 160 caracteres).',
    'empty = default image from Settings' => 'vacío = imagen predeterminada de Ajustes',
    'Shown when the link is shared on Facebook, LinkedIn or Teams (ideally 1200 × 630 px).' => 'Se muestra cuando se comparte el enlace en Facebook, LinkedIn o Teams (idealmente 1200 × 630 px).',
    'site home page' => 'página de inicio del sitio',
    'Show in the site\'s main navigation' => 'Mostrar en la navegación principal del sitio',
    'Save and open in the builder' => 'Guardar y abrir en el builder',
    'Duplicate page' => 'Duplicar página',
    'Return the page to plain text? The build stays in versions and you can go back to it.' => '¿Devolver la página a texto simple? El diseño se queda en las versiones y puedes volver a él.',
    'Return page to text' => 'Devolver la página a texto',
    'The builder needs JavaScript. The page content can also be edited without it in the page form.' => 'El builder necesita JavaScript. El contenido de la página también se puede editar sin él en el formulario de la página.',
    'Name or address contains:' => 'El nombre o la dirección contiene:',
    'Deleted pages stay here for 30 days, then they are deleted permanently.' => 'Las páginas eliminadas permanecen aquí 30 días; después se eliminan definitivamente.',
    'Back to pages' => 'Volver a páginas',
    'No page matches the search.' => 'Ninguna página coincide con la búsqueda.',
    'Try another word.' => 'Prueba con otra palabra.',
    'Clear search' => 'Borrar búsqueda',
    'A business website usually consists of Home, About us, Services and Contact.' => 'Un sitio web de empresa suele constar de Inicio, Quiénes somos, Servicios y Contacto.',
    'Pages in the trash are not on the site. A restored page comes back hidden; after 30 days it is permanently deleted from the trash.' => 'Las páginas de la papelera no están en el sitio. Una página restaurada vuelve oculta; después de 30 días se elimina definitivamente de la papelera.',
    'Delete the page permanently? This cannot be undone.' => '¿Eliminar la página definitivamente? No se puede deshacer.',
    'home' => 'inicio',
    'The builder has changes that are not on the site yet.' => 'El builder tiene cambios que aún no están en el sitio.',
    'The builder has work-in-progress changes that are not on the site yet.' => 'El builder tiene cambios en curso que aún no están en el sitio.',
    'You are building this page in the builder. The site still shows the text below – once you publish in the builder, the build replaces it.' => 'Estás creando esta página en el builder. El sitio sigue mostrando el texto de abajo – cuando publiques en el builder, el diseño lo sustituirá.',
    'Preview hidden page' => 'Vista previa de la página oculta',
    'Duplicate' => 'Duplicar',
    'Move the page to the trash? It disappears from the site; you can restore it for 30 days.' => '¿Mover la página a la papelera? Desaparecerá del sitio; puedes restaurarla durante 30 días.',
    'Most read news' => 'Noticias más leídas',
    'Where visitors come from' => 'De dónde vienen los visitantes',
    'You cannot remove administrator rights from your own account.' => 'No puedes quitar los permisos de administrador de tu propia cuenta.',
    'Really delete the user? Their news items will remain, without an author.' => '¿Seguro que quieres eliminar el usuario? Sus noticias se mantendrán, sin autor.',
    'Categories (those with posts are created)' => 'Categorías (se crean las que tienen entradas)',
    'User accounts and passwords – the news items will belong to you. Comments are not transferred.' => 'Cuentas de usuario y contraseñas – las noticias pasarán a ser tuyas. Los comentarios no se transfieren.',
    'Menus, widgets, appearance and plugin settings – you will rebuild the navigation on the new site.' => 'Menús, widgets, apariencia y ajustes de plugins – reconstruirás la navegación en el nuevo sitio.',
    'Which language version of the site the new categories and pages belong to.' => 'A qué versión de idioma del sitio pertenecen las nuevas categorías y páginas.',
    'Put posts without a category into' => 'Colocar las entradas sin categoría en',
    'a new “Uncategorised” category' => 'una nueva categoría “Sin categoría”',
    'Imported news is not announced: no webhook or IndexNow. Before a larger import, create a database backup in Settings → Backups and updates.' => 'Las noticias importadas no se anuncian: ni webhook ni IndexNow. Antes de una importación grande, crea una copia de seguridad de la base de datos en Ajustes → Copias de seguridad y actualizaciones.',
    'Downloading images from the old site: %s of %s news items and pages done, %s images downloaded. Keep this page open, I will continue automatically.' => 'Descargando imágenes del sitio antiguo: %s de %s noticias y páginas listas, %s imágenes descargadas. Mantén esta página abierta, continuaré automáticamente.',
    'New news items' => 'Noticias nuevas',
    'New categories' => 'Categorías nuevas',
    'Show news' => 'Ver noticias',
    'News and pages still show images from the old site. Downloading saves the main news images and images in texts to Media (resized, with thumbnails and WebP) and rewrites the links in the texts. Images are downloaded only from the domain %s, and the old site must still be available.' => 'Las noticias y páginas aún muestran imágenes del sitio antiguo. La descarga guarda las imágenes principales de las noticias y las imágenes de los textos en Medios (redimensionadas, con miniaturas y WebP) y reescribe los enlaces en los textos. Las imágenes solo se descargan del dominio %s, y el sitio antiguo aún debe estar disponible.',
    'In WordPress, open Tools → Export, choose “All content” and download the .xml file. Then upload it here. Pages, posts (as news), categories and tags are converted and redirects from the old addresses are created; nothing changes on the site until you confirm the import in the next step.' => 'En WordPress, abre Herramientas → Exportar, elige “Todo el contenido” y descarga el archivo .xml. Luego súbelo aquí. Las páginas, entradas (como noticias), categorías y etiquetas se convierten y se crean redirecciones desde las direcciones antiguas; nada cambia en el sitio hasta que confirmes la importación en el siguiente paso.',
    'One archive gives you the whole site in an open format (JSON): pages, news, categories, tags, redirects, menus, collections, pop-ups, site parts, components, shared classes and uploaded files – as a content backup or for moving elsewhere. Enquiries, passwords, keys and accounts are not included.' => 'Un solo archivo te da todo el sitio en un formato abierto (JSON): páginas, noticias, categorías, etiquetas, redirecciones, menús, colecciones, pop-ups, partes del sitio, componentes, clases compartidas y archivos subidos – como copia de seguridad del contenido o para trasladarlo a otro lugar. No se incluyen consultas, contraseñas, claves ni cuentas.',
    'Back to the news list' => 'Volver a la lista de noticias',
    'Shown in lists and at the start of the news item – do not repeat it in the text.' => 'Se muestra en las listas y al principio de la noticia – no lo repitas en el texto.',
    'To embed a video, put its address (YouTube, Vimeo) on a line of its own. It loads for the visitor only after a click.' => 'Para insertar un vídeo, pon su dirección (YouTube, Vimeo) en una línea aparte. Se carga para el visitante solo después de un clic.',
    'Draft' => 'Borrador',
    'An editor or site administrator publishes the news item.' => 'Un editor o el administrador del sitio publica la noticia.',
    'A future date = the news item is published automatically at that time.' => 'Una fecha futura = la noticia se publica automáticamente en ese momento.',
    'Mark as updated (with today\'s date)' => 'Marcar como actualizada (con la fecha de hoy)',
    'Comma-separated. Visitors can use a tag to see related news.' => 'Separadas por comas. Los visitantes pueden usar una etiqueta para ver noticias relacionadas.',
    'Image caption' => 'Pie de imagen',
    'Empty field = caption and credit from the Media library.' => 'Campo vacío = pie y crédito de la biblioteca de medios.',
    'Translation' => 'Traducción',
    'Language versions' => 'Versiones de idioma',
    'Translate the saved version with the assistant? A draft is created for you to read before publishing. Translation can take up to a minute.' => '¿Traducir la versión guardada con el asistente? Se crea un borrador para que lo leas antes de publicarlo. La traducción puede tardar hasta un minuto.',
    'address or number of the original news item' => 'dirección o número de la noticia original',
    'Fill in only for a news item in another language version (the category sets the language).' => 'Rellénalo solo para una noticia de otra versión de idioma (la categoría determina el idioma).',
    'SEO and more settings' => 'SEO y más ajustes',
    'The part of the address after %s. If you change it after publishing, the old address redirects automatically.' => 'La parte de la dirección después de %s. Si la cambias después de publicar, la dirección antigua redirige automáticamente.',
    'empty = news item title' => 'vacío = título de la noticia',
    'Question on one line, the answer below it, an empty line between pairs. Shown below the text and in structured data (FAQ).' => 'La pregunta en una línea, la respuesta debajo, una línea vacía entre pares. Se muestra debajo del texto y en los datos estructurados (FAQ).',
    'In the background, the system goes through published news – one every five minutes, each once a month – and checks whether its links still work. News items checked: %s of %s.' => 'En segundo plano, el sistema recorre las noticias publicadas – una cada cinco minutos, cada una una vez al mes – y comprueba si sus enlaces siguen funcionando. Noticias comprobadas: %s de %s.',
    'New news item' => 'Nueva noticia',
    'News status' => 'Estado de la noticia',
    'Category:' => 'Categoría:',
    'Total:' => 'Total:',
    'Deleted news items stay here for 30 days, then they are deleted permanently.' => 'Las noticias eliminadas permanecen aquí 30 días; después se eliminan definitivamente.',
    'No news item matches the filter.' => 'Ninguna noticia coincide con el filtro.',
    'Try another word, category or status.' => 'Prueba con otra palabra, categoría o estado.',
    'There are no news items yet.' => 'Aún no hay noticias.',
    'Until you publish a news item, it stays a draft that nobody sees on the site.' => 'Hasta que publiques una noticia, sigue siendo un borrador que nadie ve en el sitio.',
    'Write the first news item' => 'Escribir la primera noticia',
    'News items in the trash are not on the site. A restored news item comes back as a draft; after 30 days it is permanently deleted from the trash.' => 'Las noticias de la papelera no están en el sitio. Una noticia restaurada vuelve como borrador; después de 30 días se elimina definitivamente de la papelera.',
    'Delete the selected news items permanently? This cannot be undone.' => '¿Eliminar definitivamente las noticias seleccionadas? No se puede deshacer.',
    'Back to the news item' => 'Volver a la noticia',
    'Tags are created automatically as you write news. When you add a description to a tag, its page becomes a topic – an introduction to a field or project with all its news in one place.' => 'Las etiquetas se crean automáticamente al escribir noticias. Cuando añades una descripción a una etiqueta, su página se convierte en un tema – una introducción a un ámbito o proyecto con todas sus noticias en un solo lugar.',
    'Optional. Shown above the news list and as the description for search engines.' => 'Opcional. Se muestra encima de la lista de noticias y como descripción para los buscadores.',
    'The news items get the selected tag, this one is removed and its address redirects. Useful for typos and duplicate spellings.' => 'Las noticias reciben la etiqueta seleccionada, esta se elimina y su dirección redirige. Útil para erratas y grafías duplicadas.',
    'Add them in the news editor in the Tags field. Here you can then merge them and turn them into topic pages.' => 'Añádelas en el editor de noticias, en el campo Etiquetas. Aquí podrás después fusionarlas y convertirlas en páginas temáticas.',
    'Delete the tag? The news items stay, they just lose this tag.' => '¿Eliminar la etiqueta? Las noticias se mantienen, solo pierden esta etiqueta.',
    'Changed by an administrator in Users.' => 'Lo cambia un administrador en Usuarios.',
    'Shown with news items on the site.' => 'Se muestra con las noticias en el sitio.',
    'Position in the company' => 'Cargo en la empresa',
    'e.g. head of sales' => 'p. ej. jefe de ventas',
    'Shown as a short profile under your news items. What you do in the company and your background.' => 'Se muestra como un breve perfil bajo tus noticias. Lo que haces en la empresa y tu trayectoria.',
    'Colours' => 'Colores',
    'Shades (muted text, lines, soft primary colour) and the button text colour are derived automatically.' => 'Los tonos (texto atenuado, líneas, color principal suave) y el color del texto de los botones se derivan automáticamente.',
    'Readability' => 'Legibilidad',
    'according to the visitor\'s device' => 'según el dispositivo del visitante',
    'Check your logo: a dark logo on a transparent background would disappear on a dark site.' => 'Revisa tu logotipo: un logotipo oscuro sobre fondo transparente desaparecería en un sitio oscuro.',
    'Sizes' => 'Tamaños',
    'Type and spacing grow smoothly with the window width – from phone to large monitor. Headings are multiples of the base font size.' => 'El texto y los espacios crecen de forma fluida con el ancho de la ventana – del móvil al monitor grande. Los títulos son múltiplos del tamaño de fuente base.',
    'Base font size on phones' => 'Tamaño de fuente base en móviles',
    'Base font size on monitors' => 'Tamaño de fuente base en monitores',
    'Text width (news and text pages)' => 'Ancho del texto (noticias y páginas de texto)',
    'Logo and icon' => 'Logotipo e icono',
