    'Reveal on scroll' => 'Mostrar al desplazar',
    'Remove the section “%s” from my sections? It stays on pages where it is already used.' => '¿Quitar la sección “%s” de mis secciones? Se mantiene en las páginas donde ya se usa.',
    'Remove from my sections' => 'Quitar de mis secciones',
    'Used in: ' => 'Se usa en: ',
    'The section is in the Add panel → My sections.' => 'La sección está en el panel Añadir → Mis secciones.',
    'The section appears in the Add panel → My sections. Each insert is a separate copy; if it should be the same everywhere, save it as a component.' => 'La sección aparece en el panel Añadir → Mis secciones. Cada inserción es una copia independiente; si debe ser igual en todas partes, guárdala como componente.',
    'Hide in the editor only (stays on the site)' => 'Ocultar solo en el editor (se mantiene en el sitio)',
    'Element state' => 'Estado del elemento',
    'Press' => 'Pulsación',
    'The class is not used in any published or draft build yet.' => 'La clase aún no se usa en ningún diseño publicado ni en borrador.',
    'Save to my sections' => 'Guardar en mis secciones',
