    'Custom CSS and attributes' => 'CSS y atributos personalizados',
    'Outer margin left' => 'Margen exterior izquierdo',
    'Outer margin right' => 'Margen exterior derecho',
    'Lock: cannot be selected or moved on the canvas' => 'Bloquear: no se puede seleccionar ni mover en el lienzo',
    'Checking where the class is used…' => 'Comprobando dónde se usa la clase…',
    'primary → secondary' => 'principal → secundario',
    'soft from the top' => 'suave desde arriba',
    'hover and focus' => 'hover y foco',
    'background → surface' => 'fondo → superficie',
    'press' => 'pulsación',
    'slide up' => 'deslizar hacia arriba',
    'darken at the bottom (over a photo)' => 'oscurecer abajo (sobre una foto)',
    'glow in the corner' => 'brillo en la esquina',
    'Nothing like that here.' => 'Aquí no hay nada parecido.',
    'The section needs a name.' => 'La sección necesita un nombre.',
    'The element could not be saved.' => 'No se pudo guardar el elemento.',
    'Only an administrator can remove sections.' => 'Solo un administrador puede quitar secciones.',
    'section saved to library' => 'sección guardada en la biblioteca',
    'The copy of the news item is saved as a draft.' => 'La copia de la noticia se ha guardado como borrador.',
    'The copy of the item is hidden – edit it and publish it.' => 'La copia del elemento está oculta – edítala y publícala.',
    'Roles' => 'Roles',
    'Edit role' => 'Editar rol',
    'New role' => 'Nuevo rol',
    'The role does not exist.' => 'El rol no existe.',
    'Fill in the role name.' => 'Rellena el nombre del rol.',
    'A role with this name already exists.' => 'Ya existe un rol con este nombre.',
    'Select at least one section.' => 'Selecciona al menos una sección.',
    'The role has been saved.' => 'El rol se ha guardado.',
    'The role has been deleted. Its members kept their current access.' => 'El rol se ha eliminado. Sus miembros conservan su acceso actual.',
    'Writes own content' => 'Escribe contenido propio',
    'Only own news and without publishing – an editor publishes.' => 'Solo noticias propias y sin publicar – un editor las publica.',
    'Manages everyone\'s content' => 'Gestiona el contenido de todos',
    'Edits and publishes news by all authors.' => 'Edita y publica noticias de todos los autores.',
    'Back to users' => 'Volver a usuarios',
    'The built-in roles News author, Editor and Administrator are enough for most websites. A custom role is useful when someone should see only part of the administration – for example a salesperson only Enquiries.' => 'Los roles integrados Autor de noticias, Editor y Administrador bastan para la mayoría de los sitios web. Un rol personalizado es útil cuando alguien debe ver solo una parte de la administración – por ejemplo, un comercial solo Consultas.',
    'No custom roles yet.' => 'Aún no hay roles personalizados.',
    'Delete the role? Its members will keep their current access.' => '¿Eliminar el rol? Sus miembros conservarán su acceso actual.',
    'Back to roles' => 'Volver a roles',
    'Role name' => 'Nombre del rol',
    'e.g. Salesperson' => 'p. ej. Comercial',
    'Website settings, users and appearance stay with the administrator.' => 'Los ajustes del sitio web, los usuarios y la apariencia quedan en manos del administrador.',
    'Saving also changes the permissions of these users:' => 'Al guardar también cambian los permisos de estos usuarios:',
    'Custom role' => 'Rol personalizado',
    'a named set of sections, for example only Enquiries for a salesperson.' => 'un conjunto de secciones con nombre, por ejemplo solo Consultas para un comercial.',
    'An author usually has only News, an editor all content sections, an administrator everything. With a custom role, the role\'s sections apply.' => 'Un autor suele tener solo Noticias, un editor todas las secciones de contenido y un administrador todo. Con un rol personalizado se aplican las secciones del rol.',
    'Tap the place on the page to move the element to (top or bottom part of an element = before or after, middle of a container = inside). Esc cancels.' => 'Toca el lugar de la página al que quieres mover el elemento (parte superior o inferior de un elemento = antes o después, centro de un contenedor = dentro). Esc cancela.',
    'Drag or tap to move' => 'Arrastra o toca para mover',
    'Move by tapping the target (works on touch screens too)' => 'Mover tocando el destino (también funciona en pantallas táctiles)',
    'Compose your own' => 'Crear el tuyo',
    'Strength' => 'Intensidad',
    'Inset' => 'Interior',
    'Blur' => 'Desenfoque',
    'Spread' => 'Expansión',
    'Area' => 'Área',
    'fit to space' => 'ajustar al espacio',
    'Rows' => 'Filas',
    'Remove row' => 'Quitar fila',
    'Add row' => 'Añadir fila',
    'Type area names into the cells (the same name across several cells = the element spans them). Then give the nested element its “Grid area”.' => 'Escribe los nombres de las áreas en las celdas (el mismo nombre en varias celdas = el elemento las abarca). Luego asigna al elemento anidado su “Área de la cuadrícula”.',
    'Grid rows' => 'Filas de la cuadrícula',
    'Grid areas' => 'Áreas de la cuadrícula',
