    'Smooth change (on hover)' => 'Cambio suave (al pasar el ratón)',
    'Typography styles' => 'Estilos tipográficos',
    'Named text styles you pick for an element in the builder (Style → Typography). A change here applies everywhere the style is used.' => 'Estilos de texto con nombre que eliges para un elemento en el builder (Estilo → Tipografía). Un cambio aquí se aplica en todos los lugares donde se usa el estilo.',
    'Size (scale step)' => 'Tamaño (paso de la escala)',
    'Weight' => 'Grosor',
    '0 – base font' => '0 – fuente base',
    'Size: %s' => 'Tamaño: %s',
    'Weight: %s' => 'Grosor: %s',
    'largest files' => 'archivos más grandes',
