    'Search name, description or file' => 'Buscar nombre, descripción o archivo',
    'Search media' => 'Buscar en medios',
    'Description of image %s' => 'Descripción de la imagen %s',
    'You cannot edit this image.' => 'No puedes editar esta imagen.',
    'Design tokens (Figma, Tokens Studio)' => 'Tokens de diseño (Figma, Tokens Studio)',
    'Colours, fonts, sizes and typography styles in the W3C Design Tokens format (DTCG). A Kaleta export can be loaded back in full; from another tool the colours are taken.' => 'Colores, fuentes, tamaños y estilos tipográficos en el formato W3C Design Tokens (DTCG). Una exportación de Kaleta se puede volver a cargar completa; de otra herramienta se toman los colores.',
    'Download tokens (.tokens.json)' => 'Descargar tokens (.tokens.json)',
    'Load tokens? They will overwrite the appearance settings above.' => '¿Cargar los tokens? Sobrescribirán los ajustes de apariencia de arriba.',
    'Tokens file' => 'Archivo de tokens',
    'Load tokens' => 'Cargar tokens',
    'The file contains no usable design tokens (a JSON file in the DTCG format is expected).' => 'El archivo no contiene tokens de diseño utilizables (se espera un archivo JSON en formato DTCG).',
    'Design tokens have been loaded.' => 'Los tokens de diseño se han cargado.',
    'The enquiry form collects personal data – visitors must know how you handle it. The page is prepared as a hidden draft: fill in the details in square brackets and publish it.' => 'El formulario de consultas recoge datos personales – los visitantes deben saber cómo los tratas. La página está preparada como borrador oculto: rellena los datos entre corchetes y publícala.',
    'Always-on core: Pages, Collections, Media, Site appearance, Site parts, Menu, Components, Pop-ups, Users and roles, Import and export, Change log and Settings.' => 'Núcleo siempre activo: Páginas, Colecciones, Medios, Apariencia del sitio, Partes del sitio, Menú, Componentes, Pop-ups, Usuarios y roles, Importación y exportación, Registro de cambios y Ajustes.',
    'In the Claude app you do not need a token: add a custom connector with the address %s and confirm access by signing in.' => 'En la app de Claude no necesitas token: añade un conector personalizado con la dirección %s y confirma el acceso iniciando sesión.',
    'Enquiries and retention' => 'Consultas y conservación',
    'Webhook to CRM' => 'Webhook al CRM',
    'Subscribers and export' => 'Suscriptores y exportación',
    'Choose languages' => 'Elegir idiomas',
    'Provider, key and model' => 'Proveedor, clave y modelo',
    'How to connect Claude' => 'Cómo conectar Claude',
    'Links for a feature appear once it is switched on and saved.' => 'Los enlaces de una función aparecen cuando se activa y se guarda.',
    'Claude connection – how to connect' => 'Conexión con Claude – cómo conectar',
    'In the Claude app open Settings → Connectors → Add custom connector.' => 'En la app de Claude, abre Ajustes → Conectores → Añadir conector personalizado.',
    'Enter this address:' => 'Introduce esta dirección:',
    'Claude sends you here to sign in and confirm access. It then works with your account\'s permissions – builds and news are saved as drafts.' => 'Claude te envía aquí para iniciar sesión y confirmar el acceso. Después trabaja con los permisos de tu cuenta – los diseños y las noticias se guardan como borradores.',
    'In Claude Code, just run:' => 'En Claude Code, basta con ejecutar:',
    'Connected applications and personal tokens for other tools are in' => 'Las aplicaciones conectadas y los tokens personales para otras herramientas están en',
    'The connector needs the site on HTTPS in the domain root.' => 'El conector necesita el sitio en HTTPS en la raíz del dominio.',
    'Administrator' => 'Administrador',
    'Published pages' => 'Páginas publicadas',
    'Pages with unpublished changes' => 'Páginas con cambios sin publicar',
    'Published news' => 'Noticias publicadas',
    'News drafts' => 'Borradores de noticias',
    'Logo, main colour and fonts.' => 'Logotipo, color principal y fuentes.',
    'Prepare your pages' => 'Prepara tus páginas',
    'About us, Services, Contact – and pick the home page in Settings.' => 'Quiénes somos, Servicios, Contacto – y elige la página de inicio en Ajustes.',
    'Complete the privacy policy' => 'Completa la política de privacidad',
    'Set up e-mail' => 'Configurar el correo',
    'Where the site sends e-mail from (forms, password reset).' => 'Desde dónde envía correos el sitio (formularios, restablecimiento de contraseña).',
    'Business' => 'Profesional',
    'Blue, sans-serif type, modest rounding' => 'Azul, tipografía sans serif, redondeo discreto',
    'Warm earthy colours, serif headings' => 'Colores tierra cálidos, títulos con serifa',
