    'Primary' => 'Principal',
    'Primary – soft' => 'Principal – suave',
    'Text on primary' => 'Texto sobre el principal',
    'Secondary' => 'Secundario',
    'Surface (cards, footer)' => 'Superficie (tarjetas, pie de página)',
    'Surface' => 'Superficie',
    'Muted text' => 'Texto atenuado',
    'White' => 'Blanco',
    'Black' => 'Negro',
    'Text on background' => 'Texto sobre el fondo',
    'Text on surface' => 'Texto sobre la superficie',
    'Link (primary colour) on background' => 'Enlace (color principal) sobre el fondo',
    'Button text on primary colour' => 'Texto de botón sobre el color principal',
    'Secondary colour on background' => 'Color secundario sobre el fondo',
    'subtle (1.125)' => 'sutil (1,125)',
    'calm (1.2)' => 'tranquila (1,2)',
    'balanced (1.25)' => 'equilibrada (1,25)',
    'strong (1.333)' => 'marcada (1,333)',
    'dramatic (1.414)' => 'dramática (1,414)',
    'poster (1.5)' => 'cartel (1,5)',
    'A wrapper around the news item – a call to action or more news below the text, for example.' => 'Un marco alrededor de la noticia – por ejemplo, una llamada a la acción o más noticias debajo del texto.',
    'Writes and edits their own news. An editor publishes them.' => 'Escribe y edita sus propias noticias. Un editor las publica.',
    'Manages all site content – pages, news, media – and publishes.' => 'Gestiona todo el contenido del sitio – páginas, noticias, medios – y publica.',
    '301 redirects from old addresses – essential after moving from another site.' => 'Redirecciones 301 desde direcciones antiguas – imprescindibles tras migrar desde otro sitio.',
    'A site in several languages: each further version (e.g. /cs/…) has its own pages, categories and news, a language switcher and hreflang tags. Pick the languages in Settings → General.' => 'Un sitio en varios idiomas: cada versión adicional (p. ej. /cs/…) tiene sus propias páginas, categorías y noticias, un selector de idioma y etiquetas hreflang. Elige los idiomas en Ajustes → General.',
    'An address from Make, Zapier, IFTTT or n8n. When a news item is published, the system sends it the title, lead, address and image – the service then shares it on Facebook, X, Mastodon, Slack and so on.' => 'Una dirección de Make, Zapier, IFTTT o n8n. Cuando se publica una noticia, el sistema le envía el título, la entradilla, la dirección y la imagen – el servicio la comparte luego en Facebook, X, Mastodon, Slack, etc.',
    'Recommended. Applies only to releases marked as security releases; you install regular versions yourself. The system checks for updates twice a day, backs up the database before installing and e-mails the result to the site e-mail.' => 'Recomendado. Se aplica solo a las versiones marcadas como de seguridad; las versiones normales las instalas tú. El sistema busca actualizaciones dos veces al día, hace una copia de seguridad de la base de datos antes de instalar y envía el resultado al correo del sitio.',
    'Finished pages are served to visitors from memory – the site is faster and copes with traffic peaks. Leave it on.' => 'Las páginas terminadas se sirven a los visitantes desde la memoria – el sitio es más rápido y soporta picos de tráfico. Déjalo activado.',
    'Every news item also as plain text without navigation – for language models and AI search engines.' => 'Cada noticia también como texto simple sin navegación – para modelos de lenguaje y buscadores con IA.',
    'In the background, one news item every five minutes. The result is in News → Broken links.' => 'En segundo plano, una noticia cada cinco minutos. El resultado está en Noticias → Enlaces rotos.',
    'For example https://www.example.com, without a trailing slash. Links in e-mails, RSS, the sitemap and notifications are built from it. Change it after moving to another domain.' => 'Por ejemplo https://www.example.com, sin barra final. A partir de ella se crean los enlaces de los correos, el RSS, el sitemap y las notificaciones. Cámbiala tras migrar a otro dominio.',
    'For example the registered company name and company ID.' => 'Por ejemplo, la razón social y el NIF de la empresa.',
    'News items per page' => 'Noticias por página',
    'Visitors see only the notice below. Signed-in users see the site as usual.' => 'Los visitantes solo ven el aviso de abajo. Los usuarios con sesión iniciada ven el sitio como siempre.',
    'Visits, most-read news and traffic sources under Statistics. No cookies and no consent needed.' => 'Visitas, noticias más leídas y fuentes de tráfico en Estadísticas. Sin cookies ni consentimiento.',
    'News table of contents from subheadings' => 'Índice de la noticia a partir de los subtítulos',
    'Share links below the news item' => 'Enlaces para compartir bajo la noticia',
    'Notify search engines about new news (IndexNow)' => 'Avisar a los buscadores de las noticias nuevas (IndexNow)',
    'Similar news by tags and category is offered below a news item.' => 'Bajo una noticia se ofrecen noticias similares por etiquetas y categoría.',
    'Empty = the site e-mail. With SMTP it must be an address your mailbox is allowed to send from.' => 'Vacío = el correo del sitio. Con SMTP debe ser una dirección desde la que tu buzón pueda enviar.',
    'Related news' => 'Noticias relacionadas',
    'News items with at least three subheadings get a clickable outline above the text.' => 'Las noticias con al menos tres subtítulos reciben un índice clicable encima del texto.',
    'Webhook after publishing news' => 'Webhook tras publicar una noticia',
    'Plain-text news (.md)' => 'Noticias en texto simple (.md)',
    'Bodoni, Didot – elegance and fashion' => 'Bodoni, Didot – elegancia y moda',
    'Helvetica, Arial – strong and confident' => 'Helvetica, Arial – sólida y segura',
    'friendly, for services and family businesses' => 'cercana, para servicios y negocios familiares',
    'technology and development' => 'tecnología y desarrollo',
    'write and edit pages and news, and manage categories, collections and the look of the site.' => 'escribir y editar páginas y noticias, y gestionar categorías, colecciones y la apariencia del sitio.',
    'write and edit news.' => 'escribir y editar noticias.',
    'no icon' => 'sin icono',
    'Icon left of the text' => 'Icono a la izquierda del texto',
    'Current item highlight' => 'Resaltado del elemento actual',
    'underline in the secondary colour' => 'subrayado en el color secundario',
    'Site email' => 'Correo del sitio',
    'Public email' => 'Correo público',
    'With the country code, e.g. +44 20 7946 0958.' => 'Con el prefijo del país, p. ej. +44 20 7946 0958.',
    'Contact for visitors and search engines. The site email from the General tab (where enquiries are sent) is not shown on the site.' => 'Contacto para visitantes y buscadores. El correo del sitio de la pestaña General (adonde se envían las consultas) no se muestra en el sitio.',
    'Keep consent records (months)' => 'Conservar registros de consentimiento (meses)',
    'Older records are deleted automatically. 0 = keep.' => 'Los registros más antiguos se eliminan automáticamente. 0 = conservar.',
    'Headings on phones' => 'Títulos en móviles',
    'Headings on monitors' => 'Títulos en monitores',
    'News author' => 'Autor de noticias',
    'builder' => 'builder',
    'News item saved. It will appear on the site once an editor publishes it.' => 'Noticia guardada. Aparecerá en el sitio cuando un editor la publique.',
    '%s:1' => '%s:1',
    'Account and tools' => 'Cuenta y herramientas',
    'News items need a category, so the category “%s” has been created. You can rename it or add more under News → Categories.' => 'Las noticias necesitan una categoría, por eso se ha creado la categoría “%s”. Puedes cambiarle el nombre o añadir más en Noticias → Categorías.',
    'The file is larger than the server allows (%s at most). Make it smaller or ask your hosting provider to raise the limit.' => 'El archivo supera el tamaño que permite el servidor (%s como máximo). Redúcelo o pide a tu proveedor de hosting que aumente el límite.',
    'Awaiting publication' => 'Pendiente de publicación',
    'awaiting publication' => 'pendiente de publicación',
    'News authors cannot publish – review this news item and publish it.' => 'Los autores de noticias no pueden publicar – revisa esta noticia y publícala.',
    'News from authors awaiting publication' => 'Noticias de autores pendientes de publicación',
    'In your authenticator app (Google Authenticator, Microsoft Authenticator, 1Password, Aegis…) add a new account by scanning the QR code:' => 'En tu app de autenticación (Google Authenticator, Microsoft Authenticator, 1Password, Aegis…) añade una cuenta nueva escaneando el código QR:',
    'QR code for the authenticator app' => 'Código QR para la app de autenticación',
    'Cannot scan it? Add the account by typing the key:' => '¿No puedes escanearlo? Añade la cuenta escribiendo la clave:',
    'page “%s”' => 'página “%s”',
    'collection detail “%s”' => 'detalle de la colección “%s”',
    'component “%s”' => 'componente “%s”',
    'The component “%s” is used on: %s. Deleting it leaves an empty space there. Delete it anyway?' => 'El componente “%s” se usa en: %s. Si lo eliminas, quedará un espacio vacío allí. ¿Eliminarlo de todos modos?',
    'and %d more' => 'y %d más',
    'Add a description for blind visitors (alt text) to the images: what the image shows.' => 'Añade a las imágenes una descripción para visitantes ciegos (texto alternativo): qué muestra la imagen.',
    'The database update failed: %s. The site keeps running; install the fix in Settings → Backups and updates, or write to info@kaletacms.com.' => 'La actualización de la base de datos ha fallado: %s. El sitio sigue funcionando; instala la corrección en Ajustes → Copias de seguridad y actualizaciones, o escribe a info@kaletacms.com.',
    'Border colour' => 'Color del borde',
    'preview shared' => 'vista previa compartida',
    'Kaleta is free and has no ads.' => 'Kaleta es gratuito y no tiene anuncios.',
    'Support its development on GitHub Sponsors' => 'Apoya su desarrollo en GitHub Sponsors',
    'Support Kaleta' => 'Apoyar Kaleta',
    'Imprint (all details of the operator)' => 'Aviso legal (todos los datos del operador)',
    'Imprint (legal notice)' => 'Aviso legal (Impressum)',
    'Company identification number; in other countries its registration number.' => 'Número de identificación de la empresa; en otros países, su número de registro.',
    'Register court and entry, e.g. “Amtsgericht München, HRB 12345” or “Companies House, 01234567”. For the imprint.' => 'Tribunal de registro e inscripción, p. ej. “Amtsgericht München, HRB 12345” o “Companies House, 01234567”. Para el aviso legal.',
    'Who represents the company, e.g. “Managing director: Jane Smith” (Geschäftsführer). For the imprint.' => 'Quién representa a la empresa, p. ej. “Director general: Jane Smith” (Geschäftsführer). Para el aviso legal.',
    'Texts for visitors (Search, Read more…) are translated into: %s. Other languages show them in English, with dates in their own format. You write the content of pages and news in the language of the version.' => 'Los textos para visitantes (Buscar, Leer más…) están traducidos a: %s. Otros idiomas los muestran en inglés, con las fechas en su propio formato. El contenido de páginas y noticias lo escribes en el idioma de la versión.',
    '%s: %s visits' => '%s: %s visitas',
    'always dark' => 'siempre oscuro',
    'Switcher for visitors – in the header they choose light, dark or matching their device (the choice is remembered in their browser)' => 'Selector para visitantes – en el encabezado eligen claro, oscuro o según su dispositivo (la elección se recuerda en su navegador)',
    'Only items with the value (on an item page also {{field}} – related content)' => 'Solo elementos con el valor (en la página de un elemento también {{field}} – contenido relacionado)',
    'Leave out the item being shown (related content on an item page)' => 'Omitir el elemento mostrado (contenido relacionado en la página de un elemento)',
    'Another window already uses the address “%s”.' => 'Otra ventana ya usa la dirección “%s”.',
    'Pop-ups' => 'Pop-ups',
    'The pop-up does not exist.' => 'El pop-up no existe.',
    'The pop-up needs a name.' => 'El pop-up necesita un nombre.',
    'The pop-up settings were saved.' => 'Los ajustes del pop-up se han guardado.',
    'Publish the pop-up in the builder first – then you can turn it on.' => 'Publica primero el pop-up en el builder – después podrás activarlo.',
    'The pop-up counters were reset.' => 'Los contadores del pop-up se han restablecido.',
    'The pop-up was deleted.' => 'El pop-up se ha eliminado.',
    'The pop-up is off – it no longer shows on the site.' => 'El pop-up está desactivado – ya no se muestra en el sitio.',
    'The pop-up is on and shows on the site according to its rules.' => 'El pop-up está activado y se muestra en el sitio según sus reglas.',
    'New pop-up' => 'Nuevo pop-up',
    'No pop-ups yet.' => 'Aún no hay pop-ups.',
    'A window over the page for a newsletter sign-up, a download, an announcement or an offer. You build the content in the builder and set when and where it shows. The counters work without cookies.' => 'Una ventana sobre la página para suscribirse a un boletín, una descarga, un anuncio o una oferta. Creas el contenido en el builder y defines cuándo y dónde se muestra. Los contadores funcionan sin cookies.',
    'Create a pop-up' => 'Crear un pop-up',
    'Pop-up' => 'Pop-up',
    'When it shows' => 'Cuándo se muestra',
    'Views' => 'Visualizaciones',
    'Closes' => 'Cierres',
    'Language switcher' => 'Selector de idioma',
    'Choose the language version of the site – a row of codes or a dropdown (for example in the footer).' => 'Elegir la versión de idioma del sitio – una fila de códigos o un desplegable (por ejemplo, en el pie de página).',
    'dropdown' => 'desplegable',
    'codes in a row' => 'códigos en fila',
    'The dropdown opens' => 'El desplegable se abre',
    'upwards (footer)' => 'hacia arriba (pie de página)',
    'downwards (header)' => 'hacia abajo (encabezado)',
    'Language switcher (turn it off when it is elsewhere, for example in the footer)' => 'Selector de idioma (desactívalo cuando esté en otro lugar, por ejemplo en el pie de página)',
    'All pop-ups' => 'Todos los pop-ups',
    'Conversions' => 'Conversiones',
    'on the whole site' => 'en todo el sitio',
    'in selected places' => 'en lugares seleccionados',
    'A conversion is a form sent or a newsletter sign-up in the pop-up. The counters work without cookies and without any visitor data.' => 'Una conversión es un formulario enviado o una suscripción al boletín en el pop-up. Los contadores funcionan sin cookies y sin datos de los visitantes.',
    'Pop-up name' => 'Nombre del pop-up',
    'e.g. Newsletter on the blog' => 'p. ej. Boletín en el blog',
    'Only for you in the admin and for screen readers. The address #popup-… is made from the name.' => 'Solo para ti en la administración y para lectores de pantalla. La dirección #popup-… se crea a partir del nombre.',
    'Start from' => 'Empezar con',
    'The pop-up is created turned off and opens in the builder. It shows on the site once you publish it and turn it on.' => 'El pop-up se crea desactivado y se abre en el builder. Se muestra en el sitio cuando lo publicas y lo activas.',
    'Edit the content in the builder' => 'Editar el contenido en el builder',
    'A link or button to #popup-%s opens the pop-up at any time – even when it does not show on its own.' => 'Un enlace o botón a #popup-%s abre el pop-up en cualquier momento – incluso cuando no se muestra por sí solo.',
    'When the pop-up shows' => 'Cuándo se muestra el pop-up',
    'Trigger' => 'Activador',
    'Trigger value' => 'Valor del activador',
    'Seconds for time and idle, percent of the page for scrolling, number of pages for the visit.' => 'Segundos para tiempo e inactividad, porcentaje de la página para el desplazamiento, número de páginas para la visita.',
    'Frequency' => 'Frecuencia',
    'number of days' => 'número de días',
    'The visitor’s browser remembers it (sessionStorage and localStorage), not cookies.' => 'Lo recuerda el navegador del visitante (sessionStorage y localStorage), no las cookies.',
    'Where the pop-up shows' => 'Dónde se muestra el pop-up',
    'Places' => 'Lugares',
    'only on selected pages, in collections or in news' => 'solo en páginas seleccionadas, en colecciones o en noticias',
    'Collection item pages' => 'Páginas de elementos de colecciones',
    'the news list, categories and news items' => 'la lista de noticias, las categorías y las noticias',
    'from' => 'desde',
    'to' => 'hasta',
    'Empty = no limit. Outside the period the pop-up is not added to the page at all.' => 'Vacío = sin límite. Fuera del periodo, el pop-up no se añade a la página en absoluto.',
    'Only from a campaign' => 'Solo desde una campaña',
    'Text in the utm_* parameters of the address the visitor arrived with (e.g. spring or newsletter). Empty = everyone.' => 'Texto en los parámetros utm_* de la dirección con la que llegó el visitante (p. ej. spring o newsletter). Vacío = todos.',
    'Only from a referrer' => 'Solo desde un sitio de referencia',
    'Part of the address of the site the visitor came from (e.g. facebook.com). Empty = from anywhere.' => 'Parte de la dirección del sitio del que llegó el visitante (p. ej. facebook.com). Vacío = desde cualquier lugar.',
    'When several pop-ups would show, the lower number goes first. No pop-up opens over an open one.' => 'Cuando se fueran a mostrar varios pop-ups, va primero el número más bajo. Ningún pop-up se abre sobre otro abierto.',
    'Reset the counters of views, closes and conversions?' => '¿Restablecer los contadores de visualizaciones, cierres y conversiones?',
    'Reset the counters' => 'Restablecer los contadores',
    'Delete the pop-up? It disappears from the site at once.' => '¿Eliminar el pop-up? Desaparece del sitio de inmediato.',
    'Delete the pop-up' => 'Eliminar el pop-up',
    'Window in the middle' => 'Ventana en el centro',
    'Slide-in panel in the corner' => 'Panel deslizante en la esquina',
    'Bar at the top' => 'Barra arriba',
    'Bar at the bottom' => 'Barra abajo',
    'Full screen' => 'Pantalla completa',
    'After a number of seconds' => 'Tras unos segundos',
    'After scrolling part of the page' => 'Tras desplazarse por parte de la página',
    'When the visitor is about to leave' => 'Cuando el visitante está a punto de irse',
    'After a number of seconds without activity' => 'Tras unos segundos sin actividad',
    'After a number of pages in the visit' => 'Tras varias páginas en la visita',
    'Only by clicking a link or button' => 'Solo al hacer clic en un enlace o botón',
    'Once per visit' => 'Una vez por visita',
    'Once every number of days' => 'Una vez cada cierto número de días',
    'Until the visitor closes it' => 'Hasta que el visitante lo cierre',
    'Until the visitor sends the form in it' => 'Hasta que el visitante envíe el formulario que contiene',
    'Every time the trigger is met' => 'Cada vez que se cumpla el activador',
    'All devices' => 'Todos los dispositivos',
    'Computer and tablet only' => 'Solo ordenador y tablet',
    'Phone only' => 'Solo móvil',
    'A heading, a short text and an e-mail field with confirmed sign-up.' => 'Un título, un texto breve y un campo de correo con suscripción confirmada.',
    'Download for an e-mail' => 'Descarga a cambio del correo',
    'A guide or price list in exchange for contact details – the form goes to Enquiries.' => 'Una guía o lista de precios a cambio de los datos de contacto – el formulario va a Consultas.',
    'Announcement bar' => 'Barra de anuncios',
    'A slim bar at the top with a short message and a link.' => 'Una barra fina arriba con un mensaje breve y un enlace.',
    'Discount or offer' => 'Descuento u oferta',
    'A bold offer with a code and a button.' => 'Una oferta llamativa con un código y un botón.',
    'Event invitation' => 'Invitación a un evento',
    'A corner panel with the date, the place and a registration link.' => 'Un panel en la esquina con la fecha, el lugar y un enlace de inscripción.',
    'Blank pop-up' => 'Pop-up en blanco',
    'A heading and a text – build the rest in the builder.' => 'Un título y un texto – crea el resto en el builder.',
    'Pop-up settings (when and where it shows)' => 'Ajustes del pop-up (cuándo y dónde se muestra)',
    'Collection fields and settings' => 'Campos y ajustes de la colección',
    '%d%%' => '%d%%',
    '%d subscribers are going to the mailing service; the site sends the rest gradually in the background.' => '%d suscriptores van al servicio de correo; el sitio envía el resto poco a poco en segundo plano.',
    'The failed transfers were tried again – see the result in the Service column.' => 'Se han reintentado las transferencias fallidas – consulta el resultado en la columna Servicio.',
    'Confirmed subscribers go to %s automatically; those who unsubscribe are removed from it.' => 'Los suscriptores confirmados van a %s automáticamente; los que se dan de baja se eliminan de allí.',
    'Waiting to be sent: %d.' => 'Pendientes de envío: %d.',
    'Failed: %d.' => 'Fallidos: %d.',
    'Send all confirmed subscribers to the service' => 'Enviar todos los suscriptores confirmados al servicio',
    'Try the failed ones again' => 'Reintentar los fallidos',
    'Service settings' => 'Ajustes del servicio',
    'Using Brevo, MailerLite, Mailchimp, Ecomail or SmartEmailing? Once connected in Features, the site sends confirmed subscribers straight to your list.' => '¿Usas Brevo, MailerLite, Mailchimp, Ecomail o SmartEmailing? Una vez conectado en Funciones, el sitio envía los suscriptores confirmados directamente a tu lista.',
    'Connect a service' => 'Conectar un servicio',
    'Service' => 'Servicio',
    'waiting' => 'en espera',
    'The service did not respond.' => 'El servicio no ha respondido.',
    'Newsletter – connection to a mailing service' => 'Boletín – conexión con un servicio de correo',
    'Connection to a mailing service' => 'Conexión con un servicio de correo',
    'After a sign-up is confirmed (double opt-in), the site adds the address to the list in your service and removes it after unsubscribing. Sending, deliverability and unsubscribing from e-mails stay with the service. The transfer runs in the background – visitors do not wait.' => 'Tras confirmarse una suscripción (doble opt-in), el sitio añade la dirección a la lista de tu servicio y la quita tras la baja. El envío, la entregabilidad y la baja desde los correos corren a cargo del servicio. La transferencia se hace en segundo plano – los visitantes no esperan.',
    'none – you export subscribers to CSV' => 'ninguno – exportas los suscriptores a CSV',
    'Create the key in your service account (API, integrations). For SmartEmailing, enter the user name and the key separated by a colon. The key is stored only on your site and is never shown over MCP.' => 'Crea la clave en la cuenta de tu servicio (API, integraciones). Para SmartEmailing, introduce el nombre de usuario y la clave separados por dos puntos. La clave se guarda solo en tu sitio y nunca se muestra a través de MCP.',
    'The ID of the list (Brevo, Ecomail, SmartEmailing), group (MailerLite) or audience (Mailchimp) – you find it in the list settings in the service.' => 'El ID de la lista (Brevo, Ecomail, SmartEmailing), grupo (MailerLite) o audiencia (Mailchimp) – lo encontrarás en los ajustes de la lista en el servicio.',
    'Webhook URL' => 'URL del webhook',
    'Only for “Another service via a webhook”: the site sends JSON with the event novy_odberatel or odhlaseni_odberu and the e-mail.' => 'Solo para “Otro servicio mediante webhook”: el sitio envía JSON con el evento novy_odberatel u odhlaseni_odberu y el correo.',
    'Another service via a webhook (Make, Zapier, n8n)' => 'Otro servicio mediante webhook (Make, Zapier, n8n)',
    'Parts of the appearance' => 'Partes de la apariencia',
    'Styles' => 'Estilos',
    'A style is a ready set of colours, fonts, sizes and corner radius. Pick one with a click and fine-tune it in the other tabs – the content of the site does not change.' => 'Un estilo es un conjunto listo de colores, fuentes, tamaños y radio de esquinas. Elige uno con un clic y ajústalo en las demás pestañas – el contenido del sitio no cambia.',
    'current' => 'actual',
    'You do not have to put a look for your brand together by hand: connect Claude and write, for example, “Set the look of the site to our brand – primary colour #0E6E6E, serif headings, subtle rounding”. It saves the colours and fonts to the design system, and you see the result here.' => 'No tienes que montar a mano la apariencia de tu marca: conecta Claude y escribe, por ejemplo, “Ajusta la apariencia del sitio a nuestra marca – color principal #0E6E6E, títulos con serifa, redondeo sutil”. Guarda los colores y las fuentes en el sistema de diseño, y verás el resultado aquí.',
    'Buttons, cards, images and form fields across the site get this radius.' => 'Los botones, tarjetas, imágenes y campos de formulario de todo el sitio reciben este radio.',
    'Fonts and sizes' => 'Fuentes y tamaños',
    'Shapes' => 'Formas',
    'Kaleta installation' => 'Instalación de Kaleta',
    'Server check' => 'Comprobación del servidor',
    'The server does not meet the requirements. Fix the items marked with a cross and reload the page.' => 'El servidor no cumple los requisitos. Corrige los puntos marcados con una cruz y recarga la página.',
    'The installation could not be completed – check the highlighted fields.' => 'No se pudo completar la instalación – revisa los campos resaltados.',
    'MySQL or MariaDB. Create an empty database beforehand – in your hosting control panel.' => 'MySQL o MariaDB. Crea antes una base de datos vacía – en el panel de control de tu hosting.',
