    'Table prefix' => 'Prefijo de las tablas',
    'Site and administrator' => 'Sitio y administrador',
    'The account you will first sign in to the administration with.' => 'La cuenta con la que iniciarás sesión por primera vez en la administración.',
    'Scheduled news posts are published and dates are shown according to it.' => 'Las noticias programadas se publican y las fechas se muestran según esta zona.',
    'Install Kaleta' => 'Instalar Kaleta',
    'Creates the database tables and the config.php file.' => 'Crea las tablas de la base de datos y el archivo config.php.',
    'Kaleta is already installed' => 'Kaleta ya está instalado',
    'The config.php file exists, so the installer changes nothing.' => 'El archivo config.php existe, así que el instalador no cambia nada.',
    'Done, your website is running' => 'Listo, tu sitio web está funcionando',
    'The database is ready and the configuration has been written.' => 'La base de datos está lista y la configuración se ha escrito.',
    'For security reasons install.php has deleted itself – there is nothing else you need to do.' => 'Por seguridad, install.php se ha eliminado a sí mismo – no tienes que hacer nada más.',
    'For security reasons, now delete this file from the server:' => 'Por seguridad, elimina ahora este archivo del servidor:',
    'Go to the administration' => 'Ir a la administración',
