    'logs and cache' => 'registros y caché',
    'Prefix: lowercase letters, digits and underscore, at most 16 characters (e.g. ka_).' => 'Prefijo: letras minúsculas, dígitos y guion bajo, como máximo 16 caracteres (p. ej. ka_).',
    'Fill in the database name and user.' => 'Rellena el nombre y el usuario de la base de datos.',
    'Username: 2–40 characters, letters without accents, digits, dot, hyphen, underscore.' => 'Nombre de usuario: 2–40 caracteres, letras sin acentos, dígitos, punto, guion, guion bajo.',
    'Could not connect to the database:' => 'No se pudo conectar a la base de datos:',
    'Tables with this prefix already exist in the database. Choose another prefix or remove them first.' => 'Ya existen tablas con este prefijo en la base de datos. Elige otro prefijo o elimínalas primero.',
    'Creating the tables failed:' => 'La creación de las tablas ha fallado:',
    'The tables were created, but config.php could not be written. Check the write permissions.' => 'Las tablas se han creado, pero no se pudo escribir config.php. Comprueba los permisos de escritura.',
    'Start with a website' => 'Empezar con un sitio web',
    'A versatile services website: benefits, numbers, testimonials, news.' => 'Un sitio web de servicios versátil: ventajas, cifras, testimonios, noticias.',
    'Warm colours, how you work, projects and guarantees.' => 'Colores cálidos, cómo trabajas, proyectos y garantías.',
