    'This user has no access to the database. Grant it in your hosting control panel.' => 'Este usuario no tiene acceso a la base de datos. Concédeselo en el panel de control de tu hosting.',
    'There is no database with this name on the server. Create it in your hosting control panel or correct the name.' => 'No hay ninguna base de datos con este nombre en el servidor. Créala en el panel de control de tu hosting o corrige el nombre.',
    'Could not connect to the database server. Check the server and port.' => 'No se pudo conectar al servidor de base de datos. Comprueba el servidor y el puerto.',
    'The sample pages and the texts for visitors are created in this language. The administration stays in the language of the installation.' => 'Las páginas de ejemplo y los textos para visitantes se crean en este idioma. La administración se mantiene en el idioma de la instalación.',
    'A starter site brings Home, About us, Services and Contact pages with sample texts and its own style – edit the content in the builder and the style in Site appearance.' => 'Un sitio de inicio incluye las páginas Inicio, Quiénes somos, Servicios y Contacto con textos de ejemplo y su propio estilo – edita el contenido en el builder y el estilo en Apariencia del sitio.',
