    'Share preview' => 'Compartir vista previa',
    'Anyone with the link can see the draft without signing in – including changes you make later. Search engines do not index it.' => 'Cualquiera con el enlace puede ver el borrador sin iniciar sesión – incluidos los cambios que hagas después. Los buscadores no lo indexan.',
    'The Newsletter sign-up element in the builder: visitors enter an e-mail and confirm it by a link (double opt-in). Send them your latest news in an e-mail styled by the design system (through an SMTP server, while cron runs), pass confirmed subscribers to your mailing service (Brevo, MailerLite, Mailchimp, Ecomail, SmartEmailing, webhook), or export them to CSV.' => 'El elemento Suscripción al boletín en el builder: los visitantes introducen un correo y lo confirman mediante un enlace (doble opt-in). Envíales tus últimas noticias en un correo con el estilo del sistema de diseño (a través de un servidor SMTP, mientras se ejecuta el cron), pasa los suscriptores confirmados a tu servicio de correo (Brevo, MailerLite, Mailchimp, Ecomail, SmartEmailing, webhook) o expórtalos a CSV.',
    'Addresses from the Newsletter sign-up element. Only people who confirmed by the link in the e-mail count as subscribers. Send them news under Newsletters, or with your own tool – the export includes the unsubscribe link.' => 'Direcciones del elemento Suscripción al boletín. Solo cuentan como suscriptores las personas que confirmaron mediante el enlace del correo. Envíales noticias en Boletines o con tu propia herramienta – la exportación incluye el enlace de baja.',
    'Newsletters' => 'Boletines',
    'New newsletter' => 'Nuevo boletín',
    'Confirmed subscribers: %d' => 'Suscriptores confirmados: %d',
    'No newsletters yet.' => 'Aún no hay boletines.',
    'Send your latest news to subscribers in an e-mail that follows the look of your site – colours, fonts and logo come from the design system.' => 'Envía tus últimas noticias a los suscriptores en un correo que sigue la apariencia de tu sitio – los colores, las fuentes y el logotipo vienen del sistema de diseño.',
    'Write a newsletter' => 'Escribir un boletín',
    'Recipients' => 'Destinatarios',
    'Sent' => 'Enviados',
    'Failed' => 'Fallidos',
    'Sending' => 'Enviando',
    '%d of %d' => '%d de %d',
    'View' => 'Ver',
    'Delete the newsletter?' => '¿Eliminar el boletín?',
    'Delete the newsletter' => 'Eliminar el boletín',
    'All newsletters' => 'Todos los boletines',
    'Nothing tracks whether subscribers open the e-mail. Links to the site carry utm parameters, so Statistics show the visits the newsletter brought.' => 'Nada registra si los suscriptores abren el correo. Los enlaces al sitio llevan parámetros utm, así que Estadísticas muestra las visitas que trajo el boletín.',
    'Started %s' => 'Iniciado el %s',
    'finished %s' => 'finalizado el %s',
    'the e-mails go out in batches each time cron runs' => 'los correos salen por lotes cada vez que se ejecuta el cron',
    'Preview text' => 'Texto de vista previa',
    'Shown next to the subject in the inbox. Optional.' => 'Se muestra junto al asunto en la bandeja de entrada. Opcional.',
    'Introduction' => 'Introducción',
    'Plain text; an empty line starts a new paragraph, web addresses become links.' => 'Texto simple; una línea vacía inicia un nuevo párrafo, las direcciones web se convierten en enlaces.',
    'News in the e-mail' => 'Noticias en el correo',
    'the latest' => 'las últimas',
    'news items at the time of sending' => 'noticias en el momento del envío',
    'chosen news items' => 'noticias elegidas',
    'no news – only the introduction and the button' => 'sin noticias – solo la introducción y el botón',
    'Chosen news items' => 'Noticias elegidas',
    'No published news items yet.' => 'Aún no hay noticias publicadas.',
    'Optional, for example “See all news” or “Book an appointment”.' => 'Opcional, por ejemplo “Ver todas las noticias” o “Reservar una cita”.',
    'Button link' => 'Enlace del botón',
    'A path on the site (/contact) or a full https:// address.' => 'Una ruta del sitio (/contact) o una dirección https:// completa.',
    'The language of the footer texts and of the latest news items.' => 'El idioma de los textos del pie y de las últimas noticias.',
    'Save and send a test to %s' => 'Guardar y enviar una prueba a %s',
    'Preview of the e-mail' => 'Vista previa del correo',
    'Send to subscribers' => 'Enviar a los suscriptores',
    'Scheduled for %s – the latest news items are taken at that moment.' => 'Programado para el %s – las últimas noticias se toman en ese momento.',
    'Cancel scheduling' => 'Cancelar la programación',
    'Sending to subscribers needs the publishing permission – ask an editor or an administrator.' => 'Enviar a los suscriptores requiere el permiso de publicación – pídeselo a un editor o a un administrador.',
    'Send the newsletter to %d confirmed subscribers? Save your changes first – the saved version goes out.' => '¿Enviar el boletín a %d suscriptores confirmados? Guarda antes tus cambios – se envía la versión guardada.',
    'now' => 'ahora',
    'at' => 'el',
    'Date and time of sending' => 'Fecha y hora de envío',
    'Send to %d subscribers' => 'Enviar a %d suscriptores',
    'The newsletter needs a subject.' => 'El boletín necesita un asunto.',
    'Choose at least one news item, or send the latest news.' => 'Elige al menos una noticia o envía las últimas noticias.',
    'The button link must be an https:// address or a path on the site starting with /.' => 'El enlace del botón debe ser una dirección https:// o una ruta del sitio que empiece por /.',
    'The newsletter does not exist.' => 'El boletín no existe.',
    'A newsletter that is being sent or was sent cannot be changed.' => 'No se puede cambiar un boletín que se está enviando o que ya se envió.',
    'The newsletter is being sent right now – it cannot be deleted until it finishes.' => 'El boletín se está enviando ahora mismo – no se puede eliminar hasta que termine.',
    'The newsletter has already been sent.' => 'El boletín ya se ha enviado.',
    'There are no confirmed subscribers yet.' => 'Aún no hay suscriptores confirmados.',
    'The newsletter has no news items to send – publish a news item or choose No news.' => 'El boletín no tiene noticias que enviar – publica una noticia o elige Sin noticias.',
    'The time must be in the future, as YYYY-MM-DD HH:MM.' => 'La hora debe estar en el futuro, en formato AAAA-MM-DD HH:MM.',
    'The test address is not a valid e-mail.' => 'La dirección de prueba no es un correo válido.',
    'Newsletters are sent only through an SMTP server (Brevo, Amazon SES, Mailgun, your mailbox…) – set it up in Settings → Mail.' => 'Los boletines se envían solo a través de un servidor SMTP (Brevo, Amazon SES, Mailgun, tu buzón…) – configúralo en Ajustes → Correo.',
    'Cron has not called the tasks address in the last 30 minutes – newsletters go out in batches only while it runs. Set it up with the address in System status.' => 'El cron no ha llamado a la dirección de tareas en los últimos 30 minutos – los boletines solo salen por lotes mientras se ejecuta. Configúralo con la dirección de Estado del sistema.',
    'The newsletter was saved.' => 'El boletín se ha guardado.',
    'Sending to subscribers needs the publishing permission.' => 'Enviar a los suscriptores requiere el permiso de publicación.',
    'The newsletter is scheduled for %s.' => 'El boletín está programado para el %s.',
    'Sending has started: %d subscribers. The e-mails go out in batches each time cron runs.' => 'El envío ha comenzado: %d suscriptores. Los correos salen por lotes cada vez que se ejecuta el cron.',
    'Scheduling was cancelled – the newsletter is a draft again.' => 'Se ha cancelado la programación – el boletín vuelve a ser un borrador.',
    'The newsletter was deleted.' => 'El boletín se ha eliminado.',
    'Your account has no e-mail address – add one under My account.' => 'Tu cuenta no tiene dirección de correo – añade una en Mi cuenta.',
    'The test e-mail went to %s.' => 'El correo de prueba se ha enviado a %s.',
    'The test e-mail could not be sent: %s' => 'No se pudo enviar el correo de prueba: %s',
    'Cron' => 'Cron',
    'not set up – scheduled work waits for visits, and newsletters cannot be sent; you will find the address further down this page' => 'sin configurar – las tareas programadas esperan a las visitas y los boletines no se pueden enviar; encontrarás la dirección más abajo en esta página',
    'last run %s – newsletters are not being sent until cron runs again' => 'última ejecución %s – los boletines no se envían hasta que el cron vuelva a ejecutarse',
    'Newsletters: e-mails per hour' => 'Boletines: correos por hora',
    'Newsletters go out in batches while cron runs. Keep to the sending limit of your SMTP service – free plans often allow only a few hundred e-mails a day.' => 'Los boletines salen por lotes mientras se ejecuta el cron. Respeta el límite de envío de tu servicio SMTP – los planes gratuitos suelen permitir solo unos cientos de correos al día.',
    'Test' => 'Prueba',
    'Deleted items stay here for 30 days, then they are deleted permanently.' => 'Los elementos eliminados permanecen aquí 30 días; después se eliminan definitivamente.',
    'Back to items' => 'Volver a los elementos',
    'Items in the trash are not on the site. A restored item comes back hidden; after 30 days it is permanently deleted from the trash.' => 'Los elementos de la papelera no están en el sitio. Un elemento restaurado vuelve oculto; después de 30 días se elimina definitivamente de la papelera.',
    'Delete the item permanently? This cannot be undone.' => '¿Eliminar el elemento definitivamente? No se puede deshacer.',
    'Move the item to the trash? It disappears from the site; you can restore it for 30 days.' => '¿Mover el elemento a la papelera? Desaparecerá del sitio; puedes restaurarlo durante 30 días.',
    'The item is in the trash – it is no longer on the site; you can restore it for 30 days.' => 'El elemento está en la papelera – ya no está en el sitio; puedes restaurarlo durante 30 días.',
    'The item was restored as hidden.' => 'El elemento se ha restaurado como oculto.',
    'The item was deleted permanently.' => 'El elemento se ha eliminado definitivamente.',
    '%d enquiries read' => '%d consultas leídas',
    'Custom layout' => 'Diseño personalizado',
    '%s in the layout/ folder is no longer used – since 1.6 the look comes only from Site appearance and the builder. Move what you need into shared classes and site parts, then delete the folder.' => '%s en la carpeta layout/ ya no se usa – desde la 1.6 la apariencia viene solo de Apariencia del sitio y del builder. Pasa lo que necesites a clases compartidas y partes del sitio y luego elimina la carpeta.',
    'Unpublished look changes' => 'Cambios de apariencia sin publicar',
    'visitors still see the published look.' => 'los visitantes siguen viendo la apariencia publicada.',
    'Preview the whole site' => 'Vista previa de todo el sitio',
    'Publish the look' => 'Publicar la apariencia',
    'Discard the unpublished look changes?' => '¿Descartar los cambios de apariencia sin publicar?',
    'Design system: %s' => 'Sistema de diseño: %s',
    'no change' => 'sin cambios',
    'Classes: %s' => 'Clases: %s',
    'changed' => 'modificado',
    'Menus: %s' => 'Menús: %s',
    'automatic' => 'automático',
    'Saved to the draft look – preview the whole site, then publish it.' => 'Guardado en el borrador de la apariencia – revisa la vista previa de todo el sitio y luego publícala.',
    'There was nothing to publish.' => 'No había nada que publicar.',
    'The look is published: %s' => 'La apariencia se ha publicado: %s',
    'The unpublished look changes were discarded.' => 'Se han descartado los cambios de apariencia sin publicar.',
    'The earlier look is in the draft – preview the whole site, then publish it.' => 'La apariencia anterior está en el borrador – revisa la vista previa de todo el sitio y luego publícala.',
    'The look version does not exist.' => 'La versión de la apariencia no existe.',
    'Design tokens have been loaded into the draft look – preview the whole site, then publish it.' => 'Los tokens de diseño se han cargado en el borrador de la apariencia – revisa la vista previa de todo el sitio y luego publícala.',
    'Colours, fonts, sizes and shapes go to the draft look first – with changes of shared classes and menus. Visitors see them once you publish the look.' => 'Los colores, fuentes, tamaños y formas van primero al borrador de la apariencia – junto con los cambios de clases compartidas y menús. Los visitantes los ven cuando publicas la apariencia.',
    'Earlier looks' => 'Apariencias anteriores',
    'Each time you publish the look, the one before is kept here (the last 20).' => 'Cada vez que publicas la apariencia, la anterior se guarda aquí (las últimas 20).',
    'before: %s' => 'antes: %s',
    'Back to this look' => 'Volver a esta apariencia',
    'The menu is saved to the draft look – preview the whole site, then publish it.' => 'El menú se ha guardado en el borrador de la apariencia – revisa la vista previa de todo el sitio y luego publícala.',
    'In the draft look the menu is again built automatically from pages in the navigation.' => 'En el borrador de la apariencia, el menú vuelve a crearse automáticamente a partir de las páginas de la navegación.',
    'In the draft look the footer menu is empty.' => 'En el borrador de la apariencia, el menú del pie de página está vacío.',
    '%s (dark mode)' => '%s (modo oscuro)',
    'Heading font' => 'Fuente de los títulos',
    'Text font' => 'Fuente del texto',
    'Base font size' => 'Tamaño de fuente base',
    'Type scale' => 'Escala tipográfica',
    'Text width' => 'Ancho del texto',
    'Custom fonts' => 'Fuentes personalizadas',
    'Logo left, menu right' => 'Logotipo a la izquierda, menú a la derecha',
    'The logo on the left, the menu and a button on the right. Stays at the top while scrolling.' => 'El logotipo a la izquierda, el menú y un botón a la derecha. Se queda arriba al desplazar.',
    'Centred logo' => 'Logotipo centrado',
    'The logo in the middle with the menu below it – for a site led by the brand.' => 'El logotipo en el centro con el menú debajo – para un sitio centrado en la marca.',
    'With a contact bar' => 'Con barra de contacto',
    'A thin bar with the phone and e-mail above the logo and the menu.' => 'Una barra fina con el teléfono y el correo encima del logotipo y el menú.',
    'Minimal' => 'Mínimo',
    'Only the logo and one button – for a campaign page without the menu.' => 'Solo el logotipo y un botón – para una página de campaña sin menú.',
    'Columns' => 'Columnas',
    'The company, the footer menu, contacts and a newsletter sign-up, the copyright below.' => 'La empresa, el menú del pie de página, los contactos y una suscripción al boletín, con el copyright debajo.',
    'Compact' => 'Compacto',
    'One line: the company name, the footer menu and the copyright.' => 'Una línea: el nombre de la empresa, el menú del pie de página y el copyright.',
    'With the imprint' => 'Con aviso legal',
    'The company details for the imprint next to the footer menu and social networks.' => 'Los datos de la empresa para el aviso legal junto al menú del pie de página y las redes sociales.',
    'With a call to action' => 'Con llamada a la acción',
    'A coloured call to action above a two-column footer.' => 'Una llamada a la acción en color encima de un pie de página de dos columnas.',
    'The news item and a call to action below it.' => 'La noticia y una llamada a la acción debajo.',
    'Plain' => 'Sencillo',
    'Only the news item.' => 'Solo la noticia.',
    'Only the list of news.' => 'Solo la lista de noticias.',
    'With a newsletter sign-up' => 'Con suscripción al boletín',
    'The list of news and a newsletter sign-up below it.' => 'La lista de noticias y una suscripción al boletín debajo.',
    'Only the message and the links from the system.' => 'Solo el mensaje y los enlaces del sistema.',
    'With search' => 'Con búsqueda',
    'The message with a search box below it.' => 'El mensaje con un cuadro de búsqueda debajo.',
    'Templates: %s' => 'Plantillas: %s',
    'Use this template' => 'Usar esta plantilla',
    'All site parts' => 'Todas las partes del sitio',
    'A template is a clean skeleton – colours, fonts and spacing come from your design system. It goes into the draft of the part: adjust it in the builder and publish it; until then visitors see the published version.' => 'Una plantilla es un esqueleto limpio – los colores, las fuentes y los espacios vienen de tu sistema de diseño. Va al borrador de la parte: ajústala en el builder y publícala; hasta entonces, los visitantes ven la versión publicada.',
    'The template could not be used.' => 'No se pudo usar la plantilla.',
    'The template is in the draft – adjust it and publish; until then visitors see the published version.' => 'La plantilla está en el borrador – ajústala y publícala; hasta entonces, los visitantes ven la versión publicada.',
    'Webhooks' => 'Webhooks',
    'A webhook sends data to another service the moment something happens on the site – a new enquiry to a CRM or Slack, a published news item to Make, Zapier or n8n, which then share it on social networks.' => 'Un webhook envía datos a otro servicio en el momento en que ocurre algo en el sitio – una nueva consulta a un CRM o a Slack, una noticia publicada a Make, Zapier o n8n, que luego la comparten en redes sociales.',
    'Addresses' => 'Direcciones',
    'Signature' => 'Firma',
    'Signing secret' => 'Secreto de firma',
    'Every call carries the headers X-Kaleta-Timestamp and X-Kaleta-Signature (sha256=HMAC-SHA256 of “timestamp.body” with this secret). A receiver that checks the signature knows the call came from your site and was not changed. Keep the secret private.' => 'Cada llamada lleva las cabeceras X-Kaleta-Timestamp y X-Kaleta-Signature (sha256=HMAC-SHA256 de “timestamp.body” con este secreto). Un receptor que comprueba la firma sabe que la llamada vino de tu sitio y no se modificó. Mantén el secreto en privado.',
    'Create a new secret? Receivers that check the signature will reject calls until you give them the new one.' => '¿Crear un secreto nuevo? Los receptores que comprueban la firma rechazarán las llamadas hasta que les des el nuevo.',
    'Create a new secret' => 'Crear un secreto nuevo',
    'How to check the signature' => 'Cómo comprobar la firma',
    'Send a test call' => 'Enviar una llamada de prueba',
    'Delivery log' => 'Registro de entregas',
    'No webhook has been sent yet.' => 'Aún no se ha enviado ningún webhook.',
    'Event' => 'Evento',
    'Address' => 'Dirección',
    'delivered' => 'entregado',
    'not delivered' => 'no entregado',
    'Send again' => 'Volver a enviar',
    'A call that fails is retried after 1, 5 and 30 minutes and after 2 and 12 hours. Records are deleted after 30 days; the content of a delivered call is not kept.' => 'Una llamada que falla se reintenta tras 1, 5 y 30 minutos y tras 2 y 12 horas. Los registros se eliminan a los 30 días; el contenido de una llamada entregada no se conserva.',
    'First fill in and save at least one webhook address (https://).' => 'Primero rellena y guarda al menos una dirección de webhook (https://).',
    'The test call has been delivered.' => 'La llamada de prueba se ha entregado.',
    'The test call was not delivered – the reason is in the delivery log. It will be retried automatically.' => 'La llamada de prueba no se ha entregado – el motivo está en el registro de entregas. Se reintentará automáticamente.',
    'A new secret has been created. Paste it into every receiver that checks the signature.' => 'Se ha creado un secreto nuevo. Pégalo en cada receptor que compruebe la firma.',
    'Only https:// addresses are allowed.' => 'Solo se permiten direcciones https://.',
    'The receiver did not respond.' => 'El receptor no ha respondido.',
    'Its classes and components were not imported – only an administrator can add them.' => 'Sus clases y componentes no se importaron – solo un administrador puede añadirlos.',
    'New classes: %d, new components: %d (those the site already had were kept).' => 'Clases nuevas: %d, componentes nuevos: %d (se conservaron los que el sitio ya tenía).',
    'all calls of the last 7 days delivered' => 'todas las llamadas de los últimos 7 días entregadas',
    '%d call(s) of the last 7 days not delivered – see Settings → Webhooks' => '%d llamada(s) de los últimos 7 días sin entregar – consulta Ajustes → Webhooks',
    'Import from Kaleta' => 'Importar desde Kaleta',
    'Moving a site from another Kaleta installation: upload its export (the .zip archive from Export of the whole site). Everything is imported – pages, news, collections, components, menus, the look and the media – into a new, empty site; user accounts and secrets are never part of an export.' => 'Trasladar un sitio desde otra instalación de Kaleta: sube su exportación (el archivo .zip de Exportación de todo el sitio). Se importa todo – páginas, noticias, colecciones, componentes, menús, la apariencia y los medios – a un sitio nuevo y vacío; las cuentas de usuario y los secretos nunca forman parte de una exportación.',
    'This site already has its own content, so an export cannot be imported here. Install Kaleta again and choose “Start from an export”.' => 'Este sitio ya tiene contenido propio, así que aquí no se puede importar una exportación. Vuelve a instalar Kaleta y elige “Empezar desde una exportación”.',
    'Kaleta export' => 'Exportación de Kaleta',
    'imported' => 'importado',
    'Export of the site “%s” from Kaleta %s, created %s.' => 'Exportación del sitio “%s” desde Kaleta %s, creada el %s.',
    'Files in media/' => 'Archivos en media/',
    'The export has no files – copy the media/ folder from the old site over FTP before or after the import.' => 'La exportación no tiene archivos – copia la carpeta media/ del sitio antiguo por FTP antes o después de la importación.',
    'The import replaces all content of this site: pages, news, collections, components, menus, site parts, pop-ups, redirects and the media library, and takes over the site name, company details, languages and the look. User accounts, passwords, keys and the settings of mail and backups stay as they are on this site – the export never contains them. Imported news will be yours.' => 'La importación sustituye todo el contenido de este sitio: páginas, noticias, colecciones, componentes, menús, partes del sitio, pop-ups, redirecciones y la biblioteca de medios, y adopta el nombre del sitio, los datos de la empresa, los idiomas y la apariencia. Las cuentas de usuario, contraseñas, claves y los ajustes de correo y copias de seguridad se quedan como están en este sitio – la exportación nunca los contiene. Las noticias importadas serán tuyas.',
    'This site already has its own content (pages: %d, news: %d, collection items: %d, media: %d). A Kaleta export can be imported only into a new, empty site – install Kaleta again and choose “Start from an export”.' => 'Este sitio ya tiene contenido propio (páginas: %d, noticias: %d, elementos de colecciones: %d, medios: %d). Una exportación de Kaleta solo se puede importar en un sitio nuevo y vacío – vuelve a instalar Kaleta y elige “Empezar desde una exportación”.',
    'Replace the content of this site with the export. A database backup is made first.' => 'Sustituir el contenido de este sitio por la exportación. Antes se hace una copia de seguridad de la base de datos.',
    'Import' => 'Importar',
    'Copying files into media/: %s of %s. Keep this page open, it continues by itself.' => 'Copiando archivos en media/: %s de %s. Mantén esta página abierta, continúa sola.',
    'The site has been imported.' => 'El sitio se ha importado.',
    '%d skipped' => '%d omitidos',
    'Files that could not be saved' => 'Archivos que no se pudieron guardar',
    'The state before the import is in backup %s (Settings → Backups and updates). Check the site, then delete the export file – it is no longer needed.' => 'El estado anterior a la importación está en la copia de seguridad %s (Ajustes → Copias de seguridad y actualizaciones). Revisa el sitio y luego elimina el archivo de exportación – ya no es necesario.',
    'The state before the import is in backup %s (Settings → Backups and updates).' => 'El estado anterior a la importación está en la copia de seguridad %s (Ajustes → Copias de seguridad y actualizaciones).',
    'Confirm that the content of this site will be replaced.' => 'Confirma que el contenido de este sitio se sustituirá.',
    'The site already has its own content. A Kaleta export can be imported only into a new, empty site.' => 'El sitio ya tiene contenido propio. Una exportación de Kaleta solo se puede importar en un sitio nuevo y vacío.',
    'The file is not a Kaleta export.' => 'El archivo no es una exportación de Kaleta.',
    'The file is not a Kaleta export (obsah.json is missing in the archive).' => 'El archivo no es una exportación de Kaleta (falta obsah.json en el archivo comprimido).',
    'The export comes from a newer version of Kaleta – update this site first (Settings → Backups and updates).' => 'La exportación procede de una versión más reciente de Kaleta – actualiza primero este sitio (Ajustes → Copias de seguridad y actualizaciones).',
    'The PHP zip extension is missing on the server – upload obsah.json from the archive instead.' => 'Falta la extensión zip de PHP en el servidor – sube en su lugar obsah.json del archivo comprimido.',
    'Collection items' => 'Elementos de colecciones',
    'Shared classes' => 'Clases compartidas',
    'Menus' => 'Menús',
    'News' => 'Noticias',
    'Backup %s is ready, but the media could not be copied: %s' => 'La copia de seguridad %s está lista, pero no se pudieron copiar los medios: %s',
    'A backup on the same server as the site does not help if you lose the hosting. Each new database backup therefore uploads itself elsewhere, and the media/ folder is copied to the same place – only new and changed files, in the background.' => 'Una copia de seguridad en el mismo servidor que el sitio no sirve si pierdes el hosting. Por eso, cada nueva copia de seguridad de la base de datos se sube a otro lugar, y la carpeta media/ se copia al mismo sitio – solo los archivos nuevos y modificados, en segundo plano.',
    'Copy the media too' => 'Copiar también los medios',
    'Uploaded images and files go to the folder media/ of the same target. A file deleted on the site stays in the copy.' => 'Las imágenes y archivos subidos van a la carpeta media/ del mismo destino. Un archivo eliminado en el sitio se mantiene en la copia.',
    'Media: the last attempt %s failed: %s' => 'Medios: el último intento %s ha fallado: %s',
    'Media: the copy is complete (checked %s).' => 'Medios: la copia está completa (comprobado %s).',
    'Media: %d files are still waiting – the copy continues in the background.' => 'Medios: aún quedan %d archivos pendientes – la copia continúa en segundo plano.',
    'Automatic backups' => 'Copias de seguridad automáticas',
    'Every day something changed on the site, otherwise once a week – while an administrator works in the administration or cron runs. The last 10 backups are kept.' => 'Cada día en que algo cambió en el sitio, si no una vez por semana – mientras un administrador trabaja en la administración o se ejecuta el cron. Se conservan las últimas 10 copias.',
    'How to restore the site after losing the hosting' => 'Cómo restaurar el sitio tras perder el hosting',
    'Install Kaleta on the new hosting with the same table prefix (ka_ unless you changed it) and any starter site.' => 'Instala Kaleta en el nuevo hosting con el mismo prefijo de tablas (ka_ si no lo cambiaste) y cualquier sitio de inicio.',
    'Upload the latest database backup (kaleta-….sql.gz from your FTP or S3 copy, or a downloaded one) over FTP into storage/zalohy/.' => 'Sube la última copia de seguridad de la base de datos (kaleta-….sql.gz de tu copia en FTP o S3, o una descargada) por FTP a storage/zalohy/.',
    'Copy the media/ folder from the same place into the root of the site.' => 'Copia la carpeta media/ del mismo lugar a la raíz del sitio.',
    'Here in Backups, click Restore at that backup. Then sign in with the accounts from the backup.' => 'Aquí, en Copias de seguridad, haz clic en Restaurar en esa copia. Después inicia sesión con las cuentas de la copia.',
    'Moving a site to another Kaleta installation without accounts and secrets is simpler with Export of the whole site and Import from Kaleta (Import and export).' => 'Trasladar un sitio a otra instalación de Kaleta sin cuentas ni secretos es más sencillo con Exportación de todo el sitio e Importar desde Kaleta (Importación y exportación).',
    '%d visits in the last 30 days ended with “page not found” – add a redirect to the right page.' => '%d visitas en los últimos 30 días terminaron en “página no encontrada” – añade una redirección a la página correcta.',
    'An item points at a page that no longer exists.' => 'Un elemento apunta a una página que ya no existe.',
    'Component “%s”' => 'Componente “%s”',
    'Item template of “%s”' => 'Plantilla de elemento de “%s”',
    'Item “%s” (%s)' => 'Elemento “%s” (%s)',
    'Menu “%s”' => 'Menú “%s”',
    'News item “%s”' => 'Noticia “%s”',
    'No description for search engines and no longer text to take one from.' => 'Sin descripción para los buscadores y sin un texto más largo del que tomarla.',
    'No description for search engines – they then make up their own from the page text.' => 'Sin descripción para los buscadores – entonces se inventan la suya a partir del texto de la página.',
    'Page “%s”' => 'Página “%s”',
    'Pop-up “%s”' => 'Pop-up “%s”',
    'Site part “%s”' => 'Parte del sitio “%s”',
    'The item “%s” points at a hidden page – visitors do not see it in the menu.' => 'El elemento “%s” apunta a una página oculta – los visitantes no lo ven en el menú.',
    'The item “%s” points at a page in the trash.' => 'El elemento “%s” apunta a una página de la papelera.',
    'The link %s does not work (%s).' => 'El enlace %s no funciona (%s).',
    'The link %s leads to a page that does not exist.' => 'El enlace %s lleva a una página que no existe.',
    'The title “%s” is used %d times – search engines cannot tell the pages apart.' => 'El título “%s” se usa %d veces – los buscadores no pueden distinguir las páginas.',
    'no response' => 'sin respuesta',
    'External links are checked in the background, one news item every five minutes. The audit runs each time you open this page.' => 'Los enlaces externos se comprueban en segundo plano, una noticia cada cinco minutos. La auditoría se ejecuta cada vez que abres esta página.',
    'No problems found – links lead where they should, pages have descriptions and the builder checks pass.' => 'No se han encontrado problemas – los enlaces llevan adonde deben, las páginas tienen descripción y se superan las comprobaciones del builder.',
    'Show on the site' => 'Mostrar en el sitio',
    'A three-letter code (EUR, CZK, USD). Without it the price is not passed on.' => 'Un código de tres letras (EUR, CZK, USD). Sin él, el precio no se transmite.',
    'Currency of the price' => 'Moneda del precio',
    'Items are' => 'Los elementos son',
    'Structured data for search engines' => 'Datos estructurados para buscadores',
    'Tell search engines what the items are. Item pages then carry the schema.org data; the name, address, description and image come from the item itself. Save new fields first – then you can pick them here.' => 'Indica a los buscadores qué son los elementos. Las páginas de los elementos llevarán entonces los datos de schema.org; el nombre, la dirección, la descripción y la imagen vienen del propio elemento. Guarda primero los campos nuevos – después podrás elegirlos aquí.',
    'nothing specific (no structured data)' => 'nada concreto (sin datos estructurados)',
    '– none –' => '– ninguno –',
    'Item history (%s)' => 'Historial del elemento (%s)',
    'One or two sentences for search results (up to 160 characters). Empty = the beginning of the first longer text field.' => 'Una o dos frases para los resultados de búsqueda (hasta 160 caracteres). Vacío = el principio del primer campo de texto largo.',
    'Publish the hidden item automatically at:' => 'Publicar automáticamente el elemento oculto el:',
    'Restore this version of the item? The current version stays in the history.' => '¿Restaurar esta versión del elemento? La versión actual se queda en el historial.',
    'The item page stays reachable, but it is left out of search engines, the sitemap, llms.txt and site search.' => 'La página del elemento sigue accesible, pero queda fuera de los buscadores, del sitemap, de llms.txt y de la búsqueda del sitio.',
    'empty = the first image field' => 'vacío = el primer campo de imagen',
    'empty = the item name' => 'vacío = el nombre del elemento',
    'Missing descriptions' => 'Descripciones que faltan',
    'Duplicate titles' => 'Títulos duplicados',
    'Buttons, images and headings' => 'Botones, imágenes y títulos',
    'Frequent 404 errors' => 'Errores 404 frecuentes',
    'Product' => 'Producto',
    'Question and answer' => 'Pregunta y respuesta',
    'Kind of service' => 'Tipo de servicio',
    'Area served' => 'Zona de servicio',
    'Price' => 'Precio',
    'Job title' => 'Cargo',
    'Profile link' => 'Enlace al perfil',
    'Brand' => 'Marca',
    'Product code (SKU)' => 'Código de producto (SKU)',
    'Start' => 'Inicio',
    'End' => 'Fin',
    'Place' => 'Lugar',
    'Site audit' => 'Auditoría del sitio',
    'The earlier version of the item is back; the one before it is in the history.' => 'La versión anterior del elemento ha vuelto; la que había antes está en el historial.',
    'The media are too large to pack in one go. Turn on the off-site copy (it copies the media bit by bit) or download the media/ folder over FTP.' => 'Los medios son demasiado grandes para empaquetarlos de una vez. Activa la copia externa (copia los medios poco a poco) o descarga la carpeta media/ por FTP.',
    'The item is in the trash. Bring it back with restore_from_trash first.' => 'El elemento está en la papelera. Recupéralo primero con restore_from_trash.',
    'Addresses on your site that repeatedly ended with “page not found” this week: %d. Visitors came from an old link or a typo – send each one to the right page with a redirect, or ignore it.' => 'Direcciones de tu sitio que esta semana terminaron repetidamente en “página no encontrada”: %d. Los visitantes llegaron desde un enlace antiguo o una errata – envía cada una a la página correcta con una redirección, o ignórala.',
    'Review the addresses' => 'Revisar las direcciones',
    'Ignore all' => 'Ignorar todas',
    'Ignore' => 'Ignorar',
    '%d addresses ignored. A new address that visitors cannot find will show up again.' => '%d direcciones ignoradas. Una nueva dirección que los visitantes no encuentren volverá a aparecer.',
    'Nothing to do – no address ended with “page not found” repeatedly in the last 60 days.' => 'Nada que hacer – ninguna dirección terminó repetidamente en “página no encontrada” en los últimos 60 días.',
    'Visitors came to these addresses and found nothing – usually an old link from another site, a search engine or a typo. For each one choose:' => 'Los visitantes llegaron a estas direcciones y no encontraron nada – normalmente un enlace antiguo de otro sitio, un buscador o una errata. Para cada una, elige:',
    'Redirect – the old address leads to the page that replaced it (the form above is filled in, add the target).' => 'Redirigir – la dirección antigua lleva a la página que la sustituyó (el formulario de arriba está rellenado, añade el destino).',
    'Ignore – nothing replaces it, or it is a bot probing for other systems. It will not come back.' => 'Ignorar – nada la sustituye, o es un bot que busca otros sistemas. No volverá a aparecer.',
    'Ignore all these addresses? The warning on the start screen goes away until a new address appears.' => '¿Ignorar todas estas direcciones? El aviso de la pantalla de inicio desaparece hasta que aparezca una dirección nueva.',
    'Security contact' => 'Contacto de seguridad',
    'An e-mail address or an https:// page where people report security problems of this site. It is published at /.well-known/security.txt (RFC 9116); empty = no file.' => 'Una dirección de correo o una página https:// donde se informa de problemas de seguridad de este sitio. Se publica en /.well-known/security.txt (RFC 9116); vacío = sin archivo.',
    'What may Claude do?' => '¿Qué puede hacer Claude?',
    'Claude builds pages, writes news drafts, adds hidden collection items, proposes exceptions to the opening hours, sorts enquiries and prepares look changes – you review and publish them. Nothing on the live site changes without you.' => 'Claude crea páginas, escribe borradores de noticias, añade elementos ocultos a colecciones, propone excepciones al horario de apertura, ordena las consultas y prepara cambios de apariencia – tú los revisas y publicas. Nada cambia en el sitio en línea sin ti.',
    'Read only' => 'Solo lectura',
    'Claude reads pages, settings, the audit and the change log, and suggests changes. It changes nothing.' => 'Claude lee páginas, ajustes, la auditoría y el registro de cambios, y sugiere cambios. No cambia nada.',
    'It will act with your account %s (%s) – never with more than your role allows.' => 'Actuará con tu cuenta %s (%s) – nunca con más permisos de los que permite tu rol.',
    'Made by:' => 'Hecho por:',
    'people and Claude' => 'personas y Claude',
    'people in the admin' => 'personas en la administración',
    'Made by Claude through the connection %s' => 'Hecho por Claude a través de la conexión %s',
    'Connect Claude' => 'Conectar Claude',
    'Build and edit the site by talking to Claude. In the Claude app, add a custom connector with your site address followed by /mcp – My account shows the exact address.' => 'Crea y edita el sitio hablando con Claude. En la app de Claude, añade un conector personalizado con la dirección de tu sitio seguida de /mcp – Mi cuenta muestra la dirección exacta.',
    'The connector needs the site on HTTPS. In a subfolder, the Claude app finds the sign-in on its own; for a tool that does not, use a personal token.' => 'El conector necesita el sitio en HTTPS. En una subcarpeta, la app de Claude encuentra el inicio de sesión por sí sola; para una herramienta que no lo haga, usa un token personal.',
    'Instructions for Claude' => 'Instrucciones para Claude',
    'e.g. We address customers informally. Say “renovation”, never “reconstruction”. Keep headings short. Always offer a free visit.' => 'p. ej. Tuteamos a los clientes. Decimos “renovación”, nunca “reconstrucción”. Títulos breves. Ofrece siempre una visita gratuita.',
    'Brand voice, words to use or avoid, house rules. Every Claude connection gets them when it connects, and they are its resource kaleta://instructions.' => 'Voz de la marca, palabras que usar o evitar, normas de la casa. Cada conexión de Claude las recibe al conectarse, y son su recurso kaleta://instructions.',
    'Remember where leads came from' => 'Recordar de dónde vinieron los leads',
    'The first page of a visit, its campaign and the site that sent the visitor go with enquiries and newsletter sign-ups (Statistics → Campaigns and pages). Only for visitors who allow marketing in the cookie bar – turning it on adds that choice to the bar.' => 'La primera página de una visita, su campaña y el sitio que envió al visitante acompañan a las consultas y suscripciones al boletín (Estadísticas → Campañas y páginas). Solo para visitantes que permiten el marketing en la barra de cookies – al activarlo se añade esa opción a la barra.',
    'Leads (enquiries and sign-ups)' => 'Leads (consultas y suscripciones)',
    'Visits that became a lead' => 'Visitas que se convirtieron en lead',
    '%s leads' => '%s leads',
    'Pages that bring leads' => 'Páginas que traen leads',
    'Enquiries / sign-ups' => 'Consultas / suscripciones',
    'Conversion' => 'Conversión',
    'Campaigns' => 'Campañas',
    'Campaign (source / medium / name)' => 'Campaña (fuente / medio / nombre)',
    'No visits from links with utm parameters yet.' => 'Aún no hay visitas desde enlaces con parámetros utm.',
    'First pages of visits that brought a lead' => 'Primeras páginas de visitas que trajeron un lead',
    'Known only for visitors who allowed marketing cookies in the cookie bar.' => 'Se conoce solo para visitantes que permitieron las cookies de marketing en la barra de cookies.',
    'Site' => 'Sitio',
    'Devices' => 'Dispositivos',
    'Device' => 'Dispositivo',
    'Computer' => 'Ordenador',
    'The site has no pop-ups.' => 'El sitio no tiene pop-ups.',
    'News item' => 'Noticia',
    'Pop-up counters run since the pop-up was made or reset. Claude reads the same report with get_stats.' => 'Los contadores de pop-ups cuentan desde que se creó o restableció el pop-up. Claude lee el mismo informe con get_stats.',
    'inactive' => 'inactivo',
    'First page of the visit' => 'Primera página de la visita',
    'Came from' => 'Procedencia',
    'several choices (checkboxes)' => 'varias opciones (casillas)',
    'hidden value (e.g. the product the form is about)' => 'valor oculto (p. ej. el producto al que se refiere el formulario)',
    'Options to tick (one per line)' => 'Opciones para marcar (una por línea)',
    'Value sent with the form (not shown to the visitor)' => 'Valor enviado con el formulario (no se muestra al visitante)',
    'Paste the address of a Calendly or Google booking page, a Google, Microsoft, Tally, Typeform or Airtable form, or a Spotify or SoundCloud track.' => 'Pega la dirección de una página de reservas de Calendly o Google, un formulario de Google, Microsoft, Tally, Typeform o Airtable, o una pista de Spotify o SoundCloud.',
    'Embed' => 'Inserción',
    'A booking calendar, form or player from Calendly, Google, Microsoft Forms, Tally, Typeform, Airtable, Spotify or SoundCloud – loads after a click.' => 'Un calendario de reservas, formulario o reproductor de Calendly, Google, Microsoft Forms, Tally, Typeform, Airtable, Spotify o SoundCloud – se carga tras un clic.',
    'Address of the booking page, form or track (copied from the service)' => 'Dirección de la página de reservas, del formulario o de la pista (copiada del servicio)',
    'What it is, for screen readers (e.g. Book a consultation)' => 'Qué es, para lectores de pantalla (p. ej., Reservar una consulta)',
    'player (160 px)' => 'reproductor (160 px)',
    'small (450 px)' => 'pequeño (450 px)',
    'medium (700 px)' => 'mediano (700 px)',
    'large (950 px)' => 'grande (950 px)',
    'Show: %s' => 'Mostrar: %s',
    'Loads from %s after a click.' => 'Se carga desde %s tras un clic.',
    'Open in %s' => 'Abrir en %s',
    '%s from %s' => '%s de %s',
    'Booking calendar' => 'Calendario de reservas',
    'Form or table' => 'Formulario o tabla',
    'Player' => 'Reproductor',
    'Code in the head of this page' => 'Código en el head de esta página',
    'Only for this page, after the code for the whole site (Settings → Analytics) – e.g. the conversion tag of a landing page. Mind the cookie consent: code that tracks visitors belongs in the marketing code.' => 'Solo para esta página, después del código de todo el sitio (Ajustes → Analítica) – p. ej., la etiqueta de conversión de una landing page. Ten en cuenta el consentimiento de cookies: el código que rastrea visitantes va en el código de marketing.',
    'Code in the head of a page can be set only by an administrator, through a connection with full access.' => 'Solo un administrador puede definir código en el head de una página, mediante una conexión con acceso completo.',
    'Accessibility' => 'Accesibilidad',
    ' (dark mode)' => ' (modo oscuro)',
    '%s has a contrast of %s : 1 – text needs at least 4.5 : 1.' => '%s tiene un contraste de %s : 1 – el texto necesita al menos 4,5 : 1.',
    'The whole site' => 'Todo el sitio',
    'No accessibility statement – the European Accessibility Act expects a service to say how accessible it is and whom to contact about barriers. Add a page such as /accessibility.' => 'No hay declaración de accesibilidad – el Acta Europea de Accesibilidad espera que un servicio indique lo accesible que es y a quién contactar por barreras. Añade una página como /accessibility.',
    'The button “%s” does not say what it does – screen readers read buttons and links on their own.' => 'El botón “%s” no dice lo que hace – los lectores de pantalla leen botones y enlaces por separado.',
    'An image in the text has no description for blind visitors (alt).' => 'Una imagen del texto no tiene descripción para visitantes ciegos (alt).',
    'A link has no text – a screen reader has nothing to read.' => 'Un enlace no tiene texto – un lector de pantalla no tiene nada que leer.',
    'The link “%s” does not say where it leads – screen readers read links on their own.' => 'El enlace “%s” no dice adónde lleva – los lectores de pantalla leen los enlaces por separado.',
    'A table has no header cells (th) – screen readers cannot tell what the columns mean.' => 'Una tabla no tiene celdas de encabezado (th) – los lectores de pantalla no saben qué significan las columnas.',
    'An embedded frame (iframe) has no title.' => 'Un marco incrustado (iframe) no tiene título.',
