    'Na webu právě pracujeme. Zkuste to prosím za chvíli.' => 'Estamos trabajando en el sitio ahora mismo. Vuelve a intentarlo en un momento.',
    'Používáme cookies k měření návštěvnosti. Pomáhají nám zlepšovat web.' => 'Usamos cookies para medir el tráfico. Nos ayudan a mejorar el sitio.',
    'podbarvení' => 'fondo',
