    'Podoba' => 'Estilo',
    'na celém webu' => 'en todo el sitio',
    'na vybraných místech' => 'en lugares seleccionados',
    'nepublikované' => 'sin publicar',
    'Založit a otevřít v builderu' => 'Crear y abrir en el builder',
    'od' => 'desde',
    'do' => 'hasta',
    'stránek' => 'páginas',
    'Přihlášení k newsletteru' => 'Suscripción al boletín',
    'Služba' => 'Servicio',
    'Služba neodpověděla.' => 'El servicio no respondió.',
    'Start from a ready-made role:' => 'Empezar con un rol predefinido:',
    'Client' => 'Cliente',
    'Edits pages, news and collection items, answers enquiries, sees the statistics and asks Claude for changes – the look, settings and users stay with the agency.' => 'Edita páginas, noticias y elementos de colecciones, responde consultas, ve las estadísticas y pide cambios a Claude – la apariencia, los ajustes y los usuarios quedan en manos de la agencia.',
    'Writer' => 'Redactor',
    'Writes news for someone else to publish.' => 'Escribe noticias que publica otra persona.',
    'Enquiries only' => 'Solo consultas',
    'Handles enquiries from the site forms and the newsletter subscribers, and asks Claude for changes.' => 'Gestiona las consultas de los formularios del sitio y los suscriptores del boletín, y pide cambios a Claude.',
    'Built and looked after by' => 'Creado y mantenido por',
    'The agency or freelancer who looks after the site. The sign-in screen and the foot of the admin show whom to ask for help.' => 'La agencia o el profesional que mantiene el sitio. La pantalla de inicio de sesión y el pie de la administración muestran a quién pedir ayuda.',
    'E-mail for help' => 'Correo para ayuda',
    'Phone for help' => 'Teléfono para ayuda',
    'A path from Media, e.g. media/2026/10/agency.svg – click the file in Media to open it, its address starts with media/.' => 'Una ruta de Medios, p. ej., media/2026/10/agency.svg – haz clic en el archivo en Medios para abrirlo; su dirección empieza por media/.',
    'Website by %s' => 'Sitio web de %s',
    'help: %s' => 'ayuda: %s',
    'Before handing over' => 'Antes de la entrega',
    'No site e-mail: enquiries and password resets have nowhere to go.' => 'No hay correo del sitio: las consultas y los restablecimientos de contraseña no tienen adónde ir.',
    'E-mail goes out through the host’s mail() – set an SMTP server so enquiries and newsletters do not end up in spam.' => 'El correo sale a través de mail() del hosting – configura un servidor SMTP para que las consultas y los boletines no acaben en spam.',
    'Backups stay on the same server – add an off-site copy (FTPS or S3) in case the hosting is lost.' => 'Las copias de seguridad se quedan en el mismo servidor – añade una copia externa (FTPS o S3) por si se pierde el hosting.',
    'Business details are missing – the footer, the imprint and search engines use them.' => 'Faltan los datos de la empresa – el pie de página, el aviso legal y los buscadores los usan.',
    'Search engines are blocked – switch indexing on when the site goes live.' => 'Los buscadores están bloqueados – activa la indexación cuando el sitio se publique.',
    'No site icon (favicon) – browsers and phones show a blank one.' => 'No hay icono del sitio (favicon) – los navegadores y teléfonos muestran uno en blanco.',
    'Analytics or marketing codes run without a cookie bar – visitors in the EU must consent first.' => 'Los códigos de analítica o marketing se ejecutan sin barra de cookies – los visitantes de la UE deben dar su consentimiento antes.',
    'No security contact – add who takes reports of security problems (published as security.txt).' => 'No hay contacto de seguridad – añade quién recibe los avisos de problemas de seguridad (se publica como security.txt).',
    'The administrator %s signs in without two-step sign-in or a passkey.' => 'El administrador %s inicia sesión sin verificación en dos pasos ni passkey.',
    'The client has no account of their own yet – create one with the Client role (Users → Roles).' => 'El cliente aún no tiene cuenta propia – crea una con el rol Cliente (Usuarios → Roles).',
    'Your contact is not set – the client will not see whom to ask (Settings → General → Built and looked after by).' => 'Tu contacto no está configurado – el cliente no verá a quién pedir ayuda (Ajustes → General → Creado y mantenido por).',
    'Background tasks have never run – newsletters are sent only while they do. Add the cron line from System status.' => 'Las tareas en segundo plano nunca se han ejecutado – los boletines solo se envían mientras se ejecutan. Añade la línea de cron de Estado del sistema.',
    'How to use this' => 'Cómo usarlo',
    'guide, opens in a new tab' => 'guía, se abre en una pestaña nueva',
    'Could not connect to the SMTP server %s. Check the address, port and encryption; some hosts block outgoing SMTP.' => 'No se pudo conectar con el servidor SMTP %s. Comprueba la dirección, el puerto y el cifrado; algunos hostings bloquean el SMTP saliente.',
    'The SMTP server refused the sign-in – check the user name and password (Gmail and Seznam need an app password).' => 'El servidor SMTP rechazó el inicio de sesión – comprueba el nombre de usuario y la contraseña (Gmail y Seznam necesitan una contraseña de aplicación).',
    'SMTP server reply to %s: %s' => 'Respuesta del servidor SMTP a %s: %s',
    'A scheduled newsletter can be changed only by someone who may send newsletters – unschedule it first.' => 'Solo quien puede enviar boletines puede cambiar un boletín programado – primero quita la programación.',
    'Without the extra spam check (CAPTCHA from Settings → Privacy and cookies)' => 'Sin la comprobación antispam adicional (CAPTCHA en Ajustes → Privacidad y cookies)',
    'Spam check for forms' => 'Comprobación antispam de formularios',
    'Forms are protected without one: a signed time, a hidden trap field and a limit per address. Add a CAPTCHA only if spam still gets through. The provider receives the visitor’s address and browser details – name it in your privacy policy.' => 'Los formularios están protegidos sin ella: una marca de tiempo firmada, un campo trampa oculto y un límite por dirección. Añade un CAPTCHA solo si sigue entrando spam. El proveedor recibe la dirección del visitante y los datos de su navegador – menciónalo en tu política de privacidad.',
    'Extra spam check' => 'Comprobación antispam adicional',
    'none – the built-in protection only' => 'ninguna – solo la protección integrada',
    'hCaptcha and Cloudflare Turnstile suit EU sites; reCAPTCHA v3 is invisible and scores every visit.' => 'hCaptcha y Cloudflare Turnstile son adecuados para sitios de la UE; reCAPTCHA v3 es invisible y puntúa cada visita.',
    'Site key' => 'Clave del sitio',
    'From the provider’s dashboard, for this site’s domain.' => 'Del panel del proveedor, para el dominio de este sitio.',
    'Secret key' => 'Clave secreta',
    'the key is saved – enter a new one only to change it' => 'la clave está guardada – introduce una nueva solo para cambiarla',
    'Stays on your site; Claude cannot read it.' => 'Se queda en tu sitio; Claude no puede leerla.',
    'Remove the saved key' => 'Quitar la clave guardada',
    'Accept forms when the provider is down' => 'Aceptar formularios cuando el proveedor no responde',
    'The built-in protection still applies. Off = such forms are refused until the provider answers again.' => 'La protección integrada sigue aplicándose. Desactivado = esos formularios se rechazan hasta que el proveedor vuelva a responder.',
    'The container ID in the form GTM-XXXXXXX. Consent mode is built in: with the built-in cookie bar the container starts after the visitor allows analytics or marketing.' => 'El ID del contenedor con el formato GTM-XXXXXXX. El modo de consentimiento está integrado: con la barra de cookies integrada, el contenedor se inicia después de que el visitante permita la analítica o el marketing.',
    'Google Analytics is set here and probably also in your Tag Manager container – visits would be counted twice. Keep it in one place.' => 'Google Analytics está configurado aquí y probablemente también en tu contenedor de Tag Manager – las visitas se contarían dos veces. Mantenlo en un solo sitio.',
    'Kaleta sends these events to the data layer for your tags: generate_lead (a form was sent), sign_up (newsletter), popup_conversion, click_phone, click_email and file_download.' => 'Kaleta envía estos eventos a la capa de datos para tus etiquetas: generate_lead (se envió un formulario), sign_up (boletín), popup_conversion, click_phone, click_email y file_download.',
    'Download a container template with these triggers' => 'Descargar una plantilla de contenedor con estos activadores',
    'This is switched off in the public demo. Install Kaleta to try it.' => 'Esto está desactivado en la demo pública. Instala Kaleta para probarlo.',
    'This is the public demo of Kaleta. Sign in as %s with the password %s. Everything you change disappears at the next hourly reset.' => 'Esta es la demo pública de Kaleta. Inicia sesión como %s con la contraseña %s. Todo lo que cambies desaparece en el siguiente reinicio horario.',
    'Public demo: everything you change here is reset in %s minutes. E-mail, imports, updates, users and the Claude connection are switched off.' => 'Demo pública: todo lo que cambies aquí se restablece en %s minutos. El correo, las importaciones, las actualizaciones, los usuarios y la conexión con Claude están desactivados.',
    'Sending e-mail is switched off in the public demo.' => 'El envío de correo está desactivado en la demo pública.',
    'Downloading from other sites is switched off in the public demo.' => 'La descarga desde otros sitios está desactivada en la demo pública.',
    'Import from a website' => 'Importar desde un sitio web',
    'Enter the address of a site on any platform – Wix, Webnode, Jimdo, Squarespace, Joomla, Drupal or WordPress without an export. Its pages become builder pages with their images, and the old addresses redirect to the new ones. The pages stay hidden until you check and publish them; the design is not copied – the pages take this site’s look.' => 'Introduce la dirección de un sitio de cualquier plataforma – Wix, Webnode, Jimdo, Squarespace, Joomla, Drupal o WordPress sin exportación. Sus páginas se convierten en páginas del builder con sus imágenes, y las direcciones antiguas redirigen a las nuevas. Las páginas quedan ocultas hasta que las revises y publiques; el diseño no se copia – las páginas adoptan la apariencia de este sitio.',
    'This server cannot download from other sites (both curl and allow_url_fopen are missing, or the GD extension).' => 'Este servidor no puede descargar desde otros sitios (faltan curl y allow_url_fopen, o la extensión GD).',
    'Address of the site' => 'Dirección del sitio',
    'Kaleta reads the sitemap, or follows the site’s links when there is none – at most %s pages.' => 'Kaleta lee el sitemap o, si no lo hay, sigue los enlaces del sitio – como máximo %s páginas.',
    'the main language' => 'el idioma principal',
    'Download the images into Media' => 'Descargar las imágenes a Medios',
    'Redirect the old addresses to the new pages' => 'Redirigir las direcciones antiguas a las páginas nuevas',
    'Import blog posts as news (addresses like /blog/…, or with a publication date)' => 'Importar las entradas del blog como noticias (direcciones como /blog/… o con fecha de publicación)',
    'Find the pages' => 'Buscar las páginas',
    'finding pages' => 'buscando páginas',
    'Remove from the list' => 'Quitar de la lista',
    'Enter the address of the site, e.g. https://www.example.com.' => 'Introduce la dirección del sitio, p. ej., https://www.example.com.',
    'The import does not exist any more.' => 'La importación ya no existe.',
    'Site: %s' => 'Sitio: %s',
    'Finding pages: %s found so far. Keep this page open, it continues by itself.' => 'Buscando páginas: %s encontradas hasta ahora. Mantén esta página abierta, continúa sola.',
    'No pages were found. Check the address – the site has to be reachable from this server.' => 'No se encontraron páginas. Comprueba la dirección – el sitio tiene que ser accesible desde este servidor.',
    '%s pages found. They will be imported as hidden pages; nothing changes for visitors until you publish them.' => '%s páginas encontradas. Se importarán como páginas ocultas; nada cambia para los visitantes hasta que las publiques.',
    '… and %s more.' => '… y %s más.',
    'Import %s pages' => 'Importar %s páginas',
    'Importing: %s of %s pages. Keep this page open, it continues by itself.' => 'Importando: %s de %s páginas. Mantén esta página abierta, continúa sola.',
    'The import is finished. The pages are hidden until you check and publish them.' => 'La importación ha terminado. Las páginas quedan ocultas hasta que las revises y publiques.',
    'Images in Media' => 'Imágenes en Medios',
    '%s pages could not be imported' => 'No se pudieron importar %s páginas',
    'Next: check the pages, put the ones you keep into the menu and publish them. Claude can match their look to the design system and tidy the texts through the connection.' => 'Siguiente paso: revisa las páginas, pon en el menú las que conserves y publícalas. Claude puede adaptar su apariencia al sistema de diseño y pulir los textos a través de la conexión.',
    'Show pages' => 'Mostrar páginas',
    'The page could not be downloaded.' => 'No se pudo descargar la página.',
    'The page has no content to import.' => 'La página no tiene contenido para importar.',
    'Address of the old site' => 'Dirección del sitio antiguo',
    'Before you point the domain to this site, check the old site against it: every old address must lead somewhere, and no page may lose its search engine description, its form or most of its images. Nothing is changed – the check only reads.' => 'Antes de apuntar el dominio a este sitio, compara el sitio antiguo con él: cada dirección antigua debe llevar a alguna parte y ninguna página puede perder su descripción para buscadores, su formulario ni la mayoría de sus imágenes. No se cambia nada – la comprobación solo lee.',
    'Check the move' => 'Comprobar la migración',
    'Check the move before going live' => 'Comprobar la migración antes de publicar',
    'Checking: %s of %s addresses. Keep this page open, it continues by itself.' => 'Comprobando: %s de %s direcciones. Mantén esta página abierta, continúa sola.',
    'Everything moved: every old address leads to a published page and nothing was lost.' => 'Todo se ha migrado: cada dirección antigua lleva a una página publicada y no se ha perdido nada.',
    'Finding the pages of the old site. Keep this page open, it continues by itself.' => 'Buscando las páginas del sitio antiguo. Mantén esta página abierta, continúa sola.',
    'Fix what is missing – redirects in Redirects, descriptions and forms on the pages – and check again. Claude can do it through the connection (migration_report).' => 'Corrige lo que falta – redirecciones en Redirecciones, descripciones y formularios en las páginas – y vuelve a comprobar. Claude puede hacerlo a través de la conexión (migration_report).',
    'Missing' => 'Falta',
    'Nearly ready: check the warnings below.' => 'Casi listo: revisa las advertencias de abajo.',
    'Not published yet' => 'Aún sin publicar',
    'Not ready to go live: %s problems would cost visitors or search engines something.' => 'No está listo para publicarse: %s problemas costarían algo a los visitantes o a los buscadores.',
    'Nothing at this address and no redirect – it will end in 404.' => 'No hay nada en esta dirección ni redirección – acabará en 404.',
    'Old addresses' => 'Direcciones antiguas',
    'Old site: %s' => 'Sitio antiguo: %s',
    'On this site' => 'En este sitio',
    'Problems' => 'Problemas',
    'Redirected' => 'Redirigido',
    'Redirected more than once – point the redirect straight at the final page.' => 'Redirigido más de una vez – apunta la redirección directamente a la página final.',
    'Redirected to another site.' => 'Redirigido a otro sitio.',
    'Same address' => 'Misma dirección',
    'The Redirects feature is off: no redirect from an old address works.' => 'La función Redirecciones está desactivada: ninguna redirección desde una dirección antigua funciona.',
    'The new page has less than half of the old page’s images.' => 'La página nueva tiene menos de la mitad de las imágenes de la antigua.',
    'The old page could not be read, so only the address was checked.' => 'No se pudo leer la página antigua, así que solo se comprobó la dirección.',
    'The old page had a form, the new one has none.' => 'La página antigua tenía un formulario, la nueva no tiene ninguno.',
    'The old page had a search engine description, the new one has none.' => 'La página antigua tenía una descripción para buscadores, la nueva no tiene ninguna.',
    'The page is here but not published yet.' => 'La página está aquí, pero aún no se ha publicado.',
    'The report does not exist any more.' => 'El informe ya no existe.',
    'check in progress' => 'comprobación en curso',
    'Note' => 'Nota',
    'slide in from the left' => 'entrar desde la izquierda',
    'slide in from the right' => 'entrar desde la derecha',
    'from a blur' => 'desde un desenfoque',
    'Motion while scrolling' => 'Movimiento al desplazar',
    'parallax (slower than the page)' => 'parallax (más lento que la página)',
    'stronger parallax' => 'parallax más fuerte',
