    'lift with a shadow' => 'elevar con sombra',
    'grow slightly' => 'agrandar ligeramente',
    'nudge to the side' => 'desplazar a un lado',
    'fade a little' => 'atenuar un poco',
    'OK' => 'OK',
    'SEO plugin %s: %s custom titles, %s meta descriptions, %s noindex – they go into the SEO fields of the news items and pages. A title made only of the plugin’s variables is skipped; the site builds it itself.' => 'Plugin SEO %s: %s títulos personalizados, %s metadescripciones, %s noindex – van a los campos SEO de las noticias y páginas. Un título formado solo por variables del plugin se omite; el sitio lo genera por sí mismo.',
    'Canonical URLs (%s) are not transferred.' => 'Las URL canónicas (%s) no se transfieren.',
    'Redirects managed by SEO plugins (SmartCrawl, Yoast SEO, Rank Math) are not part of the export – they come over separately.' => 'Las redirecciones gestionadas por plugins SEO (SmartCrawl, Yoast SEO, Rank Math) no forman parte de la exportación – se trasladan por separado.',
    'With an SEO title, description or noindex from a plugin' => 'Con título SEO, descripción o noindex de un plugin',
    'Left out (repeaters, galleries or relationships – Claude can move them by hand): %s.' => 'Omitido (repetidores, galerías o relaciones – Claude puede moverlos a mano): %s.',
    'custom post types as collections (%s)' => 'tipos de entrada personalizados como colecciones (%s)',
    'Collection items (custom post types), in %s new collections' => 'Elementos de colecciones (tipos de entrada personalizados), en %s colecciones nuevas',
    'Excerpt' => 'Extracto',
    'none' => 'ninguno',
    'Header on scroll (header part only)' => 'Encabezado al desplazar (solo la parte del encabezado)',
    'transparent at the top, solid after scrolling' => 'transparente arriba, opaco tras desplazar',
    'smaller after scrolling' => 'más pequeño tras desplazar',
    'transparent at the top and smaller after scrolling' => 'transparente arriba y más pequeño tras desplazar',
    'Text colour while the header is transparent' => 'Color del texto mientras el encabezado es transparente',
    'as normal' => 'como siempre',
    'light (over a dark photo)' => 'claro (sobre una foto oscura)',
    'dark (over a light photo)' => 'oscuro (sobre una foto clara)',
    'An icon shows before the text. The description and group columns (a group inside a submenu with its own items) appear in a mega menu – the Navigation element with “Submenu as a wide panel”.' => 'Se muestra un icono antes del texto. Las columnas de descripción y de grupo (un grupo dentro de un submenú con sus propios elementos) aparecen en un megamenú – el elemento Navegación con “Submenú como panel ancho”.',
    'Description (mega menu)' => 'Descripción (megamenú)',
    'Into the group above (a column of the mega menu)' => 'En el grupo de arriba (una columna del megamenú)',
    '%s (default language)' => '%s (idioma predeterminado)',
    'Nothing to copy.' => 'No hay nada que copiar.',
    'The clipboard does not contain Kaleta elements.' => 'El portapapeles no contiene elementos de Kaleta.',
    'None of the elements could be inserted.' => 'No se pudo insertar ninguno de los elementos.',
    '%d images still load from %s – replace them with files from this site’s Media.' => '%d imágenes aún se cargan desde %s – sustitúyelas por archivos de Medios de este sitio.',
    '%d images were left out – the media of the other site are not available here.' => 'Se omitieron %d imágenes – los medios del otro sitio no están disponibles aquí.',
