    'Sending e-mail' => 'Enviando correo',
    'Sending newsletters' => 'Enviando boletines',
    'Subscribers to the mailing service' => 'Suscriptores al servicio de envío de correo',
    'The automatic backup failed: %s' => 'La copia de seguridad automática falló: %s',
    'The background job “%s” failed %d times in a row: %s' => 'La tarea en segundo plano “%s” falló %d veces seguidas: %s',
    'The background job “%s” works again.' => 'La tarea en segundo plano “%s” vuelve a funcionar.',
    'The look was published: %s' => 'Se publicó la apariencia: %s',
    'The off-site copy of the backup failed: %s' => 'La copia externa de la copia de seguridad falló: %s',
    'Version %s did not work (%s), so the site went back to version %s.' => 'La versión %s no funcionó (%s), así que el sitio volvió a la versión %s.',
    'Version %s was installed (from %s).' => 'Se instaló la versión %s (desde %s).',
    'Version %s was installed but the site did not work afterwards (%s). The website files have been returned to their state before the update.' => 'Se instaló la versión %s, pero el sitio no funcionó después (%s). Los archivos del sitio web se han devuelto a su estado anterior a la actualización.',
    'Webhook %s could not be delivered: %s' => 'No se pudo entregar el webhook %s: %s',
    'Webhook deliveries' => 'Entregas de webhooks',
    'When a backup, an update, e-mail, a webhook or a background job fails, the site sends one e-mail – at most one an hour, with everything that happened.' => 'Cuando falla una copia de seguridad, una actualización, el correo, un webhook o una tarea en segundo plano, el sitio envía un correo – como máximo uno por hora, con todo lo que ha pasado.',
    'You get at most one such e-mail an hour. Change the address or switch the alerts off in System status.' => 'Recibes como máximo un correo así por hora. Cambia la dirección o desactiva las alertas en Estado del sistema.',
    'cron and visits' => 'cron y visitas',
    'every %s' => 'cada %s',
    'every job worked the last time it ran' => 'todas las tareas funcionaron en su última ejecución',
    'failed %d×' => 'falló %d×',
    'not run yet' => 'aún no se ha ejecutado',
    'ok' => 'ok',
    'only from cron' => 'solo desde cron',
    'the administration' => 'la administración',
    'the home page' => 'la página de inicio',
    'the site does not start' => 'el sitio no arranca',
    'Send alert e-mails' => 'Enviar correos de alerta',
    'Send them to' => 'Enviarlos a',
    'Empty = the site e-mail (Settings → General).' => 'Vacío = el correo del sitio (Ajustes → General).',
    '%s was blocked for %d hours after probing for other systems (%s).' => '%s se bloqueó durante %d horas tras sondear otros sistemas (%s).',
    '0 = no limit. 120 is plenty for people; it stops aggressive scrapers.' => '0 = sin límite. 120 es más que suficiente para personas; frena a los scrapers agresivos.',
    'An address that asks for /wp-login.php, /.env and similar addresses of other systems 5 times in an hour is blocked for 24 hours.' => 'Una dirección que solicita /wp-login.php, /.env y direcciones similares de otros sistemas 5 veces en una hora se bloquea durante 24 horas.',
    'Block probing' => 'Bloquear sondeos',
    'Blocked addresses and networks' => 'Direcciones y redes bloqueadas',
    'Blocked countries' => 'Países bloqueados',
    'Blocked for a while' => 'Bloqueadas temporalmente',
    'Country: %s.' => 'País: %s.',
    'Firewall on' => 'Cortafuegos activado',
    'No address is blocked right now.' => 'Ahora mismo no hay ninguna dirección bloqueada.',
    'Nothing refused yet.' => 'Aún no se ha rechazado nada.',
    'One per line, e.g. 203.0.113.7 or 198.51.100.0/24; a comment after #.' => 'Una por línea, p. ej., 203.0.113.7 o 198.51.100.0/24; un comentario después de #.',
    'Refused requests' => 'Solicitudes rechazadas',
    'Requests per minute from one address' => 'Solicitudes por minuto desde una dirección',
    'The address is no longer blocked.' => 'La dirección ya no está bloqueada.',
    'The country of visitors is not known here – blocking countries works only behind Cloudflare or when the hosting sends the country.' => 'Aquí no se conoce el país de los visitantes – el bloqueo por países solo funciona detrás de Cloudflare o cuando el hosting envía el país.',
    'The firewall guards the public site and the Claude connection – never the administration, so you cannot lock yourself out. Addresses of your local network are never blocked.' => 'El cortafuegos protege el sitio público y la conexión con Claude – nunca la administración, así que no puedes quedarte fuera. Las direcciones de tu red local nunca se bloquean.',
    'The last 50; the log keeps 30 days.' => 'Las últimas 50; el registro guarda 30 días.',
    'The site runs behind' => 'El sitio funciona detrás de',
    'These lines are not addresses and are ignored: %s' => 'Estas líneas no son direcciones y se ignoran: %s',
    'Two-letter codes separated by commas, e.g. RU, CN. Only when the country is known (see above).' => 'Códigos de dos letras separados por comas, p. ej., RU, CN. Solo cuando se conoce el país (ver arriba).',
    'Unblock' => 'Desbloquear',
    'Until' => 'Hasta',
    'Why' => 'Motivo',
    'Your address as the site sees it: %s.' => 'Tu dirección tal como la ve el sitio: %s.',
    'blocked address' => 'dirección bloqueada',
    'blocked country' => 'país bloqueado',
    'blocked for a while' => 'bloqueada temporalmente',
    'nothing – visitors connect directly' => 'nada – los visitantes se conectan directamente',
    'probing for other systems' => 'sondeo de otros sistemas',
    'too many requests' => 'demasiadas solicitudes',
    'Domain and mail' => 'Dominio y correo',
    'Checks' => 'Comprobaciones',
    'switched off in the public demo – no request leaves it' => 'desactivado en la demo pública – no sale ninguna solicitud',
    'not checked yet – the background jobs check it once a day, or use Check now below' => 'aún sin comprobar – las tareas en segundo plano lo comprueban una vez al día, o usa Comprobar ahora abajo',
    'the site runs on a local address (%s) – the certificate, the domain registration and the mail DNS records are checked once it has its public address' => 'el sitio funciona en una dirección local (%s) – el certificado, el registro del dominio y los registros DNS del correo se comprueban cuando tenga su dirección pública',
    'Sending domain' => 'Dominio de envío',
    'no sender address – fill in the site e-mail (Settings → General) so the mail records can be checked' => 'no hay dirección de remitente – rellena el correo del sitio (Ajustes → General) para poder comprobar los registros de correo',
    'the DNS records of %s could not be read (the server did not get an answer from its resolver)' => 'no se pudieron leer los registros DNS de %s (el servidor no obtuvo respuesta de su resolvedor)',
    'SPF record' => 'Registro SPF',
    '%s has no SPF record – receiving servers cannot tell that its mail is legitimate and often file it as spam. Add a TXT record on %s: %s' => '%s no tiene registro SPF – los servidores receptores no pueden saber que su correo es legítimo y a menudo lo marcan como spam. Añade un registro TXT en %s: %s',
    'includes the SMTP server %s' => 'incluye el servidor SMTP %s',
    'does not seem to include the SMTP server %s; add %s (or the value your mail provider publishes)' => 'no parece incluir el servidor SMTP %s; añade %s (o el valor que publique tu proveedor de correo)',
    'DMARC record' => 'Registro DMARC',
    '%s has no DMARC record – Gmail and Microsoft require it from senders. Add a TXT record on %s: %s' => '%s no tiene registro DMARC – Gmail y Microsoft lo exigen a los remitentes. Añade un registro TXT en %s: %s',
    'policy p=none only reports; once the reports look right, move to p=quarantine' => 'la política p=none solo informa; cuando los informes se vean bien, pasa a p=quarantine',
    'DKIM signature' => 'Firma DKIM',
    'no DKIM key found under the common selectors (%s). If your mail provider signs with another selector, all is well; otherwise turn DKIM signing on with the provider and publish its key in DNS' => 'no se encontró ninguna clave DKIM con los selectores habituales (%s). Si tu proveedor de correo firma con otro selector, todo está bien; si no, activa la firma DKIM con el proveedor y publica su clave en el DNS',
    'key published under the selector %s' => 'clave publicada con el selector %s',
    'Certificate' => 'Certificado',
    'could not be read from %s: %s' => 'no se pudo leer desde %s: %s',
    'expires in %d days (%s)' => 'caduca en %d días (%s)',
    'expired %d days ago (%s) – browsers warn visitors away from the site' => 'caducó hace %d días (%s) – los navegadores advierten a los visitantes para que no entren en el sitio',
    'renew it, or check that the automatic renewal (Let’s Encrypt) still works' => 'renuévalo o comprueba que la renovación automática (Let’s Encrypt) sigue funcionando',
    'Domain registration' => 'Registro del dominio',
    'the expiry of %s could not be checked: %s' => 'no se pudo comprobar la caducidad de %s: %s',
    '%s – the registry does not publish the expiry date; check it with your registrar' => '%s – el registro no publica la fecha de caducidad; consúltala con tu registrador',
    '%s expires in %d days (%s)' => '%s caduca en %d días (%s)',
    '%s expired %d days ago (%s)' => '%s caducó hace %d días (%s)',
    'renew the domain with your registrar – an expired domain takes the site and its mail down' => 'renueva el dominio con tu registrador – un dominio caducado deja sin servicio el sitio y su correo',
    'The sending domain %s has no SPF record – mail from the forms will land in spam. Add a TXT record: %s' => 'El dominio de envío %s no tiene registro SPF – el correo de los formularios acabará en spam. Añade un registro TXT: %s',
    'The sending domain %s has no DMARC record – Gmail and Microsoft require it. Add a TXT record on %s: %s' => 'El dominio de envío %s no tiene registro DMARC – Gmail y Microsoft lo exigen. Añade un registro TXT en %s: %s',
    'The site certificate expires in %d days – check that it renews.' => 'El certificado del sitio caduca en %d días – comprueba que se renueve.',
    'The site certificate has expired – browsers warn visitors away from the site.' => 'El certificado del sitio ha caducado – los navegadores advierten a los visitantes para que no entren en el sitio.',
    'The domain %s expires in %d days – renew it with the registrar.' => 'El dominio %s caduca en %d días – renuévalo con el registrador.',
    'The domain %s has expired – renew it with the registrar before someone else takes it.' => 'El dominio %s ha caducado – renuévalo con el registrador antes de que otra persona lo registre.',
    'The site runs on a local address – the certificate, the domain and the mail records are checked once it has its public address.' => 'El sitio funciona en una dirección local – el certificado, el dominio y los registros de correo se comprueban cuando tenga su dirección pública.',
    'The domain and mail check has run – the results are in the table above.' => 'Se ha realizado la comprobación del dominio y el correo – los resultados están en la tabla de arriba.',
    'The mail DNS records (SPF, DMARC, DKIM), the site certificate and the domain registration have not been checked yet. The check runs once a day on its own; the results appear in the table above.' => 'Aún no se han comprobado los registros DNS del correo (SPF, DMARC, DKIM), el certificado del sitio ni el registro del dominio. La comprobación se ejecuta sola una vez al día; los resultados aparecen en la tabla de arriba.',
    'Last checked %s. The check runs once a day on its own; the results are in the table above.' => 'Última comprobación: %s. La comprobación se ejecuta sola una vez al día; los resultados están en la tabla de arriba.',
    'Domain, certificate and mail records' => 'Dominio, certificado y registros de correo',
    'Real-user speed (Core Web Vitals)' => 'Velocidad real de usuarios (Core Web Vitals)',
    'Measurements' => 'Mediciones',
    'good' => 'buena',
    'needs improvement' => 'mejorable',
    'poor' => 'mala',
    'No measurements yet – they arrive from visitors’ browsers while the statistics are on.' => 'Aún no hay mediciones – llegan desde los navegadores de los visitantes mientras las estadísticas están activadas.',
    'Speed: the 75th percentile of what real visitors experienced – loading of the main content (LCP, good up to 2.5 s), layout shifts (CLS, good up to 0.1) and the response to interaction (INP, good up to 200 ms); values are the upper edge of a histogram bucket, so they never flatter.' => 'Velocidad: el percentil 75 de lo que vivieron los visitantes reales – carga del contenido principal (LCP, buena hasta 2,5 s), desplazamientos del diseño (CLS, buena hasta 0,1) y respuesta a la interacción (INP, buena hasta 200 ms); los valores son el límite superior de un intervalo del histograma, así que nunca favorecen.',
    'Loading got slower: visitors wait %s s for the main content (p75 LCP) in the last 30 days, %s s in the 30 days before (%d measurements) – check the images, fonts and embeds above the fold.' => 'La carga es más lenta: los visitantes esperan %s s al contenido principal (p75 LCP) en los últimos 30 días, %s s en los 30 días anteriores (%d mediciones) – revisa las imágenes, fuentes e inserciones de la parte visible inicial.',
    'Suspend automatically' => 'Suspender automáticamente',
    'block accounts nobody has used for %d days (never the last administrator)' => 'bloquear cuentas que nadie ha usado en %d días (nunca el último administrador)',
    'revoke Claude connections nobody has used for %d days' => 'revocar conexiones de Claude que nadie ha usado en %d días',
    'Checked once a day. While this is off, System status and the site audit only report unused accounts and connections. A blocked account shows the reason in Users and an administrator can reactivate it; a revoked connection has to be connected again.' => 'Se comprueba una vez al día. Mientras esté desactivado, Estado del sistema y la auditoría del sitio solo informan de cuentas y conexiones sin usar. Una cuenta bloqueada muestra el motivo en Usuarios y un administrador puede reactivarla; una conexión revocada hay que volver a conectarla.',
    'Accounts and access' => 'Cuentas y acceso',
    'Two-step sign-in for administrators' => 'Verificación en dos pasos para administradores',
    '%d administrator(s) sign in without two-step sign-in or a passkey – it is turned on under My account (avatar at the top right)' => '%d administrador(es) inician sesión sin verificación en dos pasos ni passkey – se activa en Mi cuenta (avatar arriba a la derecha)',
    'Unused accounts' => 'Cuentas sin usar',
    'every account has been used in the last %d days' => 'todas las cuentas se han usado en los últimos %d días',
    '%d account(s) unused for %d days – the automatic suspension blocks them on its next daily run' => '%d cuenta(s) sin usar desde hace %d días – la suspensión automática las bloqueará en su próxima ejecución diaria',
    '%d account(s) unused for %d days – block them in Users, or switch on the automatic suspension in Settings → General' => '%d cuenta(s) sin usar desde hace %d días – bloquéalas en Usuarios o activa la suspensión automática en Ajustes → General',
    'last activity %s' => 'última actividad %s',
    'Unused Claude connections' => 'Conexiones de Claude sin usar',
    'every connection has been used in the last %d days' => 'todas las conexiones se han usado en los últimos %d días',
    '%d connection(s) unused for %d days – the automatic suspension revokes them on its next daily run' => '%d conexión(es) sin usar desde hace %d días – la suspensión automática las revocará en su próxima ejecución diaria',
    '%d connection(s) unused for %d days – revoke them in the user’s account, or switch on the automatic suspension in Settings → General' => '%d conexión(es) sin usar desde hace %d días – revócalas en la cuenta del usuario o activa la suspensión automática en Ajustes → General',
    'Connections without an expiry' => 'Conexiones sin caducidad',
    'every personal token has an expiry date' => 'todos los tokens personales tienen fecha de caducidad',
    '%d personal token(s) never expire – a token works until it is revoked; revoke those that are not needed, or create them again with an expiry' => '%d token(s) personal(es) nunca caducan – un token funciona hasta que se revoca; revoca los que no necesites o vuelve a crearlos con caducidad',
    '%d – blocked by an administrator or by the automatic suspension; you can reactivate them in Users' => '%d – bloqueadas por un administrador o por la suspensión automática; puedes reactivarlas en Usuarios',
    'Automatic suspension' => 'Suspensión automática',
    'off – unused accounts and connections are only reported (Settings → General)' => 'desactivada – las cuentas y conexiones sin usar solo se notifican (Ajustes → General)',
    'accounts after %d days' => 'cuentas tras %d días',
    'Claude connections after %d days' => 'conexiones de Claude tras %d días',
    'The account %s has not been used for %d days (last activity %s) – block it, or let the automatic suspension do it.' => 'La cuenta %s no se ha usado en %d días (última actividad %s) – bloquéala o deja que lo haga la suspensión automática.',
    'The Claude connection “%s” of %s has not been used for %d days – revoke it, or let the automatic suspension do it.' => 'La conexión de Claude “%s” de %s no se ha usado en %d días – revócala o deja que lo haga la suspensión automática.',
    'Unused accounts and Claude connections are only reported – switch on the automatic suspension (Settings → General) so that leftover access closes itself.' => 'Las cuentas y conexiones de Claude sin usar solo se notifican – activa la suspensión automática (Ajustes → General) para que los accesos sobrantes se cierren solos.',
    'The account is not blocked.' => 'La cuenta no está bloqueada.',
    'The account has been reactivated – the user can sign in again.' => 'La cuenta se ha reactivado – el usuario puede volver a iniciar sesión.',
    'The connection has been revoked – Claude can no longer sign in with it.' => 'La conexión se ha revocado – Claude ya no puede iniciar sesión con ella.',
    'The connection no longer exists.' => 'La conexión ya no existe.',
    'Blocked automatically on %s – nobody had used the account for %d days. An administrator can reactivate it.' => 'Bloqueada automáticamente el %s – nadie había usado la cuenta en %d días. Un administrador puede reactivarla.',
    'blocked automatically' => 'bloqueada automáticamente',
    'Reactivate' => 'Reactivar',
    'Blocked automatically on %s – nobody had used the account for %d days. Untick the box and save to reactivate the account.' => 'Bloqueada automáticamente el %s – nadie había usado la cuenta en %d días. Desmarca la casilla y guarda para reactivar la cuenta.',
    'Claude connections' => 'Conexiones de Claude',
    'Personal tokens and connected applications of this account. A connection nobody has used for %d days is reported in System status; revoke what is not needed any more.' => 'Tokens personales y aplicaciones conectadas de esta cuenta. Una conexión que nadie ha usado en %d días se notifica en Estado del sistema; revoca lo que ya no necesites.',
    'Revoke the connection? Claude will no longer be able to sign in with it.' => '¿Revocar la conexión? Claude ya no podrá iniciar sesión con ella.',
    'personal token' => 'token personal',
    'connected application' => 'aplicación conectada',
    'last used %s' => 'último uso %s',
    'never used' => 'nunca usado',
    'valid until %s' => 'válido hasta %s',
    'no expiry' => 'sin caducidad',
    'Revoke' => 'Revocar',
    'expired %s' => 'caducó el %s',
    'Valid for' => 'Válido durante',
    '1 year' => '1 año',
    '%d days' => '%d días',
    'An expired token stops working on its own; you then create a new one. A token nobody uses for %d days is reported in System status.' => 'Un token caducado deja de funcionar por sí solo; entonces creas uno nuevo. Un token que nadie usa en %d días se notifica en Estado del sistema.',
    'connection revoked automatically' => 'conexión revocada automáticamente',
    'account reactivated' => 'cuenta reactivada',
    'connection revoked' => 'conexión revocada',
    'An account not used for %d days was suspended (user #%d).' => 'Se suspendió una cuenta sin usar en %d días (usuario #%d).',
    'A Claude connection not used for %d days was revoked (user #%d).' => 'Se revocó una conexión de Claude sin usar en %d días (usuario #%d).',
    'Suspending unused accounts and connections' => 'Suspender cuentas y conexiones sin usar',
    'Fleet console' => 'Consola de sitios',
    'Makes this installation the console of your other Kaleta sites: they report to it every hour, it shows all of them on one screen sorted by what needs attention, checks that they are up and decides when they install a new version – test sites first, the rest two days later. It never gets into the sites.' => 'Convierte esta instalación en la consola de tus otros sitios Kaleta: le informan cada hora, los muestra todos en una sola pantalla ordenados por lo que requiere atención, comprueba que estén en línea y decide cuándo instalan una versión nueva – primero los sitios de prueba, el resto dos días después. Nunca entra en los sitios.',
    '%s was paired with the console.' => '%s se emparejó con la consola.',
    '%s runs version %s.' => '%s funciona con la versión %s.',
    '%s is no longer in the console.' => '%s ya no está en la consola.',
    '%s answers again.' => '%s vuelve a responder.',
    '%s does not answer (%s).' => '%s no responde (%s).',
    'no answer' => 'sin respuesta',
    '%s has not sent its heartbeat for more than a day.' => '%s no ha enviado su señal de vida en más de un día.',
    'This is not a pairing key of a Kaleta console (it starts with kaleta-console:).' => 'Esta no es una clave de emparejamiento de una consola Kaleta (empieza por kaleta-console:).',
    'Fill in the site address in Settings → General first.' => 'Primero rellena la dirección del sitio en Ajustes → General.',
    'The console refused the pairing: %s' => 'La consola rechazó el emparejamiento: %s',
    'The site was paired with the fleet console %s.' => 'El sitio se emparejó con la consola de sitios %s.',
    'The new version is allowed on %d sites; each installs it with its next report (within an hour).' => 'La nueva versión está permitida en %d sitios; cada uno la instala con su próximo informe (en menos de una hora).',
    'The site is not in the console.' => 'El sitio no está en la consola.',
    'Saved.' => 'Guardado.',
    'Checked.' => 'Comprobado.',
    'The site was removed from the console. It stops reporting with its next report; pair it again to bring it back.' => 'El sitio se quitó de la consola. Deja de informar con su próximo informe; emparéjalo de nuevo para recuperarlo.',
    'A fleet console is another Kaleta installation that shows all your sites on one screen. This site sends it a signed report every hour – version, health, background jobs, backups, enquiries waiting and visits, never names or the content of enquiries. The console cannot get into this site.' => 'Una consola de sitios es otra instalación de Kaleta que muestra todos tus sitios en una sola pantalla. Este sitio le envía un informe firmado cada hora – versión, estado, tareas en segundo plano, copias de seguridad, consultas pendientes y visitas, nunca nombres ni el contenido de las consultas. La consola no puede entrar en este sitio.',
    'Pair with a console' => 'Emparejar con una consola',
    'Pairing key' => 'Clave de emparejamiento',
    'On the console: Fleet → Add a site. The key is valid for 24 hours and only once.' => 'En la consola: Consola de sitios → Añadir un sitio. La clave es válida 24 horas y una sola vez.',
    'The console decides when new versions install here' => 'La consola decide cuándo se instalan aquí las versiones nuevas',
    'Test sites first, the rest two days later when nothing broke. Only versions signed by the Kaleta publisher install, as always.' => 'Primero los sitios de prueba, el resto dos días después si no se rompió nada. Como siempre, solo se instalan versiones firmadas por el editor de Kaleta.',
    'Pair' => 'Emparejar',
    'Console' => 'Consola',
    'Key fingerprints' => 'Huellas de las claves',
    'console %s, this site %s' => 'consola %s, este sitio %s',
    'Last report' => 'Último informe',
    'not sent yet' => 'aún no enviado',
    'Allowed update' => 'Actualización permitida',
    'Version %s – it installs with the next background run.' => 'Versión %s – se instala con la próxima ejecución en segundo plano.',
    'Without it, updates work as before: security releases install themselves when that is on in Backups and updates, others you install yourself.' => 'Sin ello, las actualizaciones funcionan como antes: las de seguridad se instalan solas si está activado en Copias de seguridad y actualizaciones; las demás las instalas tú.',
    'Save the choice about updates' => 'Guardar la elección sobre actualizaciones',
    'Send a report now' => 'Enviar un informe ahora',
    'The site will stop reporting to the console. Continue?' => 'El sitio dejará de informar a la consola. ¿Continuar?',
    'Disconnect from the console' => 'Desconectar de la consola',
    'Paste this pairing key on the site in Settings → Fleet console. It is valid for 24 hours and only once; it is not shown again.' => 'Pega esta clave de emparejamiento en el sitio, en Ajustes → Consola de sitios. Es válida 24 horas y una sola vez; no se vuelve a mostrar.',
    'No site reports to this console yet. Make a pairing key and paste it on the site.' => 'Aún no hay ningún sitio que informe a esta consola. Crea una clave de emparejamiento y pégala en el sitio.',
    'All %d sites are fine.' => 'Los %d sitios están bien.',
    '%d of %d sites need attention.' => '%d de %d sitios requieren atención.',
    'The newest version: %s.' => 'La versión más reciente: %s.',
    'Add a site' => 'Añadir un sitio',
    'Check all now' => 'Comprobar todos ahora',
    'Every site that lets the console decide installs version %s within an hour, without waiting for the test sites. Continue?' => 'Todos los sitios que dejan decidir a la consola instalarán la versión %s en menos de una hora, sin esperar a los sitios de prueba. ¿Continuar?',
    'Allow the new version everywhere now' => 'Permitir ahora la nueva versión en todos',
