    'test site' => 'sitio de prueba',
    'allowed %s' => 'permitida %s',
    'Sites report every hour; the console checks every 5 minutes that each home page answers. Problems reach you by the alert e-mail (System status → Alerts).' => 'Los sitios informan cada hora; la consola comprueba cada 5 minutos que cada página de inicio responde. Los problemas te llegan por el correo de alerta (Estado del sistema → Alertas).',
    'Administration of the site' => 'Administración del sitio',
    'Needs attention:' => 'Requiere atención:',
    'not checked yet' => 'aún sin comprobar',
    'no report yet' => 'aún sin informe',
