    'The site no longer reports to the console.' => 'El sitio ya no informa a la consola.',
    'Report to the fleet console' => 'Informe a la consola de sitios',
    'Fleet console: are the sites up' => 'Consola de sitios: ¿están en línea los sitios?',
    'Fleet' => 'Consola de sitios',
    'The console did not confirm the report.' => 'La consola no confirmó el informe.',
    'The console does not know this site any more – pair it again.' => 'La consola ya no reconoce este sitio – vuelve a emparejarlo.',
    'Version' => 'Versión',
    'Ring' => 'Anillo',
    'Monthly report' => 'Informe mensual',
    'In the first days of each month the site e-mails a short report about the previous month: traffic, enquiries and sign-ups, updates, backups, changes made by people and by Claude, the problems right now and what needs your decision. Counts and page addresses only – never names, e-mail addresses or the contents of enquiries, so the report can be forwarded. With the agency details from the General tab it carries the agency’s branding.' => 'En los primeros días de cada mes, el sitio envía por correo un breve informe del mes anterior: tráfico, consultas y suscripciones, actualizaciones, copias de seguridad, cambios hechos por personas y por Claude, los problemas actuales y lo que requiere tu decisión. Solo cifras y direcciones de páginas – nunca nombres, direcciones de correo ni el contenido de las consultas, así que el informe se puede reenviar. Con los datos de la agencia de la pestaña General, lleva la marca de la agencia.',
    'Send a monthly report by e-mail' => 'Enviar un informe mensual por correo',
    'One address per line or separated by commas, at most 10. Empty = the site e-mail (Settings → General).' => 'Una dirección por línea o separadas por comas, como máximo 10. Vacío = el correo del sitio (Ajustes → General).',
    'Preview last month' => 'Vista previa del mes pasado',
    'Send last month’s report now' => 'Enviar ahora el informe del mes pasado',
    'Save the settings first – sending uses the saved recipients.' => 'Guarda primero los ajustes – el envío usa los destinatarios guardados.',
    'There is nobody to send the report to – fill in the recipients, or the site e-mail on the General tab.' => 'No hay nadie a quien enviar el informe – rellena los destinatarios o el correo del sitio en la pestaña General.',
    'The report has been handed over for delivery to %d recipient(s).' => 'El informe se ha entregado para su envío a %d destinatario(s).',
    'Monthly report by e-mail' => 'Informe mensual por correo',
    'The monthly report for %s went to %d recipient(s).' => 'El informe mensual de %s se envió a %d destinatario(s).',
