    'December' => 'diciembre',
    'Website report – %s – %s' => 'Informe del sitio web – %s – %s',
    'Website report – %s' => 'Informe del sitio web – %s',
    '%d enquiry(ies) nobody has opened yet' => '%d consulta(s) que nadie ha abierto todavía',
    '%d problem(s) in System status need fixing' => '%d problema(s) en Estado del sistema por corregir',
    'Needs your decision' => 'Requiere tu decisión',
    'Most read pages' => 'Páginas más leídas',
    'Visitors came from' => 'Los visitantes llegaron desde',
    'Compared with the month before.' => 'En comparación con el mes anterior.',
    'The built-in statistics are off (Settings → Analytics), so there are no traffic figures.' => 'Las estadísticas integradas están desactivadas (Ajustes → Analítica), así que no hay cifras de tráfico.',
    'Enquiries received' => 'Consultas recibidas',
