    'Newsletter sign-ups' => 'Suscripciones al boletín',
    'Enquiries and sign-ups' => 'Consultas y suscripciones',
    'none this month' => 'ninguna este mes',
    '%d made, %d failed' => '%d realizadas, %d fallidas',
    'the last one %s' => 'la última %s',
    '%d by people, %d by Claude' => '%d por personas, %d por Claude',
    'Changes in the administration' => 'Cambios en la administración',
    'Care of the site' => 'Mantenimiento del sitio',
    'Problems right now' => 'Problemas actuales',
    'None – every check in System status is fine.' => 'Ninguno – todas las comprobaciones de Estado del sistema están bien.',
    'Details are in System status' => 'Los detalles están en Estado del sistema',
    'Sent once a month by the website %s. Switch it off or change the recipients in Settings → Mail.' => 'Enviado una vez al mes por el sitio web %s. Desactívalo o cambia los destinatarios en Ajustes → Correo.',
    'The monthly report by e-mail went out (the month and how many recipients).' => 'Se envió el informe mensual por correo (el mes y cuántos destinatarios).',
    'April' => 'abril',
    'August' => 'agosto',
    'September' => 'septiembre',
    'November' => 'noviembre',
    'Backups' => 'Copias de seguridad',
    'The fact %s changed.' => 'El dato clave %s ha cambiado.',
    'The key may contain lowercase letters, digits and _ and must start with a letter (2–40 characters).' => 'La clave puede contener letras minúsculas, dígitos y _ y debe empezar por una letra (2–40 caracteres).',
    'This fact comes from the settings (Business details) – change it there.' => 'Este dato clave procede de los ajustes (Datos de la empresa) – cámbialo allí.',
    'Create the fact in the default language first.' => 'Crea primero el dato clave en el idioma predeterminado.',
    'amount of money' => 'importe',
    'web address' => 'dirección web',
    'founding date' => 'fecha de fundación',
    'number of employees' => 'número de empleados',
    'price range' => 'rango de precios',
    'area served' => 'zona de servicio',
    'slogan' => 'eslogan',
    'award' => 'premio',
    'languages' => 'idiomas',
    'founder' => 'fundador',
    'text' => 'texto',
    'number' => 'número',
    'date' => 'fecha',
    'year' => 'año',
    'phone' => 'teléfono',
    'Company name' => 'Nombre de la empresa',
    'Current year' => 'Año actual',
    'The fact is saved.' => 'El dato clave se ha guardado.',
    'The fact does not exist.' => 'El dato clave no existe.',
    'The fact is deleted.' => 'El dato clave se ha eliminado.',
    'The fact is deleted – some content still uses it and shows nothing there now; the site audit lists it.' => 'El dato clave se ha eliminado – algún contenido aún lo usa y ahora no muestra nada ahí; la auditoría del sitio lo indica.',
    'Write a fact once and use it everywhere: {{fact.key}} in a text, a button or a link (tel:{{fact.company_phone}}). The site fills in the value when a page is shown; change it here and every page says the new value.' => 'Escribe un dato clave una vez y úsalo en todas partes: {{fact.key}} en un texto, un botón o un enlace (tel:{{fact.company_phone}}). El sitio rellena el valor al mostrar una página; cámbialo aquí y todas las páginas mostrarán el nuevo valor.',
    'New fact' => 'Nuevo dato clave',
    'Sentences with numbers that are not facts yet' => 'Frases con números que aún no son datos clave',
    'No facts yet. Typical ones: the year the company was founded, the number of projects or clients, a price from, the warranty, the area you serve.' => 'Aún no hay datos clave. Algunos típicos: el año de fundación de la empresa, el número de proyectos o clientes, un precio desde, la garantía, la zona en la que trabajas.',
    'Fact' => 'Dato clave',
    'Value' => 'Valor',
    'Token' => 'Token',
    'Used' => 'Usado',
    'Changed' => 'Modificado',
    'From the settings' => 'De los ajustes',
    'not filled in' => 'sin rellenar',
    'The company details are changed in Business details. Claude reads and changes facts with list_facts and save_fact.' => 'Los datos de la empresa se cambian en Datos de la empresa. Claude lee y cambia los datos clave con list_facts y save_fact.',
    'All facts' => 'Todos los datos clave',
    'No text on the site states the old value “%s” any more.' => 'Ningún texto del sitio indica ya el valor antiguo “%s”.',
    'The old value “%s” is still written as plain text in %d places – replace it with the token so it changes by itself next time:' => 'El valor antiguo “%s” sigue escrito como texto simple en %d lugares – sustitúyelo por el token para que la próxima vez cambie solo:',
    'e.g. Founded' => 'p. ej., Fundada en',
    'Lowercase letters, digits and _. In content: {{fact.key}}. It cannot change later.' => 'Letras minúsculas, dígitos y _. En el contenido: {{fact.key}}. No se puede cambiar después.',
    'Type' => 'Tipo',
    'A number is shown with the thousands separator of the language, a date in its format, an amount as 1 500 CZK (enter 1500 CZK).' => 'Un número se muestra con el separador de miles del idioma, una fecha en su formato y un importe como 1 500 CZK (introduce 1500 CZK).',
    'Empty = the same as the default value.' => 'Vacío = igual que el valor predeterminado.',
    'For search engines' => 'Para buscadores',
    'Adds the fact to the company in the structured data (schema.org) search engines and AI assistants read.' => 'Añade el dato clave a la empresa en los datos estructurados (schema.org) que leen los buscadores y los asistentes de IA.',
    'Where the number comes from – for you and your colleagues, not shown on the site.' => 'De dónde viene el número – para ti y tus colegas, no se muestra en el sitio.',
    'Delete the fact? Content that uses it will show nothing in its place.' => '¿Eliminar el dato clave? El contenido que lo usa no mostrará nada en su lugar.',
    'Delete' => 'Eliminar',
    'Not used yet. Write {{fact.%s}} into a text, a button or a link.' => 'Aún sin usar. Escribe {{fact.%s}} en un texto, un botón o un enlace.',
    'Changes' => 'Cambios',
    'Sentences with numbers, years and amounts written as plain text. When one of them changes – a new year, another project – you have to find every place yourself. Make it a fact and write {{fact.key}} instead.' => 'Frases con números, años e importes escritos como texto simple. Cuando uno de ellos cambia – un año nuevo, otro proyecto – tienes que buscar tú cada lugar. Conviértelo en un dato clave y escribe {{fact.key}} en su lugar.',
    'No such sentences – the numbers on the site are facts already.' => 'No hay frases así – los números del sitio ya son datos clave.',
    'Sentence' => 'Frase',
    'Facts' => 'Datos clave',
    'The value does not fit the type of the fact (%s).' => 'El valor no corresponde al tipo del dato clave (%s).',
    'The fact {{fact.%s}} does not exist – visitors see nothing in its place. Create it in Facts, or fix the key.' => 'El dato clave {{fact.%s}} no existe – los visitantes no ven nada en su lugar. Créalo en Datos clave o corrige la clave.',
    'Open now (and until when)' => 'Abierto ahora (y hasta cuándo)',
    'Exceptions to the opening hours' => 'Excepciones al horario de apertura',
    'Holidays, a closed day, shorter hours. The site shows them under the opening hours, knows whether it is open now, and shows a notice bar a few days ahead until the exception ends.' => 'Vacaciones, un día cerrado, un horario más corto. El sitio las muestra bajo el horario de apertura, sabe si está abierto ahora y muestra una barra de aviso unos días antes hasta que termina la excepción.',
    'notice %d days ahead' => 'aviso %d días antes',
    'no notice' => 'sin aviso',
    'From' => 'Desde',
    'One day: fill in only the first date.' => 'Un solo día: rellena solo la primera fecha.',
    'Closed' => 'Cerrado',
    'Closed all day' => 'Cerrado todo el día',
    'Or open' => 'O abierto',
    'When it is open with different hours: uncheck Closed and enter the hours, more ranges with a comma.' => 'Si abre con otro horario: desmarca Cerrado e introduce el horario; varios tramos separados por comas.',
    'e.g. Christmas' => 'p. ej., Navidad',
    'Notice bar' => 'Barra de aviso',
    'days ahead' => 'días antes',
    '0 = no notice bar.' => '0 = sin barra de aviso.',
    'Add the exception' => 'Añadir la excepción',
    'The exception is saved.' => 'La excepción se ha guardado.',
    'The exception is deleted.' => 'La excepción se ha eliminado.',
    'Enter the dates as YYYY-MM-DD; the last day must not be before the first one.' => 'Introduce las fechas como AAAA-MM-DD; el último día no puede ser anterior al primero.',
    'Enter the hours of the exception, e.g. 9:00-12:00 (more ranges with a comma), or mark the days as closed.' => 'Introduce el horario de la excepción, p. ej., 9:00-12:00 (varios tramos separados por comas), o marca los días como cerrados.',
    'closed' => 'cerrado',
    'Open now, until %s' => 'Abierto ahora, hasta las %s',
    'Closed now' => 'Cerrado ahora',
    'Closed now, opens today at %s' => 'Cerrado ahora, abre hoy a las %s',
    'Closed now, opens tomorrow at %s' => 'Cerrado ahora, abre mañana a las %s',
    'Closed now, opens on %s at %s' => 'Cerrado ahora, abre el %s a las %s',
    'item of another collection' => 'elemento de otra colección',
    'Linked collection' => 'Colección vinculada',
    'An item of another collection links two collections – a person to a branch, a reference to a service: choose the type and the linked collection. {{key}} shows the linked item\'s name, {{key_url}} its page. On the page of the linked item, a Collection list filtered by the field with the value {{seo}} lists everything linked to it.' => 'Un elemento de otra colección vincula dos colecciones – una persona con una sucursal, una referencia con un servicio: elige el tipo y la colección vinculada. {{key}} muestra el nombre del elemento vinculado, {{key_url}} su página. En la página del elemento vinculado, una Lista de la colección filtrada por el campo con el valor {{seo}} muestra todo lo vinculado a él.',
    'Hidden items redirect to' => 'Los elementos ocultos redirigen a',
    'When an item is hidden or deleted – a person who left, a product no longer sold – its page leads here (301) instead of “page not found”. Empty = page not found.' => 'Cuando un elemento se oculta o se elimina – una persona que se fue, un producto que ya no se vende – su página lleva aquí (301) en lugar de a “página no encontrada”. Vacío = página no encontrada.',
    'The redirect of hidden items must be an address on the site (/team) or https://…' => 'La redirección de los elementos ocultos debe ser una dirección del sitio (/team) o https://…',
    'Unknown template.' => 'Plantilla desconocida.',
    'The collection was created – add the first items.' => 'Se ha creado la colección – añade los primeros elementos.',
    'New team (people)' => 'Nuevo equipo (personas)',
    'Photo, role, languages, phone, e-mail, absence and a page for each person; the page of someone who left leads to the team page.' => 'Foto, cargo, idiomas, teléfono, correo, ausencia y una página para cada persona; la página de alguien que se fue lleva a la página del equipo.',
    'Languages' => 'Idiomas',
    'On leave' => 'Ausente',
    'About' => 'Sobre mí',
    'The token {{%s}} cannot be computed – visitors see nothing in its place. years_since takes a year, a date (YYYY-MM-DD) or a fact with one; count takes the address of a collection, or news.' => 'El token {{%s}} no se puede calcular – los visitantes no ven nada en su lugar. years_since admite un año, una fecha (AAAA-MM-DD) o un dato clave con uno de ellos; count admite la dirección de una colección o news.',
    'The number %s is typed in – make it a fact ({{fact.key}}) or a count, so it stays true.' => 'El número %s está escrito a mano – conviértelo en un dato clave ({{fact.key}}) o en un recuento para que siga siendo cierto.',
    'A big number with a label that counts up when shown (years of experience, customers, projects). The number may be a fact or a computed token, so it stays true.' => 'Un número grande con una etiqueta que cuenta hacia arriba al mostrarse (años de experiencia, clientes, proyectos). El número puede ser un dato clave o un token calculado, para que siga siendo cierto.',
    'Number – or a fact or count token ({{fact.projects}}, {{years_since:2004}}, {{count:reference}})' => 'Número – o un token de dato clave o de recuento ({{fact.projects}}, {{years_since:2004}}, {{count:reference}})',
    'Computed' => 'Calculados',
    'Numbers the site works out when a page is shown, so they never go stale – years since a date and counts of what is on the site. Write the token into a text, or into the number of a counter.' => 'Números que el sitio calcula al mostrar una página, para que nunca queden desfasados – años desde una fecha y recuentos de lo que hay en el sitio. Escribe el token en un texto o en el número de un contador.',
    'Shows now' => 'Muestra ahora',
    'What it counts' => 'Qué cuenta',
    'nothing – the site has no such collection or fact yet' => 'nada – el sitio aún no tiene esa colección o dato clave',
    'Full years since a year or a date (2004 or 2004-05-01).' => 'Años completos desde un año o una fecha (2004 o 2004-05-01).',
    'The same from a fact whose value is a year or a date.' => 'Lo mismo a partir de un dato clave cuyo valor es un año o una fecha.',
    'The number of visible items of a collection (by its address).' => 'El número de elementos visibles de una colección (por su dirección).',
    'The number of published news items.' => 'El número de noticias publicadas.',
    'Door sign' => 'Cartel de la puerta',
    'The exception no longer exists.' => 'La excepción ya no existe.',
    'Visible until' => 'Visible hasta',
    'Review by' => 'Revisar antes del',
    'On this day the site audit and the alert e-mail remind you to check it.' => 'Ese día, la auditoría del sitio y el correo de alerta te recuerdan que lo revises.',
    'Hides itself the day after.' => 'Se oculta solo al día siguiente.',
    'Asks for a review on this day.' => 'Pide una revisión ese día.',
    'true until %s' => 'vigente hasta %s',
    'review by %s' => 'revisar antes del %s',
    '“%s” was true until %s and hid itself.' => '“%s” era vigente hasta %s y se ocultó solo.',
    '“%s” asks for a review by %s.' => '“%s” pide una revisión antes del %s.',
    'Asked for a review by %s.' => 'Pidió una revisión antes del %s.',
    'Content that expires or asks for review' => 'Contenido que caduca o pide revisión',
    'A page, news item, collection item or pop-up was true until a past day and hid itself.' => 'Una página, noticia, elemento de colección o pop-up era vigente hasta un día pasado y se ocultó solo.',
    'A page, news item, collection item or pop-up asks for a review (its review-by day has come).' => 'Una página, noticia, elemento de colección o pop-up pide una revisión (ha llegado su fecha de revisión).',
    'E-mail signature: %s' => 'Firma de correo: %s',
    'Made from the record of %s in the look of your site. When the record or the site changes, open this page again and copy the signature anew.' => 'Creada a partir del registro de %s con la apariencia de tu sitio. Cuando cambie el registro o el sitio, vuelve a abrir esta página y copia la firma de nuevo.',
    'Copy signature' => 'Copiar firma',
    'Back to the item' => 'Volver al elemento',
    'Plain-text version' => 'Versión de texto simple',
    'For mail clients and places that take no formatting – the Copy button puts it on the clipboard together with the formatted signature.' => 'Para clientes de correo y lugares que no admiten formato – el botón Copiar la pone en el portapapeles junto con la firma con formato.',
    'Where to paste it' => 'Dónde pegarla',
    'Settings (the gear) → See all settings → General → Signature → Create new, paste the signature into the box (Ctrl+V, on a Mac ⌘V) and click Save Changes at the bottom.' => 'Configuración (el engranaje) → Ver todos los ajustes → General → Firma → Crear, pega la firma en el cuadro (Ctrl+V, en Mac ⌘V) y haz clic en Guardar cambios abajo.',
    'New message → Signature → Signatures… (Outlook on the web: Settings → Mail → Compose and reply), paste the signature and save.' => 'Mensaje nuevo → Firma → Firmas… (Outlook en la web: Configuración → Correo → Redactar y responder), pega la firma y guarda.',
    'Mail → Settings → Signatures, choose the account, click +, paste the signature and untick “Always match my default message font”.' => 'Mail → Ajustes → Firmas, elige la cuenta, haz clic en +, pega la firma y desmarca “Usar siempre mi tipo de letra predeterminado”.',
    'The photo and the logo load from your website, so they show as long as they stay there.' => 'La foto y el logotipo se cargan desde tu sitio web, así que se muestran mientras sigan ahí.',
    'E-mail signature' => 'Firma de correo',
    'The system has been updated to version %s.' => 'El sistema se ha actualizado a la versión %s.',
