    'New events calendar' => 'Nuevo calendario de eventos',
    'Dates, place, repetition, registration with a capacity and iCal; past events archive themselves and a repeating event moves to its next date.' => 'Fechas, lugar, repetición, inscripción con aforo e iCal; los eventos pasados se archivan solos y un evento periódico pasa a su siguiente fecha.',
