    'You can compare up to four products.' => 'Puedes comparar hasta cuatro productos.',
    'Add to enquiry' => 'Añadir a la consulta',
    'Variant' => 'Variante',
    'Comparison' => 'Comparación',
    'Back to %s' => 'Volver a %s',
    'Add at least one product to the enquiry.' => 'Añade al menos un producto a la consulta.',
    'The enquiry is empty – add products with Add to enquiry.' => 'La consulta está vacía – añade productos con Añadir a la consulta.',
    'Product enquiry' => 'Consulta de productos',
    'Thank you, we have received your enquiry. We will get back to you with prices and availability.' => 'Gracias, hemos recibido tu consulta. Te responderemos con precios y disponibilidad.',
    'Products' => 'Productos',
    'Your enquiry' => 'Tu consulta',
    'Datasheet' => 'Ficha técnica',
    'Add to enquiry – shows on the pages and cards of a products collection.' => 'Añadir a la consulta – se muestra en las páginas y tarjetas de una colección de productos.',
    'A product\'s variant, quantity and a button that adds it to the enquiry basket, with a box to compare products.' => 'La variante y la cantidad de un producto y un botón que lo añade a la cesta de consulta, con un cuadro para comparar productos.',
    'Page with the enquiry form (empty = the products list page)' => 'Página con el formulario de consulta (vacío = la página de la lista de productos)',
    'Compare box' => 'Cuadro de comparación',
    'parameters (Name: value per line)' => 'parámetros (Nombre: valor por línea)',
    'enquiry basket (products added with Add to enquiry)' => 'cesta de consulta (productos añadidos con Añadir a la consulta)',
    'New product catalogue' => 'Nuevo catálogo de productos',
    'Products with parameters to compare, variants and a datasheet; visitors collect them in an enquiry basket instead of a checkout.' => 'Productos con parámetros para comparar, variantes y ficha técnica; los visitantes los reúnen en una cesta de consulta en lugar de pasar por caja.',
    'Parameters' => 'Parámetros',
    'Variants' => 'Variantes',
    'Price note' => 'Nota de precio',
    'Availability' => 'Disponibilidad',
    'Code' => 'Código',
    'Industry blueprint' => 'Plantilla sectorial',
    'A blueprint sets the site up for a kind of business: the ready-made collections it needs, the facts to fill in, questions for the owner, checks in the site audit and instructions for Claude.' => 'Una plantilla sectorial prepara el sitio para un tipo de negocio: las colecciones predefinidas que necesita, los datos clave que hay que rellenar, preguntas para el propietario, comprobaciones en la auditoría del sitio e instrucciones para Claude.',
    'Applied' => 'Aplicada',
    'Questions for the owner' => 'Preguntas para el propietario',
    'Save answers' => 'Guardar respuestas',
    'Everything the blueprint checks is in place.' => 'Todo lo que comprueba la plantilla sectorial está en orden.',
    'Apply a blueprint' => 'Aplicar una plantilla sectorial',
    'No other blueprints are available. Upload a blueprint file below.' => 'No hay otras plantillas sectoriales disponibles. Sube un archivo de plantilla sectorial abajo.',
    'Blueprint file (.json)' => 'Archivo de plantilla sectorial (.json)',
    'Apply' => 'Aplicar',
    'Export this site as a blueprint' => 'Exportar este sitio como plantilla sectorial',
    'The presets your collections come from, your facts without their values, and the questions, checks and instructions of the applied blueprints.' => 'Los ajustes predefinidos de los que proceden tus colecciones, tus datos clave sin sus valores, y las preguntas, comprobaciones e instrucciones de las plantillas sectoriales aplicadas.',
    'Blueprint' => 'Plantilla sectorial',
    'The file is not a valid blueprint: %s' => 'El archivo no es una plantilla sectorial válida: %s',
    'Choose a blueprint or a file.' => 'Elige una plantilla sectorial o un archivo.',
    'The blueprint is applied: %d new collections (with hidden list pages) and %d facts. Answer its questions below.' => 'Se ha aplicado la plantilla sectorial: %d colecciones nuevas (con páginas de lista ocultas) y %d datos clave. Responde a sus preguntas abajo.',
    'The blueprint is removed – its collections and facts stay.' => 'Se ha quitado la plantilla sectorial – sus colecciones y datos clave se mantienen.',
    'The answers are saved – the site states them as facts.' => 'Las respuestas se han guardado – el sitio las presenta como datos clave.',
    'The key may contain lowercase letters, digits and _ (2–40 characters).' => 'La clave puede contener letras minúsculas, dígitos y _ (2–40 caracteres).',
    'Industry checks' => 'Comprobaciones del sector',
    'Job openings' => 'Ofertas de empleo',
    'New job openings' => 'Nuevas ofertas de empleo',
    'Location, employment type, salary, description, requirements and an application form with a CV on each job page; a job hides itself after its closing date.' => 'Ubicación, tipo de contrato, salario, descripción, requisitos y un formulario de candidatura con CV en cada página de oferta; una oferta se oculta sola tras su fecha de cierre.',
    'Employment type' => 'Tipo de contrato',
    'Salary from' => 'Salario desde',
    'Salary to' => 'Salario hasta',
    'Salary unit' => 'Unidad del salario',
    'Requirements' => 'Requisitos',
    'We offer' => 'Ofrecemos',
    'Start date' => 'Fecha de incorporación',
    'Salary' => 'Salario',
    'Apply for this job' => 'Solicitar este empleo',
    'Job application' => 'Candidatura',
    'Send application' => 'Enviar candidatura',
    'Thank you for your application. We will get back to you.' => 'Gracias por tu candidatura. Te responderemos.',
    'CV' => 'CV',
    'A few words about you' => 'Unas palabras sobre ti',
    'I agree to the processing of my personal data for the purpose of this selection procedure.' => 'Acepto el tratamiento de mis datos personales para este proceso de selección.',
    'Job opening' => 'Oferta de empleo',
    'Location (town)' => 'Ubicación (localidad)',
    'Salary unit (per month / per hour)' => 'Unidad del salario (al mes / por hora)',
    'Job opening without a closing date – set “Visible until” to the application deadline: the job then hides itself and search engines get validThrough, which they need to tell an open job from an expired one.' => 'Oferta de empleo sin fecha de cierre – ajusta “Visible hasta” al plazo de candidatura: la oferta se ocultará sola y los buscadores recibirán validThrough, que necesitan para distinguir una oferta abierta de una caducada.',
    '%d job applications older than %d months were deleted, including the CVs.' => 'Se eliminaron %d candidaturas con más de %d meses, incluidos los CV.',
    'Delete job applications after' => 'Eliminar candidaturas tras',
    'Applications sent from the pages of a Job openings collection carry CVs and are usually kept only for a limited time after the selection. 0 = like other enquiries.' => 'Las candidaturas enviadas desde las páginas de una colección de Ofertas de empleo incluyen CV y normalmente solo se conservan durante un tiempo limitado tras la selección. 0 = como las demás consultas.',
    'Usual practice in %s: %d months – check with your lawyer.' => 'Práctica habitual en %s: %d meses – consúltalo con tu abogado.',
    'Documents' => 'Documentos',
    'New document library' => 'Nueva biblioteca de documentos',
    'Price lists, terms, manuals and forms: a file with its version, summary and date of issue, a stable download address that survives a new edition, download counts and an expiry date; the previous versions stay on the document’s page.' => 'Listas de precios, condiciones, manuales y formularios: un archivo con su versión, resumen y fecha de emisión, una dirección de descarga estable que sobrevive a una nueva edición, recuentos de descargas y una fecha de caducidad; las versiones anteriores se mantienen en la página del documento.',
    'Issued' => 'Emitido',
    'Downloads (30 days / total)' => 'Descargas (30 días / total)',
    'Downloads of the stable address /…/latest: the last 30 days / total. Bots are not counted.' => 'Descargas de la dirección estable /…/latest: los últimos 30 días / total. No se cuentan los bots.',
    'The stable address of the current file – it stays the same when a new version replaces the file.' => 'La dirección estable del archivo actual – sigue siendo la misma cuando una nueva versión sustituye el archivo.',
    'Document expires soon' => 'El documento caduca pronto',
    'The document is true until %s – upload the new edition or move the date; the day after, it hides itself and its download address stops working.' => 'El documento es vigente hasta %s – sube la nueva edición o cambia la fecha; al día siguiente se oculta solo y su dirección de descarga deja de funcionar.',
    'After sending, e-mail this file to the visitor (a file from Media; the form needs an e-mail field). A file in Media stays reachable by its own address – this stops casual sharing, not a determined person.' => 'Tras el envío, manda este archivo por correo al visitante (un archivo de Medios; el formulario necesita un campo de correo). Un archivo de Medios sigue siendo accesible por su propia dirección – esto evita que se comparta a la ligera, no frena a alguien decidido.',
    'Store locator' => 'Localizador de tiendas',
    'Branches or stores from a collection: a list with directions, a search box, “Nearest to me” and a map that loads after a click.' => 'Sucursales o tiendas de una colección: una lista con indicaciones, un cuadro de búsqueda, “Más cercana a mí” y un mapa que se carga tras un clic.',
    'Collection (empty = the first Branches collection)' => 'Colección (vacío = la primera colección de Sucursales)',
    'Location field (key)' => 'Campo de ubicación (clave)',
    'Search box' => 'Cuadro de búsqueda',
    '“Nearest to me” button' => 'Botón “Más cercana a mí”',
    'Map (loads after a click)' => 'Mapa (se carga tras un clic)',
    'Create a Branches collection first (Collections → New branches), or choose a collection in the Content panel.' => 'Crea primero una colección de Sucursales (Colecciones → Nuevas sucursales) o elige una colección en el panel Contenido.',
    'The collection has no visible items yet.' => 'La colección aún no tiene elementos visibles.',
    'New branches (store locator)' => 'Nuevas sucursales (localizador de tiendas)',
    'Address, location, phone, e-mail, opening hours, photo and a page for each branch or store; the Store locator element lists them with search, the nearest one and a map.' => 'Dirección, ubicación, teléfono, correo, horario de apertura, foto y una página para cada sucursal o tienda; el elemento Localizador de tiendas las muestra con búsqueda, la más cercana y un mapa.',
    'Local business (branch, store)' => 'Negocio local (sucursal, tienda)',
    'Location (latitude, longitude)' => 'Ubicación (latitud, longitud)',
    'New services' => 'Nuevos servicios',
    'A page for each service with a summary, an image, a description and a price from; the list shows cards with the summary.' => 'Una página para cada servicio con un resumen, una imagen, una descripción y un precio desde; la lista muestra tarjetas con el resumen.',
    'Price from' => 'Precio desde',
    'References' => 'Referencias',
    'New references (case studies)' => 'Nuevas referencias (casos de éxito)',
    'Case studies with the client, an image, a quote, the result, a link and the year, each with its own page; a reference can point to the service it was for.' => 'Casos de éxito con el cliente, una imagen, una cita, el resultado, un enlace y el año, cada uno con su propia página; una referencia puede apuntar al servicio al que correspondió.',
    'Year' => 'Año',
    'Price list' => 'Lista de precios',
    'New price list' => 'Nueva lista de precios',
    'Rows with a price, a unit and a note, grouped by category with filter buttons for visitors; the rows have no pages of their own.' => 'Filas con un precio, una unidad y una nota, agrupadas por categoría con botones de filtro para los visitantes; las filas no tienen páginas propias.',
    'Unit' => 'Unidad',
    'New questions and answers' => 'Nuevas preguntas y respuestas',
    'Questions with a formatted answer, grouped by category with filter buttons; the answers are kept in one place for the FAQ page and the pages that need them.' => 'Preguntas con una respuesta con formato, agrupadas por categoría con botones de filtro; las respuestas se guardan en un solo lugar para la página de preguntas frecuentes y las páginas que las necesiten.',
    'Machines and equipment' => 'Máquinas y equipos',
    'New machines and equipment' => 'Nuevas máquinas y equipos',
    'A page for each machine with a photo, the model, a table of parameters, the year, a datasheet to download and its availability.' => 'Una página para cada máquina con una foto, el modelo, una tabla de parámetros, el año, una ficha técnica para descargar y su disponibilidad.',
    'Model' => 'Modelo',
    'Courses and training' => 'Cursos y formación',
    'New courses and training' => 'Nuevos cursos y formación',
    'A page for each course with its start and end, the place, the price, the capacity and a description; the list shows only the courses still to come, the nearest first.' => 'Una página para cada curso con su inicio y fin, el lugar, el precio, el aforo y una descripción; la lista muestra solo los cursos que aún no han empezado, el más cercano primero.',
    'Screen mode' => 'Modo pantalla',
    'Screen mode on' => 'Modo pantalla activado',
    'A TV or a tablet in the reception, showroom or waiting room opens the address below and rotates slides by itself: the latest news, items of the chosen collections and today\'s opening hours. The address has a secret part, so nobody finds the screen by guessing; it is not indexed and sets no cookies.' => 'Un televisor o una tableta en la recepción, la sala de exposición o la sala de espera abre la dirección de abajo y va pasando diapositivas por sí sola: las últimas noticias, elementos de las colecciones elegidas y el horario de apertura de hoy. La dirección tiene una parte secreta, así que nadie encuentra la pantalla adivinando; no se indexa y no usa cookies.',
    'Seconds per slide' => 'Segundos por diapositiva',
    'Collections to show' => 'Colecciones que mostrar',
    'The site has no collections yet.' => 'El sitio aún no tiene colecciones.',
    'A collection with a date field (events, courses) shows only the upcoming items.' => 'Una colección con un campo de fecha (eventos, cursos) muestra solo los elementos próximos.',
    'Show the latest news' => 'Mostrar las últimas noticias',
    'Up to five, with their images.' => 'Hasta cinco, con sus imágenes.',
    'Show today\'s opening hours' => 'Mostrar el horario de apertura de hoy',
    'From Business details, with the exceptions: “Open now, until 17:00”.' => 'De Datos de la empresa, con las excepciones: “Abierto ahora, hasta las 17:00”.',
    'Show a clock' => 'Mostrar un reloj',
    'Screen address' => 'Dirección de la pantalla',
    'Copy address' => 'Copiar dirección',
    'Open it on the screen in full-screen (kiosk) mode. Anyone with the address sees the screen – do not publish it.' => 'Ábrela en la pantalla en modo de pantalla completa (quiosco). Cualquiera con la dirección ve la pantalla – no la publiques.',
    'Save the settings with the screen mode on – the address is created then.' => 'Guarda los ajustes con el modo pantalla activado – entonces se crea la dirección.',
    'Official notice board' => 'Tablón de anuncios oficial',
    'New notice board' => 'Nuevo tablón de anuncios',
    'Posting and takedown dates, reference number, issuer, category, document and summary; the board shows what is posted now, the archive what was taken down. Notices are never deleted and every change is logged.' => 'Fechas de publicación y retirada, número de referencia, emisor, categoría, documento y resumen; el tablón muestra lo publicado ahora y el archivo lo que se ha retirado. Los anuncios nunca se eliminan y cada cambio queda registrado.',
    'Posted on' => 'Publicado el',
    'Taken down on' => 'Retirado el',
    'Reference number' => 'Número de referencia',
    'Issuer' => 'Emisor',
    '%s – archive' => '%s – archivo',
    'Official notice board: postings and takedowns' => 'Tablón de anuncios oficial: publicaciones y retiradas',
    'Notice status' => 'Estado del anuncio',
    'Notices stay in the archive – change the takedown date instead.' => 'Los anuncios permanecen en el archivo – cambia la fecha de retirada en su lugar.',
    'A notice that is or was posted cannot be hidden – it stays on the board until its takedown date and then in the archive. Change the dates instead.' => 'Un anuncio que está o estuvo publicado no se puede ocultar – permanece en el tablón hasta su fecha de retirada y después en el archivo. Cambia las fechas en su lugar.',
    'The notice board has %s notices – they stay in the archive, so the collection cannot be deleted.' => 'El tablón tiene %s anuncios – permanecen en el archivo, así que la colección no se puede eliminar.',
    'The collection is not an official notice board.' => 'La colección no es un tablón de anuncios oficial.',
    'Notice log (%s)' => 'Registro del anuncio (%s)',
    'Every creation and change of the notice and the day it was posted and taken down. The log is append-only – nothing in it can be edited or deleted.' => 'Cada creación y cambio del anuncio y el día en que se publicó y se retiró. El registro solo admite añadir – nada en él se puede editar ni eliminar.',
    'Download the whole log as CSV' => 'Descargar todo el registro como CSV',
