    'a rule' => 'una regla',
    'Drafted reply' => 'Borrador de respuesta',
    'Never sent by itself – check it, then reply by e-mail.' => 'Nunca se envía solo – revísalo y luego responde por correo.',
    'Save triage' => 'Guardar clasificación',
    'Reply by email with the draft' => 'Responder por correo con el borrador',
    'Sort new enquiries with the writing assistant' => 'Clasificar las consultas nuevas con el asistente de redacción',
    'The assistant suggests the kind, the priority and a reply; the text of each enquiry is then sent to the AI provider chosen in Features – mention it in your privacy policy. Claude can sort enquiries over its connection without this.' => 'El asistente sugiere el tipo, la prioridad y una respuesta; el texto de cada consulta se envía entonces al proveedor de IA elegido en Funciones – menciónalo en tu política de privacidad. Claude puede clasificar consultas a través de su conexión sin esto.',
    'Sorting new enquiries with the writing assistant' => 'Clasificando las consultas nuevas con el asistente de redacción',
    'normal' => 'normal',
    'new step (a multi-step form – the label is the step title)' => 'nuevo paso (un formulario de varios pasos – la etiqueta es el título del paso)',
    'price estimate (adds up the prices of the answers)' => 'presupuesto estimado (suma los precios de las respuestas)',
    'Price per unit for the estimate (the number × this price)' => 'Precio por unidad para el presupuesto (el número × este precio)',
    'Base price of the estimate' => 'Precio base del presupuesto',
    'Currency of the estimate (e.g. EUR, Kč)' => 'Moneda del presupuesto (p. ej., EUR, Kč)',
    'Show only when the field labelled…' => 'Mostrar solo cuando el campo con la etiqueta…',
    '…has this value (for options to tick: this one is ticked)' => '…tiene este valor (para opciones que marcar: esta está marcada)',
    'An estimate from your answers – the final price follows in our reply.' => 'Un presupuesto estimado según tus respuestas – el precio final te lo daremos en nuestra respuesta.',
    'Step %d' => 'Paso %d',
    'Testimonial' => 'Testimonio',
