    'the draft reference' => 'el borrador de la referencia',
    'Expired' => 'Caducado',
    'Waiting for the answer' => 'Esperando la respuesta',
    'Ask for a testimonial by e-mail' => 'Pedir un testimonio por correo',
    'Only create the link' => 'Solo crear el enlace',
    'The customer gets a personal link for 30 days; what they write arrives as a hidden draft in References, with the consent they gave.' => 'El cliente recibe un enlace personal válido 30 días; lo que escriba llega como borrador oculto en Referencias, con el consentimiento que haya dado.',
    'The request was sent. The link: %s' => 'La solicitud se ha enviado. El enlace: %s',
    'The link to send yourself: %s' => 'El enlace para enviarlo tú: %s',
    'The enquiry has no e-mail address to send the request to.' => 'La consulta no tiene una dirección de correo a la que enviar la solicitud.',
    'A customer sent a testimonial (a hidden draft reference).' => 'Un cliente envió un testimonio (un borrador de referencia oculto).',
    'Contact clicks (calls, e-mails, WhatsApp)' => 'Clics de contacto (llamadas, correos, WhatsApp)',
    'Calls / e-mails / WhatsApp' => 'Llamadas / correos / WhatsApp',
    'Contact clicks: a click on a phone number, an e-mail address or a WhatsApp link counts as a lead once per visitor, page and day – without cookies.' => 'Clics de contacto: un clic en un número de teléfono, una dirección de correo o un enlace de WhatsApp cuenta como contacto una vez por visitante, página y día – sin cookies.',
    'Calls – clicks on a phone number' => 'Llamadas – clics en un número de teléfono',
    'E-mails – clicks on an e-mail address' => 'Correos – clics en una dirección de correo',
    'WhatsApp – clicks on a WhatsApp link' => 'WhatsApp – clics en un enlace de WhatsApp',
    'Generate share images when a page has none' => 'Generar imágenes para compartir cuando una página no tiene ninguna',
    'A 1200×630 picture with the title in the site colours, the site name and the logo – so social networks show something instead of nothing.' => 'Una imagen de 1200×630 con el título en los colores del sitio, el nombre del sitio y el logotipo – para que las redes sociales muestren algo en lugar de nada.',
    'This server cannot draw pictures (the PHP GD extension is missing), so nothing is generated.' => 'Este servidor no puede dibujar imágenes (falta la extensión GD de PHP), así que no se genera nada.',
    'What happens next (one step per line, shown with the thank-you)' => 'Qué pasa después (un paso por línea, se muestra con el agradecimiento)',
    'We reply within (working hours by the opening hours in Business details; 0 = not shown)' => 'Respondemos en (horas laborables según el horario de apertura de Datos de la empresa; 0 = no se muestra)',
    'Who replies (e.g. “Jana from the office”)' => 'Quién responde (p. ej., “Jana, de la oficina”)',
    'Pricing table' => 'Tabla de precios',
    'Before and after' => 'Antes y después',
    'Hotspots' => 'Puntos interactivos',
    'Timeline' => 'Cronología',
    'Plans side by side – name, price, features and a button; one plan can be highlighted.' => 'Planes uno al lado del otro – nombre, precio, características y un botón; se puede destacar un plan.',
    'Two photos with a draggable divider – a renovation, a cleaning, a makeover.' => 'Dos fotos con un separador deslizable – una reforma, una limpieza, un cambio de imagen.',
    'An image with numbered points – a tap on a point shows its label and text (a product, a floor plan, a map of premises).' => 'Una imagen con puntos numerados – al tocar un punto se muestra su etiqueta y su texto (un producto, un plano, un mapa de las instalaciones).',
    'Milestones one after another – the company history, project steps, how a service proceeds.' => 'Hitos uno tras otro – la historia de la empresa, las fases de un proyecto, cómo se desarrolla un servicio.',
    'Plans' => 'Planes',
    'Plan name' => 'Nombre del plan',
    'Period (e.g. / month)' => 'Periodo (p. ej., / mes)',
    'Short description' => 'Descripción breve',
