    'Date or year' => 'Fecha o año',
    'Title' => 'Título',
    'Image (optional)' => 'Imagen (opcional)',
    'The site talks only to the services listed here, only after you connect them. Sign-ins and keys are stored encrypted and never shown again – not here, not to Claude, not in the site export.' => 'El sitio solo se comunica con los servicios de esta lista, y solo después de que los conectes. Los inicios de sesión y las claves se guardan cifrados y no se vuelven a mostrar – ni aquí, ni a Claude, ni en la exportación del sitio.',
    'Connected' => 'Conectado',
    'Not connected' => 'No conectado',
    'since %s' => 'desde %s',
    'Create an OAuth app (a web application) with %s and enter its client ID and secret. The redirect address to enter there:' => 'Crea una app OAuth (una aplicación web) en %s e introduce su ID de cliente y su secreto. La dirección de redirección que debes introducir allí:',
    'Where to get it' => 'Dónde conseguirlo',
    'Client ID' => 'ID de cliente',
    'Client secret' => 'Secreto de cliente',
    'stored – type to replace' => 'guardado – escribe para sustituirlo',
    'Where to get the key' => 'Dónde conseguir la clave',
    'Connect %s' => 'Conectar %s',
    'Disconnect %s? The stored sign-in is deleted; what was already sent stays there.' => '¿Desconectar %s? Se elimina el inicio de sesión guardado; lo que ya se envió permanece allí.',
    'Last calls' => 'Últimas llamadas',
    '%d deliveries are waiting or being retried.' => '%d entregas están en espera o se están reintentando.',
    'No calls yet.' => 'Aún no hay llamadas.',
    'The sign-in was cancelled: %s' => 'Se canceló el inicio de sesión: %s',
    '%s is connected.' => '%s está conectado.',
    'Disconnected – the stored sign-in was deleted.' => 'Desconectado – se eliminó el inicio de sesión guardado.',
    'Enter the client ID and secret of your OAuth app first.' => 'Introduce primero el ID de cliente y el secreto de tu app OAuth.',
    'The sign-in could not be verified. Try connecting again.' => 'No se pudo verificar el inicio de sesión. Vuelve a intentar la conexión.',
    '%s did not accept the sign-in: %s' => '%s no aceptó el inicio de sesión: %s',
    '%s was connected.' => 'Se ha conectado %s.',
    'The sign-in expired – connect %s again.' => 'El inicio de sesión caducó – vuelve a conectar %s.',
    '%s is not connected.' => '%s no está conectado.',
    'Too many calls to %s this minute – it will be tried again.' => 'Demasiadas llamadas a %s en este minuto – se volverá a intentar.',
    'A delivery to an outside service failed: %s' => 'Falló una entrega a un servicio externo: %s',
    'Deliveries to connected services' => 'Entregas a servicios conectados',
    'An outside service was connected.' => 'Se conectó un servicio externo.',
    'A delivery to an outside service failed after all retries.' => 'Una entrega a un servicio externo falló tras todos los reintentos.',
    'Links to /%s now lead to %s (%d places).' => 'Los enlaces a /%s ahora llevan a %s (%d lugares).',
    'Personal data of one address were erased on request.' => 'Se borraron a petición los datos personales de una dirección.',
    'Only an administrator can handle personal data requests.' => 'Solo un administrador puede gestionar solicitudes de datos personales.',
    'Tick that you want to erase the data.' => 'Marca que quieres borrar los datos.',
    'Erased: %d enquiries, %d subscriptions, %d e-mails in the queue, %d testimonial requests.' => 'Borrado: %d consultas, %d suscripciones, %d correos en la cola, %d solicitudes de testimonio.',
    'A testimonial the person sent stays in References (items %s) – remove it there if they ask.' => 'Un testimonio que envió la persona permanece en Referencias (elementos %s) – quítalo allí si lo pide.',
    'Personal data request' => 'Solicitud de datos personales',
    'find, export or erase everything about one e-mail address' => 'buscar, exportar o borrar todo lo relativo a una dirección de correo',
    'When someone asks what the site keeps about them, or asks to be deleted: enter their e-mail address. The search covers enquiries (the sender and every field), the newsletter subscription, e-mails waiting to be sent and testimonial requests.' => 'Cuando alguien pregunta qué guarda el sitio sobre él o pide que lo borren: introduce su dirección de correo. La búsqueda abarca las consultas (el remitente y todos los campos), la suscripción al boletín, los correos pendientes de envío y las solicitudes de testimonio.',
    'E-mail address' => 'Dirección de correo electrónico',
    'Find' => 'Buscar',
    'What the site keeps about %s' => 'Qué guarda el sitio sobre %s',
    'Nothing – the site keeps no data about this address.' => 'Nada – el sitio no guarda datos sobre esta dirección.',
    'Enquiries: %d' => 'Consultas: %d',
    'Newsletter subscription since %s' => 'Suscripción al boletín desde %s',
    'not confirmed' => 'sin confirmar',
    'E-mails in the outgoing queue: %d' => 'Correos en la cola de salida: %d',
    'Testimonial requests: %d' => 'Solicitudes de testimonio: %d',
    'An account of the administration (%s) – change or remove it in Users; it is not erased here.' => 'Una cuenta de la administración (%s) – cámbiala o quítala en Usuarios; aquí no se borra.',
    'Download as a file for the person (JSON)' => 'Descargar como archivo para la persona (JSON)',
    'Erase everything listed above for good? This cannot be undone.' => '¿Borrar definitivamente todo lo indicado arriba? No se puede deshacer.',
    'I want to erase this data for good' => 'Quiero borrar estos datos definitivamente',
    'Erase' => 'Borrar',
    'Enquiries with their attachments, the subscription (also in the connected mailing service), queued e-mails and testimonial requests are deleted. Backups keep older copies until they expire.' => 'Se eliminan las consultas con sus adjuntos, la suscripción (también en el servicio de envío de correo conectado), los correos en cola y las solicitudes de testimonio. Las copias de seguridad conservan copias anteriores hasta que caducan.',
    'The page password must have at least %d characters.' => 'La contraseña de la página debe tener al menos %d caracteres.',
    'Page password' => 'Contraseña de la página',
    'protected – type a new password to change it' => 'protegida – escribe una contraseña nueva para cambiarla',
    'none – the page is public' => 'ninguna – la página es pública',
    'Remove the password' => 'Quitar la contraseña',
    'Visitors see the page only after entering the password – e.g. a price list for partners. It is not an account: whoever knows the password reads the page. A protected page is never in search engines, the sitemap or the site search.' => 'Los visitantes ven la página solo después de introducir la contraseña – p. ej., una lista de precios para socios. No es una cuenta: quien conoce la contraseña lee la página. Una página protegida nunca aparece en buscadores, en el sitemap ni en la búsqueda del sitio.',
    '%d files in Media. The site found what can be cleaned up – nothing changes until you decide.' => '%d archivos en Medios. El sitio ha encontrado lo que se puede limpiar – nada cambia hasta que decidas.',
    '%d images have no description for blind visitors (alt).' => '%d imágenes no tienen descripción para visitantes ciegos (alt).',
    'Add language versions in Settings → General; this screen then shows which translations are missing.' => 'Añade versiones de idioma en Ajustes → General; entonces esta pantalla mostrará qué traducciones faltan.',
    'Apply the action to the selected items?' => '¿Aplicar la acción a los elementos seleccionados?',
    'Back to draft' => 'Volver a borrador',
    'Back to media' => 'Volver a Medios',
    'Category…' => 'Categoría…',
    'Clean-up' => 'Limpieza',
    'Content check' => 'Revisión del contenido',
    'Delete %s' => 'Eliminar %s',
    'Delete selected files' => 'Eliminar los archivos seleccionados',
    'Delete the selected files for good? Media has no trash. Files the site still uses are skipped.' => '¿Eliminar definitivamente los archivos seleccionados? Medios no tiene papelera. Los archivos que el sitio aún usa se omiten.',
    'Describe what each image shows – screen readers and search engines read it. Empty fields are skipped; the rest is saved together.' => 'Describe lo que muestra cada imagen – lo leen los lectores de pantalla y los buscadores. Los campos vacíos se omiten; el resto se guarda a la vez.',
    'Duplicates' => 'Duplicados',
    'Every file is used somewhere on the site.' => 'Todos los archivos se usan en alguna parte del sitio.',
    'Every image has a description (alt).' => 'Todas las imágenes tienen descripción (alt).',
    'Every image has a description for blind visitors (alt).' => 'Todas las imágenes tienen descripción para visitantes ciegos (alt).',
    'Headings do not skip a level.' => 'Los títulos no se saltan ningún nivel.',
    'Headings skip a level (%s) – screen readers and search engines read the outline.' => 'Los títulos se saltan un nivel (%s) – los lectores de pantalla y los buscadores leen la estructura.',
    'Image descriptions saved: %d.' => 'Descripciones de imágenes guardadas: %d.',
    'Images over %s or wider than %d px slow pages down. “Make smaller” re-encodes the image to %d px in place – its address and every page that shows it stay.' => 'Las imágenes de más de %s o más anchas de %d px ralentizan las páginas. “Reducir” vuelve a codificar la imagen a %d px en su lugar – su dirección y todas las páginas que la muestran se mantienen.',
    'Images without a description' => 'Imágenes sin descripción',
    'Items hidden: %d.' => 'Elementos ocultados: %d.',
    'Items moved to the language version: %d.' => 'Elementos movidos a la versión de idioma: %d.',
    'Items moved to the trash: %d.' => 'Elementos movidos a la papelera: %d.',
    'Items published: %d.' => 'Elementos publicados: %d.',
    'Language version…' => 'Versión de idioma…',
    'Make smaller' => 'Reducir',
    'Missing translations: %d, older than the original: %d.' => 'Traducciones que faltan: %d, más antiguas que el original: %d.',
    'Move to trash' => 'Mover a la papelera',
    'News items back as drafts: %d.' => 'Noticias devueltas a borrador: %d.',
    'News items moved to the category: %d.' => 'Noticias movidas a la categoría: %d.',
    'News items published: %d.' => 'Noticias publicadas: %d.',
    'No description for search engines – they make one up from the text.' => 'No hay descripción para buscadores – se inventan una a partir del texto.',
    'No file is uploaded twice.' => 'Ningún archivo se ha subido dos veces.',
    'No image is larger than %s or wider than %d px.' => 'Ninguna imagen supera %s ni es más ancha de %d px.',
    'Nothing on the site points at these files: no page, build, news item, collection item, component, pop-up, newsletter or setting. Media has no trash – deleted files cannot be restored.' => 'Nada en el sitio apunta a estos archivos: ninguna página, diseño del builder, noticia, elemento de colección, componente, pop-up, boletín ni ajuste. Medios no tiene papelera – los archivos eliminados no se pueden restaurar.',
    'Of the saved version. Search engines show about 60 characters of a title and 160 of a description.' => 'De la versión guardada. Los buscadores muestran unos 60 caracteres de un título y 160 de una descripción.',
    'One H1 heading.' => 'Un título H1.',
    'Only the owner of an image or an administrator can describe it.' => 'Solo el propietario de una imagen o un administrador puede describirla.',
    'Oversized images' => 'Imágenes demasiado grandes',
    'Pages hidden: %d.' => 'Páginas ocultadas: %d.',
