    'The description has %d characters – %d to %d is best.' => 'La descripción tiene %d caracteres – lo ideal es entre %d y %d.',
    'The description has %d characters – search engines cut it after about %d.' => 'La descripción tiene %d caracteres – los buscadores la cortan a partir de unos %d.',
    'The description has %d characters.' => 'La descripción tiene %d caracteres.',
    'The focus keyword “%s” is in the title, the description and the first paragraph.' => 'La palabra clave principal “%s” está en el título, la descripción y el primer párrafo.',
    'The focus keyword “%s” is missing from %s.' => 'La palabra clave principal “%s” falta en %s.',
