    'Reduce motion' => 'Reducir movimiento',
    'Default settings' => 'Ajustes predeterminados',
    'Purpose' => 'Finalidad',
    'Duration' => 'Duración',
    'Necessary' => 'Necesarias',
    'this site' => 'este sitio',
    'Set by the server – describe its purpose' => 'La define el servidor – describe su finalidad',
    'see the browser' => 'ver el navegador',
    'session' => 'sesión',
    'until removed' => 'hasta que se elimine',
    '2 years' => '2 años',
    '6 months' => '6 meses',
    '8 months' => '8 meses',
    '13 months' => '13 meses',
    '3 months' => '3 meses',
    '1 month' => '1 mes',
    '24 hours' => '24 horas',
    '30 minutes' => '30 minutos',
    '1 minute' => '1 minuto',
    'Cookie bar: the categories the visitor allowed (cookie)' => 'Barra de cookies: las categorías que permitió el visitante (cookie)',
    'The chosen light or dark appearance (local storage)' => 'La apariencia clara u oscura elegida (almacenamiento local)',
    'The chosen language version (local storage)' => 'La versión de idioma elegida (almacenamiento local)',
    'Accessibility toolbar: text size, contrast, underlined links, reduced motion (local storage)' => 'Barra de accesibilidad: tamaño del texto, contraste, enlaces subrayados, movimiento reducido (almacenamiento local)',
    'Sign-in to the administration – only after signing in, never for visitors' => 'Inicio de sesión en la administración – solo después de iniciar sesión, nunca para visitantes',
    'Video player: bandwidth and preferences' => 'Reproductor de vídeo: ancho de banda y preferencias',
    'Video player: views within a session' => 'Reproductor de vídeo: reproducciones dentro de una sesión',
    'Video player: preferences' => 'Reproductor de vídeo: preferencias',
    'Video player: statistics of plays' => 'Reproductor de vídeo: estadísticas de reproducciones',
    'Map: preferences and usage' => 'Mapa: preferencias y uso',
    'Map: the consent given to Google' => 'Mapa: el consentimiento dado a Google',
    'Statistics: tells visitors apart' => 'Estadísticas: distingue a los visitantes',
    'Statistics: keeps the session state' => 'Estadísticas: guarda el estado de la sesión',
    'Tag manager: limits the number of requests' => 'Gestor de etiquetas: limita el número de solicitudes',
    'Statistics: the session' => 'Estadísticas: la sesión',
    'Advertising: tells visitors apart across sites' => 'Publicidad: distingue a los visitantes entre sitios',
    'Advertising: shows and measures ads' => 'Publicidad: muestra y mide anuncios',
    'Spam check: the risk analysis of the visitor' => 'Comprobación antispam: el análisis de riesgo del visitante',
    'Spam check: the passed challenge' => 'Comprobación antispam: el desafío superado',
    'Spam check: accessibility of the challenge' => 'Comprobación antispam: accesibilidad del desafío',
    'Cookies and storage this site uses' => 'Cookies y almacenamiento que usa este sitio',
    'What Kaleta itself sets, what the known embeds and tags found in your pages and settings set (YouTube, Google Maps, Analytics, Tag Manager, Matomo, Meta Pixel, CAPTCHA) and what the server answers with. Put {{cookie_table}} into your cookie policy page – the table appears there in the site language.' => 'Lo que define Kaleta, lo que definen las inserciones y etiquetas conocidas encontradas en tus páginas y ajustes (YouTube, Google Maps, Analytics, Tag Manager, Matomo, Meta Pixel, CAPTCHA) y lo que responde el servidor. Pon {{cookie_table}} en la página de tu política de cookies – la tabla aparece allí en el idioma del sitio.',
    'Last scan of the site’s own pages: %s, %d pages, %d cookies set by the server.' => 'Último análisis de las páginas propias del sitio: %s, %d páginas, %d cookies definidas por el servidor.',
    'The server could not reach the site: %s.' => 'El servidor no pudo acceder al sitio: %s.',
    'The site’s own pages have not been scanned yet – the background tasks do it daily.' => 'Las páginas propias del sitio aún no se han analizado – las tareas en segundo plano lo hacen a diario.',
    'Scan the site now' => 'Analizar el sitio ahora',
    'Documents from the configuration' => 'Documentos a partir de la configuración',
    'Templates assembled from what the site is set up to do – review and complete them, they are not legal advice.' => 'Plantillas elaboradas a partir de lo que el sitio está configurado para hacer – revísalas y complétalas; no son asesoramiento jurídico.',
    'Record of processing' => 'Registro de actividades de tratamiento',
    'Show the record' => 'Ver el registro',
    'GDPR Art. 30 style: forms and their fields, enquiries and applications with their retention, newsletter, statistics, connected services, mail, backups, the writing assistant, cookies.' => 'Al estilo del art. 30 del RGPD: formularios y sus campos, consultas y candidaturas con su plazo de conservación, boletín, estadísticas, servicios conectados, correo, copias de seguridad, el asistente de redacción, cookies.',
    'Accessibility statement' => 'Declaración de accesibilidad',
    'published' => 'publicada',
    'hidden draft' => 'borrador oculto',
    'Regenerate the draft from the audit' => 'Regenerar el borrador a partir de la auditoría',
    'Create the draft from the audit' => 'Crear el borrador a partir de la auditoría',
    'Filled from the site audit: the standard (EN 301 549 / WCAG 2.1 AA), the status by the accessibility findings, the known barriers and the contact. Created as a hidden page – review it, then publish it. Regenerating updates the draft.' => 'Rellenado a partir de la auditoría del sitio: la norma (EN 301 549 / WCAG 2.1 AA), el estado según los hallazgos de accesibilidad, las barreras conocidas y el contacto. Se crea como página oculta – revísala y luego publícala. Al regenerarlo se actualiza el borrador.',
    'Accessibility toolbar for visitors' => 'Barra de accesibilidad para visitantes',
    'A small button on every page: larger text, higher contrast, underlined links, reduced motion. Remembered in the visitor’s browser, no cookies.' => 'Un pequeño botón en cada página: texto más grande, más contraste, enlaces subrayados, movimiento reducido. Se recuerda en el navegador del visitante, sin cookies.',
    'The scan could not reach the site from the server (%s). The table shows what Kaleta and the known embeds set.' => 'El análisis no pudo acceder al sitio desde el servidor (%s). La tabla muestra lo que definen Kaleta y las inserciones conocidas.',
    'Scanned %d pages: %d cookies set by the server.' => 'Se analizaron %d páginas: %d cookies definidas por el servidor.',
    'The accessibility statement is ready as a hidden page – review it, then publish it: %s' => 'La declaración de accesibilidad está lista como página oculta – revísala y luego publícala: %s',
    'Generated on %s from the site’s configuration. A template to review and complete – not legal advice.' => 'Generado el %s a partir de la configuración del sitio. Una plantilla para revisar y completar – no es asesoramiento jurídico.',
    'Add what the site does not know about (paper files, accounting, other systems) and keep the record with your documentation; print it from the browser.' => 'Añade lo que el sitio no conoce (archivos en papel, contabilidad, otros sistemas) y guarda el registro con tu documentación; imprímelo desde el navegador.',
    'As Markdown (to copy)' => 'Como Markdown (para copiar)',
    'After that period' => 'Tras ese plazo',
    'delete them including attachments' => 'eliminarlas, incluidos los adjuntos',
    'anonymise them – the row stays for statistics (date, form, page, topic, kind) without the name, e-mail, phone, message and attachments' => 'anonimizarlas – la fila se mantiene para estadísticas (fecha, formulario, página, tema, tipo) sin el nombre, el correo, el teléfono, el mensaje ni los adjuntos',
    'Anonymised' => 'Anonimizada',
    'the row stays for statistics without the person' => 'la fila se mantiene para estadísticas sin la persona',
    'Blank the name, e-mail, phone, message and attachments of this enquiry? The row stays for statistics.' => '¿Borrar el nombre, el correo, el teléfono, el mensaje y los adjuntos de esta consulta? La fila se mantiene para estadísticas.',
    'Anonymise' => 'Anonimizar',
    'The enquiry was anonymised – the row stays for statistics without the person.' => 'La consulta se ha anonimizado – la fila se mantiene para estadísticas sin la persona.',
    'What cookies the site sets' => 'Qué cookies define el sitio',
    'Controller' => 'Responsable del tratamiento',
    'Company: %s' => 'Empresa: %s',
    'Company: not filled in (Business details)' => 'Empresa: sin rellenar (Datos de la empresa)',
    'Address: %s' => 'Dirección: %s',
    'Contact: %s' => 'Contacto: %s',
    'Contact: no site e-mail (Settings → General)' => 'Contacto: no hay correo del sitio (Ajustes → General)',
    'Form “%s” on %s: fields %s; notification to %s%s' => 'Formulario “%s” en %s: campos %s; notificación a %s%s',
    'the site e-mail' => 'el correo del sitio',
    'the sender gets a confirmation e-mail' => 'el remitente recibe un correo de confirmación',
    'Enquiries and form messages' => 'Consultas y mensajes de formularios',
    'No form on the published site.' => 'No hay ningún formulario en el sitio publicado.',
    'Purpose: answering the enquiry and the business relationship that follows. Legal basis: performance of a contract or steps before it (Art. 6(1)(b)), legitimate interest in answering.' => 'Finalidad: responder a la consulta y la relación comercial posterior. Base jurídica: ejecución de un contrato o medidas precontractuales (art. 6.1.b), interés legítimo en responder.',
    'Retention: %d months, then %s automatically.' => 'Conservación: %d meses; después, automáticamente: %s.',
    'anonymised (the row stays for statistics without the person)' => 'anonimizadas (la fila se mantiene para estadísticas sin la persona)',
    'deleted including attachments' => 'eliminadas, incluidos los adjuntos',
    'Retention: not limited – set it in Enquiries → Settings.' => 'Conservación: sin límite – configúrala en Consultas → Ajustes.',
    'Recipients: the people with access to Enquiries in the administration%s.' => 'Destinatarios: las personas con acceso a Consultas en la administración%s.',
    'a webhook at %s' => 'un webhook en %s',
    'Job applications' => 'Candidaturas',
    'Applications to job openings arrive as enquiries from the job pages, with CVs as attachments.' => 'Las candidaturas a ofertas de empleo llegan como consultas desde las páginas de las ofertas, con los CV como adjuntos.',
    'Retention: %d months, then deleted including the CVs.' => 'Conservación: %d meses; después se eliminan, incluidos los CV.',
    'Retention: the same as other enquiries (%d months).' => 'Conservación: la misma que la de las demás consultas (%d meses).',
    'Legal basis: steps before a contract (Art. 6(1)(b)); keeping an application longer needs the applicant’s consent.' => 'Base jurídica: medidas precontractuales (art. 6.1.b); conservar una candidatura más tiempo requiere el consentimiento del candidato.',
    'Subscribers: %d confirmed, %d waiting for confirmation (double opt-in; unconfirmed sign-ups are deleted after 30 days).' => 'Suscriptores: %d confirmados, %d pendientes de confirmación (doble opt-in; las suscripciones sin confirmar se eliminan tras 30 días).',
    'Data: e-mail address, date and language of the sign-up%s.' => 'Datos: dirección de correo, fecha e idioma de la suscripción%s.',
    'the first page of the visit and its campaign (with consent to marketing)' => 'la primera página de la visita y su campaña (con consentimiento para marketing)',
    'Legal basis: consent (Art. 6(1)(a)); every e-mail carries an unsubscribe link.' => 'Base jurídica: consentimiento (art. 6.1.a); cada correo incluye un enlace para darse de baja.',
    'Processor: the mailing service %s (confirmed subscribers are passed to it).' => 'Encargado del tratamiento: el servicio de envío de correo %s (se le transfieren los suscriptores confirmados).',
    'Processor: none – the newsletter is sent from this site.' => 'Encargado del tratamiento: ninguno – el boletín se envía desde este sitio.',
    'Built-in statistics: page views, devices and campaigns counted without cookies; the visitor’s address is hashed with a daily salt and never stored.' => 'Estadísticas integradas: páginas vistas, dispositivos y campañas contados sin cookies; la dirección del visitante se cifra con hash con una sal diaria y nunca se guarda.',
    '%s – a third-party service (processor); runs only after consent in the cookie bar unless the bar is off.' => '%s – un servicio de terceros (encargado del tratamiento); solo se ejecuta tras el consentimiento en la barra de cookies, salvo que la barra esté desactivada.',
    'No traffic statistics.' => 'Sin estadísticas de tráfico.',
    '%s (account %s) – data the deliveries send leaves the site to this service.' => '%s (cuenta %s) – los datos que envían las entregas salen del sitio hacia este servicio.',
    'Connected services and processors' => 'Servicios conectados y encargados del tratamiento',
    'E-mail: sent through the SMTP server %s.' => 'Correo: se envía a través del servidor SMTP %s.',
    'E-mail: sent by the hosting server’s mail function.' => 'Correo: lo envía la función de correo del servidor de hosting.',
    'Backups: automatic %s, an off-site copy over %s to %s.' => 'Copias de seguridad: automáticas %s, una copia externa mediante %s a %s.',
    'Backups: automatic %s, kept on this server only.' => 'Copias de seguridad: automáticas %s, guardadas solo en este servidor.',
    'Writing assistant: %s – texts the administrators ask about%s are sent to it.' => 'Asistente de redacción: %s – se le envían los textos sobre los que preguntan los administradores%s.',
    'and new enquiries (triage)' => 'y las consultas nuevas (clasificación)',
    'Writing assistant: off.' => 'Asistente de redacción: desactivado.',
    'Claude (MCP): administrators’ assistants work with the content; enquiries are shown to them as the Enquiries screen shows them.' => 'Claude (MCP): los asistentes de los administradores trabajan con el contenido; las consultas se les muestran tal como las muestra la pantalla Consultas.',
    'Spam check: %s receives the visitor’s address and browser details when a form is sent.' => 'Comprobación antispam: %s recibe la dirección del visitante y los datos de su navegador al enviar un formulario.',
    'Spam check: built-in only (a signed time, a trap field, a limit per address) – no third party.' => 'Comprobación antispam: solo la integrada (una marca de tiempo firmada, un campo trampa, un límite por dirección) – sin terceros.',
    'Cookies and storage' => 'Cookies y almacenamiento',
    'Cookie bar: %s.' => 'Barra de cookies: %s.',
    'built-in, tracking starts after consent' => 'integrada, el seguimiento empieza tras el consentimiento',
    'an external service' => 'un servicio externo',
    'Consents are logged (time, a random identifier, the categories – no IP address)%s.' => 'Los consentimientos se registran (hora, un identificador aleatorio, las categorías – sin dirección IP)%s.',
    'and deleted after %d months' => 'y se eliminan tras %d meses',
    'Consents are not logged.' => 'Los consentimientos no se registran.',
    'Security' => 'Seguridad',
    'Access to personal data: %d administration account(s); two-step sign-in %s.' => 'Acceso a datos personales: %d cuenta(s) de la administración; verificación en dos pasos %s.',
    'on for everyone' => 'activada para todos',
    'not on for every account' => 'no activada en todas las cuentas',
    'Firewall: on (rate limits, probes, country and address blocks).' => 'Cortafuegos: activado (límites de solicitudes, sondeos, bloqueos por país y por dirección).',
    'Transport: %s.' => 'Transmisión: %s.',
    'HTTP – switch the site to HTTPS' => 'HTTP – cambia el sitio a HTTPS',
    '%s is committed to making its website accessible in line with the European Accessibility Act and the national legislation that implements it. This accessibility statement applies to %s.' => '%s se compromete a hacer accesible su sitio web conforme al Acta Europea de Accesibilidad y a la legislación nacional que la aplica. Esta declaración de accesibilidad se aplica a %s.',
    'The website aims to meet EN 301 549 and WCAG 2.1 level AA.' => 'El sitio web aspira a cumplir la norma EN 301 549 y las WCAG 2.1 nivel AA.',
    'Compliance status: this website is fully compliant – the automatic check found no barriers.' => 'Situación de cumplimiento: este sitio web es plenamente conforme – la comprobación automática no encontró barreras.',
    'Compliance status: this website is partially compliant because of the non-compliances listed below.' => 'Situación de cumplimiento: este sitio web es parcialmente conforme debido a los incumplimientos que se indican a continuación.',
    'Non-accessible content:' => 'Contenido no accesible:',
    'This statement was prepared on %s from an automatic check of the site. The automatic check does not cover everything a person would notice; the owner reviews the statement before publishing it.' => 'Esta declaración se preparó el %s a partir de una comprobación automática del sitio. La comprobación automática no detecta todo lo que notaría una persona; el propietario revisa la declaración antes de publicarla.',
    'Feedback and contact: if you find a barrier or need content in another form, write to %s. We will answer as soon as we can.' => 'Comentarios y contacto: si encuentras una barrera o necesitas el contenido en otro formato, escribe a %s. Te responderemos lo antes posible.',
    'Feedback and contact: add the e-mail address people can write to about barriers (Settings → General → Site e-mail).' => 'Comentarios y contacto: añade la dirección de correo a la que se puede escribir sobre barreras (Ajustes → General → Correo del sitio).',
    'Enforcement: if you are not satisfied with our answer, you can contact the body in your country that supervises the accessibility of websites.' => 'Procedimiento de aplicación: si no estás satisfecho con nuestra respuesta, puedes contactar con el organismo de tu país que supervisa la accesibilidad de los sitios web.',
    'Website: %s' => 'Sitio web: %s',
    'Pages nobody links to' => 'Páginas sin enlaces entrantes',
    'No published page, menu or text links here – visitors and search engines reach it only by its address. Add a link from a related page (Claude: suggest_internal_links).' => 'Ninguna página, menú o texto publicado enlaza aquí: los visitantes y los buscadores solo llegan por su dirección. Añade un enlace desde una página relacionada (Claude: suggest_internal_links).',
    '/%s now redirects to /%s by itself (score %d of 100). Undo: Administration → Redirects.' => '/%s ahora redirige a /%s automáticamente (puntuación %d de 100). Deshacer: Administración → Redirecciones.',
    'Created by the site itself from an address visitors could not find. Delete it to undo.' => 'Creada por el propio sitio a partir de una dirección que los visitantes no encontraron. Elimínala para deshacerla.',
    'automatic, score %d' => 'automática, puntuación %d',
    'By themselves' => 'Automáticamente',
    'Create redirects for missing addresses by themselves' => 'Crear redirecciones automáticas para direcciones inexistentes',
    'Once a day the site redirects an address visitors could not find to the page it is sure they meant (the same address written differently, moved to another section or language). Such a redirect is marked automatic; deleting it undoes it. Less certain candidates stay below as suggestions.' => 'Una vez al día, el sitio redirige una dirección que los visitantes no encontraron a la página que seguro buscaban (la misma dirección escrita de otra forma, movida a otra sección o idioma). Esa redirección se marca como automática; eliminarla la deshace. Los candidatos menos seguros quedan abajo como sugerencias.',
    'Needed score' => 'Puntuación necesaria',
    '0–100; 100 = the same address written differently, 95 = another section or language, 90 = the same last part of the address, lower = a similar address.' => '0–100; 100 = la misma dirección escrita de otra forma, 95 = otra sección o idioma, 90 = la misma última parte de la dirección, menos = una dirección parecida.',
    'Create redirect – one click accepts the page the site thinks the visitor meant (the score says how sure it is).' => 'Crear redirección: un clic acepta la página que el sitio cree que buscaba el visitante (la puntuación indica su grado de seguridad).',
    'Probably meant' => 'Probablemente buscaba',
    'score %d' => 'puntuación %d',
    'no similar page' => 'ninguna página parecida',
    'Create redirect' => 'Crear redirección',
    'It will be checked again within a few minutes.' => 'Se volverá a comprobar en unos minutos.',
    'In the background, the system goes through published news, pages and collection items – one every five minutes, each once a month – and checks whether their links still work. Checked: %s of %s.' => 'En segundo plano, el sistema recorre las noticias, páginas y elementos de colecciones publicados (uno cada cinco minutos, cada uno una vez al mes) y comprueba si sus enlaces siguen funcionando. Comprobados: %s de %s.',
    'Item' => 'Elemento',
    'element %s' => 'elemento %s',
    'Redirects for addresses visitors could not find' => 'Redirecciones para direcciones que los visitantes no encontraron',
    'Item “%s”' => 'Elemento “%s”',
    'Whistleblowing' => 'Canal de denuncias',
    'An internal reporting channel for the EU Whistleblower Directive (2019/1937) and the national laws built on it. Reports are stored encrypted and only the readers chosen below can open them – other administrators see case numbers and dates. Acknowledge a report within %d days and give feedback within %d months.' => 'Un canal interno de denuncias según la Directiva europea de protección de denunciantes (2019/1937) y las leyes nacionales que la desarrollan. Las denuncias se guardan cifradas y solo pueden abrirlas los lectores elegidos abajo; los demás administradores ven los números de caso y las fechas. Acusa recibo de una denuncia en %d días y da una respuesta en %d meses.',
    'This is a tool, not legal advice: your company must appoint the person responsible for reports and check the rules of its country (who must have a channel, what the deadlines and the records are).' => 'Esto es una herramienta, no asesoramiento jurídico: tu empresa debe designar a la persona responsable de las denuncias y comprobar las normas de su país (quién debe tener un canal, cuáles son los plazos y los registros).',
    'The channel is switched off – the public address answers with a 404 error.' => 'El canal está desactivado: la dirección pública responde con un error 404.',
    'No reader is chosen – reports arrive, but nobody can open them.' => 'No hay ningún lector elegido: las denuncias llegan, pero nadie puede abrirlas.',
    'No reports yet.' => 'Aún no hay denuncias.',
    'The form is at %s – put a link to it in the footer menu (Menu) or on a page.' => 'El formulario está en %s: pon un enlace a él en el menú del pie de página (Menú) o en una página.',
    'Switch the channel on below and put a link to the form in the footer menu.' => 'Activa el canal abajo y pon un enlace al formulario en el menú del pie de página.',
    '%d open, %d in total.' => '%d abiertos, %d en total.',
    'Case' => 'Caso',
    'Acknowledge by' => 'Acusar recibo antes de',
    'Feedback by' => 'Responder antes de',
    'Acknowledged' => 'Recibo acusado',
    'In progress' => 'En curso',
    'Case closed' => 'Caso cerrado',
    'acknowledged %s' => 'recibo acusado %s',
    'overdue' => 'vencido',
    'closed %s' => 'cerrado %s',
    'You are not among the readers, so the cases do not open for you.' => 'No estás entre los lectores, así que los casos no se abren para ti.',
    'Setup' => 'Configuración',
    'The channel is on' => 'El canal está activado',
    'The public form: %s. Add a link to it to the footer menu or a page – the site does not add it by itself.' => 'El formulario público: %s. Añade un enlace a él en el menú del pie de página o en una página; el sitio no lo añade automáticamente.',
    'Shown above the form: who handles reports in your company, what belongs here, where the whistleblowing policy is.' => 'Se muestra encima del formulario: quién gestiona las denuncias en tu empresa, qué corresponde aquí y dónde está la política de denuncias.',
    'Who may read reports' => 'Quién puede leer las denuncias',
    'no e-mail – will not be notified' => 'sin correo: no recibirá avisos',
    'Only these people open the reports – other administrators see case numbers and dates. A new report is announced to them by e-mail with the case number only.' => 'Solo estas personas abren las denuncias; los demás administradores ven los números de caso y las fechas. Se les avisa de cada nueva denuncia por correo, solo con el número de caso.',
    'Delete closed cases after' => 'Eliminar los casos cerrados después de',
    'Closed cases are deleted with their attachments and messages; open cases are kept. Check the retention period your national law requires.' => 'Los casos cerrados se eliminan con sus adjuntos y mensajes; los casos abiertos se conservan. Comprueba el plazo de conservación que exige la ley de tu país.',
    'Claude and other connected tools never see the reports: no MCP tool reads or lists them, and the site export leaves them out.' => 'Claude y otras herramientas conectadas nunca ven las denuncias: ninguna herramienta MCP las lee ni las lista, y la exportación del sitio las excluye.',
    'All cases' => 'Todos los casos',
    'Reporter' => 'Denunciante',
    'anonymous' => 'anónimo',
    'Report' => 'Denuncia',
    'Attachments' => 'Adjuntos',
    'Messages' => 'Mensajes',
    'No messages yet. Your first answer acknowledges the receipt.' => 'Aún no hay mensajes. Tu primera respuesta acusa recibo.',
    'Handler' => 'Responsable',
    'Reply to the reporter' => 'Responder al denunciante',
    'The reporter reads it after opening the case with the case number and the access code. Nothing is e-mailed.' => 'El denunciante la lee al abrir el caso con el número de caso y el código de acceso. No se envía nada por correo.',
    'Send the reply' => 'Enviar la respuesta',
    'Change the status' => 'Cambiar el estado',
    'A closed case is deleted after the retention period set in the channel.' => 'Un caso cerrado se elimina tras el plazo de conservación fijado en el canal.',
    'Case %s' => 'Caso %s',
    'Only the appointed readers and administrators see the whistleblowing channel.' => 'Solo los lectores designados y los administradores ven el canal de denuncias.',
    'Saved. Choose at least one reader – until then nobody can open the reports.' => 'Guardado. Elige al menos un lector: hasta entonces nadie puede abrir las denuncias.',
    'Only the appointed readers open reports. An administrator can add readers in the setup of the channel.' => 'Solo los lectores designados abren las denuncias. Un administrador puede añadir lectores en la configuración del canal.',
    'The case does not exist.' => 'El caso no existe.',
    'Write the message first.' => 'Escribe primero el mensaje.',
    'The message was added – the reporter sees it after opening the case with the code.' => 'Se ha añadido el mensaje: el denunciante lo ve al abrir el caso con el código.',
    'The status is saved.' => 'Estado guardado.',
    'Whistleblowing: due deadlines and the retention of closed cases' => 'Canal de denuncias: plazos vencidos y conservación de los casos cerrados',
    'Search Console property' => 'Propiedad de Search Console',
    'sc-domain:example.com or https://example.com/ – load the list with the button below; empty = this site’s address.' => 'sc-domain:example.com o https://example.com/ – carga la lista con el botón de abajo; vacío = la dirección de este sitio.',
    'Site in Bing Webmaster Tools' => 'Sitio en Bing Webmaster Tools',
    'The address as it is registered there, e.g. https://example.com/ – empty = this site’s address.' => 'La dirección tal como está registrada allí, p. ej. https://example.com/ – vacío = la dirección de este sitio.',
    'Load my properties' => 'Cargar mis propiedades',
    'The account has no Search Console property. Add the site at search.google.com/search-console first.' => 'La cuenta no tiene ninguna propiedad de Search Console. Añade primero el sitio en search.google.com/search-console.',
