    'Indexed' => 'Indexados',
    'Search Console has no sitemap of this site yet.' => 'Search Console aún no tiene ningún sitemap de este sitio.',
    'Search engines' => 'Buscadores',
    'Connect Google Search Console or Bing Webmaster Tools in Administration → Connections; the queries and pages arrive with the daily job.' => 'Conecta Google Search Console o Bing Webmaster Tools en Administración → Conexiones; las consultas y páginas llegan con la tarea diaria.',
    'Search engines: the latest snapshot of the period (%s), each covering the 28 days before it; the position is the average place in the results, 1 = first.' => 'Buscadores: la última instantánea del periodo (%s), cada una con los 28 días anteriores; la posición es el lugar medio en los resultados, 1 = primero.',
    '%s on %s' => '%s el %s',
