    'Position' => 'Posición',
    'Sitemap' => 'Sitemap',
    'Sitemaps (Google)' => 'Sitemaps (Google)',
    'Social post drafts' => 'Borradores de publicaciones sociales',
    'When a news item is published, a post draft per network is prepared under the news item – with a tracked link and the image. You copy and post it yourself; the site never posts anywhere.' => 'Al publicar una noticia, se prepara bajo la noticia un borrador de publicación por cada red, con un enlace rastreado y la imagen. Tú lo copias y lo publicas; el sitio nunca publica en ningún sitio.',
    'Social posts' => 'Publicaciones sociales',
    'No network is chosen. Pick the networks under Settings → General → More options and the drafts appear here.' => 'No hay ninguna red elegida. Elige las redes en Ajustes → General → Más opciones y los borradores aparecerán aquí.',
    'Prepared when the news item was published, with a tracked link – the statistics show the visits from each network. Edit the text, copy it and post it yourself; the site never posts anywhere.' => 'Preparados al publicar la noticia, con un enlace rastreado: las estadísticas muestran las visitas de cada red. Edita el texto, cópialo y publícalo tú; el sitio nunca publica en ningún sitio.',
    'Rewrite all the drafts with the assistant? Your edits to them are replaced. Hashtags and the link are added back.' => '¿Reescribir todos los borradores con el asistente? Se reemplazarán tus cambios. Los hashtags y el enlace se vuelven a añadir.',
    'Suggest with the assistant' => 'Sugerir con el asistente',
    'posted %s' => 'publicado %s',
    'Post for %s' => 'Publicación para %s',
    'At most %d characters; a link counts as %d.' => 'Como máximo %d caracteres; un enlace cuenta como %d.',
    'Image:' => 'Imagen:',
    'Link for the bio:' => 'Enlace para la bio:',
    'Not posted yet' => 'Aún sin publicar',
    'Mark as posted' => 'Marcar como publicado',
    'Social post drafts waiting to be posted' => 'Borradores de publicaciones sociales pendientes de publicar',
    'The post draft is saved.' => 'Borrador de publicación guardado.',
    'Marked as posted.' => 'Marcado como publicado.',
    'Marked as not posted yet.' => 'Marcado como aún sin publicar.',
    'The assistant rewrote the drafts – read them before posting.' => 'El asistente ha reescrito los borradores: léelos antes de publicar.',
    'The draft does not exist.' => 'El borrador no existe.',
    'The post needs a text.' => 'La publicación necesita un texto.',
    'The post is too long (at most 3000 characters).' => 'La publicación es demasiado larga (como máximo 3000 caracteres).',
    'X allows 280 characters with a link counted as 23 – this post is longer.' => 'X permite 280 caracteres y cuenta un enlace como 23: esta publicación es más larga.',
    'There are no drafts to rewrite.' => 'No hay borradores que reescribir.',
    'Link in bio' => 'Enlace en la bio',
    'Business Profile' => 'Perfil de Empresa',
    'The opening hours from Business details and their exceptions go to the chosen location whenever they change and once a day; the newest reviews and the rating come back for the Google reviews element and the facts {{fact.google_rating}} and {{fact.google_reviews}}.' => 'El horario de Datos de la empresa y sus excepciones se envían a la ubicación elegida cada vez que cambian y una vez al día; las reseñas más recientes y la valoración vuelven para el elemento Reseñas de Google y los datos clave {{fact.google_rating}} y {{fact.google_reviews}}.',
    '– none, nothing is synced –' => '– ninguna, no se sincroniza nada –',
    'Load the locations of the connected account with the button below.' => 'Carga las ubicaciones de la cuenta conectada con el botón de abajo.',
    'Connect Google first.' => 'Conecta primero Google.',
    'Post news to the Business Profile' => 'Publicar noticias en el Perfil de Empresa',
    'Every newly published news item becomes a post with its image and a “Learn more” button.' => 'Cada noticia recién publicada se convierte en una publicación con su imagen y un botón “Más información”.',
    'Google rating %s out of 5 from %d reviews' => 'Valoración en Google: %s de 5 en %d reseñas',
