    'The Google account manages no Business Profile location.' => 'La cuenta de Google no gestiona ninguna ubicación del Perfil de Empresa.',
    '%d locations loaded – choose one and save.' => '%d ubicaciones cargadas: elige una y guarda.',
    'The hours were sent and the reviews fetched.' => 'Se ha enviado el horario y se han obtenido las reseñas.',
