    'Only these forms' => 'Solo estos formularios',
    'Form names separated by commas; empty = every form' => 'Nombres de formularios separados por comas; vacío = todos los formularios',
    'Include job applications' => 'Incluir candidaturas de empleo',
    'They carry CVs – only the file name goes out, never the file' => 'Llevan CV: solo se envía el nombre del archivo, nunca el archivo',
    'Enquiries to a sheet' => 'Consultas a una hoja',
    'Spreadsheet ID' => 'ID de la hoja de cálculo',
    'Filled in by “Create the sheet”; clear it to have a new sheet created' => 'Se rellena con “Crear la hoja”; vacíalo para que se cree una hoja nueva',
    'Company domain' => 'Dominio de la empresa',
    'The <x> of <x>.pipedrive.com' => 'El <x> de <x>.pipedrive.com',
    'Instance name' => 'Nombre de la instancia',
