    'Create the sheet' => 'Crear la hoja',
    'Open the sheet' => 'Abrir la hoja',
    'Create the sheet first – without it no enquiry is sent.' => 'Crea primero la hoja: sin ella no se envía ninguna consulta.',
    'The sheet was created – tick “Enquiries to a sheet” and new enquiries will appear in it.' => 'Se ha creado la hoja: marca “Consultas a una hoja” y las nuevas consultas aparecerán en ella.',
    '%s – enquiries' => '%s – consultas',
    'Google did not return the sheet.' => 'Google no ha devuelto la hoja.',
    'No sheet – create it in Administration → Connections.' => 'No hay hoja: créala en Administración → Conexiones.',
    'Enter the company domain of Pipedrive in Connections.' => 'Introduce el dominio de empresa de Pipedrive en Conexiones.',
    'Enter the Raynet instance name in Connections.' => 'Introduce el nombre de la instancia de Raynet en Conexiones.',
    'Fields' => 'Campos',
    'Why: %s' => 'Motivo: %s',
    'Guardrails for Claude' => 'Salvaguardas para Claude',
    'They hold for every Claude connection on top of its access. Claude is told why when it hits one, so it can tell you.' => 'Se aplican a cada conexión de Claude además de su acceso. Claude recibe el motivo cuando choca con una, para que pueda explicártelo.',
    'Changes per connection and hour' => 'Cambios por conexión y hora',
    '0 = no limit. A long run of changes stops here until the next hour.' => '0 = sin límite. Una serie larga de cambios se detiene aquí hasta la hora siguiente.',
    'Deleting' => 'Eliminación',
    'Claude may delete, trash and discard drafts' => 'Claude puede eliminar, enviar a la papelera y descartar borradores',
    'Off: those tools are refused for every connection; you do them in the admin.' => 'Desactivado: esas herramientas se rechazan para todas las conexiones; las usas tú en la administración.',
    'Protected pages' => 'Páginas protegidas',
    'Page numbers (shown in the page editor’s address) that Claude must not change – neither their settings nor their build.' => 'Números de página (se ven en la dirección del editor de páginas) que Claude no debe cambiar: ni sus ajustes ni su construcción.',
    'Notebook' => 'Cuaderno',
    'New note' => 'Nueva nota',
    'The note does not exist.' => 'La nota no existe.',
    'The note is saved.' => 'Nota guardada.',
    'The note is deleted.' => 'Nota eliminada.',
    'A note needs a title.' => 'Una nota necesita un título.',
    'A note needs a text.' => 'Una nota necesita un texto.',
    'The topic must be one of: %s.' => 'El tema debe ser uno de estos: %s.',
    'Notes for whoever works on the site next – Claude in a new conversation, or a colleague: decisions, wording rules, photo credits, the history of the site, what the client is sensitive about. Claude reads them with read_notebook before larger changes and writes decisions down with write_notebook – a drafts-only connection too. Nothing here is shown on the site.' => 'Notas para quien trabaje después en el sitio (Claude en una conversación nueva o un compañero): decisiones, reglas de redacción, créditos de fotos, la historia del sitio, aquello a lo que el cliente es sensible. Claude las lee con read_notebook antes de cambios grandes y anota las decisiones con write_notebook, también con una conexión solo de borradores. Nada de esto se muestra en el sitio.',
    'All topics' => 'Todos los temas',
    'Decisions' => 'Decisiones',
    'Style and wording' => 'Estilo y redacción',
    'Credits' => 'Créditos',
    'Search (title, text):' => 'Buscar (título, texto):',
    'No note matches the filter.' => 'Ninguna nota coincide con el filtro.',
    'Try another word or topic.' => 'Prueba con otra palabra o tema.',
    'No notes yet.' => 'Aún no hay notas.',
    'Write down what the next person – or Claude – should know: a decision, a wording rule, who took the photos, why a page looks the way it does.' => 'Anota lo que debería saber la siguiente persona (o Claude): una decisión, una regla de redacción, quién hizo las fotos, por qué una página es como es.',
    'pinned' => 'fijada',
    'Unpin' => 'Desfijar',
    'Pin' => 'Fijar',
    'Delete the note? It cannot be brought back.' => '¿Eliminar la nota? No se puede recuperar.',
    'Only the first %d notes are shown – narrow the list by a topic or a search.' => 'Solo se muestran las primeras %d notas: acota la lista con un tema o una búsqueda.',
    'All notes' => 'Todas las notas',
    'e.g. We never use the word “cheap”' => 'p. ej. Nunca usamos la palabra “barato”',
    'Plain text. Write it for someone who knows nothing about the site yet – what was decided, why, and what to keep to.' => 'Texto sin formato. Escríbelo para alguien que aún no sabe nada del sitio: qué se decidió, por qué y qué hay que respetar.',
    'Pinned' => 'Fijada',
    'Pinned notes come first and Claude sees their titles as soon as it connects.' => 'Las notas fijadas aparecen primero y Claude ve sus títulos en cuanto se conecta.',
    'Written by %s, %s; last changed %s.' => 'Escrita por %s, %s; último cambio %s.',
    'Requests' => 'Encargos',
    'New request' => 'Nuevo encargo',
    'New' => 'Nuevo',
    'Declined' => 'Rechazado',
    '(no longer exists)' => '(ya no existe)',
    'A new request for Claude: %s' => 'Un nuevo encargo para Claude: %s',
    '(account removed)' => '(cuenta eliminada)',
    'New request for Claude: %s' => 'Nuevo encargo para Claude: %s',
    'A colleague wrote a new request for Claude: %s' => 'Un compañero ha escrito un nuevo encargo para Claude: %s',
    'Your request is done: %s' => 'Tu encargo está hecho: %s',
    'Your request “%s” is marked done.' => 'Tu encargo “%s” está marcado como hecho.',
    'The drafts wait for your review in the administration – nothing was published by itself.' => 'Los borradores esperan tu revisión en la administración; no se ha publicado nada automáticamente.',
    'The attachment %s could not be saved: %s' => 'No se ha podido guardar el adjunto %s: %s',
    'Request #%d' => 'Encargo n.º %d',
    'The request is saved. Claude will see it the next time it works on the site; you will read its notes here.' => 'Encargo guardado. Claude lo verá la próxima vez que trabaje en el sitio; aquí leerás sus notas.',
    'The request does not exist.' => 'El encargo no existe.',
    'Write the reply first.' => 'Escribe primero la respuesta.',
    'The reply is added – Claude reads it with the request.' => 'Respuesta añadida: Claude la lee junto con el encargo.',
    'This status change is not possible.' => 'Este cambio de estado no es posible.',
    'Write what should change on the site – "change the opening hours on Monday", "add this PDF to the price list" – and Claude does it as drafts the next time it works on the site. Its notes and the links to the drafts appear in the request; a person reviews and publishes them.' => 'Escribe qué debe cambiar en el sitio (“cambia el horario del lunes”, “añade este PDF a la lista de precios”) y Claude lo hará como borradores la próxima vez que trabaje en el sitio. Sus notas y los enlaces a los borradores aparecen en el encargo; una persona los revisa y los publica.',
    'The Claude connection is switched off (Features) – requests are saved, but nobody reads them until it is on.' => 'La conexión con Claude está desactivada (Funciones): los encargos se guardan, pero nadie los lee hasta que se active.',
    'Request status' => 'Estado del encargo',
    'No request has this status.' => 'Ningún encargo tiene este estado.',
    'No requests yet.' => 'Aún no hay encargos.',
    'Write the first one: what should change, on which page, with the files Claude needs.' => 'Escribe el primero: qué debe cambiar, en qué página y con los archivos que Claude necesita.',
    '%d open, %d shown.' => '%d abiertos, %d mostrados.',
    'Request' => 'Encargo',
    'Written' => 'Escrito',
    'Last change' => 'Último cambio',
    '%d attachments' => '%d adjuntos',
    'All requests' => 'Todos los encargos',
    'What should change' => 'Qué debe cambiar',
    'e.g. Opening hours on Monday' => 'p. ej. Horario del lunes',
    'Write it as you would to a colleague: what, where on the site, and by when it matters.' => 'Escríbelo como se lo dirías a un compañero: qué, en qué parte del sitio y para cuándo es importante.',
    'Claude reads it as a job to do as drafts – it never publishes anything by itself; you or an administrator review and publish the drafts.' => 'Claude lo lee como una tarea que hacer en borradores: nunca publica nada por sí mismo; los borradores los revisas y publicas tú o un administrador.',
    'It is about' => 'Se refiere a',
    '— the site in general —' => '— el sitio en general —',
    'or paste the address, e.g. /price-list' => 'o pega la dirección, p. ej. /lista-de-precios',
    'Address of the page it is about' => 'Dirección de la página a la que se refiere',
    'Up to %d files – a PDF, a photo, a document (%s each at most). They are saved to Media, so Claude can place them on the site.' => 'Hasta %d archivos: un PDF, una foto, un documento (%s como máximo cada uno). Se guardan en Medios para que Claude pueda colocarlos en el sitio.',
    'Save the request' => 'Guardar el encargo',
    'Saved in Media – Claude places them on the site from there.' => 'Guardados en Medios: Claude los coloca en el sitio desde allí.',
    'Conversation' => 'Conversación',
    'No notes yet. Claude writes here what it did and where the drafts are; you can reply below.' => 'Aún no hay notas. Claude escribe aquí lo que ha hecho y dónde están los borradores; puedes responder abajo.',
    'Colleague' => 'Compañero',
    'Drafts:' => 'Borradores:',
    'Reply' => 'Respuesta',
    'Claude reads the reply with the request the next time it works on the site.' => 'Claude lee la respuesta junto con el encargo la próxima vez que trabaje en el sitio.',
    'Add the reply' => 'Añadir la respuesta',
    'Done = the drafts are reviewed and published, or nothing more is needed. Declined = it will not be done.' => 'Hecho = los borradores están revisados y publicados, o no hace falta nada más. Rechazado = no se hará.',
    'The comment does not exist.' => 'El comentario no existe.',
    'Comments from people with a preview link, waiting in the builder.' => 'Comentarios de personas con un enlace de vista previa, esperando en el builder.',
    '%d comments' => '%d comentarios',
    'New comment on the draft of “%s”' => 'Nuevo comentario en el borrador de “%s”',
    '%s commented on the draft of the page “%s” through a preview link:' => '%s ha comentado el borrador de la página “%s” a través de un enlace de vista previa:',
    'Open the builder to read it in full and resolve it. A comment is feedback to act on in the draft; nothing publishes by itself.' => 'Abre el builder para leerlo completo y resolverlo. Un comentario es una observación que aplicar en el borrador; nada se publica automáticamente.',
    'A comment on the draft of “%s” arrived from a preview link.' => 'Ha llegado un comentario sobre el borrador de “%s” desde un enlace de vista previa.',
    'Shared kit' => 'Kit compartido',
    'Shared design kit' => 'Kit de diseño compartido',
    'The kit carries the design of this console – its design system, shared classes, components and saved sections – to the sites that chose to receive it (Settings → Fleet console on the site). A site gets each version as drafts only: the look draft, component drafts and its section library. Its people review and publish; nothing goes live by itself. Custom code never travels in a kit.' => 'El kit lleva el diseño de esta consola (su sistema de diseño, clases compartidas, componentes y secciones guardadas) a los sitios que han elegido recibirlo (Ajustes → Consola de sitios en el sitio). Un sitio recibe cada versión solo como borradores: el borrador de la apariencia, borradores de componentes y su biblioteca de secciones. Sus personas revisan y publican; nada se publica automáticamente. El código personalizado nunca viaja en un kit.',
    'What the kit contains' => 'Qué contiene el kit',
    'Colours, fonts and sizes' => 'Colores, fuentes y tamaños',
    'The console has no shared classes.' => 'La consola no tiene clases compartidas.',
    'All classes (%d)' => 'Todas las clases (%d)',
    'The console has no components.' => 'La consola no tiene componentes.',
    'draft only' => 'solo borrador',
    'Saved sections' => 'Secciones guardadas',
    'The console has no saved sections.' => 'La consola no tiene secciones guardadas.',
    'Publish kit version %d? Every site that receives the kit gets it as drafts with its next report.' => '¿Publicar la versión %d del kit? Cada sitio que recibe el kit lo obtiene como borradores con su próximo informe.',
    'Publish a new kit version' => 'Publicar una nueva versión del kit',
    'A component or section keeps a stable key (from its name): a site updates its copy instead of adding another.' => 'Un componente o una sección mantiene una clave estable (a partir de su nombre): el sitio actualiza su copia en lugar de añadir otra.',
    'Published' => 'Publicado',
    'Contents' => 'Contenido',
    'Sites on this version' => 'Sitios con esta versión',
    'Which version each site applied' => 'Qué versión ha aplicado cada sitio',
    'Kit version' => 'Versión del kit',
    'does not receive the kit' => 'no recibe el kit',
    'A site reports the version it applied with its next report; a site that did not switch the kit on shows none.' => 'Un sitio informa de la versión aplicada con su próximo informe; un sitio que no ha activado el kit no muestra ninguna.',
    'Kit version %d is published (%s). Every site that receives the kit picks it up with its next report, within an hour – as drafts for its people to publish.' => 'Se ha publicado la versión %d del kit (%s). Cada sitio que recibe el kit la obtiene con su próximo informe, en menos de una hora, como borradores que su equipo publicará.',
    'Choose at least one thing for the kit: the design system, a class, a component or a section.' => 'Elige al menos una cosa para el kit: el sistema de diseño, una clase, un componente o una sección.',
    'The kit is too large (%s) – choose fewer components or sections.' => 'El kit es demasiado grande (%s): elige menos componentes o secciones.',
    'Kit version %d was published for the fleet: %s.' => 'Se ha publicado la versión %d del kit para los sitios: %s.',
    'Kit version %d from the console arrived as drafts: %s.' => 'La versión %d del kit de la consola ha llegado como borradores: %s.',
    'Kit version %d from the console was refused: %s' => 'Se ha rechazado la versión %d del kit de la consola: %s',
    'The console can share a design kit – its design system, shared classes, components and saved sections. Here it arrives as drafts only: into the look draft, into component drafts and into the section library. Nothing is published until you publish it. Custom code never travels in a kit.' => 'La consola puede compartir un kit de diseño: su sistema de diseño, clases compartidas, componentes y secciones guardadas. Aquí llega solo como borradores: al borrador de la apariencia, a borradores de componentes y a la biblioteca de secciones. Nada se publica hasta que tú lo publiques. El código personalizado nunca viaja en un kit.',
    'Receive the shared design kit' => 'Recibir el kit de diseño compartido',
    'Received kit version %d on %s.' => 'Versión %d del kit recibida el %s.',
    'The look draft and the component drafts are waiting for your review:' => 'El borrador de la apariencia y los borradores de componentes esperan tu revisión:',
    'The last kit was refused: %s' => 'Se rechazó el último kit: %s',
    'Save the choice about the kit' => 'Guardar la elección sobre el kit',
    'The choice about the shared kit is saved.' => 'Elección sobre el kit compartido guardada.',
    'The console did not hand over the kit (%s).' => 'La consola no ha entregado el kit (%s).',
    'The kit is not signed by the console – refused.' => 'El kit no está firmado por la consola: rechazado.',
    'The console handed over a different kit version than it announced – refused.' => 'La consola ha entregado una versión del kit distinta de la anunciada: rechazado.',
    'The kit is too large – refused.' => 'El kit es demasiado grande: rechazado.',
    'The kit does not match the hash the console announced – refused.' => 'El kit no coincide con el hash que anunció la consola: rechazado.',
    'The kit is not readable – refused.' => 'El kit no se puede leer: rechazado.',
    'Design system' => 'Sistema de diseño',
    'Claude sessions' => 'Sesiones de Claude',
    'undo everything one Claude session changed' => 'deshacer todo lo que cambió una sesión de Claude',
    'Changes one Claude connection makes in a row (with less than %d minutes between them) form a session. Undo puts back everything the session changed – pages, builds and drafts, news, collection items, menus, settings, the look – as it was before. Sessions are kept %d days.' => 'Los cambios que una conexión de Claude hace seguidos (con menos de %d minutos entre ellos) forman una sesión. Deshacer devuelve todo lo que cambió la sesión (páginas, construcciones y borradores, noticias, elementos de colecciones, menús, ajustes, la apariencia) a como estaba antes. Las sesiones se conservan %d días.',
    '%d rows were changed after the session (by a person or another session) and were left as they are. Undo again with “Also overwrite later changes” to put them back too.' => '%d filas se cambiaron después de la sesión (por una persona u otra sesión) y se han dejado como están. Vuelve a deshacer con “Sobrescribir también los cambios posteriores” para restaurarlas también.',
    'These changes could not be followed row by row and stay as they are – check them by hand:' => 'Estos cambios no se pudieron seguir fila por fila y quedan como están; revísalos a mano:',
    'No Claude session yet.' => 'Aún no hay ninguna sesión de Claude.',
    'Connection' => 'Conexión',
    'Changes that undo cannot follow' => 'Cambios que deshacer no puede seguir',
    'Undone %s by %s' => 'Deshecha el %s por %s',
    'Undo everything this session changed?' => '¿Deshacer todo lo que cambió esta sesión?',
    'Also overwrite later changes' => 'Sobrescribir también los cambios posteriores',
    'Undo the session' => 'Deshacer la sesión',
    'The session is undone: %d rows restored, %d removed.' => 'Sesión deshecha: %d filas restauradas, %d eliminadas.',
    'A Claude session was undone: %d rows restored, %d removed, %d left because they changed since.' => 'Se ha deshecho una sesión de Claude: %d filas restauradas, %d eliminadas, %d sin tocar porque han cambiado desde entonces.',
    'The session does not exist.' => 'La sesión no existe.',
    'This session was already undone.' => 'Esta sesión ya se ha deshecho.',
    'Add-ons are code from other developers. Copy an add-on into the folder extensions/<name>/ on your hosting and switch it on here. An add-on runs with the same rights as Kaleta – switch on only code you trust, from a source you know. Kaleta never uploads or downloads add-ons by itself.' => 'Los complementos son código de otros desarrolladores. Copia un complemento en la carpeta extensions/<name>/ de tu hosting y actívalo aquí. Un complemento se ejecuta con los mismos permisos que Kaleta: activa solo código en el que confíes, de una fuente que conozcas. Kaleta nunca sube ni descarga complementos por sí misma.',
    'A developer’s guide is in docs/EXTENSIONS.md. This Kaleta offers extension API %d.' => 'Hay una guía para desarrolladores en docs/EXTENSIONS.md. Esta instalación de Kaleta ofrece la API de extensiones %d.',
    'Add-ons do not run in the public demo.' => 'Los complementos no se ejecutan en la demo pública.',
    'Add-ons are switched off in config.php (safe mode) – none is loaded.' => 'Los complementos están desactivados en config.php (modo seguro): no se carga ninguno.',
    'No add-on in extensions/ yet.' => 'Aún no hay ningún complemento en extensions/.',
    'Add-on' => 'Complemento',
    'Switched off after an error: %s' => 'Desactivado tras un error: %s',
    'On' => 'Activado',
    'Off' => 'Desactivado',
    'Switch off' => 'Desactivar',
    'I trust this code' => 'Confío en este código',
    'Switch on' => 'Activar',
    'Pages of add-ons' => 'Páginas de complementos',
    'This page belongs to the add-on %s.' => 'Esta página pertenece al complemento %s.',
    'Tick that you trust the code of this add-on.' => 'Marca que confías en el código de este complemento.',
    'The add-on is switched on.' => 'Complemento activado.',
    'The add-on is switched off – its data stays.' => 'Complemento desactivado: sus datos se conservan.',
    'The add-on page does not exist or its add-on is switched off.' => 'La página del complemento no existe o su complemento está desactivado.',
    'The add-on failed: %s' => 'El complemento ha fallado: %s',
    'The add-on %s was switched on.' => 'Se ha activado el complemento %s.',
    'The add-on %s failed and was switched off: %s' => 'El complemento %s ha fallado y se ha desactivado: %s',
    'The folder name must be lowercase letters, digits and _ (it is the add-on\'s slug).' => 'El nombre de la carpeta debe tener solo minúsculas, dígitos y _ (es el slug del complemento).',
    'extension.json is not valid JSON.' => 'extension.json no es un JSON válido.',
    'extension.json has no valid "class".' => 'extension.json no tiene un "class" válido.',
    'The entry file is missing or not a .php file inside the add-on.' => 'Falta el archivo de entrada o no es un archivo .php dentro del complemento.',
    'Add-ons' => 'Complementos',
    'Also:' => 'Además:',
    'Handed out but not reported within %d hours – written off by the site.' => 'Entregada pero sin informe en %d horas: el sitio la ha dado por perdida.',
    'The scheduled Claude run “%s” was not picked up – check the routine in Claude (Scheduled runs).' => 'La ejecución programada de Claude “%s” no se ha recogido: revisa la rutina en Claude (Ejecuciones programadas).',
    'Give the schedule a name.' => 'Ponle un nombre a la programación.',
    'Choose what the run does.' => 'Elige qué hace la ejecución.',
    'Write the instructions for the run.' => 'Escribe las instrucciones para la ejecución.',
    'Choose how often it runs.' => 'Elige con qué frecuencia se ejecuta.',
    'Choose the day of the week.' => 'Elige el día de la semana.',
    'The day of the month must be 1–28, so that every month has it.' => 'El día del mes debe ser 1–28, para que exista en todos los meses.',
    'The time must be HH:MM.' => 'La hora debe tener el formato HH:MM.',
    'The schedule does not exist.' => 'La programación no existe.',
    'The schedule is saved. The site hands the run to the routine in Claude when its time comes – set the routine up below if you have not yet.' => 'Programación guardada. El sitio entrega la ejecución a la rutina en Claude cuando llega su hora; configura la rutina abajo si aún no lo has hecho.',
    'The schedule and its history are deleted.' => 'Se han eliminado la programación y su historial.',
    'The schedule is active again.' => 'La programación vuelve a estar activa.',
    'The schedule is paused – no runs are handed out until you resume it.' => 'Programación en pausa: no se entregan ejecuciones hasta que la reanudes.',
    'Scheduled runs' => 'Ejecuciones programadas',
    'no run yet' => 'aún sin ejecuciones',
    'every %s at %s' => 'cada %s a las %s',
    'every month on day %d at %s' => 'cada mes el día %d a las %s',
    'every day at %s' => 'cada día a las %s',
    'The site cannot run Claude by itself. It keeps the schedules below, tells a routine in Claude what is due, records each run and notices runs nobody picked up. The run itself happens in Claude – a scheduled task in the Claude app or a Claude Code routine – connected to this site with drafts-only access, so a run never publishes, deletes or sends anything.' => 'El sitio no puede ejecutar Claude por sí mismo. Guarda las programaciones de abajo, avisa a una rutina en Claude de lo que toca, registra cada ejecución y detecta las ejecuciones que nadie recogió. La ejecución en sí ocurre en Claude (una tarea programada en la app de Claude o una rutina de Claude Code), conectado a este sitio con acceso solo a borradores, así que una ejecución nunca publica, elimina ni envía nada.',
    'The Claude connection is switched off (Features) – the schedules are kept, but no routine can pick the runs up until it is on.' => 'La conexión con Claude está desactivada (Funciones): las programaciones se conservan, pero ninguna rutina puede recoger las ejecuciones hasta que se active.',
    'New schedule' => 'Nueva programación',
    'No schedules yet.' => 'Aún no hay programaciones.',
    'Typical ones: a site review every Monday, a report on the first of the month, a triage of new enquiries every morning, the open requests from staff every day.' => 'Las habituales: una revisión del sitio cada lunes, un informe el día uno de cada mes, una clasificación de las nuevas consultas cada mañana, los encargos abiertos del equipo cada día.',
    'Schedule' => 'Programación',
    'Next due' => 'Próxima',
    'paused' => 'en pausa',
    'Pause' => 'Pausar',
    'Resume' => 'Reanudar',
    'Set up in Claude' => 'Configurar en Claude',
    'Connect Claude to this site with a drafts-only token or connection: My account → Claude connection, access “drafts only”. A drafts-only connection can read the site and save drafts, and the two tools the routine needs (get_due_agent_runs, report_agent_run) – it cannot publish, delete or send.' => 'Conecta Claude a este sitio con un token o una conexión solo de borradores: Mi cuenta → Conexión con Claude, acceso “solo borradores”. Una conexión solo de borradores puede leer el sitio y guardar borradores, además de usar las dos herramientas que necesita la rutina (get_due_agent_runs, report_agent_run); no puede publicar, eliminar ni enviar.',
    'no drafts-only token yet' => 'aún no hay ningún token solo de borradores',
    'In Claude, create a scheduled task (the Claude app) or a routine (Claude Code) that runs a little after the earliest time in your schedules – for example every day at 07:15 – with this prompt:' => 'En Claude, crea una tarea programada (la app de Claude) o una rutina (Claude Code) que se ejecute un poco después de la hora más temprana de tus programaciones (por ejemplo, cada día a las 07:15) con este prompt:',
    'The routine asks the site what is due, does each run as drafts and reports it; the summary and the links to the drafts appear in the history here. You review and publish. A run nobody picks up within 6 hours is marked missed and reported in the events and the alert e-mails.' => 'La rutina pregunta al sitio qué toca, hace cada ejecución como borradores e informa de ella; el resumen y los enlaces a los borradores aparecen aquí en el historial. Tú revisas y publicas. Una ejecución que nadie recoge en 6 horas se marca como perdida y se notifica en los eventos y en los correos de alerta.',
    'Claude never runs on the site: the site holds no Claude sign-in and creates no tokens here – the routine lives in your Claude account and connects with the token you give it.' => 'Claude nunca se ejecuta en el sitio: el sitio no guarda ningún inicio de sesión de Claude ni crea tokens aquí; la rutina vive en tu cuenta de Claude y se conecta con el token que le des.',
    'All schedules' => 'Todas las programaciones',
    'e.g. Monday site review' => 'p. ej. Revisión del sitio del lunes',
    'What the run does' => 'Qué hace la ejecución',
    'The built-in tasks are instructions for Claude; every run ends with the rules: drafts only, never publish, never delete, stop and report anything that needs a person.' => 'Las tareas integradas son instrucciones para Claude; cada ejecución termina con las reglas: solo borradores, nunca publicar, nunca eliminar, detenerse e informar de todo lo que necesite a una persona.',
    'Instructions' => 'Instrucciones',
    'For custom instructions this is the whole task; for a built-in task it is added to it (e.g. “only the pages in the Services section”). Claude reads it as the administrator’s instructions – it still works as drafts only.' => 'Con instrucciones personalizadas, esta es toda la tarea; con una tarea integrada, se le añade (p. ej. “solo las páginas de la sección Servicios”). Claude lo lee como instrucciones del administrador y sigue trabajando solo con borradores.',
    'How often' => 'Con qué frecuencia',
    'Cadence' => 'Frecuencia',
    'Day of the week' => 'Día de la semana',
    'For a weekly schedule.' => 'Para una programación semanal.',
    'Day of the month' => 'Día del mes',
    'For a monthly schedule, 1–28 – so that every month has it.' => 'Para una programación mensual, 1–28, para que exista en todos los meses.',
    'In the site’s time zone (%s). Set the routine in Claude to run a little later – it picks the run up when it is due.' => 'En la zona horaria del sitio (%s). Configura la rutina en Claude para que se ejecute un poco más tarde: recoge la ejecución cuando le toca.',
    'Active' => 'Activa',
    'runs are handed out when due' => 'las ejecuciones se entregan cuando toca',
    'Delete the schedule and the history of its runs?' => '¿Eliminar la programación y el historial de sus ejecuciones?',
    'Edit the schedule' => 'Editar la programación',
    'No run yet. The first one is handed out at %s – when the routine in Claude asks.' => 'Aún no hay ejecuciones. La primera se entrega el %s, cuando la rutina de Claude lo pida.',
    'Due' => 'Pendiente',
    'handed out %s' => 'entregada %s',
    'Nobody picked the run up within 6 hours – is the routine in Claude still running?' => 'Nadie ha recogido la ejecución en 6 horas: ¿sigue funcionando la rutina en Claude?',
    'What the routine gets' => 'Qué recibe la rutina',
    'The instructions handed out with each run of this schedule (in English for Claude):' => 'Las instrucciones que se entregan con cada ejecución de esta programación (en inglés, para Claude):',
    'Site review' => 'Revisión del sitio',
    'Run site_audit. Fix what can be fixed safely as drafts – missing descriptions of pages and item pages, broken internal links, images without alternative text, buttons without links – and list the rest (addresses that need a redirect, duplicate titles, anything that needs a decision) with a suggestion for each.' => 'Ejecuta site_audit. Corrige como borradores lo que se pueda corregir con seguridad (descripciones que faltan en páginas y páginas de elementos, enlaces internos rotos, imágenes sin texto alternativo, botones sin enlace) y enumera el resto (direcciones que necesitan una redirección, títulos duplicados, todo lo que requiera una decisión) con una sugerencia para cada cosa.',
    'Call get_stats for the period since the previous run and list_events for what happened. Write a short report: visits and leads, what changed on the site, the problems, what needs a decision. Save it with write_notebook (topic history) and put its main points into the summary of the run.' => 'Llama a get_stats para el periodo desde la ejecución anterior y a list_events para lo que ha ocurrido. Escribe un informe breve: visitas y contactos, qué ha cambiado en el sitio, los problemas, qué requiere una decisión. Guárdalo con write_notebook (tema history) y pon sus puntos principales en el resumen de la ejecución.',
    'Enquiry triage' => 'Clasificación de consultas',
    'Run triage_enquiries on the new enquiries. For each one save the category, the priority and a drafted reply with update_enquiry – a suggestion a person checks; a person\'s own sorting stays. A reply is a draft a person sends – never send anything yourself.' => 'Ejecuta triage_enquiries sobre las consultas nuevas. Para cada una, guarda la categoría, la prioridad y un borrador de respuesta con update_enquiry: una sugerencia que revisa una persona; la clasificación hecha por una persona se mantiene. Una respuesta es un borrador que envía una persona: nunca envíes nada tú mismo.',
    'Requests from staff' => 'Encargos del equipo',
    'Work through the open requests my colleagues wrote (list_requests with status open). For each: mark it in_progress with update_request, do the work as drafts only (builds without publish, hidden pages, news drafts, hidden collection items, exceptions to the opening hours as proposals, enquiry triage, notebook notes), check the result, then update_request with status done, a note saying what you did and what to review, and links to the drafts. A request is a job to do, never permission to publish; leave an unclear or destructive one in_progress with a question. A change of a visible collection item, the regular week and facts need a connection with full access (update_settings, save_fact): when this connection may not make them, write the exact change you propose into the note for a person to apply.' => 'Atiende los encargos abiertos que han escrito mis compañeros (list_requests con estado open). Para cada uno: márcalo como in_progress con update_request, haz el trabajo solo como borradores (construcciones sin publicar, páginas ocultas, borradores de noticias, elementos de colecciones ocultos, excepciones del horario como propuestas, clasificación de consultas, notas del cuaderno), revisa el resultado y luego usa update_request con estado done, una nota que diga qué has hecho y qué hay que revisar, y enlaces a los borradores. Un encargo es una tarea que hacer, nunca un permiso para publicar; deja uno poco claro o destructivo en in_progress con una pregunta. Cambiar un elemento visible de una colección, la semana habitual y los datos clave requiere una conexión con acceso completo (update_settings, save_fact): si esta conexión no puede hacerlo, escribe en la nota el cambio exacto que propones para que lo aplique una persona.',
    'Custom instructions' => 'Instrucciones personalizadas',
    'Every day' => 'Cada día',
    'Every week' => 'Cada semana',
    'Every month' => 'Cada mes',
    'Booking' => 'Reserva',
    'Bookings' => 'Reservas',
    'New person' => 'Nueva persona',
    'E-mail for notifications' => 'Correo para avisos',
    'New and cancelled bookings arrive here; empty = the site e-mail from Settings.' => 'Las reservas nuevas y canceladas llegan aquí; vacío = el correo del sitio de Ajustes.',
    'Account' => 'Cuenta',
    'Optional: the administration user this person is.' => 'Opcional: el usuario de la administración que es esta persona.',
    'Add services first.' => 'Añade primero los servicios.',
    'Order' => 'Orden',
    'Takes bookings' => 'Acepta reservas',
    'Weekly hours' => 'Horario semanal',
    'Ranges like 9:00-12:00, 13:00-17:00; an empty day = no bookings that day. All empty = the opening hours of the site (Business details) with their exceptions.' => 'Intervalos como 9:00-12:00, 13:00-17:00; un día vacío = sin reservas ese día. Todos vacíos = el horario del sitio (Datos de la empresa) con sus excepciones.',
    'Days off' => 'Días libres',
    'everyone' => 'todos',
    'Off from' => 'Libre desde',
    'e.g. holiday' => 'p. ej. vacaciones',
    'Add' => 'Añadir',
    'All bookings' => 'Todas las reservas',
    'New service' => 'Nuevo servicio',
    'No services yet. A service is what the visitor books: a haircut, a consultation, a tyre change – with how long it takes.' => 'Aún no hay servicios. Un servicio es lo que reserva el visitante: un corte de pelo, una consulta, un cambio de neumáticos, con lo que dura.',
    'Buffer' => 'Margen',
    'Offered by' => 'Ofrecido por',
    'switched off' => 'desactivado',
    'nobody yet' => 'nadie todavía',
    'Delete the service?' => '¿Eliminar el servicio?',
    'e.g. Haircut' => 'p. ej. Corte de pelo',
    'The offered times step by the duration (up to an hour; longer services every 15 minutes).' => 'Las horas ofrecidas avanzan según la duración (hasta una hora; los servicios más largos, cada 15 minutos).',
    'minutes kept free after the appointment' => 'minutos libres después de la cita',
    'e.g. from 450 CZK' => 'p. ej. desde 450 CZK',
    'Shown as written. No payments – the customer pays on the spot.' => 'Se muestra tal como está escrito. Sin pagos: el cliente paga en el lugar.',
    'Add people first.' => 'Añade primero personas.',
    'Offered to visitors' => 'Ofrecido a los visitantes',
    'all services' => 'todos los servicios',
    'any' => 'cualquiera',
    'New booking' => 'Nueva reserva',
    'Set up the booking first.' => 'Configura primero las reservas.',
    'Add a service (what and how long) and a person who offers it. Then put the Booking element on a page – visitors pick a service, a person, a day and a free time.' => 'Añade un servicio (qué y cuánto dura) y una persona que lo ofrezca. Después pon el elemento Reserva en una página: los visitantes eligen un servicio, una persona, un día y una hora libre.',
    'Add a service' => 'Añadir un servicio',
    'No bookings here.' => 'No hay reservas aquí.',
    'Nothing booked for these days and filters.' => 'No hay nada reservado para estos días y filtros.',
    'Customer' => 'Cliente',
    'anonymised' => 'anonimizado',
    'Earliest booking' => 'Reserva más temprana',
    'hours ahead' => 'horas de antelación',
    'Bookable ahead' => 'Reservable con antelación',
    'Cancel link works until' => 'El enlace de cancelación funciona hasta',
    'hours before the start' => 'horas antes del inicio',
    'Reminder e-mail' => 'Correo de recordatorio',
    'hours before the start (0 = none)' => 'horas antes del inicio (0 = ninguno)',
    'Bookings follow the enquiry retention: %d months after the appointment they are %s (Enquiries → settings).' => 'Las reservas siguen la conservación de las consultas: a los %d meses de la cita, %s (Consultas → ajustes).',
    'Bookings are kept for good – set a retention in Enquiries so personal data does not stay forever.' => 'Las reservas se conservan para siempre: fija un plazo de conservación en Consultas para que los datos personales no se queden indefinidamente.',
    'Appointment' => 'Cita',
    'Anyone available' => 'Cualquiera disponible',
    'Day and time' => 'Día y hora',
    'The time must be free for the person within their hours; the lead time for visitors does not apply here.' => 'La hora debe estar libre para la persona dentro de su horario; la antelación para visitantes no se aplica aquí.',
    'With an e-mail the customer gets the confirmation, the cancel link and the reminder.' => 'Con un correo, el cliente recibe la confirmación, el enlace de cancelación y el recordatorio.',
    'Save booking' => 'Guardar reserva',
    'Booked' => 'Reservado',
    'in the administration' => 'en la administración',
    'Reminder' => 'Recordatorio',
    'sent %s' => 'enviado %s',
    'not yet' => 'aún no',
    'the customer may cancel online until %s' => 'el cliente puede cancelar en línea hasta el %s',
    'Did not come' => 'No se presentó',
    'Cancel the appointment? The customer will get an e-mail.' => '¿Cancelar la cita? El cliente recibirá un correo.',
    'Cancel the appointment' => 'Cancelar la cita',
    'Blank the name, e-mail, phone and note of this booking? The row stays for statistics.' => '¿Borrar el nombre, el correo, el teléfono y la nota de esta reserva? La fila se mantiene para las estadísticas.',
    'Everything about the person is erased for all bookings of one e-mail address in Enquiries → Personal data request.' => 'Todo lo relativo a la persona se borra de todas las reservas de una dirección de correo en Consultas → Solicitud de datos personales.',
    'Nobody takes bookings yet. Add the people (or just one entry for the whole business) and tick the services each offers.' => 'Aún nadie acepta reservas. Añade las personas (o una sola entrada para todo el negocio) y marca los servicios que ofrece cada una.',
    'none yet' => 'ninguno todavía',
    'Remove the person?' => '¿Quitar a la persona?',
    'Holidays and closed days of the whole business. A closed day in the opening hours exceptions (Business details) counts as a day off for everyone too; a person has their own days off on their form.' => 'Vacaciones y días de cierre de todo el negocio. Un día cerrado en las excepciones del horario (Datos de la empresa) también cuenta como día libre para todos; cada persona tiene sus propios días libres en su formulario.',
    'Everyone off from' => 'Todos libres desde',
    'When someone asks what the site keeps about them, or asks to be deleted: enter their e-mail address. The search covers enquiries (the sender and every field), the newsletter subscription, e-mails waiting to be sent, testimonial requests and bookings of appointments.' => 'Cuando alguien pregunte qué guarda el sitio sobre él o pida que lo borren, introduce su dirección de correo. La búsqueda abarca las consultas (el remitente y cada campo), la suscripción al boletín, los correos pendientes de envío, las solicitudes de testimonios y las reservas de citas.',
    'Bookings of appointments: %d' => 'Reservas de citas: %d',
    'Enquiries with their attachments, the subscription (also in the connected mailing service), queued e-mails, testimonial requests and bookings are deleted. Backups keep older copies until they expire.' => 'Se eliminan las consultas con sus adjuntos, la suscripción (también en el servicio de correo conectado), los correos en cola, las solicitudes de testimonios y las reservas. Las copias de seguridad conservan copias anteriores hasta que caducan.',
    'Service (id from Bookings → Services; 0 = the visitor chooses)' => 'Servicio (id de Reservas → Servicios; 0 = lo elige el visitante)',
    'Person (id from Bookings → People; 0 = the visitor chooses, or anyone)' => 'Persona (id de Reservas → Personas; 0 = la elige el visitante, o cualquiera)',
    'Consent text (a required checkbox)' => 'Texto de consentimiento (una casilla obligatoria)',
    'Online booking of an appointment: a service, a person, a day and a free time – the bookings are in Bookings and arrive by e-mail.' => 'Reserva de citas en línea: un servicio, una persona, un día y una hora libre; las reservas están en Reservas y llegan por correo.',
    'The service does not exist.' => 'El servicio no existe.',
    'Enter the name of the service.' => 'Introduce el nombre del servicio.',
    'The duration is in minutes, 5 to 480.' => 'La duración se indica en minutos, de 5 a 480.',
    'The person does not exist.' => 'La persona no existe.',
    'Enter the name of the person.' => 'Introduce el nombre de la persona.',
    'Enter a valid e-mail address of the person, or leave it empty.' => 'Introduce una dirección de correo válida de la persona o déjala vacía.',
    'Write the hours per weekday as ranges, e.g. 9:00-12:00, 13:00-17:00 (empty = the opening hours of the site).' => 'Escribe el horario de cada día de la semana como intervalos, p. ej. 9:00-12:00, 13:00-17:00 (vacío = el horario del sitio).',
    'Days off are given as from and to (YYYY-MM-DD or YYYY-MM-DD HH:MM) with an optional note.' => 'Los días libres se indican como desde y hasta (YYYY-MM-DD o YYYY-MM-DD HH:MM) con una nota opcional.',
    'Enter the day off as YYYY-MM-DD (and HH:MM for a part of a day); the end must not be before the start.' => 'Introduce el día libre como YYYY-MM-DD (y HH:MM para una parte del día); el final no puede ser anterior al inicio.',
    'The service has upcoming bookings – cancel them first, or switch the service off instead.' => 'El servicio tiene reservas próximas: cancélalas primero o, en su lugar, desactiva el servicio.',
    'The person has upcoming bookings – cancel or move them first, or switch the person off instead.' => 'La persona tiene reservas próximas: cancélalas o muévelas primero o, en su lugar, desactiva a la persona.',
    'The booking does not exist.' => 'La reserva no existe.',
    'The booking is cancelled and the customer was told by e-mail.' => 'Reserva cancelada; se ha avisado al cliente por correo.',
    'The booking is cancelled.' => 'Reserva cancelada.',
    'Only a confirmed booking can be cancelled.' => 'Solo se puede cancelar una reserva confirmada.',
    'Only a confirmed booking can be marked.' => 'Solo se puede marcar una reserva confirmada.',
    'The booking was anonymised – the row stays for statistics without the person.' => 'La reserva se ha anonimizado: la fila se mantiene para las estadísticas sin la persona.',
    'This time is not free for the chosen person – pick another time.' => 'Esta hora no está libre para la persona elegida: elige otra hora.',
    'Choose a service.' => 'Elige un servicio.',
    'Enter a valid e-mail address, or leave it empty.' => 'Introduce una dirección de correo válida o déjala vacía.',
    'Enter a valid phone number, or leave it empty.' => 'Introduce un número de teléfono válido o déjalo vacío.',
    'Enter the name of the customer.' => 'Introduce el nombre del cliente.',
    'The booking is saved and the confirmation was sent to the customer.' => 'Reserva guardada; se ha enviado la confirmación al cliente.',
    'The booking is saved.' => 'Reserva guardada.',
    'Only an administrator changes the booking set-up.' => 'Solo un administrador cambia la configuración de las reservas.',
    'The service is saved.' => 'Servicio guardado.',
    'The service is deleted.' => 'Servicio eliminado.',
    'The person is saved.' => 'Persona guardada.',
    'The person is removed.' => 'Persona quitada.',
    'The day off is saved.' => 'Día libre guardado.',
    'The day off is removed.' => 'Día libre quitado.',
    'Booking settings saved.' => 'Ajustes de reservas guardados.',
    'Enter the day as YYYY-MM-DD and the time as HH:MM.' => 'Introduce el día como YYYY-MM-DD y la hora como HH:MM.',
    'done' => 'hecha',
    'did not come' => 'no se presentó',
    'cancelled' => 'cancelada',
    'Monday' => 'lunes',
    'Tuesday' => 'martes',
    'Wednesday' => 'miércoles',
    'Thursday' => 'jueves',
    'Friday' => 'viernes',
    'Saturday' => 'sábado',
    'Sunday' => 'domingo',
    'Running' => 'En curso',
    'Partly done' => 'Hecha en parte',
    'Missed' => 'Perdida',
    'Scheduled Claude runs: noticing runs nobody picked up' => 'Ejecuciones programadas de Claude: detectar las que nadie recogió',
    '%s images have no absolute address (http…) and cannot be downloaded; they stay as they are.' => '%s imágenes no tienen una dirección absoluta (http…) y no se pueden descargar; se quedan como están.',
    '%s posts or pages share an address with another one – the second gets a number (slug-2).' => '%s entradas o páginas comparten dirección con otra: la segunda recibe un número (slug-2).',
    'The export does not say the address of the old site. Enter it below – images are downloaded from it and the old addresses redirect from it.' => 'La exportación no indica la dirección del sitio antiguo. Introdúcela abajo: las imágenes se descargan desde ella y las direcciones antiguas redirigen desde ella.',
    'In Ghost Admin open Settings → Labs → Export your content and download the .json file.' => 'En Ghost Admin abre Settings → Labs → Export your content y descarga el archivo .json.',
    'The file is empty or larger than 256 MB.' => 'El archivo está vacío o supera los 256 MB.',
    'This is not a Ghost export. In Ghost Admin open Settings → Labs → Export your content and download the .json file.' => 'Esto no es una exportación de Ghost. En Ghost Admin abre Settings → Labs → Export your content y descarga el archivo .json.',
    'Old addresses are taken as /slug/ (Ghost’s default routes). A custom routes.yaml is not part of the export and is not read.' => 'Las direcciones antiguas se toman como /slug/ (las rutas predeterminadas de Ghost). Un routes.yaml personalizado no forma parte de la exportación y no se lee.',
    'The primary tag of a post is offered as its category, the other tags as tags; internal tags (#name) are skipped.' => 'La etiqueta principal de una entrada se ofrece como su categoría y las demás etiquetas como etiquetas; las etiquetas internas (#nombre) se omiten.',
    'Members, newsletters, comments and the theme are not transferred. A post that was only sent by e-mail is imported as a draft.' => 'No se transfieren los miembros, los boletines, los comentarios ni el tema. Una entrada que solo se envió por correo se importa como borrador.',
    'In Blogger open Settings → Manage blog → Back up content and download the .xml file.' => 'En Blogger abre Configuración → Gestionar blog → Crear copia de seguridad del contenido y descarga el archivo .xml.',
    'This is not a Blogger export. In Blogger open Settings → Manage blog → Back up content and download the .xml file.' => 'Esto no es una exportación de Blogger. En Blogger abre Configuración → Gestionar blog → Crear copia de seguridad del contenido y descarga el archivo .xml.',
    'The file contains no blog content (the feed element is missing).' => 'El archivo no contiene contenido del blog (falta el elemento feed).',
    'The file contains a DOCTYPE or custom entities. An export never has them – the file was rejected for security reasons.' => 'El archivo contiene un DOCTYPE o entidades personalizadas. Una exportación nunca los tiene: el archivo se ha rechazado por motivos de seguridad.',
    'The file is not valid XML – it is damaged or incomplete. Download the export again. The error is on line:' => 'El archivo no es un XML válido: está dañado o incompleto. Vuelve a descargar la exportación. El error está en la línea:',
    'Comments are skipped; so are the blog’s settings and template.' => 'Los comentarios se omiten, igual que los ajustes y la plantilla del blog.',
    'Labels become tags. Blogger has no categories – choose one for the posts below.' => 'Las etiquetas de Blogger pasan a ser etiquetas. Blogger no tiene categorías: elige una para las entradas abajo.',
    'Images are downloaded from Blogger’s image hosts (blogger.googleusercontent.com), so the blog may already be gone.' => 'Las imágenes se descargan de los servidores de imágenes de Blogger (blogger.googleusercontent.com), así que el blog puede haber desaparecido ya.',
    'The file must have the .%s extension.' => 'El archivo debe tener la extensión .%s.',
    'Import from %s' => 'Importar desde %s',
    'File %s – %s export of “%s”. Nothing has been imported yet; this is only an overview of what the file contains.' => 'Archivo %s: exportación de %s de “%s”. Aún no se ha importado nada; esto es solo un resumen de lo que contiene el archivo.',
    'Images in texts' => 'Imágenes en los textos',
    'User accounts and passwords – choose below whose the posts will be.' => 'Cuentas de usuario y contraseñas: elige abajo de quién serán las entradas.',
    'Content blocks the import cannot convert – they are left out, the text around them stays:' => 'Bloques de contenido que la importación no puede convertir; se omiten, pero el texto a su alrededor se mantiene:',
    'What becomes what' => 'Qué se convierte en qué',
    'The export does not carry it. Images are downloaded from this address and the redirects from the old addresses count on it.' => 'La exportación no lo incluye. Las imágenes se descargan desde esta dirección y las redirecciones desde las direcciones antiguas cuentan con ella.',
    'Posts (%s)' => 'Entradas (%s)',
    'Pages (%s)' => 'Páginas (%s)',
    'drafts too (%s) – as hidden news items and pages' => 'también los borradores (%s), como noticias y páginas ocultas',
    'No accounts are created. Each author’s posts belong to the user you choose; by default to you.' => 'No se crea ninguna cuenta. Las entradas de cada autor pertenecen al usuario que elijas; por defecto, a ti.',
    'me (the importing user)' => 'yo (el usuario que importa)',
    'New tags' => 'Etiquetas nuevas',
    'News and pages still show images from the old site. Downloading saves the main news images and images in texts to Media (resized, with thumbnails and WebP) and rewrites the links in the texts. Images are downloaded from the image hosts of %s, which must still be available.' => 'Las noticias y páginas aún muestran imágenes del sitio antiguo. La descarga guarda las imágenes principales de las noticias y las imágenes de los textos en Medios (redimensionadas, con miniaturas y WebP) y reescribe los enlaces de los textos. Las imágenes se descargan de los servidores de imágenes de %s, que deben seguir disponibles.',
    'From another system' => 'Desde otro sistema',
    'Moving from a system with its own export: posts become news items, pages become pages, categories and tags come along, old addresses redirect to the new ones. In the next step you see what the file contains and choose what becomes what; nothing changes on the site until you confirm.' => 'Migración desde un sistema con su propia exportación: las entradas pasan a ser noticias, las páginas, páginas; las categorías y etiquetas se traen, y las direcciones antiguas redirigen a las nuevas. En el siguiente paso ves qué contiene el archivo y eliges qué se convierte en qué; nada cambia en el sitio hasta que lo confirmes.',
    'Export file' => 'Archivo de exportación',
    'The server allows uploads of at most %s. Copy a larger file over FTP into the storage/import/sources/ folder, named system-name.extension (for example ghost-blog.json) – it will appear in the list below.' => 'El servidor permite subir como máximo %s. Copia un archivo más grande por FTP en la carpeta storage/import/sources/, con el nombre sistema-nombre.extensión (por ejemplo ghost-blog.json); aparecerá en la lista de abajo.',
    'You can import the same file repeatedly – whatever has already been imported is skipped. Delete the file when the import is finished; it contains e-mail addresses of authors from the old site.' => 'Puedes importar el mismo archivo varias veces: lo que ya se ha importado se omite. Elimina el archivo cuando termine la importación; contiene direcciones de correo de autores del sitio antiguo.',
    'The file could not be uploaded. If it is larger than the server allows, upload it over FTP into the storage/import/sources/ folder.' => 'No se ha podido subir el archivo. Si es más grande de lo que permite el servidor, súbelo por FTP a la carpeta storage/import/sources/.',
    'news items' => 'noticias',
    'do not import' => 'no importar',
    'news categories (the first one of a post)' => 'categorías de noticias (la primera de cada entrada)',
    'The first posts' => 'Las primeras entradas',
    'The first pages' => 'Las primeras páginas',
    'drafts' => 'borradores',
    'scheduled' => 'programados',
    'System' => 'Sistema',
    'by the customer' => 'por el cliente',
    'by Claude' => 'por Claude',
    'Upcoming' => 'Próximas',
    'Today' => 'Hoy',
    'Last 30 days' => 'Últimos 30 días',
    'All' => 'Todas',
    'With' => 'Con',
    'From %s' => 'Desde %s',
    'API token' => 'Token de API',
    'The token is used only for this fetch and is not stored anywhere.' => 'El token solo se usa para esta descarga y no se guarda en ningún sitio.',
    'What to fetch' => 'Qué descargar',
    'Fetch and show preview' => 'Descargar y mostrar vista previa',
    'being fetched from the site' => 'descargándose del sitio',
    'The PHP extension curl is missing on the server – the site’s API cannot be read without it.' => 'Falta la extensión de PHP curl en el servidor: sin ella no se puede leer la API del sitio.',
    'Fetching from %s: step %s of %s (%s), %s pages and %s items so far. Keep this page open, it continues by itself.' => 'Descargando de %s: paso %s de %s (%s), %s páginas y %s elementos hasta ahora. Mantén esta página abierta; continúa sola.',
    '%s has no export file – enter the site address below and the content is fetched from its API.' => '%s no tiene archivo de exportación: introduce abajo la dirección del sitio y el contenido se descargará de su API.',
    'Unknown system.' => 'Sistema desconocido.',
    'Enter the public address of the site, e.g. https://www.example.com – not an internal address.' => 'Introduce la dirección pública del sitio, p. ej. https://www.example.com, no una dirección interna.',
    'The token has an unexpected form.' => 'El token tiene un formato inesperado.',
    'articles' => 'artículos',
    'categories' => 'categorías',
    'authors (names only)' => 'autores (solo nombres)',
    'tags' => 'etiquetas',
    'articles (with their images, tags and authors)' => 'artículos (con sus imágenes, etiquetas y autores)',
    'pages' => 'páginas',
    'Joomla 4 and 5 have no export file: enter the site address and an API token below and the content is fetched from its Web Services API.' => 'Joomla 4 y 5 no tienen archivo de exportación: introduce abajo la dirección del sitio y un token de API y el contenido se descargará de su Web Services API.',
    'In Joomla open Users → Manage → the user → Joomla API Token, tick Enabled and copy the token. The user must be allowed to read articles, categories and users. The Web Services API plugins must be switched on (System → Plugins → Web Services).' => 'En Joomla abre Users → Manage → el usuario → Joomla API Token, marca Enabled y copia el token. El usuario debe poder leer artículos, categorías y usuarios. Los plugins de Web Services API deben estar activados (System → Plugins → Web Services).',
    'Drupal 9, 10 and 11 have no export file: enter the site address below and the content is fetched from its JSON:API (the core module must be switched on).' => 'Drupal 9, 10 y 11 no tienen archivo de exportación: introduce abajo la dirección del sitio y el contenido se descargará de su JSON:API (el módulo del núcleo debe estar activado).',
    'Optional. Published content needs no sign-in. For unpublished content type user:password (HTTP Basic authentication must be switched on in Drupal) or an access token.' => 'Opcional. El contenido publicado no necesita inicio de sesión. Para el contenido sin publicar, escribe usuario:contraseña (la autenticación HTTP Basic debe estar activada en Drupal) o un token de acceso.',
    'In the Webflow Designer open CMS → the collection → Export and download the .csv file (one collection per file).' => 'En el Webflow Designer abre CMS → la colección → Export y descarga el archivo .csv (una colección por archivo).',
    'The API does not say an article’s address. Old addresses are the best guess /category-path/id-alias; SEF URL rewriting differs per site, so check the redirects with the migration report after the import.' => 'La API no indica la dirección de un artículo. Las direcciones antiguas son la mejor suposición /ruta-de-categoría/id-alias; la reescritura de URL SEF varía en cada sitio, así que revisa las redirecciones con el informe de migración después de importar.',
    'Trashed articles are skipped, unpublished ones come as drafts, archived ones as published.' => 'Los artículos en la papelera se omiten, los no publicados llegan como borradores y los archivados como publicados.',
    'Modules, menus, the template, custom fields and the content of other extensions are not transferred.' => 'No se transfieren los módulos, los menús, la plantilla, los campos personalizados ni el contenido de otras extensiones.',
    'Old addresses are the path aliases (or /node/number). Articles become news items, basic pages become pages.' => 'Las direcciones antiguas son los alias de ruta (o /node/número). Los artículos pasan a ser noticias y las páginas básicas, páginas.',
    'Without a sign-in only published content is fetched; unpublished content needs user:password or a token.' => 'Sin inicio de sesión solo se descarga el contenido publicado; el no publicado necesita usuario:contraseña o un token.',
    'Blocks, menus, views, the theme, other content types, custom fields and comments are not transferred.' => 'No se transfieren los bloques, los menús, las vistas, el tema, otros tipos de contenido, los campos personalizados ni los comentarios.',
    'Enter the address of the collection including its folder, e.g. https://www.example.com/blog – the old address of an item is that address followed by /slug, and the redirects count on it.' => 'Introduce la dirección de la colección incluida su carpeta, p. ej. https://www.example.com/blog: la dirección antigua de un elemento es esa dirección seguida de /slug, y las redirecciones cuentan con ella.',
    'Static Webflow pages are not in a collection export. Import them from the live site with Import and export → From a live website.' => 'Las páginas estáticas de Webflow no están en la exportación de una colección. Impórtalas desde el sitio en línea con Importación y exportación → Desde un sitio web en línea.',
    'Draft and archived items come as hidden news items. Images are downloaded from Webflow’s CDN (website-files.com), which keeps them after the site is gone.' => 'Los elementos en borrador y archivados llegan como noticias ocultas. Las imágenes se descargan de la CDN de Webflow (website-files.com), que las conserva después de que desaparezca el sitio.',
    'This is not a Joomla fetch. Enter the site address and the API token in Import and export → From another system and fetch the content again.' => 'Esto no es una descarga de Joomla. Introduce la dirección del sitio y el token de API en Importación y exportación → Desde otro sistema y vuelve a descargar el contenido.',
    'This is not a Drupal fetch. Enter the site address in Import and export → From another system and fetch the content again.' => 'Esto no es una descarga de Drupal. Introduce la dirección del sitio en Importación y exportación → Desde otro sistema y vuelve a descargar el contenido.',
    'The fetch from the site did not finish. Start it again.' => 'La descarga del sitio no ha terminado. Vuelve a iniciarla.',
    'This is not a Webflow collection export – the first row has no Name and Slug columns. In the Webflow Designer open CMS → the collection → Export and download the .csv file.' => 'Esto no es una exportación de una colección de Webflow: la primera fila no tiene las columnas Name y Slug. En el Webflow Designer abre CMS → la colección → Export y descarga el archivo .csv.',
    'This system has no fetch step.' => 'Este sistema no tiene paso de descarga.',
    'The site answers more than 5000 pages – the fetch was stopped.' => 'El sitio devuelve más de 5000 páginas: se ha detenido la descarga.',
    'The site sent a "next page" link that leads outside the site – the fetch was stopped.' => 'El sitio ha enviado un enlace de "página siguiente" que lleva fuera del sitio: se ha detenido la descarga.',
    'Fetching from other sites is switched off in the public demo.' => 'La descarga desde otros sitios está desactivada en la demo pública.',
    'The address does not belong to the old site, or it is not a public http(s) address on the standard port.' => 'La dirección no pertenece al sitio antiguo o no es una dirección http(s) pública en el puerto estándar.',
    'The site refused the request – the API token is wrong or missing, or it has no permission. Response:' => 'El sitio ha rechazado la solicitud: el token de API es incorrecto o falta, o no tiene permiso. Respuesta:',
    'The API is not available at this address (the site answered 404). Check the address and that the API is switched on.' => 'La API no está disponible en esta dirección (el sitio ha respondido 404). Comprueba la dirección y que la API esté activada.',
    'The site did not answer the API request, it responded with error' => 'El sitio no ha atendido la solicitud a la API; ha respondido con el error',
    'The site did not answer with JSON – this is not the address of the API.' => 'El sitio no ha respondido con JSON: esta no es la dirección de la API.',
    'The answer is larger than the fetch allows (8 MB per page, 48 MB in total).' => 'La respuesta es más grande de lo que permite la descarga (8 MB por página, 48 MB en total).',
    'This is not the Web Services API of Joomla – the answer has no "data" and "links".' => 'Esta no es la Web Services API de Joomla: la respuesta no tiene "data" ni "links".',
    'This is not the JSON:API of Drupal – the answer has no "jsonapi" and "data".' => 'Esta no es la JSON:API de Drupal: la respuesta no tiene "jsonapi" ni "data".',
    'We are closed from 24 to 26 December – put it on the site.' => 'Cerramos del 24 al 26 de diciembre: ponlo en el sitio.',
    'Write a news item about our new service and link it from the home page.' => 'Escribe una noticia sobre nuestro nuevo servicio y enlázala desde la página de inicio.',
    'Add our new colleague to the team page – the photo and a short bio are attached.' => 'Añade a nuestra nueva compañera a la página del equipo: adjunto la foto y una breve biografía.',
    'Update the price list from the attached PDF.' => 'Actualiza la lista de precios con el PDF adjunto.',
    'Sort this week\'s enquiries and draft a reply to each.' => 'Ordena las consultas de esta semana y prepara un borrador de respuesta para cada una.',
    'Why did we get fewer enquiries this month than last month?' => '¿Por qué hemos recibido menos consultas este mes que el mes pasado?',
    'Find broken links and missing image descriptions and fix them as drafts.' => 'Busca enlaces rotos y descripciones de imágenes que falten y corrígelos como borradores.',
    'Make a landing page for our spring campaign with an enquiry form.' => 'Crea una página de destino para nuestra campaña de primavera con un formulario de consulta.',
    'Translate the Services page into German.' => 'Traduce la página Servicios al alemán.',
    'Suggest three news topics from what people search for on Google.' => 'Sugiere tres temas de noticias a partir de lo que la gente busca en Google.',
    'Prepare a short report of this month for the owner.' => 'Prepara un breve informe de este mes para el propietario.',
    'Check the site before we hand it over to the client and list what is missing.' => 'Revisa el sitio antes de entregárselo al cliente y enumera lo que falta.',
    'On my Kaleta site %s (use its connector):' => 'En mi sitio de Kaleta %s (usa su conector):',
    'Work as drafts and send me the preview links – do not publish anything.' => 'Trabaja con borradores y envíame los enlaces de vista previa; no publiques nada.',
    'on day %d of every month at %s' => 'el día %d de cada mes a las %s',
    'Ask Claude' => 'Preguntar a Claude',
    'Write what you need done on the site, as you would to a colleague. Claude does it as drafts and answers in Requests; a person reviews and publishes.' => 'Escribe lo que necesitas hacer en el sitio, como se lo dirías a un compañero. Claude lo hace como borradores y responde en Encargos; una persona revisa y publica.',
    'What should Claude do?' => '¿Qué debe hacer Claude?',
    'e.g. Add the new opening hours to the contact page' => 'p. ej. Añade el nuevo horario a la página de contacto',
    'Send to Claude' => 'Enviar a Claude',
    'Attach files' => 'Adjuntar archivos',
    'Copied – paste it into Claude' => 'Copiado: pégalo en Claude',
    'Copy for the Claude app' => 'Copiar para la app de Claude',
    'For example – click one, change it and send:' => 'Por ejemplo: haz clic en uno, modifícalo y envíalo:',
    'A scheduled run works through the requests %s.' => 'Una ejecución programada atiende los encargos %s.',
    'Next: %s.' => 'Siguiente: %s.',
    'No scheduled run works through the requests yet – Claude reads them when someone asks it to.' => 'Aún no hay ninguna ejecución programada que atienda los encargos: Claude los lee cuando alguien se lo pide.',
    'Schedule a run' => 'Programar una ejecución',
    'Claude reads the requests the next time it works on the site.' => 'Claude lee los encargos la próxima vez que trabaja en el sitio.',
    'Your requests' => 'Tus encargos',
    'Sent to Claude as request #%d. Claude does it as drafts the next time it works on the site; its notes appear in the request.' => 'Enviado a Claude como encargo n.º %d. Claude lo hará como borradores la próxima vez que trabaje en el sitio; sus notas aparecen en el encargo.',
    'Claude is not connected to this site yet, so requests wait until it is.' => 'Claude aún no está conectado a este sitio, así que los encargos esperan hasta que lo esté.',
    'Claude is not connected to this site yet – requests wait until an administrator connects it.' => 'Claude aún no está conectado a este sitio: los encargos esperan hasta que un administrador lo conecte.',
    'Delete this enquiry and its attachments for good? This cannot be undone.' => '¿Eliminar definitivamente esta consulta y sus adjuntos? No se puede deshacer.',
    'Another user already has this username.' => 'Otro usuario ya tiene este nombre de usuario.',
    'Claude token created' => 'Token de Claude creado',
    'Mark as spam' => 'Marcar como spam',
    'Claude can check free times and set up services and people; reading bookings is recorded in the change log.' => 'Claude puede consultar las horas libres y configurar servicios y personas; la lectura de reservas queda en el registro de cambios.',
    'Most sites need none – the features of a business site are built in. A developer can write one with the extension API.' => 'La mayoría de los sitios no necesitan ninguno: las funciones de un sitio de empresa vienen integradas. Un desarrollador puede escribir uno con la API de extensiones.',
    'Menu' => 'Menú',
    'Sections' => 'Secciones',
    'Access' => 'Acceso',
    'Each person creates and revokes their own connections in' => 'Cada persona crea y revoca sus propias conexiones en',
    'Expires' => 'Caduca',
    'How to connect' => 'Cómo conectar',
    'Nobody has connected Claude yet.' => 'Nadie ha conectado Claude todavía.',
    'The Claude connection is switched off.' => 'La conexión con Claude está desactivada.',
    'never' => 'nunca',
    'Business details' => 'Datos de la empresa',
    'Claude settings' => 'Ajustes de Claude',
    'Customers' => 'Clientes',
    'Integrations' => 'Integraciones',
    'Site care' => 'Mantenimiento del sitio',
    'How to connect Claude, its instructions, its guardrails and every connection are in' => 'Cómo conectar Claude, sus instrucciones, sus salvaguardas y cada conexión están en',
    'Blueprints' => 'Plantillas sectoriales',
    'Claims' => 'Afirmaciones',
    'Company and opening hours' => 'Empresa y horario',
    'Features' => 'Funciones',
    'Settings and connections' => 'Ajustes y conexiones',
    'Analytics and tags' => 'Analítica y etiquetas',
    'Enquiries and events to Make, Zapier or your own system, signed.' => 'Consultas y eventos a Make, Zapier o tu propio sistema, firmados.',
    'Google Analytics, Tag Manager, Matomo or Plausible.' => 'Google Analytics, Tag Manager, Matomo o Plausible.',
    'Mailing service' => 'Servicio de correo masivo',
    'Set up' => 'Configurar',
    'Settings of the connection' => 'Ajustes de la conexión',
    'Subscribers to Brevo, MailerLite, Mailchimp, Ecomail or SmartEmailing.' => 'Suscriptores a Brevo, MailerLite, Mailchimp, Ecomail o SmartEmailing.',
    'Your kind of business' => 'Tu tipo de negocio',
    'Twenty ready-made setups – from a software company or a restaurant to a clinic or a trade – add the collections, facts and checks such a business needs; Claude can make one for any other.' => 'Veinte configuraciones listas, desde una empresa de software o un restaurante hasta una clínica o un oficio, añaden las colecciones, los datos clave y las comprobaciones que necesita ese negocio; Claude puede crear una para cualquier otro.',
    'Personal token' => 'Token personal',
    'Waiting for you' => 'Pendiente de ti',
    'Requests Claude finished – review the drafts' => 'Encargos que Claude ha terminado: revisa los borradores',
    'Unresolved comments on drafts' => 'Comentarios sin resolver en borradores',
    'News drafts to publish' => 'Borradores de noticias por publicar',
    'Hidden collection items changed in the last 30 days' => 'Elementos ocultos de colecciones cambiados en los últimos 30 días',
    'Proposed exceptions to the opening hours' => 'Excepciones del horario propuestas',
    'Site parts with unpublished changes' => 'Partes del sitio con cambios sin publicar',
    'Unpublished changes of the look' => 'Cambios de la apariencia sin publicar',
    'Proposed by Claude – the site does not use these until you apply them.' => 'Propuestas por Claude: el sitio no las usa hasta que las apliques.',
    'Proposed by Claude' => 'Propuesta por Claude',
    'The exception is applied.' => 'Excepción aplicada.',
    'The proposal no longer exists.' => 'La propuesta ya no existe.',
    'The proposal is discarded.' => 'Propuesta descartada.',
    'Online booking of appointments: the Booking element in the builder, services and people with their hours, reminders by e-mail and the Bookings list in the administration.' => 'Reserva de citas en línea: el elemento Reserva en el builder, servicios y personas con sus horarios, recordatorios por correo y la lista de Reservas en la administración.',
    'An internal reporting channel under the EU Whistleblower Directive: an encrypted report form at /_report that only the readers you choose can open.' => 'Un canal interno de denuncias según la Directiva europea de protección de denunciantes: un formulario de denuncia cifrado en /_report que solo pueden abrir los lectores que elijas.',
    'On – visits, most-read news and traffic sources under Statistics. No cookies and no consent needed.' => 'Activado: visitas, noticias más leídas y fuentes de tráfico en Estadísticas. Sin cookies y sin necesidad de consentimiento.',
    'Off – nothing is measured.' => 'Desactivado: no se mide nada.',
    'Switched on and off as a feature under %s.' => 'Se activa y desactiva como función en %s.',
    'Channel set-up and readers' => 'Configuración del canal y lectores',
    'Pricing plans' => 'Planes de precios',
    'New pricing plans' => 'Nuevos planes de precios',
    'Plans or packages side by side with the price and its period, who each is for, what it includes and a button; one can be marked as recommended. The plans have no pages of their own.' => 'Planes o paquetes uno al lado de otro con el precio y su periodo, para quién es cada uno, qué incluye y un botón; uno puede marcarse como recomendado. Los planes no tienen páginas propias.',
    'Badge' => 'Distintivo',
    'Billing period' => 'Periodo de facturación',
    'Who it is for' => 'Para quién es',
    'What is included' => 'Qué incluye',
    'Food and drink menu' => 'Carta de comidas y bebidas',
    'New food and drink menu' => 'Nueva carta de comidas y bebidas',
    'Dishes and drinks with a description, a price, the portion, allergens and diet labels, grouped by section (starters, mains, drinks) with filter buttons; the dishes have no pages of their own.' => 'Platos y bebidas con descripción, precio, ración, alérgenos y etiquetas de dieta, agrupados por sección (entrantes, principales, bebidas) con botones de filtro; los platos no tienen páginas propias.',
    'Menu section' => 'Sección de la carta',
    'Portion' => 'Ración',
    'Diet labels' => 'Etiquetas de dieta',
    'Allergens' => 'Alérgenos',
    'Rooms and accommodation' => 'Habitaciones y alojamiento',
    'New rooms' => 'Nuevas habitaciones',
    'A page for each room, apartment or cottage with a photo, how many guests it takes, the beds, the size, the price per night from, the amenities and a booking link.' => 'Una página para cada habitación, apartamento o casa rural con una foto, cuántos huéspedes admite, las camas, el tamaño, el precio por noche desde, los servicios y un enlace de reserva.',
    'Guests' => 'Huéspedes',
    'Beds' => 'Camas',
    'Size (m²)' => 'Tamaño (m²)',
    'Price per night from' => 'Precio por noche desde',
    'Amenities' => 'Servicios',
    'Booking link' => 'Enlace de reserva',
    'Book now' => 'Reservar ahora',
    'Property listings' => 'Inmuebles',
    'New property listings' => 'Nuevos inmuebles',
    'A page for each property for sale or to let with a photo, the price, the location, the floor and plot area, the layout, the energy rating, parameters and a map; the list filters by offer.' => 'Una página para cada inmueble en venta o alquiler con una foto, el precio, la ubicación, la superficie construida y la de parcela, la distribución, la calificación energética, características y un mapa; la lista se filtra por oferta.',
    'Offer' => 'Oferta',
    'Floor area (m²)' => 'Superficie construida (m²)',
    'Plot area (m²)' => 'Superficie de parcela (m²)',
    'Room layout' => 'Distribución',
    'Energy rating' => 'Calificación energética',
    'Services and trades' => 'Servicios y oficios',
    'Health, sport and learning' => 'Salud, deporte y formación',
    'Food and stays' => 'Comida y alojamiento',
    'Shops and production' => 'Tiendas y producción',
    'Software and agencies' => 'Software y agencias',
    'Public and non-profit' => 'Sector público y sin ánimo de lucro',
    'Search blueprints' => 'Buscar plantillas sectoriales',
    'Apply the blueprint %s? It creates its collections with hidden list pages and adds its facts, questions and checks. You can take it off again.' => '¿Aplicar la plantilla sectorial %s? Crea sus colecciones con páginas de lista ocultas y añade sus datos clave, preguntas y comprobaciones. Puedes quitarla de nuevo.',
    'No blueprint matches the search.' => 'Ninguna plantilla sectorial coincide con la búsqueda.',
    'None of them fits?' => '¿No encaja ninguna?',
    'Ask Claude to make a blueprint for your kind of business: it asks you what it needs to know, shows you the draft and applies it only when you agree. In the Claude app, the prompt is called draft_blueprint.' => 'Pide a Claude que cree una plantilla sectorial para tu tipo de negocio: te pregunta lo que necesita saber, te muestra el borrador y solo la aplica cuando estés de acuerdo. En la app de Claude, el prompt se llama draft_blueprint.',
    'Request for Claude' => 'Encargo para Claude',
    'Make a blueprint for our kind of business. We are … (what we do and for whom). Ask me what you need to know.' => 'Crea una plantilla sectorial para nuestro tipo de negocio. Somos … (qué hacemos y para quién). Pregúntame lo que necesites saber.',
    'From a file' => 'Desde un archivo',
    'Choose this plan' => 'Elegir este plan',
    'The site redirected the API request from https to plain http – the token would travel unencrypted, so the fetch was stopped. Use the https address of the site.' => 'El sitio ha redirigido la solicitud a la API de https a http sin cifrar: el token viajaría sin cifrar, así que se ha detenido la descarga. Usa la dirección https del sitio.',
    'An update left a newer .htaccess.kaleta-nova next to your customised .htaccess – carry its new rules over (since 3.3.2 they keep the code of add-ons in extensions/ away from visitors), then delete the file.' => 'Una actualización ha dejado un .htaccess.kaleta-nova más reciente junto a tu .htaccess personalizado: traslada sus nuevas reglas (desde la 3.3.2 mantienen el código de los complementos de extensions/ fuera del alcance de los visitantes) y después elimina el archivo.',
    'The update source now offers version %s instead of %s – nothing was installed. Check for updates again.' => 'La fuente de actualizaciones ahora ofrece la versión %s en lugar de la %s: no se ha instalado nada. Vuelve a buscar actualizaciones.',
    'The update source now offers version %s instead of %s – nothing was installed. The screen now shows version %s; check what it brings and update again.' => 'La fuente de actualizaciones ahora ofrece la versión %s en lugar de la %s: no se ha instalado nada. La pantalla muestra ahora la versión %s; mira lo que trae y vuelve a actualizar.',
    'The update source changed whether version %s is a security release – nothing was installed. Check for updates again.' => 'La fuente de actualizaciones ha cambiado si la versión %s es una versión de seguridad: no se ha instalado nada. Vuelve a buscar actualizaciones.',
    'Categories are changed by an editor or an administrator.' => 'Las categorías las cambia un editor o un administrador.',
    'The application sent an incomplete sign-in request, so it was stopped here. Please connect it again.' => 'La aplicación ha enviado una solicitud de inicio de sesión incompleta, así que se ha detenido aquí. Vuelve a conectarla.',
    'A text fact cannot begin with an address scheme other than http, https, mailto or tel (javascript:, data:…). For a link use the type web address.' => 'Un dato clave de texto no puede empezar con un esquema de dirección distinto de http, https, mailto o tel (javascript:, data:…). Para un enlace, usa el tipo dirección web.',
    'Imported content' => 'Contenido importado',
    'checked again with the sanitizers of 3.3.3: %d records, %d changed' => 'revisado de nuevo con los saneadores de la 3.3.3: %d registros, %d cambiados',
    'being checked again with the sanitizers of 3.3.3 by the background tasks: %d records so far, %d changed' => 'en revisión con los saneadores de la 3.3.3 mediante tareas en segundo plano: %d registros hasta ahora, %d cambiados',
    'only risky markup was removed; the version before is in the history of each news item, page or collection item' => 'solo se ha quitado el marcado peligroso; la versión anterior está en el historial de cada noticia, página o elemento de colección',
    'Imported content checked again with today\'s sanitizers' => 'Contenido importado revisado de nuevo con los saneadores actuales',
    'Wrong user name or password, or the account is temporarily locked after a series of failed attempts. Try again in 15 minutes or reset your password.' => 'Nombre de usuario o contraseña incorrectos, o la cuenta está bloqueada temporalmente tras varios intentos fallidos. Vuelve a intentarlo en 15 minutos o restablece tu contraseña.',
    'Enter your current password to change the e-mail address. Nothing was saved.' => 'Introduce tu contraseña actual para cambiar la dirección de correo. No se ha guardado nada.',
    'Enter your current password to add a passkey.' => 'Introduce tu contraseña actual para añadir una llave de acceso.',
    'The e-mail address of your account was changed' => 'Se ha cambiado la dirección de correo de tu cuenta',
    'the e-mail address of the account %s in the administration of %s was changed to %s.' => 'la dirección de correo de la cuenta %s en la administración de %s se ha cambiado a %s.',
    'If you did not change it, tell the administrator of the site at once – someone else may be using your account.' => 'Si no la has cambiado tú, avisa de inmediato al administrador del sitio: puede que otra persona esté usando tu cuenta.',
    'Needed only when you change the e-mail – a password reset goes there. The old address gets a notice.' => 'Solo hace falta si cambias el correo: allí se envía el restablecimiento de contraseña. La dirección antigua recibe un aviso.',
    'Needed to add a passkey.' => 'Necesaria para añadir una llave de acceso.',
    'received during a flood' => 'recibida durante una avalancha',
    'At least %d reports arrived within the hour before this one – perhaps sent by a script. The channel still accepts every report; read this one as carefully as any other.' => 'Al menos %d denuncias llegaron en la hora anterior a esta, quizá enviadas por un script. El canal sigue aceptando todas las denuncias; lee esta con el mismo cuidado que cualquier otra.',
    'After you allow it, the application returns to' => 'Cuando lo permitas, la aplicación volverá a',
    '%s is not an address of Claude’s own apps. Allow access only if you started this connection yourself and know this application – if a message or someone else sent you here, choose Deny.' => '%s no es una dirección de las apps propias de Claude. Permite el acceso solo si has iniciado tú esta conexión y conoces esta aplicación; si te ha traído aquí un mensaje u otra persona, elige Denegar.',
    'new, not verified' => 'nueva, sin verificar',
    'This website has not connected this application before. An application chooses its name itself, so the name is not verified – check the address above.' => 'Este sitio web no ha conectado antes esta aplicación. Una aplicación elige su nombre ella misma, así que el nombre no está verificado: comprueba la dirección de arriba.',
    'You can revoke the connection at any time in My account → Connected applications.' => 'Puedes revocar la conexión en cualquier momento en Mi cuenta → Aplicaciones conectadas.',
    'What may the application do?' => '¿Qué puede hacer la aplicación?',
    'The application builds pages, writes news drafts, adds hidden collection items, proposes exceptions to the opening hours, sorts enquiries and prepares look changes – you review and publish them. Nothing on the live site changes without you.' => 'La aplicación construye páginas, escribe borradores de noticias, añade elementos ocultos a colecciones, propone excepciones del horario, clasifica consultas y prepara cambios de la apariencia; tú los revisas y publicas. Nada cambia en el sitio publicado sin ti.',
    'The application reads pages, settings, the audit and the change log. It changes nothing.' => 'La aplicación lee páginas, ajustes, la auditoría y el registro de cambios. No cambia nada.',
    'Connecting apps' => 'Conexión de aplicaciones',
    'Only allow Claude’s own apps to connect' => 'Permitir conectarse solo a las apps propias de Claude',
    'On: only Claude on the web, desktop and phone (claude.ai, claude.com) and Claude Code on your computer can register and sign in. Connections that already exist keep working. Off: other MCP applications can connect too, after a warning on the consent screen.' => 'Activado: solo Claude en la web, el escritorio y el móvil (claude.ai, claude.com) y Claude Code en tu equipo pueden registrarse e iniciar sesión. Las conexiones existentes siguen funcionando. Desactivado: otras aplicaciones MCP también pueden conectarse, tras una advertencia en la pantalla de consentimiento.',
    'A replaced refresh token of the connected application “%s” was used again, so all its tokens were revoked. If it was you, connect the application again.' => 'Se ha vuelto a usar un token de actualización ya reemplazado de la aplicación conectada “%s”, así que se han revocado todos sus tokens. Si has sido tú, vuelve a conectar la aplicación.',
    'This website lets only Claude’s own apps connect. If you need to connect another application, ask the administrator of the website.' => 'Este sitio web solo permite conectarse a las apps propias de Claude. Si necesitas conectar otra aplicación, pídeselo al administrador del sitio web.',
    'Hours for %s' => 'Horario para %s',
    'Only for this service: when set, these hours replace the weekly hours above for it. All empty = the weekly hours above. Bookings of all services share the same calendar of the person, so times never overlap.' => 'Solo para este servicio: si se define, este horario sustituye para él al horario semanal de arriba. Todo vacío = el horario semanal de arriba. Las reservas de todos los servicios comparten el mismo calendario de la persona, así que las horas nunca se solapan.',
    'Hours per service need an existing service (the ids are listed by booking_availability).' => 'El horario por servicio necesita un servicio existente (booking_availability lista los ids).',
    'News URL' => 'URL de noticias',
    'The first part of the news addresses in every language: blog gives /blog/…. Empty = the default address. Lowercase letters, digits and hyphens; not the address of a page, a collection or the system. The old addresses redirect to the new one.' => 'La primera parte de las direcciones de las noticias en todos los idiomas: blog da /blog/…. Vacío = la dirección predeterminada. Minúsculas, dígitos y guiones; no puede ser la dirección de una página, una colección o del sistema. Las direcciones antiguas redirigen a la nueva.',
    'A page or a collection already uses this URL.' => 'Una página o una colección ya usa esta URL.',
    'Use only lowercase letters without accents, digits and single hyphens (e.g. blog), at most 40 characters.' => 'Usa solo minúsculas sin tildes, dígitos y guiones sueltos (p. ej. blog), como máximo 40 caracteres.',
    'The page has been restored with the address %s, because the news now uses its old address – publish it in its settings.' => 'La página se ha restaurado con la dirección %s porque las noticias usan ahora su dirección antigua: publícala en sus ajustes.',
    'Trailing slash in URLs' => 'Barra final en las URL',
    'without – /page (canonical), /page/ redirects to it' => 'sin – /page (canónica), /page/ redirige a ella',
    'with – /page/ (canonical), /page redirects to it' => 'con – /page/ (canónica), /page redirige a ella',
    'The other form redirects with 301 and the canonical URL always uses the chosen one. Does not apply to the home page, files such as sitemap.xml, or the API.' => 'La otra forma redirige con 301 y la URL canónica siempre usa la elegida. No se aplica a la página de inicio, a archivos como sitemap.xml ni a la API.',
    '.html – /page.html (canonical), /page and /page/ redirect to it' => '.html – /page.html (canónica), /page y /page/ redirigen a ella',
    'Form of address in German' => 'Forma de tratamiento en alemán',
    'Formal (Sie)' => 'Formal (Sie)',
    'Informal (du)' => 'Informal (du)',
    'How the German texts for visitors address them (forms, search, cookie bar). The administration has its own choice in My account.' => 'Cómo se dirigen a los visitantes los textos en alemán (formularios, búsqueda, barra de cookies). La administración tiene su propia opción en Mi cuenta.',
    'How the German administration addresses you. The texts for visitors have their own setting in Settings.' => 'Cómo se dirige a ti la administración en alemán. Los textos para visitantes tienen su propio ajuste en Ajustes.',
    'Write German texts for visitors with the informal “du”.' => 'Escribe los textos en alemán para visitantes con el “du” informal.',
    'Write German texts for visitors with the formal “Sie”.' => 'Escribe los textos en alemán para visitantes con el “Sie” formal.',
    'waiting for confirmation' => 'pendiente de confirmación',
    'declined' => 'rechazada',
    'Accept' => 'Aceptar',
    'Decline' => 'Rechazar',
    'Propose other times' => 'Proponer otras horas',
    'Send the proposal' => 'Enviar la propuesta',
    'Personal message (optional)' => 'Mensaje personal (opcional)',
    'Free times (pick 1 to 3)' => 'Horas libres (elige de 1 a 3)',
    'Proposed to the customer' => 'Propuestas al cliente',
    'The time is held until %s.' => 'La hora queda reservada hasta el %s.',
    'The hold ran out on %s – the time is free for others, but you can still answer.' => 'La reserva provisional caducó el %s: la hora está libre para otros, pero aún puedes responder.',
    'The customer gets the confirmation with the calendar and cancel links.' => 'El cliente recibe la confirmación con los enlaces del calendario y de cancelación.',
    'Decline the request? The customer will get an e-mail.' => '¿Rechazar la solicitud? El cliente recibirá un correo.',
    'confirmed and waiting' => 'confirmada y en espera',
    '%d requests are waiting for your answer.' => '%d solicitudes esperan tu respuesta.',
    'Hold a request for' => 'Reservar una solicitud durante',
    'Services that need confirmation: the requested time is held this long. Then it is free again and you get a reminder; the customer hears nothing until you answer.' => 'Servicios que requieren confirmación: la hora solicitada se reserva durante este tiempo. Después vuelve a quedar libre y recibes un recordatorio; el cliente no recibe nada hasta que respondas.',
    'Thank-you after a request' => 'Agradecimiento tras una solicitud',
    'empty = the built-in text' => 'vacío = el texto integrado',
    'Acknowledgement e-mail' => 'Correo de acuse de recibo',
    'Decline e-mail' => 'Correo de rechazo',
    'The opening text of the e-mail; the details follow. Write it in your own tone and form of address; {name} is the customer\'s name.' => 'El texto inicial del correo; después siguen los detalles. Escríbelo con tu propio tono y forma de tratamiento; {name} es el nombre del cliente.',
    'The opening text; your personal message from the request follows it.' => 'El texto inicial; le sigue tu mensaje personal de la solicitud.',
    'requires confirmation' => 'requiere confirmación',
    'Requires confirmation' => 'Requiere confirmación',
    'A request, not a booking: the time is held, you accept it, decline it or propose other times. The customer is told by e-mail.' => 'Una solicitud, no una reserva: la hora queda reservada y tú la aceptas, la rechazas o propones otras horas. Se avisa al cliente por correo.',
    'Only a booking waiting for confirmation can be accepted.' => 'Solo se puede aceptar una reserva pendiente de confirmación.',
    'This time has been taken meanwhile – propose other times or decline the request.' => 'Esta hora se ha ocupado entretanto: propón otras horas o rechaza la solicitud.',
    'Only a booking waiting for confirmation can get other times.' => 'Solo una reserva pendiente de confirmación puede recibir otras horas.',
    'The customer left no e-mail address – call them, or decline the request.' => 'El cliente no ha dejado ninguna dirección de correo: llámalo o rechaza la solicitud.',
    'Propose one to three times.' => 'Propón de una a tres horas.',
    'Enter every time as YYYY-MM-DD HH:MM.' => 'Introduce cada hora como YYYY-MM-DD HH:MM.',
    'One of the times is not free for this person – pick them from the free times.' => 'Una de las horas no está libre para esta persona: elígelas entre las horas libres.',
    'The booking is accepted and the customer got the confirmation.' => 'Reserva aceptada; el cliente ha recibido la confirmación.',
    'The booking is accepted.' => 'Reserva aceptada.',
    'The request is declined and the customer was told by e-mail.' => 'Solicitud rechazada; se ha avisado al cliente por correo.',
    'Only a booking waiting for confirmation can be declined.' => 'Solo se puede rechazar una reserva pendiente de confirmación.',
    'The other times were sent to the customer.' => 'Se han enviado las otras horas al cliente.',
    'When to load the image' => 'Cuándo cargar la imagen',
    'Automatically – at once if it is the first image of the page' => 'Automáticamente: de inmediato si es la primera imagen de la página',
    'At once – the main image of the page' => 'De inmediato: la imagen principal de la página',
    'When scrolled into view' => 'Al desplazarse hasta ella',
    'Preview: draft look' => 'Vista previa: borrador de la apariencia',
    'Neither the site e-mail (Settings → General) nor a sender address is filled in.' => 'No se ha rellenado ni el correo del sitio (Ajustes → General) ni una dirección de remitente.',
    'This file type cannot be uploaded. Images and these attachments are allowed: %s.' => 'Este tipo de archivo no se puede subir. Se permiten imágenes y estos adjuntos: %s.',
    'The folder %s cannot be created – check the write permissions.' => 'No se puede crear la carpeta %s: comprueba los permisos de escritura.',
    'The backup contains a foreign table %s – the restore was stopped.' => 'La copia de seguridad contiene una tabla ajena %s: se ha detenido la restauración.',
    '(credentials)' => '(credenciales)',
    'the connection' => 'la conexión',
    'The mailing service is not set up.' => 'El servicio de correo masivo no está configurado.',
    'The FTP server %s does not support an encrypted connection (FTPS). Kaleta does not use unencrypted FTP – choose S3 storage.' => 'El servidor FTP %s no admite una conexión cifrada (FTPS). Kaleta no usa FTP sin cifrar: elige un almacenamiento S3.',
    'Signing in to the FTP server %s failed.' => 'No se ha podido iniciar sesión en el servidor FTP %s.',
    'The folder %s does not exist on the FTP server and cannot be created.' => 'La carpeta %s no existe en el servidor FTP y no se puede crear.',
    'The file could not be uploaded to the FTP server.' => 'No se ha podido subir el archivo al servidor FTP.',
    'The cURL extension is missing on the server.' => 'Falta la extensión cURL en el servidor.',
    'Fill in the storage address (e.g. s3.eu-central-1.amazonaws.com) and the bucket name.' => 'Rellena la dirección del almacenamiento (p. ej. s3.eu-central-1.amazonaws.com) y el nombre del bucket.',
    'The storage refused the upload (code %s)' => 'El almacenamiento ha rechazado la subida (código %s)',
    'could not connect' => 'no se ha podido conectar',
    'connection tokens revoked: %d' => 'tokens de conexión revocados: %d',
    'with a passkey' => 'con llave de acceso',
    'two-factor' => 'en dos pasos',
    'invitation sent, account: %s' => 'invitación enviada, cuenta: %s',
    'link sent, account: %s' => 'enlace enviado, cuenta: %s',
    'password changed, connection tokens revoked, account: %s' => 'contraseña cambiada, tokens de conexión revocados, cuenta: %s',
    'password reset' => 'contraseña restablecida',
    'e-mail changed' => 'correo cambiado',
    'password changed' => 'contraseña cambiada',
    'two-factor sign-in turned on' => 'verificación en dos pasos activada',
    'two-factor sign-in turned off' => 'verificación en dos pasos desactivada',
    'passkey added' => 'llave de acceso añadida',
    'passkey removed' => 'llave de acceso quitada',
    'app connected' => 'app conectada',
    'Fill in the title.' => 'Rellena el título.',
    'Only a news item in the default language can be translated, into one of the other language versions of the site.' => 'Solo se puede traducir una noticia en el idioma predeterminado, a una de las otras versiones de idioma del sitio.',
    'There is no category in the target language yet. Create one in News → Categories (the Language version field).' => 'Aún no hay ninguna categoría en el idioma de destino. Crea una en Noticias → Categorías (el campo Versión de idioma).',
    'First write at least a bit of text – the assistant works from it.' => 'Escribe primero al menos un poco de texto: el asistente parte de él.',
    'The text is too short to translate.' => 'El texto es demasiado corto para traducirlo.',
    'The text is too long for the assistant to translate.' => 'El texto es demasiado largo para que lo traduzca el asistente.',
    'The translation did not fit into the assistant\'s answer. Try splitting the text.' => 'La traducción no cabía en la respuesta del asistente. Prueba a dividir el texto.',
    'The assistant reports an error (%s): %s' => 'El asistente informa de un error (%s): %s',
    'unknown error' => 'error desconocido',
    'look published' => 'apariencia publicada',
    'look draft discarded' => 'borrador de la apariencia descartado',
    'Page saved. It stays hidden until it has content – add text or publish it in the builder, and it goes on the site.' => 'Página guardada. Permanece oculta hasta que tenga contenido: añade texto o publícala en el builder y aparecerá en el sitio.',
    'Hidden until it has content: it goes on the site, and into the navigation, when you publish it in the builder or add text.' => 'Oculta hasta que tenga contenido: aparece en el sitio, y en la navegación, cuando la publiques en el builder o le añadas texto.',
    'A page from a template or the builder stays hidden until you publish it there.' => 'Una página creada desde una plantilla o el builder permanece oculta hasta que la publiques allí.',
    'hidden until published' => 'oculta hasta su publicación',
    'This site is not on HTTPS, so the Claude app cannot connect to it yet. Switch the site to HTTPS – most hosting does it for free – and open the administration at its https:// address.' => 'Este sitio no usa HTTPS, así que la app de Claude aún no puede conectarse. Cambia el sitio a HTTPS (la mayoría de los hostings lo hacen gratis) y abre la administración en su dirección https://.',
    'Build and edit the site by talking to Claude. Connect it once – it takes a minute – and Claude works on the site in your name and with your permissions.' => 'Construye y edita el sitio hablando con Claude. Conéctalo una vez (se tarda un minuto) y Claude trabajará en el sitio en tu nombre y con tus permisos.',
    'Paste the address above as the connector URL and add it.' => 'Pega la dirección de arriba como URL del conector y añádelo.',
    'Claude sends you here to sign in. Choose what it may do – then ask it anything about your site.' => 'Claude te envía aquí para iniciar sesión. Elige qué puede hacer y después pregúntale lo que quieras sobre tu sitio.',
    'Claude Code or another tool without sign-in? Create a personal token in' => '¿Claude Code u otra herramienta sin inicio de sesión? Crea un token personal en',
    'Saved as request #%d – Claude picks it up once it is connected to the site.' => 'Guardado como encargo n.º %d: Claude lo recogerá cuando esté conectado al sitio.',
    'The request is saved – Claude picks it up once it is connected to the site; you will read its notes here.' => 'Encargo guardado: Claude lo recogerá cuando esté conectado al sitio; aquí leerás sus notas.',
    'Connected – Claude last worked on the site %s.' => 'Conectado: Claude trabajó por última vez en el sitio %s.',
    'Not connected yet – no Claude connection has called the site.' => 'Aún sin conectar: ninguna conexión de Claude ha contactado con el sitio.',
    'In a subfolder, the Claude app finds the sign-in on its own; for a tool that does not, use a personal token.' => 'En una subcarpeta, la app de Claude encuentra el inicio de sesión por sí sola; para una herramienta que no lo haga, usa un token personal.',
    'Set up Bookings' => 'Configurar Reservas',
    'Add a person' => 'Añadir una persona',
    'Who takes the bookings – or one entry for the whole business – with their weekly hours.' => 'Quién acepta las reservas (o una entrada para todo el negocio), con su horario semanal.',
    'What visitors book and how long it takes – tick the person who offers it.' => 'Qué reservan los visitantes y cuánto dura: marca la persona que lo ofrece.',
    'Create a Book page' => 'Crear una página de reservas',
    'A page with the Booking element, where visitors pick a time.' => 'Una página con el elemento Reserva, donde los visitantes eligen una hora.',
    'A page with the Booking element opens in the builder. It stays hidden until you publish it.' => 'Se abre en el builder una página con el elemento Reserva. Permanece oculta hasta que la publiques.',
    'Follow the three steps above: a person, a service, a page. Visitors then pick a service, a person, a day and a free time.' => 'Sigue los tres pasos de arriba: una persona, un servicio, una página. Después los visitantes eligen un servicio, una persona, un día y una hora libre.',
    'An administrator adds the people, the services and the booking page. Bookings then appear here.' => 'Un administrador añade las personas, los servicios y la página de reservas. Después las reservas aparecen aquí.',
    'No free time in the next 14 days: %s has no weekly hours and the site has no opening hours, so no time is offered. Give them weekly hours, or fill in the opening hours in Business details.' => 'No hay horas libres en los próximos 14 días: %s no tiene horario semanal y el sitio no tiene horario de apertura, así que no se ofrece ninguna hora. Asígnale un horario semanal o rellena el horario en Datos de la empresa.',
    'No free time in the next 14 days – visitors see an empty calendar. Check the weekly hours and days off of the people, and the earliest booking and how far ahead visitors may book.' => 'No hay horas libres en los próximos 14 días: los visitantes ven un calendario vacío. Revisa el horario semanal y los días libres de las personas, la reserva más temprana y con cuánta antelación pueden reservar los visitantes.',
    'Add a person first' => 'Añade primero una persona',
    'A service needs someone who offers it. Add the person (or one entry for the whole business) with their weekly hours, then the service.' => 'Un servicio necesita a alguien que lo ofrezca. Añade la persona (o una entrada para todo el negocio) con su horario semanal y después el servicio.',
    'Nobody can offer it yet –' => 'Aún nadie puede ofrecerlo:',
    'add a person first' => 'añade primero una persona',
    'Nobody takes bookings yet.' => 'Aún nadie acepta reservas.',
    'Add the people (or just one entry for the whole business) with their weekly hours. Then add the services and tick who offers each.' => 'Añade las personas (o una sola entrada para todo el negocio) con su horario semanal. Después añade los servicios y marca quién ofrece cada uno.',
    'No services yet – save the person, then add a service and tick them in it.' => 'Aún no hay servicios: guarda la persona y después añade un servicio y márcala en él.',
    'Set up Bookings →' => 'Configurar Reservas →',
    'booking page created' => 'página de reservas creada',
    'Link (primary colour) on surface' => 'Enlace (color principal) sobre superficie',
    'Primary colour on its soft shade (current menu item, secondary button)' => 'Color principal sobre su tono suave (elemento de menú actual, botón secundario)',
    'Focus ring (secondary colour) on background' => 'Anillo de foco (color secundario) sobre fondo',
    'Focus ring (secondary colour) on surface' => 'Anillo de foco (color secundario) sobre superficie',
    '%s has a contrast of %s : 1 – a focus ring needs at least 3 : 1.' => '%s tiene un contraste de %s : 1; un anillo de foco necesita al menos 3 : 1.',
    'Text should have a contrast of at least 4.5 : 1 (WCAG AA), a focus ring at least 3 : 1. Pairs marked in red will be hard to read for some visitors.' => 'El texto debería tener un contraste de al menos 4.5 : 1 (WCAG AA) y un anillo de foco, al menos 3 : 1. Las parejas marcadas en rojo serán difíciles de leer para algunos visitantes.',
    'Automatic primary and secondary colours keep the hue of the light ones, made lighter until links, buttons and focus rings are readable on the dark background. Pick a colour to set your own.' => 'Los colores principal y secundario automáticos mantienen el tono de los claros, aclarados hasta que los enlaces, los botones y los anillos de foco se lean bien sobre el fondo oscuro. Elige un color para fijar el tuyo.',
    'Readability in dark mode' => 'Legibilidad en modo oscuro',
    'Dark mode: some colour pairs are hard to read – see the readability list in the Dark mode tab.' => 'Modo oscuro: algunas parejas de colores son difíciles de leer; consulta la lista de legibilidad en la pestaña Modo oscuro.',
    'Menus go to the draft look with links to the new addresses: the navigation on the site changes only when you publish the look.' => 'Los menús van al borrador de la apariencia con enlaces a las nuevas direcciones: la navegación del sitio solo cambia cuando publicas la apariencia.',
    'left out – this site has a main and a footer menu' => 'omitido: este sitio tiene un menú principal y uno del pie de página',
    'User accounts and passwords – no account is created. A news item belongs to the user here with the same e-mail as its WordPress author, otherwise to you. Comments are not transferred.' => 'Cuentas de usuario y contraseñas: no se crea ninguna cuenta. Una noticia pertenece al usuario de aquí con el mismo correo que su autor de WordPress; si no, a ti. Los comentarios no se transfieren.',
    'Widgets, appearance and plugin settings.' => 'Widgets, apariencia y ajustes de plugins.',
    'navigation menus (%s) into the draft look' => 'menús de navegación (%s) al borrador de la apariencia',
    'everything hidden – news as drafts, pages hidden; publish them when they are ready' => 'todo oculto: las noticias como borradores y las páginas ocultas; publícalas cuando estén listas',
    'Public on WordPress, imported hidden' => 'Público en WordPress, importado como oculto',
    'this site has a main and a footer menu, and other menus took them' => 'este sitio tiene un menú principal y uno del pie de página, y otros menús los ocuparon',
    'none of its links lead to anything that was imported' => 'ninguno de sus enlaces lleva a algo que se haya importado',
    'the draft look already holds a different menu for this place – nothing was overwritten' => 'el borrador de la apariencia ya contiene otro menú para este lugar: no se ha sobrescrito nada',
    'it was imported by an earlier run' => 'lo importó una ejecución anterior',
    'Menu “%s” was not imported: %s.' => 'No se ha importado el menú “%s”: %s.',
    'Open the menu' => 'Abrir el menú',
    '%s: the news items belong to %s, who has the same e-mail' => '%s: las noticias pertenecen a %s, que tiene el mismo correo',
    '%s: the news items belong to %s' => '%s: las noticias pertenecen a %s',
    'Old addresses that were not redirected (%s)' => 'Direcciones antiguas que no se han redirigido (%s)',
    'the address is already in use on this site' => 'la dirección ya se usa en este sitio',
    'the address already redirects elsewhere' => 'la dirección ya redirige a otro lugar',
    'The file is larger than the download limit.' => 'El archivo supera el límite de descarga.',
    'colours' => 'colores',
    'fonts' => 'fuentes',
    'sizes' => 'tamaños',
    'design system' => 'sistema de diseño',
    'classes' => 'clases',
    'menu' => 'menú',
    'Unpublished changes:' => 'Cambios sin publicar:',
    'Visitors still see the published look until you publish.' => 'Los visitantes siguen viendo la apariencia publicada hasta que publiques.',
    'Review' => 'Revisar',
    'The menu is published – visitors see it now.' => 'Menú publicado: los visitantes ya lo ven.',
    'Save and publish menu' => 'Guardar y publicar el menú',
    'Save to the draft look' => 'Guardar en el borrador de la apariencia',
    'Publishing the menu leaves other unpublished look changes (colours, fonts, classes) waiting in the draft.' => 'Publicar el menú deja en el borrador los demás cambios de la apariencia sin publicar (colores, fuentes, clases).',
    'menu published' => 'menú publicado',
    'Enter the old address – a path on this site, e.g. /old-page.' => 'Introduce la dirección antigua: una ruta de este sitio, p. ej. /old-page.',
    'An address may have at most 255 characters.' => 'Una dirección puede tener como máximo 255 caracteres.',
    'The old address must be a path on this site, e.g. /old-page (without ? or #).' => 'La dirección antigua debe ser una ruta de este sitio, p. ej. /old-page (sin ? ni #).',
    'Use at most 3 wildcards (*) in the old address, never two in a row.' => 'Usa como máximo 3 comodines (*) en la dirección antigua, nunca dos seguidos.',
    'A pattern needs a fixed part besides the wildcards, e.g. /blog/*.' => 'Un patrón necesita una parte fija además de los comodines, p. ej. /blog/*.',
    'The target must be a path on this site or a full https://… address; a wildcard (*) only after the domain.' => 'El destino debe ser una ruta de este sitio o una dirección https://… completa; un comodín (*) solo después del dominio.',
    'The target has more wildcards (*) than the old address.' => 'El destino tiene más comodines (*) que la dirección antigua.',
    'The old address and the target are the same.' => 'La dirección antigua y el destino son iguales.',
    'It would make a loop – the redirects would lead back to this address.' => 'Crearía un bucle: las redirecciones volverían a esta dirección.',
    'The site already has the most pattern rules it can use (500).' => 'El sitio ya tiene el máximo de reglas con patrón que puede usar (500).',
    'Only 301 (permanent), 302 (temporary) and 410 (gone for good).' => 'Solo 301 (permanente), 302 (temporal) y 410 (eliminada definitivamente).',
    'Enter the target – a path on this site or a full https://… address.' => 'Introduce el destino: una ruta de este sitio o una dirección https://… completa.',
    'The same old address is in an earlier row – the first one counts.' => 'La misma dirección antigua está en una fila anterior: cuenta la primera.',
    'The rule is switched off in the file.' => 'La regla está desactivada en el archivo.',
    'A regular expression – add this one by hand as a pattern with * (e.g. /blog/* → /news/*).' => 'Una expresión regular: añádela a mano como patrón con * (p. ej. /blog/* → /news/*).',
    'Choose a CSV file or paste its rows (old address, target, code).' => 'Elige un archivo CSV o pega sus filas (dirección antigua, destino, código).',
    'The file has no redirects – one per row: old address, target, code (301 or 302).' => 'El archivo no tiene redirecciones; una por fila: dirección antigua, destino, código (301 o 302).',
    'Import redirects' => 'Importar redirecciones',
    'Redirects imported: %d added, %d changed, %d refused.' => 'Redirecciones importadas: %d añadidas, %d cambiadas, %d rechazadas.',
    'An asterisk stands for the rest of the address: /blog/* → /news/* sends /blog/2019/post to /news/2019/post. An exact redirect always wins over a pattern, and the longer fixed beginning wins among patterns.' => 'Un asterisco representa el resto de la dirección: /blog/* → /news/* envía /blog/2019/post a /news/2019/post. Una redirección exacta siempre gana a un patrón y, entre patrones, gana el comienzo fijo más largo.',
    'Leave it empty for “gone (410)”.' => 'Déjalo vacío para “eliminada (410)”.',
    'gone (410) – removed for good, search engines drop it' => 'eliminada (410): quitada definitivamente, los buscadores la descartan',
    'gone (410)' => 'eliminada (410)',
    'Import from a CSV file' => 'Importar desde un archivo CSV',
    'One redirect per row: old address, target and code (301 or 302, empty = 301; 410 with an empty target = gone for good). A header row is optional; the CSV export of the WordPress Redirection plugin works as it is. You see what will be added, changed or refused before anything is saved.' => 'Una redirección por fila: dirección antigua, destino y código (301 o 302, vacío = 301; 410 con destino vacío = eliminada definitivamente). La fila de encabezado es opcional; la exportación CSV del plugin Redirection de WordPress funciona tal cual. Ves qué se añadirá, cambiará o rechazará antes de guardar nada.',
    'CSV file' => 'Archivo CSV',
    'Or paste the rows' => 'O pega las filas',
    'Show what will change' => 'Mostrar qué cambiará',
    'will be added' => 'se añadirá',
    'will change' => 'cambiará',
    'refused' => 'rechazada',
    '%d rows: %d will be added, %d will change, %d stay as they are, %d are refused.' => '%d filas: %d se añadirán, %d cambiarán, %d se quedan como están, %d se rechazan.',
    'Row' => 'Fila',
    'Save %d redirects' => 'Guardar %d redirecciones',
    'the news list' => 'la lista de noticias',
    'items of %s' => 'elementos de %s',
    'pages under %s' => 'páginas bajo %s',
    'also: %s' => 'también: %s',
    'Also on' => 'También en',
    'Besides the pages above, the variant can take a kind of content. A page ticked above always gets its variant; otherwise the first variant (by name) whose choice fits wins.' => 'Además de las páginas de arriba, la variante puede asignarse a un tipo de contenido. Una página marcada arriba siempre recibe su variante; si no, gana la primera variante (por nombre) cuya elección encaje.',
    'the news list, categories, tags and search' => 'la lista de noticias, categorías, etiquetas y búsqueda',
    'Pages under' => 'Páginas bajo',
    'The export file changed after the preview, so the import stopped. Start it again with the file you want to import.' => 'El archivo de exportación cambió después de la vista previa, así que se ha detenido la importación. Vuelve a iniciarla con el archivo que quieres importar.',
    'A cron job that already calls the older address …/ulohy?token= keeps working – there is no need to change it.' => 'Una tarea cron que ya llama a la dirección antigua …/ulohy?token= sigue funcionando: no hace falta cambiarla.',
    'English system addresses' => 'Direcciones del sistema en inglés',
    'The site itself uses %s, so the system keeps writing the older address %s there – both keep working. Rename the page if you want the English address.' => 'El propio sitio usa %s, así que el sistema sigue escribiendo allí la dirección antigua %s; ambas siguen funcionando. Cambia el nombre de la página si quieres la dirección en inglés.',
    'Undo journal of Claude sessions: older than 30 days removed' => 'Registro para deshacer sesiones de Claude: eliminadas las entradas de más de 30 días',
    'Online booking: reminders before the appointment' => 'Reserva en línea: recordatorios antes de la cita',
    'Imports not finished' => 'Importaciones sin terminar',
    '%s rows' => '%s filas',
    'A CSV file (from Excel or another system – comma, semicolon or tab) or a JSON list, up to %s rows. The first row names the columns; one row is one item. You pair the columns with the fields and see what will be added, changed or refused before anything is saved.' => 'Un archivo CSV (de Excel u otro sistema; coma, punto y coma o tabulador) o una lista JSON, de hasta %s filas. La primera fila nombra las columnas; cada fila es un elemento. Emparejas las columnas con los campos y ves qué se añadirá, cambiará o rechazará antes de guardar nada.',
    'Columns named like the fields are paired by themselves: %s.' => 'Las columnas con el mismo nombre que los campos se emparejan solas: %s.',
    'An image or file column with web addresses (https://…) is downloaded into Media after the items are saved.' => 'Una columna de imagen o archivo con direcciones web (https://…) se descarga en Medios después de guardar los elementos.',
    'CSV or JSON file' => 'Archivo CSV o JSON',
    'Another file' => 'Otro archivo',
    '%s: %d rows – %d will be added, %d will change, %d stay as they are, %d are refused.' => '%s: %d filas – %d se añadirán, %d cambiarán, %d se quedan como están, %d se rechazan.',
    'Column in the file' => 'Columna del archivo',
    'Example' => 'Ejemplo',
    'Goes to' => 'Va a',
    '– not imported –' => '– no se importa –',
    'Default language' => 'Idioma predeterminado',
    'For rows without a language column.' => 'Para las filas sin columna de idioma.',
    'Show new items on the site at once' => 'Mostrar los nuevos elementos en el sitio de inmediato',
    'Without it new items arrive hidden, so you can check them first. Items that change keep their visibility.' => 'Sin esta opción, los nuevos elementos llegan ocultos para que puedas revisarlos antes. Los elementos que cambian mantienen su visibilidad.',
    'An item is found by its address (slug), or by the address made from its name – importing the same file again updates the items instead of adding them twice. An empty cell leaves the value of an item as it is.' => 'Un elemento se identifica por su dirección (slug) o por la dirección formada a partir de su nombre: importar de nuevo el mismo archivo actualiza los elementos en lugar de añadirlos dos veces. Una celda vacía deja el valor del elemento como está.',
    'Update preview' => 'Actualizar la vista previa',
    'Save %d items' => 'Guardar %d elementos',
    'Invalid value, left empty: %s' => 'Valor no válido, se deja vacío: %s',
    'The first 100 rows are shown, then the refused ones and those with an invalid value.' => 'Se muestran las primeras 100 filas, luego las rechazadas y las que tienen un valor no válido.',
    'File: %s' => 'Archivo: %s',
    'Saving: %s of %s rows. Keep this page open, it continues by itself.' => 'Guardando: %s de %s filas. Mantén esta página abierta; continúa sola.',
    'Downloading images: %s of %s. Keep this page open, it continues by itself.' => 'Descargando imágenes: %s de %s. Mantén esta página abierta; continúa sola.',
    'The import is finished.' => 'La importación ha terminado.',
    'The import is finished. New items are hidden until you check and show them.' => 'La importación ha terminado. Los nuevos elementos están ocultos hasta que los revises y los muestres.',
    'No change' => 'Sin cambios',
    'Refused' => 'Rechazada',
    '%d items had a field with an invalid value – it was left empty. Check them in the list.' => '%d elementos tenían un campo con un valor no válido, que se ha dejado vacío. Revísalos en la lista.',
    'Refused rows: %d' => 'Filas rechazadas: %d',
    'Row %d' => 'Fila %d',
    '%d images could not be downloaded' => 'No se han podido descargar %d imágenes',
    'Show items' => 'Mostrar elementos',
    'Import another file' => 'Importar otro archivo',
    'Import from CSV or JSON' => 'Importar desde CSV o JSON',
    'Import items: %s' => 'Importar elementos: %s',
    'The file is larger than %d MB.' => 'El archivo supera los %d MB.',
    'The robots.txt of the old site asks robots not to read this page, so only the address was checked.' => 'El robots.txt del sitio antiguo pide a los robots que no lean esta página, así que solo se ha comprobado la dirección.',
    'Address (slug)' => 'Dirección (slug)',
    'Title for search engines' => 'Título para buscadores',
    'Description for search engines' => 'Descripción para buscadores',
    'Image for sharing' => 'Imagen para compartir',
    'The file is empty.' => 'El archivo está vacío.',
    'The file has no rows – the first row names the columns, every further row is one item.' => 'El archivo no tiene filas: la primera fila nombra las columnas y cada fila siguiente es un elemento.',
    'The file has more than 5,000 rows – split it into smaller files.' => 'El archivo tiene más de 5000 filas: divídelo en archivos más pequeños.',
    'The JSON file must be a list of items: [{"name":"…","price":"…"}, …].' => 'El archivo JSON debe ser una lista de elementos: [{"name":"…","price":"…"}, …].',
    'The file could not be read.' => 'No se ha podido leer el archivo.',
    'The item is in the trash – restore it first.' => 'El elemento está en la papelera: restáuralo primero.',
    'The same item is in this batch twice – only the first one is saved.' => 'El mismo elemento está dos veces en este lote: solo se guarda el primero.',
    'Invalid item address.' => 'Dirección del elemento no válida.',
    'The item could not be saved.' => 'No se ha podido guardar el elemento.',
    'Only https addresses are downloaded.' => 'Solo se descargan direcciones https.',
    'This server cannot download files from other sites.' => 'Este servidor no puede descargar archivos de otros sitios.',
    'SVG files are not downloaded – upload them with upload_file.' => 'Los archivos SVG no se descargan: súbelos con upload_file.',
    'The robots.txt of the old site asks robots not to read this page.' => 'El robots.txt del sitio antiguo pide a los robots que no lean esta página.',
    'Categories: %s' => 'Categorías: %s',
    'Category page: %s' => 'Página de categoría: %s',
    'Category description' => 'Descripción de la categoría',
    'Number of items' => 'Número de elementos',
    'Parent category' => 'Categoría superior',
    'Parent category page' => 'Página de la categoría superior',
    'Add category' => 'Añadir categoría',
    'Category page template' => 'Plantilla de la página de categoría',
    'Category page template (%s)' => 'Plantilla de la página de categoría (%s)',
    'No categories yet.' => 'Aún no hay categorías.',
    'Categories sort the items into groups with their own pages – /%s/category and /%s/category/subcategory – with a description, breadcrumbs and a list of the items. Tick the categories on each item.' => 'Las categorías agrupan los elementos en páginas propias – /%s/categoria y /%s/categoria/subcategoria – con descripción, migas de pan y una lista de los elementos. Marca las categorías en cada elemento.',
    'Two levels: a category and its subcategories. A category page lists the items of the category and of its subcategories; an address can never be both a category and an item of this collection.' => 'Dos niveles: una categoría y sus subcategorías. La página de una categoría lista los elementos de la categoría y de sus subcategorías; una dirección nunca puede ser a la vez una categoría y un elemento de esta colección.',
    'Edit the %s version' => 'Editar la versión %s',
    'Add the %s version' => 'Añadir la versión %s',
    'Add subcategory' => 'Añadir subcategoría',
    'Delete the category in every language? Its items stay in the collection; its page disappears.' => '¿Eliminar la categoría en todos los idiomas? Sus elementos se quedan en la colección; su página desaparece.',
    'From the name if left empty. It cannot be the address of an item of this collection.' => 'Si se deja vacío, se toma del nombre. No puede ser la dirección de un elemento de esta colección.',
    'Shown on the category page ({{popis}} in the category template) – an introduction for visitors and search engines.' => 'Se muestra en la página de la categoría ({{popis}} en la plantilla de categoría) – una introducción para visitantes y buscadores.',
    'empty = the category name' => 'vacío = el nombre de la categoría',
    'One or two sentences for search results (up to 160 characters). Empty = the beginning of the description.' => 'Una o dos frases para los resultados de búsqueda (hasta 160 caracteres). Vacío = el comienzo de la descripción.',
    'Shared by every language' => 'Compartido por todos los idiomas',
    '– none (a top-level category) –' => '– ninguna (categoría de nivel superior) –',
    'It has subcategories, so it stays a top-level category.' => 'Tiene subcategorías, así que sigue siendo una categoría de nivel superior.',
    'Shown on the category page and its card ({{obrazek}}) and when the page is shared.' => 'Se muestra en la página de la categoría y en su tarjeta ({{obrazek}}) y al compartir la página.',
    'A hidden category has no page and is in no list; its items stay where they are.' => 'Una categoría oculta no tiene página ni aparece en ninguna lista; sus elementos se quedan donde están.',
    'Save category' => 'Guardar categoría',
    'Remove the %s version of the category? The other languages keep it.' => '¿Quitar la versión %s de la categoría? Los demás idiomas la conservan.',
    'Remove this language version' => 'Quitar esta versión de idioma',
    'The item is listed on the pages of the ticked categories (a top-level category page also lists the items of its subcategories).' => 'El elemento aparece en las páginas de las categorías marcadas (la página de una categoría de nivel superior también lista los elementos de sus subcategorías).',
    'Manage categories' => 'Gestionar categorías',
    'Attachment size limit per file in MB (1–25). This server accepts files up to %s, so a higher limit applies only up to that.' => 'Límite de tamaño por archivo adjunto en MB (1–25). Este servidor acepta archivos de hasta %s, así que un límite mayor solo se aplica hasta ese tamaño.',
    'Attachment size limit per file in MB (1–25). This server accepts files up to %s.' => 'Límite de tamaño por archivo adjunto en MB (1–25). Este servidor acepta archivos de hasta %s.',
    'Attachment size limit per file in MB (1–25)' => 'Límite de tamaño por archivo adjunto en MB (1–25)',
    'The address “%s” belongs to a category of this collection – give the item another address.' => 'La dirección “%s” pertenece a una categoría de esta colección – dale otra dirección al elemento.',
    'The category does not exist in this collection.' => 'La categoría no existe en esta colección.',
    'The category needs a name.' => 'La categoría necesita un nombre.',
    'The address “%s” cannot be used for a category.' => 'La dirección “%s” no se puede usar para una categoría.',
    'The address “%s” is already used by another category of this collection.' => 'La dirección “%s” ya la usa otra categoría de esta colección.',
    'The address “%s” is already used by an item of this collection – a category page and an item page cannot share it.' => 'La dirección “%s” ya la usa un elemento de esta colección – una página de categoría y una página de elemento no pueden compartirla.',
    'A subcategory belongs under a top-level category of the same collection (two levels).' => 'Una subcategoría va bajo una categoría de nivel superior de la misma colección (dos niveles).',
    'The category has subcategories, so it cannot become a subcategory itself (two levels).' => 'La categoría tiene subcategorías, así que no puede convertirse en subcategoría (dos niveles).',
    'The image must be a file from Media or an https address.' => 'La imagen debe ser un archivo de Medios o una dirección https.',
    'The category has subcategories – delete them or move them under another category first.' => 'La categoría tiene subcategorías – elimínalas o muévelas antes bajo otra categoría.',
    'There is nothing in this category yet.' => 'Aún no hay nada en esta categoría.',
    'Item name' => 'Nombre del elemento',
    'Previous and next item' => 'Elemento anterior y siguiente',
    'The category was saved.' => 'La categoría se ha guardado.',
    'The category was deleted; its items stay in the collection.' => 'La categoría se ha eliminado; sus elementos se quedan en la colección.',
    'Previous / next item' => 'Elemento anterior / siguiente',
    'Links to the previous and the next item on an item page (references, products, projects) – in the collection order or by date, within the item’s category.' => 'Enlaces al elemento anterior y al siguiente en la página de un elemento (referencias, productos, proyectos) – en el orden de la colección o por fecha, dentro de la categoría del elemento.',
    'items' => 'elementos',
    'Category (its address; * = the category page shown, on an item page the item’s category). Categories: the subcategories of it, empty = the top-level ones' => 'Categoría (su dirección; * = la página de categoría mostrada, en la página de un elemento la categoría del elemento). Categorías: sus subcategorías, vacío = las de nivel superior',
    'as in the administration (order, then name)' => 'como en la administración (orden y después nombre)',
    'by date (previous = older)' => 'por fecha (anterior = más antiguo)',
    'Only within the item’s category (when it has one)' => 'Solo dentro de la categoría del elemento (si tiene una)',
    'Label of the previous item' => 'Etiqueta del elemento anterior',
    'Label of the next item' => 'Etiqueta del elemento siguiente',
    'Show the item names' => 'Mostrar los nombres de los elementos',
    'Show thumbnails' => 'Mostrar miniaturas',
    'Thumbnail field (key of an image field; empty = the first image field)' => 'Campo de la miniatura (clave de un campo de imagen; vacío = el primer campo de imagen)',
    'Collection categories' => 'Categorías de la colección',
    'version %s needs PHP %s or newer, the server runs PHP %s – ask the hosting for a newer PHP to update' => 'la versión %s necesita PHP %s o posterior, el servidor usa PHP %s – pide a tu hosting un PHP más reciente para actualizar',
    'Version %s needs PHP %s or newer; the server runs PHP %s. Ask your hosting to switch the site to a newer PHP, then the update will be offered here.' => 'La versión %s necesita PHP %s o posterior; el servidor usa PHP %s. Pide a tu hosting que cambie el sitio a un PHP más reciente y la actualización se ofrecerá aquí.',
    'The robots.txt of the old site is very long: only its first %s KB and %s rules for Kaleta were read.' => 'El robots.txt del sitio antiguo es muy largo: solo se leyeron sus primeros %s KB y %s reglas para Kaleta.',
    '%s sitemaps on other hosts were not read (%s): only the old site’s own sitemaps are followed.' => '%s sitemaps en otros hosts no se leyeron (%s): solo se siguen los sitemaps propios del sitio antiguo.',
    '%s more sitemaps were not read: at most %s are read.' => '%s sitemaps más no se leyeron: se leen como máximo %s.',
    'Finished imports' => 'Importaciones terminadas',
    'The result of an import stays here until you remove it, at most %s days; the items stay either way. The uploaded rows are deleted as soon as they are saved.' => 'El resultado de una importación se queda aquí hasta que lo quites, como máximo %s días; los elementos se quedan en cualquier caso. Las filas subidas se eliminan en cuanto se guardan.',
    'Remove this import' => 'Quitar esta importación',
    'The address %s is used by the system, so the page got %s.' => 'La dirección %s la usa el sistema, así que la página recibió %s.',
    'The page has been restored with the address %s, because its old address %s is used by the system – publish it in its settings.' => 'La página se ha restaurado con la dirección %s porque su dirección anterior %s la usa el sistema – publícala en sus ajustes.',
    'Changed so the site keeps working:' => 'Cambiado para que el sitio siga funcionando:',
    'Collection category %s: its parent is not a top-level category of the same collection, so it became a top-level category.' => 'Categoría de la colección %s: su categoría superior no es una categoría de nivel superior de la misma colección, así que pasó a ser de nivel superior.',
    'Collection category “%s”: the address %s cannot be used (an item of the collection has it, or it is reserved), so the category got %s.' => 'Categoría de la colección “%s”: la dirección %s no se puede usar (la tiene un elemento de la colección o está reservada), así que la categoría recibió %s.',
    'Its address %s is taken by another item or a category now, so the item keeps %s.' => 'Su dirección %s la tiene ahora otro elemento o una categoría, así que el elemento conserva %s.',
    'The item was restored as hidden with the address %s, because a category of the collection has its old address.' => 'El elemento se ha restaurado como oculto con la dirección %s porque una categoría de la colección tiene su dirección anterior.',
    'The address “%s” belongs to a category of this collection, so the item has “%s”.' => 'La dirección “%s” pertenece a una categoría de esta colección, así que el elemento tiene “%s”.',
    'Items with another address: %d' => 'Elementos con otra dirección: %d',
    'A cron job that calls /tasks reaches that page and runs nothing – point it at /ulohy.' => 'Un cron que llama a /tasks llega a esa página y no ejecuta nada – apúntalo a /ulohy.',
    'PHP JIT' => 'PHP JIT',
    'opcache.jit = %s on PHP %s can crash pages (a bug in PHP 8.3) – ask the hosting for opcache.jit = tracing (the default) or PHP 8.4' => 'opcache.jit = %s en PHP %s puede bloquear páginas (un error de PHP 8.3) – pide a tu hosting opcache.jit = tracing (el valor predeterminado) o PHP 8.4',
    'https://… or /page' => 'https://… o /pagina',
    'Latest channel' => 'Canal Última',
    'Stable channel' => 'Canal Estable',
    'custom update source' => 'fuente de actualizaciones propia',
    'This site runs version %s, which is newer than the stable channel (%s). Nothing is offered until the stable channel moves past this version – a site never goes back to an older one. Until then, security fixes reach this site only on the Latest channel.' => 'Este sitio usa la versión %s, más reciente que el canal estable (%s). No se ofrece nada hasta que el canal estable supere esta versión – un sitio nunca vuelve a una versión anterior. Hasta entonces, las correcciones de seguridad solo llegan a este sitio en el canal Última.',
    'You have the newest version of the stable channel.' => 'Tienes la versión más reciente del canal estable.',
    'Update channel' => 'Canal de actualizaciones',
    'Latest' => 'Última',
    'A new minor version every week, with new features and fixes. Recommended for most sites.' => 'Una nueva versión menor cada semana, con nuevas funciones y correcciones. Recomendado para la mayoría de los sitios.',
    'Stable' => 'Estable',
    'Security fixes only, and a new minor version about once a month, after it has run on Latest. For sites that should change as little as possible.' => 'Solo correcciones de seguridad y una nueva versión menor aproximadamente una vez al mes, después de pasar por Última. Para sitios que deben cambiar lo menos posible.',
    'The custom update source below is not a file named aktualizace.json, so it has no stable twin: the site follows it whatever channel you choose.' => 'La fuente de actualizaciones propia de abajo no es un archivo llamado aktualizace.json, así que no tiene equivalente estable: el sitio la sigue sea cual sea el canal que elijas.',
    'A site on Stable never goes back to an older version: after switching from Latest it waits until the stable channel passes the version it runs.' => 'Un sitio en Estable nunca vuelve a una versión anterior: tras cambiar desde Última, espera hasta que el canal estable supere la versión que usa.',
    'Stable – this site runs %s, newer than the stable channel (%s): nothing is offered until the stable channel passes it, so security fixes reach it only on Latest (Settings → Backups and updates)' => 'Estable – este sitio usa %s, más reciente que el canal estable (%s): no se ofrece nada hasta que el canal estable la supere, así que las correcciones de seguridad solo le llegan en Última (Ajustes → Copias de seguridad y actualizaciones)',
    'Stable – security fixes only, a new minor version about once a month' => 'Estable – solo correcciones de seguridad, una nueva versión menor aproximadamente una vez al mes',
    'custom update source – the site follows it whatever channel is chosen' => 'fuente de actualizaciones propia – el sitio la sigue sea cual sea el canal elegido',
    'Latest – a new minor version every week' => 'Última – una nueva versión menor cada semana',
    'Kaleta version' => 'Versión de Kaleta',
    'The markup is %s bytes long; the limit is %s.' => 'El código tiene %s bytes; el límite es %s.',
    'The markup is nested %s levels deep; the limit is %s.' => 'El código está anidado en %s niveles; el límite es %s.',
    'An element in the markup has %s attributes; the limit is %s.' => 'Un elemento del código tiene %s atributos; el límite es %s.',
    'The markup has %s elements; the limit is %s.' => 'El código tiene %s elementos; el límite es %s.',
    'The SVG file was refused: %s' => 'Se rechazó el archivo SVG: %s',
    'The page was not imported: %s' => 'La página no se importó: %s',
    'Nothing was saved: %s' => 'No se guardó nada: %s',
    'The description: %s' => 'La descripción: %s',
    'The old page is over a safety limit for HTML (too large or nested too deeply), so only the address was checked.' => 'La página antigua supera un límite de seguridad para HTML (demasiado grande o demasiado anidada), así que solo se comprobó la dirección.',
    'Not imported – the HTML is over a safety limit:' => 'No importado – el HTML supera un límite de seguridad:',
    '“%s” was skipped: %s' => 'Se omitió “%s”: %s',
    'A builder field (%s) was over a safety limit for HTML and was left empty.' => 'Un campo del builder (%s) superaba un límite de seguridad para HTML y se dejó vacío.',
    'Collection category “%s”: the description was left empty: %s' => 'Categoría de la colección “%s”: la descripción se dejó vacía: %s',
    'The assistant\'s reply is over a safety limit for HTML. Please try again.' => 'La respuesta del asistente supera un límite de seguridad para HTML. Inténtalo de nuevo.',
    'The text is over a safety limit for HTML (too large or nested too deeply), so it cannot be translated.' => 'El texto supera un límite de seguridad para HTML (demasiado grande o demasiado anidado), así que no se puede traducir.',
    'Nothing was saved: the text is over a safety limit for HTML (too large or nested too deeply).' => 'No se guardó nada: el texto supera un límite de seguridad para HTML (demasiado grande o demasiado anidado).',
    'Send through' => 'Enviar a través de',
    'Other server – your host, Google Workspace, Seznam…' => 'Otro servidor – tu hosting, Google Workspace, Seznam…',
    'Mail services with an SMTP relay' => 'Servicios de correo con relay SMTP',
    'A mail service fills in the server, the port and the encryption. The user name and the password stay yours to paste – the service’s SMTP credentials, not its API key unless the service says so.' => 'Un servicio de correo rellena el servidor, el puerto y el cifrado. El nombre de usuario y la contraseña los pegas tú – las credenciales SMTP del servicio, no su clave API, salvo que el servicio indique lo contrario.',
    'Amazon SES region' => 'Región de Amazon SES',
    'The region where the sending domain is verified in Amazon SES – the SMTP credentials work only there.' => 'La región en la que el dominio de envío está verificado en Amazon SES – las credenciales SMTP solo funcionan allí.',
    'User name' => 'Nombre de usuario',
    'Your newsletter integration uses %s too. Its API key is not copied here – the SMTP relay signs in with its own credentials, so paste them below.' => 'Tu integración de boletines también usa %s. Su clave API no se copia aquí – el relay SMTP inicia sesión con sus propias credenciales, así que pégalas abajo.',
    'Newsletter integration' => 'Integración de boletines',
    '%s: SMTP guide' => '%s: guía SMTP',
    'Your newsletter integration uses %s, which also relays e-mail over SMTP – choose %s above to send the site’s mail through the same account.' => 'Tu integración de boletines usa %s, que también envía correo por SMTP – elige %s arriba para enviar el correo del sitio a través de la misma cuenta.',
    'DNS records for %s' => 'Registros DNS para %s',
    'The SPF record of %s must include %s – one SPF record per domain, for example:' => 'El registro SPF de %s debe incluir %s – un solo registro SPF por dominio, por ejemplo:',
    'none found on %s' => 'no se encontró ninguno en %s',
    'found – all is well' => 'encontrado – todo correcto',
    'found, but it does not seem to include %s yet' => 'encontrado, pero parece que aún no incluye %s',
    'not found yet' => 'aún no encontrado',
    'System status checks the sending domain once a day; after adding the records, use Check now there.' => 'Estado del sistema comprueba el dominio de envío una vez al día; después de añadir los registros, usa allí Comprobar ahora.',
    'The site’s own e-mail goes through %s too (Settings → Mail), signed in with an SMTP key of its own – this API key is not used there.' => 'El correo propio del sitio también pasa por %s (Ajustes → Correo), con su propia clave SMTP – esta clave API no se usa allí.',
    '%s can also send the site’s own e-mail (password resets, enquiries, newsletters) over SMTP – choose it in Settings → Mail and paste an SMTP key there; this API key is not copied.' => '%s también puede enviar el correo propio del sitio (restablecimiento de contraseñas, consultas, boletines) por SMTP – elígelo en Ajustes → Correo y pega allí una clave SMTP; esta clave API no se copia.',
    'Settings → Mail' => 'Ajustes → Correo',
    '%s needs no include in this record – its DKIM and return-path records authenticate the mail' => '%s no necesita include en este registro – sus registros DKIM y return-path autentican el correo',
    'no DKIM key found under the common selectors. %s: %s' => 'no se encontró ninguna clave DKIM con los selectores habituales. %s: %s',
    'via %s (SMTP server %s)' => 'a través de %s (servidor SMTP %s)',
    'E-mail: sent through %s (SMTP server %s) – the service processes the recipients’ addresses and the messages.' => 'Correo electrónico: enviado a través de %s (servidor SMTP %s) – el servicio procesa las direcciones de los destinatarios y los mensajes.',
    '%s – password: %s' => '%s – contraseña: %s',
    'The SMTP login shown in Brevo under SMTP & API → SMTP (it ends in @smtp-brevo.com).' => 'El login SMTP que Brevo muestra en SMTP & API → SMTP (termina en @smtp-brevo.com).',
    'An SMTP key generated on the same page – not an API key: the Brevo relay refuses API keys.' => 'Una clave SMTP generada en la misma página – no una clave API: el relay de Brevo rechaza las claves API.',
    'In Brevo → Senders, Domains → Domains, authenticate the sending domain: add the brevo-code TXT record and the two DKIM records (brevo1._domainkey and brevo2._domainkey) Brevo shows. With shared sending IPs no SPF include is needed.' => 'En Brevo → Senders, Domains → Domains, autentica el dominio de envío: añade el registro TXT brevo-code y los dos registros DKIM (brevo1._domainkey y brevo2._domainkey) que muestra Brevo. Con IP de envío compartidas no hace falta include en el SPF.',
    'The SMTP login of your sending domain from Mailgun → Sending → Domain settings → SMTP credentials, for example postmaster@mg.example.com.' => 'El login SMTP de tu dominio de envío en Mailgun → Sending → Domain settings → SMTP credentials, por ejemplo postmaster@mg.example.com.',
    'The password of that SMTP login – not the Mailgun API key.' => 'La contraseña de ese login SMTP – no la clave API de Mailgun.',
    'Mailgun → Sending → Domains → DNS records lists the SPF (include:mailgun.org) and DKIM TXT records for the sending domain – add both.' => 'Mailgun → Sending → Domains → DNS records muestra los registros TXT de SPF (include:mailgun.org) y DKIM del dominio de envío – añade ambos.',
    'The SMTP user name from Amazon SES → SMTP settings → Create SMTP credentials – not the AWS access key ID.' => 'El nombre de usuario SMTP de Amazon SES → SMTP settings → Create SMTP credentials – no el ID de clave de acceso de AWS.',
    'The SMTP password shown once with it – not the AWS secret access key.' => 'La contraseña SMTP que se muestra una sola vez junto a él – no la clave de acceso secreta de AWS.',
    'Verify the sending domain in Amazon SES with Easy DKIM: add the three CNAME records (…._domainkey) SES shows. include:amazonses.com in SPF is needed only with a custom MAIL FROM domain.' => 'Verifica el dominio de envío en Amazon SES con Easy DKIM: añade los tres registros CNAME (…._domainkey) que muestra SES. include:amazonses.com en el SPF solo hace falta con un dominio MAIL FROM propio.',
    'The Access Key of an SMTP token (Postmark → your server → the message stream → Settings), or the Server API token. For newsletters use a broadcast stream and the server smtp-broadcasts.postmarkapp.com.' => 'La Access Key de un token SMTP (Postmark → tu servidor → el message stream → Settings) o el Server API token. Para boletines, usa un broadcast stream y el servidor smtp-broadcasts.postmarkapp.com.',
    'The Secret Key of that SMTP token – or the same Server API token again, which Postmark accepts as both.' => 'La Secret Key de ese token SMTP – o de nuevo el mismo Server API token, que Postmark acepta para ambos.',
    'Postmark → Sender signatures → DNS settings: add the DKIM TXT record (…pm._domainkey) and the Return-Path CNAME pointing to pm.mtasv.net. Postmark needs no SPF include.' => 'Postmark → Sender signatures → DNS settings: añade el registro TXT de DKIM (…pm._domainkey) y el CNAME Return-Path que apunta a pm.mtasv.net. Postmark no necesita include en el SPF.',
    'Literally apikey – the same for every account.' => 'Literalmente apikey – igual para todas las cuentas.',
    'A SendGrid API key with the Mail Send permission: SendGrid uses the API key as the SMTP password.' => 'Una clave API de SendGrid con el permiso Mail Send: SendGrid usa la clave API como contraseña SMTP.',
    'SendGrid → Settings → Sender authentication → Authenticate your domain: add the CNAME records it shows (em…, s1._domainkey and s2._domainkey); they cover SPF and DKIM.' => 'SendGrid → Settings → Sender authentication → Authenticate your domain: añade los registros CNAME que muestra (em…, s1._domainkey y s2._domainkey); cubren SPF y DKIM.',
    'The SMTP user MailerSend generates on the domain page (Domains → your domain → SMTP).' => 'El usuario SMTP que MailerSend genera en la página del dominio (Domains → tu dominio → SMTP).',
    'The password of that SMTP user – shown only once; not an API token.' => 'La contraseña de ese usuario SMTP – solo se muestra una vez; no es un token API.',
    'MailerSend → Domains → your domain: add the SPF (include:_spf.mailersend.net), DKIM and Return-Path records it shows.' => 'MailerSend → Domains → tu dominio: añade los registros SPF (include:_spf.mailersend.net), DKIM y Return-Path que muestra.',
    'An SMTP user created in SMTP2GO → Sending → SMTP Users – not your dashboard login. If port 587 is blocked, use 2525.' => 'Un usuario SMTP creado en SMTP2GO → Sending → SMTP Users – no tu login del panel. Si el puerto 587 está bloqueado, usa el 2525.',
    'The password of that SMTP user.' => 'La contraseña de ese usuario SMTP.',
    'SMTP2GO → Sending → Verified senders: add the sending domain and the CNAME records it shows (return path, DKIM and link tracking); they cover SPF.' => 'SMTP2GO → Sending → Verified senders: añade el dominio de envío y los registros CNAME que muestra (return path, DKIM y seguimiento de enlaces); cubren SPF.',
    'Your Mailjet API key (Account settings → SMTP and Send API settings) – Mailjet uses it as the SMTP user name.' => 'Tu clave API de Mailjet (Account settings → SMTP and Send API settings) – Mailjet la usa como nombre de usuario SMTP.',
    'The secret key belonging to that API key.' => 'La clave secreta de esa clave API.',
    'Mailjet → Account settings → Domains: add include:spf.mailjet.com to the SPF record and the DKIM TXT record (mailjet._domainkey) Mailjet shows.' => 'Mailjet → Account settings → Domains: añade include:spf.mailjet.com al registro SPF y el registro TXT de DKIM (mailjet._domainkey) que muestra Mailjet.',
    'Any name – Mailchimp does not check it and recommends your account’s primary contact e-mail.' => 'Cualquier nombre – Mailchimp no lo comprueba y recomienda el correo de contacto principal de tu cuenta.',
    'A Mailchimp Transactional (Mandrill) API key from Settings → SMTP & API Info – a Mailchimp marketing API key does not work.' => 'Una clave API de Mailchimp Transactional (Mandrill) de Settings → SMTP & API Info – una clave API de marketing de Mailchimp no funciona.',
    'Mailchimp Transactional → Domains → Sending domains: verify the domain and add the DKIM and SPF records it shows (include:spf.mandrillapp.com).' => 'Mailchimp Transactional → Domains → Sending domains: verifica el dominio y añade los registros DKIM y SPF que muestra (include:spf.mandrillapp.com).',
    'Ecomail sends transactional e-mail only through its API, not over SMTP – keep it for the newsletter and choose another service or your mailbox for the site’s mail.' => 'Ecomail envía correo transaccional solo mediante su API, no por SMTP – úsalo para el boletín y elige otro servicio o tu buzón para el correo del sitio.',
    'SmartEmailing sends transactional e-mail only through its API, not over SMTP – keep it for the newsletter and choose another service or your mailbox for the site’s mail.' => 'SmartEmailing envía correo transaccional solo mediante su API, no por SMTP – úsalo para el boletín y elige otro servicio o tu buzón para el correo del sitio.',
    'MailerLite has no SMTP relay of its own; its transactional service is MailerSend, a separate account with its own SMTP user.' => 'MailerLite no tiene relay SMTP propio; su servicio transaccional es MailerSend, una cuenta aparte con su propio usuario SMTP.',
    'Multilingual site (%s): %s.' => 'Sitio multilingüe (%s): %s.',
    'languages in the addresses' => 'idiomas en las direcciones',
    'no language named' => 'ningún idioma indicado',
    'Each post, page and category arrives in its language version and is linked to its original in the default language.' => 'Cada entrada, página y categoría llega a su versión de idioma y se vincula a su original en el idioma predeterminado.',
    'Not imported – this site cannot offer these languages yet: %s.' => 'No importado – este sitio aún no puede ofrecer estos idiomas: %s.',
    'Translations linked to their original' => 'Traducciones vinculadas a su original',
    'Language versions added to the site: %s.' => 'Versiones de idioma añadidas al sitio: %s.',
    'Addresses another language version already had (%s)' => 'Direcciones que ya tenía otra versión de idioma (%s)',
    'These got a number at the end; the old address redirects to the new one. Once each language version can have its own addresses, they can get their original address back.' => 'Recibieron un número al final; la dirección antigua redirige a la nueva. Cuando cada versión de idioma pueda tener sus propias direcciones, podrán recuperar su dirección original.',
    '%s instead of %s – %s has it' => '%s en lugar de %s – la tiene %s',
    'Banner text and policy link in other language versions' => 'Texto del banner y enlace a la política en otras versiones de idioma',
    'Visitors of each language version read the banner in its language. An empty field means the same as in the default language.' => 'Los visitantes de cada versión de idioma leen el banner en su idioma. Un campo vacío significa lo mismo que en el idioma predeterminado.',
    'The same address in every language' => 'La misma dirección en todos los idiomas',
    'A page, a news item or a category may have the same address as one in another language version (/kontakt and /en/kontakt), as on a multilingual WordPress site. System addresses and language codes stay reserved in every language. Switching it off again is possible only while no two language versions share an address.' => 'Una página, una noticia o una categoría puede tener la misma dirección que otra en otra versión de idioma (/kontakt y /en/kontakt), como en un sitio WordPress multilingüe. Las direcciones del sistema y los códigos de idioma siguen reservados en todos los idiomas. Solo se puede volver a desactivar mientras ninguna pareja de versiones de idioma comparta una dirección.',
    'The same address in every language cannot be switched off while two language versions share an address: %s. Change one of each pair first.' => 'La misma dirección en todos los idiomas no se puede desactivar mientras dos versiones de idioma compartan una dirección: %s. Cambia antes una de cada pareja.',
    'The same address in every language cannot be switched off while two language versions share an address: %s. Change one of each pair first – two tags with the same address can be merged in Tags and topics.' => 'La misma dirección en todos los idiomas no se puede desactivar mientras dos versiones de idioma compartan una dirección: %s. Cambia antes una de cada pareja – dos etiquetas con la misma dirección se pueden fusionar en Etiquetas y temas.',
    'The database is not updated yet (migration 0083) – open the administration once more and try again.' => 'La base de datos aún no está actualizada (migración 0083) – vuelve a abrir la administración e inténtalo de nuevo.',
    'A news item of this category has the same address as a news item in that language version. Change one of them first.' => 'Una noticia de esta categoría tiene la misma dirección que una noticia de esa versión de idioma. Cambia antes una de ellas.',
    'Two language versions in the export share addresses, so the same address in every language was switched on (Settings → General).' => 'Dos versiones de idioma de la exportación comparten direcciones, así que se activó la misma dirección en todos los idiomas (Ajustes → General).',
    'Skipped: %d (that language version already has the address).' => 'Omitidos: %d (esa versión de idioma ya tiene la dirección).',
    'Apps connected to this account (the Claude connector) are disconnected with the new password – connect them again in the Claude app.' => 'Las apps conectadas a esta cuenta (el conector de Claude) se desconectan con la nueva contraseña – vuelve a conectarlas en la app de Claude.',
    'Language versions the site does not have yet: %s – add them below, otherwise their posts are left out.' => 'Versiones de idioma que el sitio aún no tiene: %s – añádelas abajo; si no, sus entradas se omiten.',
    'add the language versions %s to the site – they show in the language switcher at once' => 'añadir al sitio las versiones de idioma %s – aparecen al instante en el selector de idioma',
    'The collection list shows the collection “%s”, which does not exist.' => 'La lista de la colección muestra la colección “%s”, que no existe.',
    'The collection list shows the category “%s”, which the collection does not have – it will stay empty.' => 'La lista de la colección muestra la categoría “%s”, que la colección no tiene – se quedará vacía.',
    '{{%s}} is not a field of the collection “%s” – it will stay empty on the site.' => '{{%s}} no es un campo de la colección “%s” – se quedará vacío en el sitio.',
    'A newer media/.htaccess.kaleta-nova is next to your customised media/.htaccess – carry over its deny rule (since 3.9.2 it also blocks files like photo.php.jpg), then delete the file.' => 'Junto a tu media/.htaccess personalizado hay un media/.htaccess.kaleta-nova más reciente – traslada su regla deny (desde 3.9.2 también bloquea archivos como photo.php.jpg) y después elimina el archivo.',
    'media/.htaccess does not have the rule of Kaleta 3.9.2 that blocks files like photo.php.jpg – copy media/.htaccess from the release package (on nginx, the media rules of system/nginx.example.conf).' => 'media/.htaccess no tiene la regla de Kaleta 3.9.2 que bloquea archivos como photo.php.jpg – copia media/.htaccess del paquete de la versión (en nginx, las reglas de medios de system/nginx.example.conf).',
    'Files with a script extension in their name are in media/ (%s) – check them and delete them over FTP.' => 'En media/ hay archivos con una extensión de script en el nombre (%s) – revísalos y elimínalos por FTP.',
    'Media files' => 'Archivos de medios',
    'Every tool at once – each conversation starts with the whole list.' => 'Todas las herramientas a la vez – cada conversación empieza con la lista completa.',
    'essentials' => 'básicas',
    'all tools' => 'todas las herramientas',
    'Claude tool set changed' => 'Conjunto de herramientas de Claude cambiado',
    'The update source answered with older update information (version %s, published %s) than it gave this site before (version %s, published %s) – an outdated copy of the file, or someone serving an old one on purpose. Nothing is offered or installed from it; the check repeats every hour.' => 'La fuente de actualizaciones respondió con información de actualización más antigua (versión %s, publicada %s) que la que dio antes a este sitio (versión %s, publicada %s) – una copia desactualizada del archivo o alguien que sirve una antigua a propósito. No se ofrece ni instala nada de ella; la comprobación se repite cada hora.',
    'The checks have been failing for %d days.' => 'Las comprobaciones llevan %d días fallando.',
    'Update information' => 'Información de actualización',
    'The time zone setting is %s, but PHP runs in %s – this server does not know the zone, so dates are written and shown on the %s clock. Choose the zone again in Settings → General.' => 'La zona horaria configurada es %s, pero PHP funciona en %s – este servidor no conoce la zona, así que las fechas se escriben y muestran con la hora de %s. Vuelve a elegir la zona en Ajustes → General.',
    'PHP writes dates in %s (%s), but the database compares them in %s – scheduled publishing and time limits are off by %d minutes. Ask the hosting whether the database connection keeps its session time zone.' => 'PHP escribe las fechas en %s (%s), pero la base de datos las compara en %s – la publicación programada y los límites de tiempo se desfasan %d minutos. Pregunta a tu hosting si la conexión a la base de datos conserva la zona horaria de su sesión.',
    '%s (%s) – PHP and the database count time the same way' => '%s (%s) – PHP y la base de datos cuentan el tiempo igual',
    'the update source signs its update information with a date in the future (%s), so the site does not remember it for the freshness check. Check the date and time of the server; if they are right, tell the Kaleta publisher.' => 'la fuente de actualizaciones firma su información de actualización con una fecha futura (%s), así que el sitio no la recuerda para la comprobación de vigencia. Comprueba la fecha y la hora del servidor; si son correctas, avisa al editor de Kaleta.',
    'Drafts only – you publish' => 'Solo borradores – tú publicas',
    'Can also publish' => 'También puede publicar',
    'recommended' => 'recomendado',
    'Everything your role (%s) allows, publishing included – Claude publishes when you ask it to. The menu and the look still wait in the draft look until they are published.' => 'Todo lo que permite tu rol (%s), incluida la publicación – Claude publica cuando se lo pides. El menú y la apariencia siguen esperando en el borrador de la apariencia hasta que se publiquen.',
    'Everything your role (%s) allows, publishing included. The menu and the look still wait in the draft look until they are published.' => 'Todo lo que permite tu rol (%s), incluida la publicación. El menú y la apariencia siguen esperando en el borrador de la apariencia hasta que se publiquen.',
    'Advanced (for Claude Code)' => 'Avanzado (para Claude Code)',
    'How much should Claude load at the start?' => '¿Cuánto debe cargar Claude al empezar?',
    'How much should the application load at the start?' => '¿Cuánto debe cargar la aplicación al empezar?',
    'Essentials – recommended, faster' => 'Básicas – recomendado, más rápido',
    'Everything at once – for Claude Code and scripts' => 'Todo a la vez – para Claude Code y scripts',
    'The tools for pages, builds, the look, collections, media and requests. Claude finds the other tools when it needs them.' => 'Las herramientas para páginas, estructuras, la apariencia, colecciones, medios y encargos. Claude encuentra las demás herramientas cuando las necesita.',
    'The tools for pages, builds, the look, collections, media and requests. The application finds the other tools when it needs them.' => 'Las herramientas para páginas, estructuras, la apariencia, colecciones, medios y encargos. La aplicación encuentra las demás herramientas cuando las necesita.',
    'Switch to all tools' => 'Cambiar a todas las herramientas',
    'Switch to essentials' => 'Cambiar a básicas',
    'Claude sends you here to sign in. You choose what it may do: drafts only, which you publish (recommended), also publish, or only read.' => 'Claude te envía aquí para iniciar sesión. Tú eliges qué puede hacer: solo borradores, que publicas tú (recomendado), también publicar o solo leer.',
    'With “Drafts only”, pages and news stay drafts until you publish them; with “Can also publish”, Claude publishes when you ask it to. All its changes are in the Change log.' => 'Con “Solo borradores”, las páginas y noticias siguen como borradores hasta que las publiques; con “También puede publicar”, Claude publica cuando se lo pides. Todos sus cambios están en el Registro de cambios.',
    'Personal tokens (Claude Code and other tools)' => 'Tokens personales (Claude Code y otras herramientas)',
    'For tools without sign-in. Protect a token like a password.' => 'Para herramientas sin inicio de sesión. Protege un token como una contraseña.',
    'Done – Claude will load the essentials in the next conversation it starts and find the other tools when it needs them.' => 'Listo – Claude cargará las herramientas básicas en la próxima conversación que empiece y encontrará las demás cuando las necesite.',
    'Done – Claude will see all tools in the next conversation it starts.' => 'Listo – Claude verá todas las herramientas en la próxima conversación que empiece.',
    'After this day the page hides itself. Leave empty to keep it visible.' => 'Después de este día, la página se oculta sola. Déjalo vacío para que siga visible.',
    'After this day the news item hides itself. Leave empty to keep it visible.' => 'Después de este día, la noticia se oculta sola. Déjalo vacío para que siga visible.',
    'After this day the item hides itself. Leave empty to keep it visible.' => 'Después de este día, el elemento se oculta solo. Déjalo vacío para que siga visible.',
    'After this day the pop-up switches itself off. Leave empty to keep it on.' => 'Después de este día, el pop-up se desactiva solo. Déjalo vacío para que siga activo.',
    'e.g. Garden design' => 'p. ej. Diseño de jardines',
    'Translation: %s → %s' => 'Traducción: %s → %s',
    'Translate “%s” into %s – the page starts as a copy of the original; replace the texts and publish.' => 'Traduce “%s” al idioma %s – la página empieza como copia del original; sustituye los textos y publícala.',
    'Translate “%s” into %s – the text below is a copy of the original; replace it and publish.' => 'Traduce “%s” al idioma %s – el texto de abajo es una copia del original; sustitúyelo y publica.',
    'The translation starts as a copy of the original – replace the texts, then publish.' => 'La traducción empieza como copia del original – sustituye los textos y después publica.',
    'Create the translation and open the builder' => 'Crear la traducción y abrir el builder',
    'Translate the page “%s” into %s: start the translation as a copy of the original build, translate all its texts and leave it as a draft for me to check.' => 'Traduce la página “%s” al idioma %s: empieza la traducción como copia de la estructura original, traduce todos sus textos y déjala como borrador para que yo la revise.',
    'Or let Claude do it: it creates the translation as a draft for you to check.' => 'O deja que lo haga Claude: crea la traducción como borrador para que la revises.',
    'Ask Claude to translate it' => 'Pedir a Claude que la traduzca',
    'Created, with a hidden page %s that lists it – add the first items, then publish the page in Pages.' => 'Creada, con una página oculta %s que la lista – añade los primeros elementos y después publica la página en Páginas.',
    'Created. The page “%s” already uses the address %s, so no list page was added – open that page in the builder and add the Collection list element.' => 'Creada. La página “%s” ya usa la dirección %s, así que no se añadió una página de listado – abre esa página en el builder y añade el elemento Lista de la colección.',
    'Created. The address %s is taken, so no list page was added – add the Collection list element to a page in the builder.' => 'Creada. La dirección %s está ocupada, así que no se añadió una página de listado – añade el elemento Lista de la colección a una página en el builder.',
    'The update source of the stable channel does not offer a stable-channel release, so nothing is offered. Switch to the Latest channel or check the custom update source.' => 'La fuente de actualizaciones del canal estable no ofrece ninguna versión del canal estable, así que no se ofrece nada. Cambia al canal Última o revisa la fuente de actualizaciones propia.',
    'The update information is not signed by the Kaleta publisher, so nothing is offered or installed.' => 'La información de actualización no está firmada por el editor de Kaleta, así que no se ofrece ni instala nada.',
    'The update source of the Latest channel answered with the stable-channel release (version %s) – usually a wrong redirect at the source. Nothing is offered or installed from it; the check repeats every hour.' => 'La fuente de actualizaciones del canal Última respondió con la versión del canal estable (versión %s) – normalmente una redirección errónea en la fuente. No se ofrece ni instala nada de ella; la comprobación se repite cada hora.',
    'If the publisher really published this, reset the update history in Settings → Backups and updates.' => 'Si el editor realmente publicó esto, restablece el historial de actualizaciones en Ajustes → Copias de seguridad y actualizaciones.',
    'Kaleta can’t confirm this is the newest version – the update information is %d days old. Usually this clears itself within a day; if it is still here after a week, write to info@kaletacms.com (include this message).' => 'Kaleta no puede confirmar que esta sea la versión más reciente – la información de actualización tiene %d días. Normalmente se resuelve sola en un día; si sigue aquí después de una semana, escribe a info@kaletacms.com (incluye este mensaje).',
    'Kaleta refused the update information it received, so nothing is offered or installed. Usually this clears itself within a day; if it is still here after a week, write to info@kaletacms.com (include this message).' => 'Kaleta rechazó la información de actualización recibida, así que no se ofrece ni instala nada. Normalmente se resuelve sola en un día; si sigue aquí después de una semana, escribe a info@kaletacms.com (incluye este mensaje).',
    'Details for your developer' => 'Detalles para tu desarrollador',
    'The newest update information this site has received (version %s) was published on %s. The publisher refreshes it at least every %d days, so the update source may be stuck or serving an old copy.' => 'La información de actualización más reciente que ha recibido este sitio (versión %s) se publicó el %s. El editor la renueva al menos cada %d días, así que la fuente de actualizaciones puede estar atascada o sirviendo una copia antigua.',
    'Troubleshooting' => 'Solución de problemas',
    'Only when Kaleta support or a refusal message above tells you to. After a reset, the next check also accepts older signed update information.' => 'Solo cuando te lo indique el soporte de Kaleta o un mensaje de rechazo de arriba. Tras restablecerlo, la siguiente comprobación también acepta información de actualización firmada más antigua.',
    'Reset the update history? Use it only when you know the update source is right: the next check accepts any update information signed by the publisher, even an older one.' => '¿Restablecer el historial de actualizaciones? Úsalo solo si sabes que la fuente de actualizaciones es correcta: la siguiente comprobación acepta cualquier información de actualización firmada por el editor, incluso una más antigua.',
    'Reset update history' => 'Restablecer historial de actualizaciones',
    'The update history was reset; the next check accepts any update information signed by the publisher.' => 'Se restableció el historial de actualizaciones; la siguiente comprobación acepta cualquier información de actualización firmada por el editor.',
    'Sample testimonial “%s” – use a real customer’s words, with their permission, or delete it.' => 'Testimonio de ejemplo “%s” – usa las palabras de un cliente real, con su permiso, o elimínalo.',
    'Placeholder figure “%s” – put in your real number or delete it.' => 'Cifra provisional “%s” – pon tu cifra real o elimínala.',
    'Sample text “%s” – write your own or delete it.' => 'Texto de ejemplo “%s” – escribe el tuyo o elimínalo.',
    'sample testimonials: %d' => 'testimonios de ejemplo: %d',
    'placeholder figures: %d' => 'cifras provisionales: %d',
    'sample texts: %d' => 'textos de ejemplo: %d',
    'This page still has sample content from the starter site (%s). Replace or delete it before publishing – invented reviews and numbers can mislead visitors.' => 'Esta página aún tiene contenido de ejemplo del sitio de inicio (%s). Sustitúyelo o elimínalo antes de publicar – las reseñas y cifras inventadas pueden engañar a los visitantes.',
    'Sample content' => 'Contenido de ejemplo',
    'The page text still has placeholders in square brackets (%s) – fill them in or delete them.' => 'El texto de la página aún tiene marcadores entre corchetes (%s) – rellénalos o elimínalos.',
    'Building this for a client?' => '¿Lo creas para un cliente?',
    'Found %d things to fix. Each one links to where you fix it; Claude can go through them too – ask it to audit the site.' => 'Se encontraron %d cosas por corregir. Cada una enlaza al lugar donde se corrige; Claude también puede revisarlas – pídele que audite el sitio.',
    '%s is not in the language switcher yet.' => '%s aún no está en el selector de idioma.',
    'It appears, with the hreflang links for search engines, once the home page has a published translation.' => 'Aparece, con los enlaces hreflang para los buscadores, en cuanto la página de inicio tenga una traducción publicada.',
    'Translate the home page' => 'Traducir la página de inicio',
    'Publish the translated home page' => 'Publicar la página de inicio traducida',
    'visitor texts in English' => 'textos para visitantes en inglés',
    'Not in the language switcher yet: %s. A language appears there once the home page has a published translation.' => 'Aún no están en el selector de idioma: %s. Un idioma aparece allí en cuanto la página de inicio tiene una traducción publicada.',
    'The item heading of a Collection list skips a level (h%d → h%d).' => 'El título de los elementos de una Lista de la colección se salta un nivel (h%d → h%d).',
    'In templates:' => 'En plantillas:',
    'Consent: yes' => 'Consentimiento: sí',
    'For example – click one, change it and save:' => 'Por ejemplo – haz clic en uno, cámbialo y guarda:',
    'This page does not exist.' => 'Esta página no existe.',
    'Logo and icon saved and live. Colours, fonts and sizes are in the draft look – preview the whole site, then publish them.' => 'Logo e icono guardados y publicados. Los colores, fuentes y tamaños están en el borrador de la apariencia – previsualiza todo el sitio y después publícalos.',
    'Menu “%s” (items: %d): %s' => 'Menú “%s” (elementos: %d): %s',
    'Laid out with %s (pages and posts: %d): the layout is not in the export, only the text in the post content comes over.' => 'Maquetado con %s (páginas y entradas: %d): el diseño no está en la exportación, solo se importa el texto del contenido de las entradas.',
    'Show the pages' => 'Mostrar las páginas',
    'Show the redirects' => 'Mostrar las redirecciones',
    '%s: their news items now belong to your account' => '%s: sus noticias pertenecen ahora a tu cuenta',
    '[number]' => '[número]',
    '[price]' => '[precio]',
    '[year]' => '[año]',
    '[rating]' => '[valoración]',
    '[A customer’s words – a real quote, used with their permission]' => '[Palabras de un cliente – una cita real, usada con su permiso]',
    '[Customer’s name]' => '[Nombre del cliente]',
    '[Role, company]' => '[Cargo, empresa]',
    '[A short review from a real customer]' => '[Una breve reseña de un cliente real]',
    '[Name]' => '[Nombre]',
    '[Place, year]' => '[Lugar, año]',
    '[Town]' => '[Localidad]',
    '[Street and number]' => '[Calle y número]',
    '[Postcode and town]' => '[Código postal y localidad]',
    '[Opening hours]' => '[Horario de apertura]',
    'out of 5 · [number] reviews' => 'de 5 · [número] reseñas',
    'Business details on the left, an enquiry form on the right.' => 'Datos de la empresa a la izquierda y un formulario de consulta a la derecha.',
    'Settings saved. Now confirm the new time zone and choose what happens to the dates already saved.' => 'Ajustes guardados. Ahora confirma la nueva zona horaria y elige qué pasa con las fechas ya guardadas.',
    'Saved dates are still being converted after the last time zone change. Change the zone again when that has finished.' => 'Las fechas guardadas aún se están convirtiendo tras el último cambio de zona horaria. Vuelve a cambiar la zona cuando haya terminado.',
    'The time zone is now %s. Dates already saved keep their clock time.' => 'La zona horaria es ahora %s. Las fechas ya guardadas conservan su hora.',
    'The time zone is now %s. Saved dates were converted: %d values in %d tables.' => 'La zona horaria es ahora %s. Las fechas guardadas se convirtieron: %d valores en %d tablas.',
    'The time zone is now %s. Saved dates are being converted in the background – the progress is under the time zone below.' => 'La zona horaria es ahora %s. Las fechas guardadas se están convirtiendo en segundo plano – el progreso aparece bajo la zona horaria, abajo.',
    'You are changing the site’s time zone from %s to %s.' => 'Vas a cambiar la zona horaria del sitio de %s a %s.',
    'The dates saved so far were written on the clock of %s. What should happen to them?' => 'Las fechas guardadas hasta ahora se escribieron con la hora de %s. ¿Qué debe pasar con ellas?',
    'Convert saved dates' => 'Convertir las fechas guardadas',
    'scheduled publishing, newsletters, creation and change times, sign-ins and logs move to the new clock and keep their moment: a news item scheduled for 12:00 in %s is then scheduled for %s in %s. It runs in batches; on a large site it finishes in the background.' => 'la publicación programada, los boletines, las horas de creación y modificación, los inicios de sesión y los registros pasan a la nueva hora y conservan su momento: una noticia programada para las 12:00 en %s queda programada para las %s en %s. Se hace por lotes; en un sitio grande termina en segundo plano.',
    'Keep their clock time' => 'Conservar su hora',
    'every saved date stays as written: a news item scheduled for 12:00 is published at 12:00 in %s.' => 'cada fecha guardada se queda tal como se escribió: una noticia programada para las 12:00 se publica a las 12:00 en %s.',
    'Never converted, whichever you choose: calendar days (visible until, review by, the days of statistics), opening hours and their exceptions, bookings and days off, and the times of scheduled Claude runs – they mean the clock where the business is.' => 'Nunca se convierten, elijas lo que elijas: los días del calendario (visible hasta, revisar antes de, los días de las estadísticas), el horario de apertura y sus excepciones, las reservas y los días libres, y las horas de las ejecuciones programadas de Claude – se refieren a la hora del lugar donde está el negocio.',
    'When you change it, you choose whether the dates already saved are converted to the new zone or keep their clock time.' => 'Al cambiarla, eliges si las fechas ya guardadas se convierten a la nueva zona o conservan su hora.',
    'Converting saved dates from %s to %s: %d of %d tables done, %d values so far. The background jobs continue it.' => 'Convirtiendo las fechas guardadas de %s a %s: %d de %d tablas listas, %d valores hasta ahora. Las tareas en segundo plano lo continúan.',
    'Saved dates were converted from %s to %s: %d values in %d tables.' => 'Las fechas guardadas se convirtieron de %s a %s: %d valores en %d tablas.',
    '%d of them were in the hour that repeats when daylight saving time ends; the first of the two hours was taken.' => '%d de ellas estaban en la hora que se repite al terminar el horario de verano; se tomó la primera de las dos horas.',
    'Saved dates converted to a new time zone' => 'Fechas guardadas convertidas a una nueva zona horaria',
    'The logo, the icon, colours, fonts, sizes and shapes go to the draft look first – with changes of shared classes and menus. Visitors see them once you publish the look.' => 'El logo, el icono, los colores, las fuentes, los tamaños y las formas van primero al borrador de la apariencia – junto con los cambios de clases compartidas y menús. Los visitantes los ven cuando publicas la apariencia.',
    'logo' => 'logo',
    'site icon' => 'icono del sitio',
    'Published: %s. Visitors see the new look now.' => 'Publicado: %s. Los visitantes ya ven la nueva apariencia.',
    'Preferably a PNG with a transparent background, at least 120 px high. Without a logo, the site name is shown in the header.' => 'Preferiblemente un PNG con fondo transparente, de al menos 120 px de alto. Sin logo, el encabezado muestra el nombre del sitio.',
    'Smaller' => 'Más pequeño',
    'Base size' => 'Tamaño base',
    'Larger %s' => 'Más grande %s',
    'The look as a file (Figma, Tokens Studio)' => 'La apariencia como archivo (Figma, Tokens Studio)',
    'Download the look (.tokens.json)' => 'Descargar la apariencia (.tokens.json)',
    'Load the look from the file? Its colours, fonts and sizes replace the ones above – in the draft look, so you can check them before publishing.' => '¿Cargar la apariencia desde el archivo? Sus colores, fuentes y tamaños sustituyen a los de arriba – en el borrador de la apariencia, para que puedas revisarlos antes de publicar.',
    'File with the look (.tokens.json)' => 'Archivo con la apariencia (.tokens.json)',
    'Load the look from the file' => 'Cargar la apariencia desde el archivo',
    'The file contains no usable look (a .tokens.json file from Kaleta, Figma or Tokens Studio is expected).' => 'El archivo no contiene ninguna apariencia utilizable (se espera un archivo .tokens.json de Kaleta, Figma o Tokens Studio).',
    'The look from the file is in the draft look – preview the whole site, then publish it.' => 'La apariencia del archivo está en el borrador de la apariencia – previsualiza todo el sitio y después publícala.',
    'Field to sort by' => 'Campo para ordenar',
    'Filter by field (optional)' => 'Filtrar por campo (opcional)',
    'Only items where the field has the value (on an item page, {{field}} takes it from the item shown)' => 'Solo los elementos en los que el campo tiene el valor (en la página de un elemento, {{field}} lo toma del elemento mostrado)',
    'Start date field' => 'Campo de fecha de inicio',
    'End date field (optional)' => 'Campo de fecha de fin (opcional)',
    'Pages Claude must not change – neither their settings nor their build.' => 'Páginas que Claude no debe cambiar – ni sus ajustes ni su estructura.',
    'The site has no pages yet.' => 'El sitio aún no tiene páginas.',
    'Visitors of %s see the site texts (Search, Read more, the cookie bar…) in English – Kaleta has no translation of them yet. Your pages and news are in the language you write them in.' => 'Los visitantes de %s ven los textos del sitio (Buscar, Leer más, la barra de cookies…) en inglés – Kaleta aún no los tiene traducidos. Tus páginas y noticias están en el idioma en que las escribes.',
    '%s – items: %d → %d.' => '%s – elementos: %d → %d.',
    'Leaves the menu: %s.' => 'Sale del menú: %s.',
    'New: %s.' => 'Nuevo: %s.',
    'Items leading to hidden pages (they show once you publish those pages): %d.' => 'Elementos que llevan a páginas ocultas (aparecen cuando publiques esas páginas): %d.',
    'Visitors keep seeing the current menus until you publish.' => 'Los visitantes siguen viendo los menús actuales hasta que publiques.',
    'Publish the changes? %s' => '¿Publicar los cambios? %s',
    'The menus are published – visitors see them now: %s' => 'Los menús están publicados – los visitantes ya los ven: %s',
    'In the file' => 'En el archivo',
    'Language of the export: %s. Language of your site: %s.' => 'Idioma de la exportación: %s. Idioma de tu sitio: %s.',
    'Under Import options the content goes into a new language version (%s) unless you choose the main language (%s).' => 'En Opciones de importación, el contenido va a una nueva versión de idioma (%s), salvo que elijas el idioma principal (%s).',
    'Language of the export: %s – the content goes into this language version of the site.' => 'Idioma de la exportación: %s – el contenido va a esta versión de idioma del sitio.',
    'The export names its language “%s”, which this site cannot offer – check the language version under Import options.' => 'La exportación indica como idioma “%s”, que este sitio no puede ofrecer – revisa la versión de idioma en Opciones de importación.',
    'Check these after the import: %s.' => 'Revisa esto después de la importación: %s.',
    'Custom post type “%s” (items: %s) becomes a collection with item pages at /%s/…, with the fields %s.' => 'El tipo de contenido personalizado “%s” (elementos: %s) se convierte en una colección con páginas de elemento en /%s/…, con los campos %s.',
    '%s – add this language version' => '%s – añadir esta versión de idioma',
    'A new language version shows in the language switcher once the translation of the home page is published.' => 'Una nueva versión de idioma aparece en el selector de idioma en cuanto se publica la traducción de la página de inicio.',
    'A new language version shows in the language switcher at once.' => 'Una nueva versión de idioma aparece al instante en el selector de idioma.',
    'Next steps' => 'Próximos pasos',
    'Check the imported pages and news – they are hidden until you publish them.' => 'Revisa las páginas y noticias importadas – están ocultas hasta que las publiques.',
    'Check the imported pages and news.' => 'Revisa las páginas y noticias importadas.',
    'Preview the site with the new menus, then publish them – see Menus below.' => 'Previsualiza el sitio con los nuevos menús y después publícalos – consulta Menús abajo.',
    'Look through the redirects from the old addresses.' => 'Revisa las redirecciones desde las direcciones antiguas.',
    'Download the images from the old site – see Images from the old site below.' => 'Descarga las imágenes del sitio antiguo – consulta Imágenes del sitio antiguo abajo.',
    'Before you point the domain here, check the old site against this one: every old address must lead somewhere. The old site must still be online.' => 'Antes de apuntar el dominio aquí, compara el sitio antiguo con este: cada dirección antigua debe llevar a algún sitio. El sitio antiguo aún debe estar en línea.',
    'Menu “%s” is in the draft look – %s (items: %s).' => 'El menú “%s” está en el borrador de la apariencia – %s (elementos: %s).',
    'What visitors will see after you publish the menus:' => 'Lo que verán los visitantes cuando publiques los menús:',
    'Preview the site with the new menus' => 'Vista previa del sitio con los nuevos menús',
    'Publish the menus? %s' => '¿Publicar los menús? %s',
    'Publish the menus' => 'Publicar los menús',
    'Last import:' => 'Última importación:',
    '%s (%s) – new news items: %s, new pages: %s, redirects: %s.' => '%s (%s) – noticias nuevas: %s, páginas nuevas: %s, redirecciones: %s.',
    'Result and next steps' => 'Resultado y próximos pasos',
    'WooCommerce shop: %s products become a product catalogue at /%s/… (code, price, availability, parameters and the picture), and %s product categories become its categories with their own pages; the old /product-category/… addresses redirect to them. Variations, orders and coupons stay in WordPress.' => 'Tienda WooCommerce: %s productos se convierten en un catálogo de productos en /%s/… (código, precio, disponibilidad, parámetros e imagen) y %s categorías de productos pasan a ser sus categorías con páginas propias; las direcciones antiguas /product-category/… redirigen a ellas. Las variaciones, los pedidos y los cupones se quedan en WordPress.',
    'Categories of collections (product categories)' => 'Categorías de colecciones (categorías de productos)',
    'Arabic sans-serif' => 'Árabe sin serifa',
    'Noto Sans Arabic, IBM Plex Sans Arabic – for Arabic text' => 'Noto Sans Arabic, IBM Plex Sans Arabic – para texto en árabe',
    'Arabic' => 'árabes',
    'Hebrew' => 'hebreas',
    'Cyrillic' => 'cirílicas',
    'Greek' => 'griegas',
    'The heading font %s has no %s letters, so the %s version shows them in a fallback font of the visitor’s device.' => 'La fuente de títulos %s no tiene letras %s, así que la versión %s las muestra con una fuente alternativa del dispositivo del visitante.',
    'The text font %s has no %s letters, so the %s version shows them in a fallback font of the visitor’s device.' => 'La fuente del texto %s no tiene letras %s, así que la versión %s las muestra con una fuente alternativa del dispositivo del visitante.',
    'Kaleta cannot tell whether the heading font %s has %s letters for the %s version – check the languages the font supports.' => 'Kaleta no puede saber si la fuente de títulos %s tiene letras %s para la versión %s – comprueba qué idiomas admite la fuente.',
    'Kaleta cannot tell whether the text font %s has %s letters for the %s version – check the languages the font supports.' => 'Kaleta no puede saber si la fuente del texto %s tiene letras %s para la versión %s – comprueba qué idiomas admite la fuente.',
    'Fonts with them: %s; or upload one as a custom font (e.g. %s).' => 'Fuentes que las tienen: %s; o sube una como fuente personalizada (p. ej. %s).',
    'Hidden categories shown with their first published item: %s.' => 'Categorías ocultas que se muestran con su primer elemento publicado: %s.',
    'Left hidden for review (written by a drafts-only Claude connection): %s – check them and show them in Categories.' => 'Dejadas ocultas para revisión (escritas por una conexión de Claude de solo borradores): %s – revísalas y muéstralas en Categorías.',
    'The time zone could not be changed: %s' => 'No se pudo cambiar la zona horaria: %s',
    'The time zone was not changed: it has just been changed in another window, or saved dates are still being converted.' => 'La zona horaria no se cambió: se acaba de cambiar en otra ventana o las fechas guardadas aún se están convirtiendo.',
    'Some were left as they were – see the time zone below and System status.' => 'Algunas se dejaron como estaban – consulta la zona horaria abajo y Estado del sistema.',
    'Time zone conversion' => 'Conversión de zona horaria',
    'saved dates are being converted from %s to %s by the background tasks' => 'las tareas en segundo plano están convirtiendo las fechas guardadas de %s a %s',
    'saved dates were converted from %s to %s' => 'las fechas guardadas se convirtieron de %s a %s',
    'not converted (an error, see the change log): %s' => 'no convertidas (un error, consulta el registro de cambios): %s',
    '%d values left as they were: they would leave the years 1000–9999' => '%d valores se dejaron como estaban: quedarían fuera de los años 1000–9999',
    '%d values were left as they were: they would leave the years 1000–9999.' => '%d valores se dejaron como estaban: quedarían fuera de los años 1000–9999.',
    'Not converted because of an error (see the change log): %s.' => 'No convertidas por un error (consulta el registro de cambios): %s.',
    'Name' => 'Nombre',
    'Server' => 'Servidor',
    'Port' => 'Puerto',
    'SMTP server' => 'Servidor SMTP',
    'SSL/TLS – port 465' => 'SSL/TLS – puerto 465',
    'Monitoring' => 'Monitorización',
    'Firewall' => 'Cortafuegos',
    'Print' => 'Imprimir',
    'Regular opening hours' => 'Horario habitual',
    'hours' => 'horas',
    'Text' => 'Texto',
    'Logo' => 'Logotipo',
    'Standard' => 'Estándar',
    'Video' => 'Vídeo',
    'Online' => 'En línea',
    'Newsletter' => 'Boletín',
    'Full name' => 'Nombre completo',
    'Previous versions' => 'Versiones anteriores',
    'Version %s' => 'Versión %s',
    'variants (name | code | price per line)' => 'variantes (nombre | código | precio por línea)',
    'Submenu: %s' => 'Submenú: %s',
    'Page %s of %s' => 'Página %s de %s',
    'not included' => 'no incluido',
    'Upload the latest database backup (kaleta-….sql.gz from your FTP or S3 copy, or a downloaded one) over FTP into the backups folder storage/zalohy/.' => 'Sube por FTP la copia de seguridad más reciente de la base de datos (kaleta-….sql.gz de tu copia en FTP o S3, o una descargada) a la carpeta de copias storage/zalohy/.',
    // 3.13: the cookie table as the code sets it (Core\Privacy::OWN)
    'Cookie bar: a random identifier that links the choice to its record, only when consents are recorded (cookie)' => 'Aviso de cookies: un identificador aleatorio que vincula la elección con su registro, solo cuando se registran los consentimientos (cookie)',
    'Preview of drafts: only for someone who opened a signed preview link (cookie)' => 'Vista previa de borradores: solo para quien abrió un enlace de vista previa firmado (cookie)',
    'until the preview link expires, at most 7 days' => 'hasta que caduque el enlace de vista previa, como máximo 7 días',
    'My e-mail signature' => 'Mi firma de correo',
    'Made from your record in %s (%s) in the look of your site. When your record or the site changes, open this page again and copy the signature anew.' => 'Creada a partir de tu registro en %s (%s) con la apariencia de tu sitio. Cuando cambie tu registro o el sitio, vuelve a abrir esta página y copia la firma de nuevo.',
    'You are not linked to a record yet.' => 'Todavía no estás vinculado a ningún registro.',
    'Ask an administrator to link you to your record in the Team collection.' => 'Pide a un administrador que te vincule con tu registro en la colección Equipo.',
    'This site has no Team collection.' => 'Este sitio no tiene una colección Equipo.',
    'E-mail signatures are made from the records of people in a Team collection.' => 'Las firmas de correo se crean a partir de los registros de las personas de una colección Equipo.',
    'Staff can copy their own signature in My account.' => 'El personal puede copiar su propia firma en Mi cuenta.',
    'Team record: %s (chosen)' => 'Registro del equipo: %s (elegido)',
    'Team record: %s (by e-mail)' => 'Registro del equipo: %s (por correo)',
    'Team record: not linked' => 'Registro del equipo: sin vincular',
    'Team record' => 'Registro del equipo',
    'automatic by e-mail' => 'automático por correo',
    'The person\'s record the user copies their own e-mail signature from in My account. Automatically, it is the record with the same e-mail as the account.' => 'El registro de la persona del que el usuario copia su propia firma de correo en Mi cuenta. Automáticamente es el registro con el mismo correo que la cuenta.',
    'Now linked by e-mail to %s.' => 'Ahora vinculado por correo a %s.',
    'No record has this e-mail now.' => 'Ahora ningún registro tiene este correo.',
    // 3.14: Ready for 4.0 (Core\Readiness, System status)
    'Could not check yet – the database update of 3.14 has not run. Open this page again in a minute.' => 'Aún no se pudo comprobar: la actualización de la base de datos de la 3.14 todavía no se ha ejecutado. Vuelve a abrir esta página dentro de un minuto.',
    'Ready for 4.0' => 'Preparado para la 4.0',
    'Nothing on this site stands in the way of Kaleta 4.0 so far. The checks only read – they change nothing.' => 'Por ahora nada en este sitio impide pasar a Kaleta 4.0. Las comprobaciones solo leen, no cambian nada.',
    'Some items need attention before the update to Kaleta 4.0. The checks only read – they change nothing.' => 'Algunos puntos requieren atención antes de actualizar a Kaleta 4.0. Las comprobaciones solo leen, no cambian nada.',
    'for information' => 'para información',
    'Old addresses of redirects prepared for Kaleta 4.0' => 'Direcciones antiguas de las redirecciones preparadas para Kaleta 4.0',
    'Database server' => 'Servidor de base de datos',
    '%s %s – supported by Kaleta 4.0' => '%s %s – compatible con Kaleta 4.0',
    '%s %s – Kaleta 4.0 needs MySQL %s or newer, or MariaDB %s or newer. Ask the hosting to upgrade the database server before you update.' => '%s %s – Kaleta 4.0 necesita MySQL %s o posterior, o MariaDB %s o posterior. Pide al hosting que actualice el servidor de base de datos antes de actualizar.',
    'Database user rights' => 'Permisos del usuario de la base de datos',
    'Could not check: the database server did not show the rights of the user. The update to Kaleta 4.0 renames tables and changes keys, so the user needs %s on this database – ask the hosting if you are not sure.' => 'No se pudo comprobar: el servidor de base de datos no mostró los permisos del usuario. La actualización a Kaleta 4.0 renombra tablas y cambia claves, así que el usuario necesita %s en esta base de datos; si no estás seguro, pregunta al hosting.',
    'the user may rename tables and change keys (%s)' => 'el usuario puede renombrar tablas y cambiar claves (%s)',
    'The user lacks %s on this database. The update to Kaleta 4.0 renames tables and changes keys – ask the hosting to grant them.' => 'Al usuario le falta %s en esta base de datos. La actualización a Kaleta 4.0 renombra tablas y cambia claves: pide al hosting que se los conceda.',
    '%d× an old placeholder' => '%d× un marcador antiguo',
    '%d× a table name with the prefix' => '%d× un nombre de tabla con prefijo',
    'add-on %s' => 'complemento %s',
    '%s used %s while running (last on %s)' => '%s usó %s al ejecutarse (la última vez el %s)',
    'Add-ons and old table names' => 'Complementos y nombres de tabla antiguos',
    'no add-on or custom layout writes the old Czech table names' => 'ningún complemento ni diseño propio escribe los antiguos nombres de tabla en checo',
    'Nothing found in the first %d files – the add-ons are too large to check them all here.' => 'No se encontró nada en los primeros %d archivos: los complementos son demasiado grandes para comprobarlos enteros aquí.',
    'Some add-ons write the table names with the prefix (e.g. %s). Kaleta 4.0 renames the tables, so these queries will stop working – ask the add-on’s developer to write the placeholders with the English names from system/sql/names.php ({news} instead of {novinky}).' => 'Algunos complementos escriben los nombres de tabla con prefijo (p. ej. %s). Kaleta 4.0 renombra las tablas, así que esas consultas dejarán de funcionar: pide al desarrollador del complemento que escriba los marcadores con los nombres en inglés de system/sql/names.php ({news} en lugar de {novinky}).',
    'Some add-ons write the old Czech placeholders (e.g. {novinky}). They keep working in Kaleta 4.0, but are planned to go – ask the add-on’s developer to write the English names from system/sql/names.php ({news} instead of {novinky}).' => 'Algunos complementos escriben los antiguos marcadores en checo (p. ej. {novinky}). Siguen funcionando en Kaleta 4.0, pero está previsto retirarlos: pide al desarrollador del complemento que escriba los nombres en inglés de system/sql/names.php ({news} en lugar de {novinky}).',
    'Only the first %d files were checked.' => 'Solo se comprobaron los primeros %d archivos.',
    'Tags in several languages' => 'Etiquetas en varios idiomas',
    'no tag is used by news items in more than one language' => 'ninguna etiqueta la usan noticias en más de un idioma',
    '%d tag(s) are used by news items in more than one language. That is fine today; in Kaleta 4.0 tags get a language, and each of these will need a tag per language.' => '%d etiqueta(s) las usan noticias en más de un idioma. Hoy no hay problema; en Kaleta 4.0 las etiquetas tendrán idioma y cada una necesitará una etiqueta por idioma.',
    'Old addresses of redirects' => 'Direcciones antiguas de las redirecciones',
    '%d group(s) of redirects have old addresses that count as one address today – they differ only in letter case, accents, percent-encoding or slashes. Kaleta 4.0 compares old addresses exactly: delete the extra ones in Redirects, or merge them into one.' => '%d grupo(s) de redirecciones tienen direcciones antiguas que hoy cuentan como una sola: solo se diferencian en mayúsculas, acentos, codificación porcentual o barras. Kaleta 4.0 compara las direcciones antiguas de forma exacta: borra las sobrantes en Redirecciones o fusiónalas en una.',
    'no two old addresses would collide when Kaleta 4.0 compares them exactly' => 'ninguna pareja de direcciones antiguas chocará cuando Kaleta 4.0 las compare de forma exacta',
    '%d redirect(s) are still being prepared by the background jobs.' => 'Las tareas en segundo plano aún están preparando %d redirección(es).',
    'Addresses shared by language versions' => 'Direcciones compartidas por versiones de idioma',
    'every page, news item and category has an address of its own, in every language – Kaleta 4.0 allows the same address in each language' => 'cada página, noticia y categoría tiene su propia dirección en todos los idiomas; Kaleta 4.0 permite la misma dirección en cada idioma',
    '“The same address in every language” is on, and no address is shared yet' => '«La misma dirección en todos los idiomas» está activada y aún no se comparte ninguna dirección',
    '%d address(es) are shared by versions in different languages – allowed, “The same address in every language” is on, as it will be for every site in Kaleta 4.0' => '%d dirección(es) las comparten versiones en distintos idiomas: está permitido, «La misma dirección en todos los idiomas» está activada, como lo estará en todos los sitios con Kaleta 4.0',
    '%d address(es) are shared by versions in different languages although “The same address in every language” is off – Kaleta 4.0 allows it, nothing to do' => '%d dirección(es) las comparten versiones en distintos idiomas aunque «La misma dirección en todos los idiomas» está desactivada: Kaleta 4.0 lo permite, no hay nada que hacer',
    'Table names' => 'Nombres de las tablas',
    'the tables already have their English names (Kaleta 4.0 renamed them) – this version works with them too' => 'las tablas ya tienen sus nombres en inglés (los cambió Kaleta 4.0) – esta versión también funciona con ellos',
    'the tables have today’s names; Kaleta 4.0 renames them to the English ones, and this version already works with both' => 'las tablas tienen los nombres actuales; Kaleta 4.0 los cambiará a los ingleses, y esta versión ya funciona con ambos',
    'The update source of Kaleta %d offers version %s – nothing was installed.' => 'La fuente de actualizaciones de Kaleta %d ofrece la versión %s – no se ha instalado nada.',
    'Version %s is a new major version of Kaleta. It is never installed as a regular update – Settings → Backups and updates offers it on its own, with a backup first.' => 'La versión %s es una nueva versión principal de Kaleta. Nunca se instala como actualización normal – Ajustes → Copias de seguridad y actualizaciones la ofrece por separado, con una copia de seguridad antes.',
    'Confirm that you have read what changes and checked Ready for 4.0, then start the update again.' => 'Confirma que has leído lo que cambia y revisado Preparado para la 4.0, y vuelve a iniciar la actualización.',
    'Install version %s first – a new major version is installed only from the newest release of the current one.' => 'Instala primero la versión %s – una nueva versión principal solo se instala desde la última publicación de la actual.',
    'The system has been updated to version %s. The database backup from before the update is %s.' => 'El sistema se ha actualizado a la versión %s. La copia de seguridad de la base de datos de antes de la actualización es %s.',
    'New major version' => 'Nueva versión principal',
    'Kaleta %s is available – read what changes, back up, then update.' => 'Kaleta %s está disponible – lee lo que cambia, haz una copia de seguridad y luego actualiza.',
    'A new major version is never installed automatically, not even as a security update. Check Ready for 4.0 first and download a database backup off the server.' => 'Una nueva versión principal nunca se instala automáticamente, ni siquiera como actualización de seguridad. Revisa primero Preparado para la 4.0 y descarga una copia de seguridad de la base de datos fuera del servidor.',
    'I have read what changes and checked Ready for 4.0' => 'He leído lo que cambia y he revisado Preparado para la 4.0',
    'Update to Kaleta %s? A database backup is created first; the update cannot be undone by a click – going back means restoring that backup and the files of this version.' => '¿Actualizar a Kaleta %s? Primero se crea una copia de seguridad de la base de datos; la actualización no se deshace con un clic – volver atrás significa restaurar esa copia y los archivos de esta versión.',
    'Back up and update to %s' => 'Hacer copia y actualizar a %s',
